window.QUIZ_DATA = {"topics":[{"id":"mac-lenin","title":"Chủ nghĩa Mác - Lênin về chiến tranh và quân đội","question_count":140,"test_count":7,"questions_per_test":30},{"id":"ho-chi-minh","title":"Tư tưởng Hồ Chí Minh về quân sự và quốc phòng","question_count":140,"test_count":7,"questions_per_test":30}],"tests":{"mac-lenin":[{"number":1,"title":"Đề 1","questions":[{"id":"mac-lenin-q36","number":1,"source_number":36,"text":"Đâu không phải là mục đích của chiến tranh Nhân dân Việt Nam:","choices":[{"letter":"A","text":"Bảo vệ quyền con người và chống khủng bố"},{"letter":"B","text":"Bảo vệ Đảng, nhà nước, nhân dân và chế độ xã hội chủ nghĩa"},{"letter":"C","text":"Bảo vệ vững chắc độc lập, chủ quyền, thống nhất toàn vẹn lãnh thổ"},{"letter":"D","text":"Giữ vững ổn định chính trị và môi trường hòa bình"}],"correct_letter":"A"},{"id":"mac-lenin-q34","number":2,"source_number":34,"text":"Sau cách mạng tháng 8/1945, đối tượng tác chiến của quân và dân ta là:","choices":[{"letter":"A","text":"Quân đội Nhật, quân đội Tưởng"},{"letter":"B","text":"Quân đội Anh, quân đội Tưởng"},{"letter":"C","text":"Quân đội Nhật, quân đội Pháp"},{"letter":"D","text":"Quân đội Pháp xâm lược"}],"correct_letter":"D"},{"id":"mac-lenin-q125","number":3,"source_number":125,"text":"Yếu tố cơ bản, là cơ sở để phát huy các yếu tố khác, suy đến cùng có vai trò quyết định sức mạnh chiến đấu của quân đội:","choices":[{"letter":"A","text":"Trình độ khoa học và nghệ thuật quân sự"},{"letter":"B","text":"Chính trị, tinh thần và kỷ luật"},{"letter":"C","text":"Số lượng, chất lượng vũ khí, trang bị kỹ thuật quân sự"},{"letter":"D","text":"Quân số, tổ chức biên chế"}],"correct_letter":"B"},{"id":"mac-lenin-q135","number":4,"source_number":135,"text":"Một trong những yêu cầu xây dựng Quân đội Nhân dân Việt Nam trong giai đoạn mới là gì?","choices":[{"letter":"A","text":"Trung thành với chế độ xã hội chủ nghĩa và nhân dân"},{"letter":"B","text":"Trung thành với sự nghiệp đổi mới"},{"letter":"C","text":"Trung thành với Tổ quốc, với Đảng và Nhân dân"},{"letter":"D","text":"Trung thành với Tổ quốc và chế độ xã hội chủ nghĩa Việt Nam"}],"correct_letter":"C"},{"id":"mac-lenin-q123","number":5,"source_number":123,"text":"Một trong những nguyên tắc cơ bản xây dựng Quân đội của V.I.Lênin là gì?","choices":[{"letter":"A","text":"Xây dựng quân đội chính quy"},{"letter":"B","text":"Xây dựng quân đội có tính kỷ luật cao"},{"letter":"C","text":"Xây dựng quân đội tinh nhuệ"},{"letter":"D","text":"Xây dựng quân đội hiện đại"}],"correct_letter":"A"},{"id":"mac-lenin-q29","number":6,"source_number":29,"text":"Đâu không phải là kiểu quân đội của nhà nước bóc lột:","choices":[{"letter":"A","text":"Quân đội tư sản"},{"letter":"B","text":"Quân đội của nhà nước chiếm hữu nô lệ"},{"letter":"C","text":"Quân đội của phong kiến"},{"letter":"D","text":"Quân đội xã hội chủ nghĩa"}],"correct_letter":"D"},{"id":"mac-lenin-q110","number":7,"source_number":110,"text":"Chọn phương án đúng theo quan điểm đại hội XIV của Đảng:","choices":[{"letter":"A","text":"Việt Nam chủ trương xây dựng Quân đội nhân dân cách mạng, chính quy, tinh nhuệ, từng bước hiện đại"},{"letter":"B","text":"Việt Nam chủ trương xây dựng Quân đội nhân dân cách mạng, chính quy, tinh nhuệ, hiện đại"},{"letter":"C","text":"Việt Nam chủ trương xây dựng Quân đội nhân dân cách mạng, chính quy, tinh nhuệ, một số lực lượng hiện đại"},{"letter":"D","text":"Việt Nam chủ trương xây dựng Quân đội nhân dân hiện đại, chính quy, tinh nhuệ và thực sự cách mạng"}],"correct_letter":"B"},{"id":"mac-lenin-q99","number":8,"source_number":99,"text":"Lựa chọn phương án đúng theo quan điểm của chủ nghĩa Mác - Lênin:","choices":[{"letter":"A","text":"Quân đội thuộc phương thức sản xuất"},{"letter":"B","text":"Quân đội là một bộ phận của lực lượng sản xuất"},{"letter":"C","text":"Quân đội là bộ phận của kiến trúc thượng tầng"},{"letter":"D","text":"Quân đội là bộ phận của cơ sở hạ tầng"}],"correct_letter":"C"},{"id":"mac-lenin-q94","number":9,"source_number":94,"text":"Cuộc chiến tranh nào sau đây được coi là phi nghĩa:","choices":[{"letter":"A","text":"Chiến tranh bảo vệ Tổ quốc"},{"letter":"B","text":"Chiến tranh bảo vệ chủ quyền quốc gia của các nước tư bản chống chiến tranh xâm lược của các nước đế quốc"},{"letter":"C","text":"Chiến tranh giải phóng dân tộc"},{"letter":"D","text":"Chiến tranh của các nước đế quốc chống các nước xã hội chủ nghĩa"}],"correct_letter":"D"},{"id":"mac-lenin-q120","number":10,"source_number":120,"text":"Xây dựng tinh thần đoàn kết toàn dân tộc là biện pháp xây dựng tiềm lực nào?","choices":[{"letter":"A","text":"Tiềm lực chính trị"},{"letter":"B","text":"Tiềm lực tinh thần"},{"letter":"C","text":"Tiềm lực kinh tế"},{"letter":"D","text":"Tiềm lực xã hội"}],"correct_letter":"B"},{"id":"mac-lenin-q59","number":11,"source_number":59,"text":"Chọn phương án đúng về chức năng của Quân đội Nhân dân Việt Nam:","choices":[{"letter":"A","text":"Chiến đấu và tham gia giữ gìn hòa bình khu vực"},{"letter":"B","text":"Chiến đấu, lao động sản xuất, tuyên truyền"},{"letter":"C","text":"Chiến đấu, công tác, lao động sản xuất"},{"letter":"D","text":"Chiến đấu, sẵn sàng chiến đấu"}],"correct_letter":"C"},{"id":"mac-lenin-q37","number":12,"source_number":37,"text":"Đối tượng của chiến tranh nhân dân bảo vệ Tổ quốc Việt Nam xã hội chủ nghĩa là:","choices":[{"letter":"A","text":"Chủ nghĩa đế quốc và các thế lực phản động"},{"letter":"B","text":"Chủ nghĩa đế quốc và chủ nghĩa ly khai"},{"letter":"C","text":"Các thế lực phản cách mạng trong và ngoài nước"},{"letter":"D","text":"Chủ nghĩa khủng bố quốc tế"}],"correct_letter":"A"},{"id":"mac-lenin-q71","number":13,"source_number":71,"text":"Chọn phương án đúng về sự ra đời của Quân đội Nhân dân Việt Nam:","choices":[{"letter":"A","text":"Là hiện tượng tự phát do đòi hỏi đấu tranh dân tộc ở Việt Nam"},{"letter":"B","text":"Có tính quy luật trong đấu tranh giai cấp, đấu tranh dân tộc ở Việt Nam"},{"letter":"C","text":"Là hiện tượng ngẫu nhiên trong quá trình cách mạng Việt Nam"},{"letter":"D","text":"Là sự kế thừa trong lịch sử chống giặc ngoại xâm của dân tộc ta"}],"correct_letter":"B"},{"id":"mac-lenin-q43","number":14,"source_number":43,"text":"Lựa chọn phương án sai về tính tất yếu xây dựng quân đội kiểu mới:","choices":[{"letter":"A","text":"Từ tính chất thời đại quy định"},{"letter":"B","text":"Bảo vệ vững chắc thành quả của cách mạng"},{"letter":"C","text":"Chống lại các thế lực phản cách mạng"},{"letter":"D","text":"Để mở rộng lãnh thổ và lợi ích"}],"correct_letter":"D"},{"id":"mac-lenin-q57","number":15,"source_number":57,"text":"Theo quan điểm của chủ nghĩa Mác-Lênin về bản chất của chiến tranh:","choices":[{"letter":"A","text":"Là thủ đoạn chính trị của một giai cấp"},{"letter":"B","text":"Là thủ đoạn để đạt được chính trị của một giai cấp"},{"letter":"C","text":"Là sự tiếp tục của chính trị bằng bạo lực"},{"letter":"D","text":"Là sự tiếp tục mục tiêu kinh tế bằng thủ đoạn bạo lực"}],"correct_letter":"C"},{"id":"mac-lenin-q108","number":16,"source_number":108,"text":"Quy luật có ý nghĩa trực tiếp quyết định tiến trình và kết cục chiến tranh:","choices":[{"letter":"A","text":"Quy luật tiến trình và kết cục chiến tranh phụ thuộc so sánh lực lượng quân sự của các bên tham chiến"},{"letter":"B","text":"Quy luật tiến trình và kết cục chiến tranh phụ thuộc so sánh lực lượng tinh thần của các bên tham chiến"},{"letter":"C","text":"Quy luật tiến trình và kết cục chiến tranh phụ thuộc so sánh lực lượng kinh tế của các bên tham chiến"},{"letter":"D","text":"Quy luật tiến trình và kết cục chiến tranh phụ thuộc so sánh lực lượng khoa học của các bên tham chiến"}],"correct_letter":"A"},{"id":"mac-lenin-q89","number":17,"source_number":89,"text":"Đâu không phải là những căn cứ đánh giá tính chất chính trị - xã hội của chiến tranh:","choices":[{"letter":"A","text":"Mục đích chính trị"},{"letter":"B","text":"Hoàn cảnh lịch sử nổ ra và diễn biến của cuộc chiến tranh"},{"letter":"C","text":"Mục đích xã hội"},{"letter":"D","text":"Vai trò, địa vị của giai cấp lãnh đạo, tiến hành chiến tranh"}],"correct_letter":"C"},{"id":"mac-lenin-q68","number":18,"source_number":68,"text":"Theo quan điểm của chủ nghĩa Mác - Lênin, chiến tranh là:","choices":[{"letter":"A","text":"Một bộ phận, một phương tiện của chính trị, là kết quả phản ánh những cố gắng cao nhất của chính trị"},{"letter":"B","text":"Một thành phần, một yếu tố cấu thành của chính trị"},{"letter":"C","text":"Hậu quả của chính trị"},{"letter":"D","text":"Lực lượng quan trọng không thể thiếu của chính trị"}],"correct_letter":"A"},{"id":"mac-lenin-q12","number":19,"source_number":12,"text":"Theo quan điểm chủ nghĩa Mác - Lênin về sự tồn tại của chiến tranh:","choices":[{"letter":"A","text":"Chiến tranh chỉ mất đi khi loài người không còn"},{"letter":"B","text":"Chiến tranh là hiện tượng vĩnh viễn không mất đi"},{"letter":"C","text":"Chiến tranh sẽ mất đi khi con người phát triển cao về trình độ"},{"letter":"D","text":"Chiến tranh sẽ mất đi khi không còn chế độ tư hữu"}],"correct_letter":"D"},{"id":"mac-lenin-q78","number":20,"source_number":78,"text":"Hoàn chỉnh định nghĩa: Nguyên nhân của chiến tranh: “Là sự tác động tổng hợp của các nhân tố……trong những điều kiện, hoàn cảnh và không gian, thời gian xác định làm xuất hiện cuộc chiến tranh cụ thể”:","choices":[{"letter":"A","text":"Khách quan"},{"letter":"B","text":"Khách quan và chủ quan"},{"letter":"C","text":"Chính trị - xã hội"},{"letter":"D","text":"Chủ quan"}],"correct_letter":"B"},{"id":"mac-lenin-q111","number":21,"source_number":111,"text":"Đâu không phải là yếu tố cấu thành sức mạnh chiến đấu của quân đội:","choices":[{"letter":"A","text":"Chính trị, tinh thần và kỷ luật"},{"letter":"B","text":"Kiểm soát các hoạt động của quân đội"},{"letter":"C","text":"Trình độ huấn luyện và thể lực của bộ đội"},{"letter":"D","text":"Quân số, cơ cấu tổ chức biên chế"}],"correct_letter":"B"},{"id":"mac-lenin-q55","number":22,"source_number":55,"text":"Dựa trên cơ sở nào V.I. Lênin xác định tính chất xã hội của chiến tranh?","choices":[{"letter":"A","text":"Chế độ xã hội tiến hành chiến tranh"},{"letter":"B","text":"Giai cấp lãnh đạo chiến tranh"},{"letter":"C","text":"Bản chất xã hội của chiến tranh"},{"letter":"D","text":"Mục đích chính trị của chiến tranh"}],"correct_letter":"D"},{"id":"mac-lenin-q114","number":23,"source_number":114,"text":"Tiến hành chiến tranh nhân dân với tinh thần tự lực tự cường nhưng:","choices":[{"letter":"A","text":"Chỉ cần một số nước xã hội chủ nghĩa giúp đỡ"},{"letter":"B","text":"Chỉ cần huy động mọi tiềm năng sẵn có của đất nước"},{"letter":"C","text":"Cần sự đồng tình ủng hộ, giúp đỡ của cả loài người tiến bộ trên thế giới"},{"letter":"D","text":"Cần phát huy nội lực của đất nước không cần giúp đỡ từ bên ngoài"}],"correct_letter":"C"},{"id":"mac-lenin-q25","number":24,"source_number":25,"text":"Dấu hiệu đặc thù phân biệt quân đội với các tổ chức xã hội khác:","choices":[{"letter":"A","text":"Được vũ trang, sử dụng vũ khí chuyên dùng và tiến hành chiến tranh"},{"letter":"B","text":"Nhằm mục đích bảo vệ nhà nước, giai cấp sinh ra nó"},{"letter":"C","text":"Được vũ trang để bảo vệ lợi ích giai cấp thống trị"},{"letter":"D","text":"Được nhà nước nuôi dưỡng để bảo vệ lợi ích giai cấp thống trị"}],"correct_letter":"A"},{"id":"mac-lenin-q84","number":25,"source_number":84,"text":"Chọn phương án sai về chiến tranh:","choices":[{"letter":"A","text":"Chiến tranh bắt nguồn khi xuất hiện giai cấp"},{"letter":"B","text":"Chiến tranh bắt nguồn khi xuất hiện chế độ tư hữu"},{"letter":"C","text":"Chiến tranh bắt nguồn khi xuất hiện đảng phái"},{"letter":"D","text":"Chiến tranh bắt nguồn khi xuất hiện nhà nước"}],"correct_letter":"C"},{"id":"mac-lenin-q11","number":26,"source_number":11,"text":"Chọn phương án đúng về mối quan hệ giữa chiến tranh và chính trị:","choices":[{"letter":"A","text":"Chiến tranh hỗ trợ chính trị"},{"letter":"B","text":"Chính trị quyết định chiến tranh"},{"letter":"C","text":"Chính trị hỗ trợ chiến tranh"},{"letter":"D","text":"Chiến tranh quyết định thắng lợi chính trị"}],"correct_letter":"B"},{"id":"mac-lenin-q83","number":27,"source_number":83,"text":"Một trong những hạn chế chủ yếu của các nhà tư tưởng trước C.Mác quan niệm về chiến tranh:","choices":[{"letter":"A","text":"Thế giới quan"},{"letter":"B","text":"Trình độ nhận thức"},{"letter":"C","text":"Tri thức khoa học"},{"letter":"D","text":"Lập trường giai cấp"}],"correct_letter":"A"},{"id":"mac-lenin-q23","number":28,"source_number":23,"text":"Đâu không phải là mục đích cho sự ra đời của Quân đội:","choices":[{"letter":"A","text":"Bảo vệ lãnh thổ quốc gia khỏi sự xâm lược từ bên ngoài"},{"letter":"B","text":"Duy trì sự áp bức, bóc lột của giai cấp thống trị trong nước"},{"letter":"C","text":"Xâm chiếm lãnh thổ, quốc gia khác để mở rộng ách áp bức, bóc lột"},{"letter":"D","text":"Bảo đảm an ninh chính trị và trật tự xã hội"}],"correct_letter":"D"},{"id":"mac-lenin-q31","number":29,"source_number":31,"text":"Biểu hiện của tiềm lực chính trị, tinh thần là gì?","choices":[{"letter":"A","text":"Ý chí, quyết tâm của nhân dân, của các lực lượng vũ trang nhân dân."},{"letter":"B","text":"Khả năng bảo đảm vũ khí trang bị cho quân đội"},{"letter":"C","text":"Là tính chất đồng thuận hay không đồng thuận của cơ cấu giai cấp - xã hội"},{"letter":"D","text":"Khả năng huy động kinh tế của đất nước"}],"correct_letter":"A"},{"id":"mac-lenin-q102","number":30,"source_number":102,"text":"Chọn phương án đúng về quy luật xây dựng quân đội xã hội chủ nghĩa:","choices":[{"letter":"A","text":"Quy luật sự thống nhất giữa quân đội và nhân dân"},{"letter":"B","text":"Quy luật phụ thuộc trực tiếp vào điều kiện kinh tế - xã hội đất nước"},{"letter":"C","text":"Quy luật lãnh đạo của Đảng Cộng sản"},{"letter":"D","text":"Quy luật chạy đua vũ trang"}],"correct_letter":"C"}]},{"number":2,"title":"Đề 2","questions":[{"id":"mac-lenin-q1","number":1,"source_number":1,"text":"Chọn phương án đúng theo quan điểm của chủ nghĩa Mác - Lênin về chiến tranh:","choices":[{"letter":"A","text":"Chiến tranh là những cuộc xung đột tự phát ngẫu nhiên"},{"letter":"B","text":"Chiến tranh là một hiện tượng xã hội mang tính vĩnh viễn"},{"letter":"C","text":"Chiến tranh là một hiện tượng chính trị - xã hội có tính lịch sử"},{"letter":"D","text":"Chiến tranh là những xung đột do mâu thuẫn không mang tính xã hội bản chất và tính chất chính trị xã hội của chiến tranh"}],"correct_letter":"C"},{"id":"mac-lenin-q46","number":2,"source_number":46,"text":"Sức mạnh chiến đấu của quân đội được biểu hiện:","choices":[{"letter":"A","text":"Trình độ, khả năng sẵn sàng chiến đấu và chiến đấu của quân đội"},{"letter":"B","text":"Nền kinh tế và lòng dũng cảm của người lính"},{"letter":"C","text":"Vai trò lãnh đạo của giai cấp"},{"letter":"D","text":"Nhà nước tổ chức và nuôi dưỡng"}],"correct_letter":"A"},{"id":"mac-lenin-q138","number":3,"source_number":138,"text":"Đâu là một trong những âm mưu, thủ đoạn của kẻ thù khi xâm lược nước ta:","choices":[{"letter":"A","text":"Tiến công quân sự với quân số đông, kết hợp bạo loạn lật đổ từ bên trong"},{"letter":"B","text":"Kết hợp tiến công quân sự từ bên ngoài với bạo loạn lật đổ từ bên trong"},{"letter":"C","text":"Tiến công hỏa lực với mức độ cao, kết hợp tiến công quân sự từ bên ngoài"},{"letter":"D","text":"Gây bạo loạn với quy mô lớn, kết hợp tiến công quân sự từ bên ngoài"}],"correct_letter":"B"},{"id":"mac-lenin-q86","number":4,"source_number":86,"text":"Quan điểm của V.I. Lênin về nguồn gốc của chiến tranh trong giai đoạn đế quốc chủ nghĩa:","choices":[{"letter":"A","text":"Trong thời đại đế quốc chủ nghĩa, chiến tranh bắt nguồn từ bản chất của các nước tư bản trên thế giới"},{"letter":"B","text":"Bắt nguồn từ sự khác biệt về sự phát triển kinh tế của các nước đế quốc"},{"letter":"C","text":"Bắt nguồn từ sự phát triển mạnh mẽ của khoa học kỹ thuật"},{"letter":"D","text":"Bắt nguồn từ bản chất của chủ nghĩa đế quốc"}],"correct_letter":"D"},{"id":"mac-lenin-q21","number":5,"source_number":21,"text":"Chọn phương án sai: Tại sao trong xã hội cộng sản nguyên thủy lại không có quân đội?","choices":[{"letter":"A","text":"Chưa xuất hiện nhà nước"},{"letter":"B","text":"Trình độ của lực lượng sản xuất rất thấp kém"},{"letter":"C","text":"Chưa xuất hiện giai cấp"},{"letter":"D","text":"Chưa xuất hiện đạo đức"}],"correct_letter":"D"},{"id":"mac-lenin-q73","number":6,"source_number":73,"text":"Chọn phương án đúng nhất để căn cứ phân chia kiểu chiến tranh:","choices":[{"letter":"A","text":"Cơ sở về khoa học, vũ khí sử dụng"},{"letter":"B","text":"Cơ sở lịch sử xã hội"},{"letter":"C","text":"Lực lượng tham gia đấu tranh"},{"letter":"D","text":"Cơ sở của các chế độ kinh tế - xã hội"}],"correct_letter":"B"},{"id":"mac-lenin-q81","number":7,"source_number":81,"text":"Cơ sở C.Mác và Ph.Ăngghen đưa ra quan niệm chiến tranh và quân đội:","choices":[{"letter":"A","text":"Góc độ triết học - xã hội học"},{"letter":"B","text":"Góc độ triết học - chính trị học"},{"letter":"C","text":"Góc độ triết học - tâm lý học"},{"letter":"D","text":"Góc độ chính trị - xã hội học"}],"correct_letter":"A"},{"id":"mac-lenin-q44","number":8,"source_number":44,"text":"Chọn phương án sai về bản chất của quân đội xã hội chủ nghĩa:","choices":[{"letter":"A","text":"Thực hiện nghĩa vụ quốc tế"},{"letter":"B","text":"Công cụ bạo lực của nhà nước xã hội chủ nghĩa"},{"letter":"C","text":"Công cụ xâm chiếm lãnh thổ các quốc gia"},{"letter":"D","text":"Công cụ bạo lực vũ trang của giai cấp công nhân"}],"correct_letter":"C"},{"id":"mac-lenin-q2","number":9,"source_number":2,"text":"Theo V.I.Lênin, đánh giá tính chất chính trị - xã hội của chiến tranh phải đứng vững trên lập trường:","choices":[{"letter":"A","text":"Tầng lớp trí thức"},{"letter":"B","text":"Giai cấp tư sản"},{"letter":"C","text":"Giai cấp nông dân"},{"letter":"D","text":"Giai cấp vô sản"}],"correct_letter":"D"},{"id":"mac-lenin-q70","number":10,"source_number":70,"text":"Đảng ta chỉ đạo phương châm tiến hành chiến tranh là gì?","choices":[{"letter":"A","text":"Tự lực cánh sinh, đánh lâu dài, dựa vào sức mình là chính"},{"letter":"B","text":"Tự lực cánh sinh tranh thủ sự giúp đỡ của các nước khác"},{"letter":"C","text":"Tự lực cánh sinh, đánh lâu dài, dựa vào sức mạnh thời đại là chính"},{"letter":"D","text":"Tự lực cánh sinh, đánh nhanh, thắng nhanh, dựa vào sức mình là chính"}],"correct_letter":"A"},{"id":"mac-lenin-q107","number":11,"source_number":107,"text":"Theo quan điểm của chủ nghĩa Mác – Lênin, đâu không phải là quy luật vận động, phát triển của quân đội:","choices":[{"letter":"A","text":"Quy luật vận động, phát triển của quân đội phụ thuộc vào sức mạnh tinh thần và hệ tư tưởng của xã hội"},{"letter":"B","text":"Quy luật vận động, phát triển của quân đội phụ thuộc vào chế độ chính trị - xã hội và vào tính chất giai cấp của nhà nước tổ chức ra nó"},{"letter":"C","text":"Quy luật vận động, phát triển của quân đội phụ thuộc vào số, chất lượng binh sĩ và cơ cấu tổ chức biên chế"},{"letter":"D","text":"Quy luật vận động, phát triển của quân đội phụ thuộc vào những điều kiện kinh tế - xã hội"}],"correct_letter":"C"},{"id":"mac-lenin-q140","number":12,"source_number":140,"text":"Những câu trích dưới đây, câu nào không thể hiện tinh thần chiến tranh nhân dân:","choices":[{"letter":"A","text":"“Hễ là người Việt Nam thì phải cầm vũ khí đứng lên chống thực dân Pháp cứu Tổ quốc”"},{"letter":"B","text":"“Nhằm thẳng quân thù mà bắn, máy bay Mỹ không có gì đáng sợ”"},{"letter":"C","text":"“Giặc đến nhà đàn bà cũng đánh”"},{"letter":"D","text":"“31 triệu dân tất cả hành quân, tất cả thành chiến sĩ…”"}],"correct_letter":"B"},{"id":"mac-lenin-q77","number":13,"source_number":77,"text":"Hạn chế của C.Ph.Claudovít trong quan niệm về chính trị, trong mối quan hệ giữa chiến tranh và chính trị là gì?","choices":[{"letter":"A","text":"Chính trị là đường lối đối nội, quan hệ với kinh tế"},{"letter":"B","text":"Chính trị là đường lối đối ngoại, tách rời với kinh tế"},{"letter":"C","text":"Chính trị quan hệ chặt chẽ với kinh tế"},{"letter":"D","text":"Chính trị là đường lối đối nội và đối ngoại"}],"correct_letter":"B"},{"id":"mac-lenin-q117","number":14,"source_number":117,"text":"Đấu tranh chống tham nhũng, tiêu cực của Đảng ta hiện nay là xây dựng tiềm lực nào là chủ yếu trong sức mạnh quân sự quốc gia:","choices":[{"letter":"A","text":"Tiềm lực tinh thần"},{"letter":"B","text":"Tiềm lực quân sự"},{"letter":"C","text":"Tiềm lực kinh tế"},{"letter":"D","text":"Tiềm lực xã hội"}],"correct_letter":"A"},{"id":"mac-lenin-q128","number":15,"source_number":128,"text":"Quân đội nhân dân Việt Nam có nhiệm vụ:","choices":[{"letter":"A","text":"Xây dựng quân đội ngày càng đông đảo và sẵn sàng chiến đấu"},{"letter":"B","text":"Xây dựng quân đội có chất lượng cao và sẵn sàng chiến đấu"},{"letter":"C","text":"Xây dựng quân đội hùng mạnh và sẵn sàng chiến đấu"},{"letter":"D","text":"Xây dựng quân đội ngày càng hùng mạnh và sẵn sàng chiến đấu"}],"correct_letter":"D"},{"id":"mac-lenin-q137","number":16,"source_number":137,"text":"Một trong những âm mưu, thủ đoạn chủ yếu của kẻ thù khi xâm lược nước ta là:","choices":[{"letter":"A","text":"Đánh lâu dài"},{"letter":"B","text":"Đánh chắc, tiến chắc"},{"letter":"C","text":"Đánh nhanh, thắng nhanh"},{"letter":"D","text":"Tiến công từng bước"}],"correct_letter":"C"},{"id":"mac-lenin-q119","number":17,"source_number":119,"text":"Khẳng định nào sau đây là đúng:","choices":[{"letter":"A","text":"Tương lai chiến tranh nhân dân không còn tác dụng nữa"},{"letter":"B","text":"Chiến tranh hiện đại, sử dụng vũ khí công nghệ cao, chiến tranh nhân dân vẫn được tiến hành và phát huy hiệu quả"},{"letter":"C","text":"Chiến tranh nhân dân chỉ phù hợp với vũ khí thông thường"},{"letter":"D","text":"Chiến tranh hiện đại, sử dụng vũ khí công nghệ cao, không thể tiến hành chiến tranh nhân dân"}],"correct_letter":"B"},{"id":"mac-lenin-q126","number":18,"source_number":126,"text":"Theo quan điểm của chủ nghĩa Mác - Lênin, bản chất giai cấp của quân đội phụ thuộc vào:","choices":[{"letter":"A","text":"Bản chất của các giai cấp và của nhà nước đã tổ chức ra quân đội đó"},{"letter":"B","text":"Bản chất của nhà nước tổ chức ra quân đội đó"},{"letter":"C","text":"Bản chất của lực lượng chính trị tổ chức ra quân đội đó"},{"letter":"D","text":"Bản chất của giai cấp công nông và nhà nước đã tổ chức ra quân đội đó"}],"correct_letter":"A"},{"id":"mac-lenin-q104","number":19,"source_number":104,"text":"Chức năng của quân đội:","choices":[{"letter":"A","text":"Là lực lượng lao động và bảo vệ chủ yếu của toàn xã hội"},{"letter":"B","text":"Là lao động sản xuất tạo ra của cải cho xã hội"},{"letter":"C","text":"Là phương tiện quân sự để đạt mục tiêu chính trị"},{"letter":"D","text":"Là công cụ bạo lực chủ yếu của giai cấp thống trị và nhà nước"}],"correct_letter":"D"},{"id":"mac-lenin-q19","number":20,"source_number":19,"text":"Theo quan điểm của chủ nghĩa Mác - Lênin, luận điểm nào sau đây là sai:","choices":[{"letter":"A","text":"Chính trị quyết định"},{"letter":"B","text":"Chính trị quyết định mục đích chiến tranh"},{"letter":"C","text":"Chính trị và chiến tranh tách rời nhau"},{"letter":"D","text":"Chính trị quyết định tiến trình và kết cục chiến tranh"}],"correct_letter":"C"},{"id":"mac-lenin-q121","number":21,"source_number":121,"text":"Trong nghệ thuật kết hợp đấu tranh giữa các mặt trận thì chính trị được xác định:","choices":[{"letter":"A","text":"Là mặt trận quyết định thắng lợi trực tiếp của chiến tranh"},{"letter":"B","text":"Là cơ sở để tạo ra sức mạnh về quân sự"},{"letter":"C","text":"Là mặt trận quan trọng nhất, chủ yếu nhất"},{"letter":"D","text":"Là mặt trận chủ yếu để phân hóa, cô lập kẻ thù"}],"correct_letter":"B"},{"id":"mac-lenin-q22","number":22,"source_number":22,"text":"Bản chất giai cấp của quân đội:","choices":[{"letter":"A","text":"Là lực lượng chung của quảng đại quần chúng"},{"letter":"B","text":"Là lực lượng chung của xã hội"},{"letter":"C","text":"Là bản chất của giai cấp sinh ra và nuôi dưỡng quân đội"},{"letter":"D","text":"Là lực lượng siêu giai cấp"}],"correct_letter":"C"},{"id":"mac-lenin-q131","number":23,"source_number":131,"text":"Chính quy trong quân đội thể hiện ở chỗ:","choices":[{"letter":"A","text":"Là thực hiện thống nhất về mọi mặt"},{"letter":"B","text":"Là sự thống nhất về tổ chức biên chế"},{"letter":"C","text":"Là sự thống nhất về nghệ thuật tác chiến"},{"letter":"D","text":"Là sự thống nhất về huấn luyện tác chiến"}],"correct_letter":"A"},{"id":"mac-lenin-q97","number":24,"source_number":97,"text":"Quan điểm chủ nghĩa Mác - Lênin về bản chất giai cấp của quân đội:","choices":[{"letter":"A","text":"Mang bản chất của dân tộc sử dụng quân đội đó"},{"letter":"B","text":"Mang bản chất của nhân dân lao động"},{"letter":"C","text":"Mang bản chất của giai cấp bóc lột"},{"letter":"D","text":"Mang bản chất của giai cấp tổ chức, nuôi dưỡng và sử dụng quân đội"}],"correct_letter":"D"},{"id":"mac-lenin-q15","number":25,"source_number":15,"text":"Đâu không phải là các kiểu chiến tranh trong thời đại ngày nay:","choices":[{"letter":"A","text":"Chiến tranh giữa các dân tộc đấu tranh giành, giữ quyền độc lập, tự chủ với bọn thực dân, đế quốc"},{"letter":"B","text":"Chiến tranh lạnh"},{"letter":"C","text":"Chiến tranh giữa các nước tư bản chủ nghĩa với các nước xã hội chủ nghĩa"},{"letter":"D","text":"Nội chiến"}],"correct_letter":"B"},{"id":"mac-lenin-q62","number":26,"source_number":62,"text":"Lựa chọn phương án đúng theo quan điểm tư sản về tiêu chuẩn tính chất chính trị - xã hội của chiến tranh:","choices":[{"letter":"A","text":"Tiêu chuẩn đạo đức, thẩm mỹ"},{"letter":"B","text":"Tiêu chuẩn pháp quyền"},{"letter":"C","text":"Bên nào tiến hành chiến tranh trên địa phận nước mình là chính nghĩa và tiến hành chiến tranh trên địa phận quốc gia, dân tộc khác là phi nghĩa"},{"letter":"D","text":"Căn cứ vào chiến tranh xâm lược hay phòng ngự"}],"correct_letter":"C"},{"id":"mac-lenin-q134","number":27,"source_number":134,"text":"Sức mạnh của nền quốc phòng toàn dân ở nước ta là:","choices":[{"letter":"A","text":"Sức mạnh tổng hợp do thiên thời địa lợi nhân hòa tạo ra"},{"letter":"B","text":"Sức mạnh do các yếu tố chính trị, kinh tế, văn hóa, khoa học"},{"letter":"C","text":"Sức mạnh của lực lượng vũ trang nhân dân tạo ra"},{"letter":"D","text":"Sức mạnh tổng hợp do nhiều yếu tố tạo thành"}],"correct_letter":"D"},{"id":"mac-lenin-q9","number":28,"source_number":9,"text":"Tính chất xã hội của chiến tranh phụ thuộc chính vào:","choices":[{"letter":"A","text":"Mục đích chính trị của cuộc chiến"},{"letter":"B","text":"Trình độ nghệ thuật quân sự cuộc chiến"},{"letter":"C","text":"Trình độ tác chiến của cuộc chiến"},{"letter":"D","text":"Trình độ vũ khí của cuộc chiến"}],"correct_letter":"A"},{"id":"mac-lenin-q53","number":29,"source_number":53,"text":"Cơ sở của sự phát triển số lượng, chất lượng vũ khí, trang bị kỹ thuật quân sự:","choices":[{"letter":"A","text":"Mục đích chính trị của giai cấp"},{"letter":"B","text":"Trình độ phát triển của lực lượng sản xuất, khoa học công nghệ"},{"letter":"C","text":"Trình độ phát triển kinh tế"},{"letter":"D","text":"Mục đích chính trị của nhà nước"}],"correct_letter":"B"},{"id":"mac-lenin-q112","number":30,"source_number":112,"text":"Chọn phương án đúng về đối tác của Việt Nam hiện nay:","choices":[{"letter":"A","text":"Những ai tôn trọng độc lập, chủ quyền và hợp tác bình đẳng cùng có lợi với Việt Nam"},{"letter":"B","text":"Những quốc gia, vùng lãnh thổ, tổ chức phi chính phủ tạo điều kiện thuận lợi cho Việt Nam"},{"letter":"C","text":"Những tổ chức, cá nhân tôn trọng giúp đỡ Việt Nam."},{"letter":"D","text":"Những nước xã hội chủ nghĩa và các nước đang phát triển giúp đỡ Việt Nam"}],"correct_letter":"A"}]},{"number":3,"title":"Đề 3","questions":[{"id":"mac-lenin-q32","number":1,"source_number":32,"text":"Trong 4 mặt trận sau, mặt trận nào có ý nghĩa quyết định trực tiếp trong chiến tranh:","choices":[{"letter":"A","text":"Mặt trận quân sự"},{"letter":"B","text":"Mặt trận kinh tế"},{"letter":"C","text":"Mặt trận ngoại giao"},{"letter":"D","text":"Mặt trận chính trị"}],"correct_letter":"A"},{"id":"mac-lenin-q20","number":2,"source_number":20,"text":"Chọn phương án đúng theo quan điểm của chủ nghĩa Mác - Lênin về quân đội:","choices":[{"letter":"A","text":"Quân đội tự ra đời ngẫu nhiên của đời sống xã hội"},{"letter":"B","text":"Quân đội là hiện tượng xã hội vĩnh viễn"},{"letter":"C","text":"Quân đội là hiện tượng chính trị - xã hội có tính lịch sử"},{"letter":"D","text":"Quân đội ra đời do ý chí của thần linh tối cao"}],"correct_letter":"C"},{"id":"mac-lenin-q45","number":3,"source_number":45,"text":"Chọn phương án sai về đặc trưng bản chất quân đội xã hội chủ nghĩa:","choices":[{"letter":"A","text":"Mang tính nhân dân"},{"letter":"B","text":"Sự lãnh đạo của đảng cộng sản đối với quân đội xã hội chủ nghĩa"},{"letter":"C","text":"Mang tính quốc tế"},{"letter":"D","text":"Là đội quân thiện chiến"}],"correct_letter":"D"},{"id":"mac-lenin-q51","number":4,"source_number":51,"text":"Quân đội ta mang bản chất giai cấp công nhân đồng thời có:","choices":[{"letter":"A","text":"Tính quần chúng sâu sắc"},{"letter":"B","text":"Tính nhân dân, tính dân tộc sâu sắc"},{"letter":"C","text":"Tính phong phú đa dạng"},{"letter":"D","text":"Tính phổ biến, rộng rãi"}],"correct_letter":"B"},{"id":"mac-lenin-q103","number":5,"source_number":103,"text":"Nguyên tắc cơ bản và quan trọng nhất về xây dựng quân đội kiểu mới của V.I. Lênin là:","choices":[{"letter":"A","text":"Quân đội chính quy, hiện đại, trung thành với giai cấp công nhân và nhân dân lao động"},{"letter":"B","text":"Giữ vững quan điểm giai cấp trong xây dựng quân đội"},{"letter":"C","text":"Sự lãnh đạo của Đảng Cộng sản đối với quân đội"},{"letter":"D","text":"Tính kỷ luật cao là yếu tố quyết định sức mạnh quân đội"}],"correct_letter":"C"},{"id":"mac-lenin-q63","number":6,"source_number":63,"text":"Thực chất phạm trù tính chất chính trị - xã hội của chiến tranh là:","choices":[{"letter":"A","text":"Việc xác định vị trí đóng quân của các bên tham chiến"},{"letter":"B","text":"Sự phân định vai trò của mỗi bên tham chiến đối với tiến bộ xã hội"},{"letter":"C","text":"Sự phân định việc đúng sai về mặt pháp luật của mỗi bên tham chiến"},{"letter":"D","text":"Là những căn cứ cơ bản để xác định chiến tranh chính nghĩa hay phi nghĩa của các bên tham chiến"}],"correct_letter":"B"},{"id":"mac-lenin-q133","number":7,"source_number":133,"text":"Một trong những đặc trưng của nền quốc phòng toàn dân là:","choices":[{"letter":"A","text":"Nền quốc phòng bảo vệ quyền lợi của dân"},{"letter":"B","text":"Do nhân dân xây dựng, mang tính nhân dân sâu sắc"},{"letter":"C","text":"Nền quốc phòng mang tính giai cấp, nhân dân sâu sắc"},{"letter":"D","text":"Vì dân, của dân và do toàn thể nhân dân tiến hành"}],"correct_letter":"D"},{"id":"mac-lenin-q79","number":8,"source_number":79,"text":"Hạn chế của C.Ph.Claudovít trong quan niệm về chiến tranh là gì?","choices":[{"letter":"A","text":"Chưa luận giải được bản chất của hành vi bạo lực"},{"letter":"B","text":"Chưa thấy được bản chất của hành vi chiến tranh"},{"letter":"C","text":"Không làm rõ bản chất của hành vi đấu tranh vũ trang"},{"letter":"D","text":"Chưa khẳng định được bản chất của hành vi bạo lực"}],"correct_letter":"A"},{"id":"mac-lenin-q49","number":9,"source_number":49,"text":"Lựa chọn phương án sai:","choices":[{"letter":"A","text":"Bản chất giai cấp công nhân của quân đội ta thể hiện ở nguyên tắc tổ chức quân đội"},{"letter":"B","text":"Bản chất giai cấp công nhân của quân đội ta thể hiện ở hệ tư tưởng thống trị quân đội"},{"letter":"C","text":"Bản chất giai cấp công nhân của quân đội ta thể hiện ở mục tiêu, lý tưởng chiến đấu"},{"letter":"D","text":"Bản chất giai cấp công nhân của quân đội ta thể hiện ở lịch sử của dân tộc"}],"correct_letter":"D"},{"id":"mac-lenin-q35","number":10,"source_number":35,"text":"Xây dựng quân đội phải tinh nhuệ trên các lĩnh vực:","choices":[{"letter":"A","text":"Chính trị, quân sự, hậu cần"},{"letter":"B","text":"Chính trị, tổ chức, kỹ chiến thuật"},{"letter":"C","text":"Chính trị, tư tưởng, huấn luyện"},{"letter":"D","text":"Chính trị, an ninh, kỹ thuật"}],"correct_letter":"B"},{"id":"mac-lenin-q136","number":11,"source_number":136,"text":"Tính chất cơ bản chiến tranh nhân dân Việt Nam bảo vệ Tổ quốc là:","choices":[{"letter":"A","text":"Cuộc chiến tranh toàn dân, toàn diện, dưới sự lãnh đạo của Đảng Cộng sản Việt Nam"},{"letter":"B","text":"Cuộc chiến tranh toàn diện lấy mặt trận quân sự làm yếu tố quyết định"},{"letter":"C","text":"Cuộc chiến tranh cách mạng chống các thế lực phản cách mạng"},{"letter":"D","text":"Cuộc chiến tranh toàn dân, lấy lực lượng vũ trang làm nòng cốt"}],"correct_letter":"A"},{"id":"mac-lenin-q66","number":12,"source_number":66,"text":"Chọn phương án sai về dấu hiệu đặc trưng để phân chia các kiểu chiến tranh:","choices":[{"letter":"A","text":"Cơ sở về quy mô chiến tranh"},{"letter":"B","text":"Cơ sở lịch sử xã hội"},{"letter":"C","text":"Cơ sở về quy mô đấu tranh"},{"letter":"D","text":"Cơ sở kỹ thuật quân sự"}],"correct_letter":"C"},{"id":"mac-lenin-q127","number":13,"source_number":127,"text":"Quy luật làm cơ sở chạy đua vũ trang:","choices":[{"letter":"A","text":"Quy luật tiến trình và kết cục chiến tranh phụ thuộc so sánh lực lượng tinh thần của các bên tham chiến"},{"letter":"B","text":"Quy luật tiến trình và kết cục chiến tranh phụ thuộc so sánh lực lượng quân sự của các bên tham chiến"},{"letter":"C","text":"Quy luật tiến trình và kết cục chiến tranh phụ thuộc so sánh lực lượng kinh tế của các bên tham chiến"},{"letter":"D","text":"Quy luật tiến trình và kết cục chiến tranh phụ thuộc so sánh lực lượng khoa học của các bên tham chiến"}],"correct_letter":"B"},{"id":"mac-lenin-q38","number":14,"source_number":38,"text":"Khi Mỹ xâm lược Việt Nam, Đảng ta nhận định:","choices":[{"letter":"A","text":"Mỹ giàu và mạnh"},{"letter":"B","text":"Mỹ rất giàu và rất mạnh"},{"letter":"C","text":"Mỹ giàu nhưng không mạnh"},{"letter":"D","text":"Mỹ là nước giàu nhưng không thực sự mạnh"}],"correct_letter":"C"},{"id":"mac-lenin-q28","number":15,"source_number":28,"text":"Nguồn gốc sâu xa về sự ra đời và tồn tại của quân đội:","choices":[{"letter":"A","text":"Sự xuất hiện nhà nước"},{"letter":"B","text":"Để bảo vệ quyền và lợi ích của giai cấp thống trị"},{"letter":"C","text":"Sự xuất hiện giai cấp và phân chia giai cấp"},{"letter":"D","text":"Sự ra đời và tồn tại của chế độ chiếm hữu tư nhân về tư liệu sản xuất"}],"correct_letter":"D"},{"id":"mac-lenin-q48","number":16,"source_number":48,"text":"Bản chất giai cấp của quân đội nào không phải là kiểu quân đội của nhà nước bóc lột?","choices":[{"letter":"A","text":"Bản chất giai cấp vô sản của quân đội"},{"letter":"B","text":"Bản chất giai cấp tư sản của quân đội"},{"letter":"C","text":"Bản chất giai cấp địa chủ, phong kiến của quân đội"},{"letter":"D","text":"Bản chất giai cấp chủ nô của quân đội"}],"correct_letter":"A"},{"id":"mac-lenin-q101","number":17,"source_number":101,"text":"Quan điểm nào cho rằng quân đội tồn tại vĩnh viễn:","choices":[{"letter":"A","text":"Quan điểm chủ nghĩa Mác - Lênin"},{"letter":"B","text":"Quan điểm tôn giáo"},{"letter":"C","text":"Quan điểm tư sản"},{"letter":"D","text":"Quan điểm vô sản"}],"correct_letter":"C"},{"id":"mac-lenin-q87","number":18,"source_number":87,"text":"Theo quan điểm của chủ nghĩa Mác - Lênin, chiến tranh xuất hiện đầu tiên ở hình thái kinh tế - xã hội nào?","choices":[{"letter":"A","text":"Hình thái kinh tế - xã hội phong kiến"},{"letter":"B","text":"Hình thái kinh tế - xã hội tư bản chủ nghĩa"},{"letter":"C","text":"Hình thái kinh tế - xã hội công xã nguyên thủy"},{"letter":"D","text":"Hình thái kinh tế - xã hội chiếm hữu nô lệ"}],"correct_letter":"D"},{"id":"mac-lenin-q8","number":19,"source_number":8,"text":"Tiêu chí nhận diện đúng nhất về cuộc chiến tranh chính nghĩa:","choices":[{"letter":"A","text":"Là chiến tranh lạnh"},{"letter":"B","text":"Là cuộc chiến tranh bảo vệ quyền lợi chính đáng của dân tộc"},{"letter":"C","text":"Là cuộc chiến tranh phòng ngự"},{"letter":"D","text":"Là cuộc chiến tranh do giai cấp đã lỗi thời, lạc hậu tiến hành"}],"correct_letter":"B"},{"id":"mac-lenin-q54","number":20,"source_number":54,"text":"Chọn phương án đúng về mục đích phát triển vũ khí, trang bị kỹ thuật quân sự phụ thuộc vào:","choices":[{"letter":"A","text":"Tính chất của chế độ kinh tế, chính trị - xã hội"},{"letter":"B","text":"Trình độ phát triển của lực lượng sản xuất, khoa học công nghệ"},{"letter":"C","text":"Trình độ phát triển kinh tế"},{"letter":"D","text":"Trình độ phát triển nghệ thuật quân sự"}],"correct_letter":"A"},{"id":"mac-lenin-q116","number":21,"source_number":116,"text":"Tiềm lực chính trị tinh thần trong nội dung xây dựng nền quốc phòng toàn dân là:","choices":[{"letter":"A","text":"Khả năng về chính trị tinh thần của nhân dân có thể huy động được để chiến đấu chống quân xâm lược"},{"letter":"B","text":"Khả năng về chính trị tinh thần có thể huy động để thực hiện nhiệm vụ quốc phòng, an ninh"},{"letter":"C","text":"Khả năng về chính trị tinh thần có thể huy động để tự vệ chống lại mọi kẻ thù xâm lược"},{"letter":"D","text":"Khả năng về chính trị tinh thần của xã hội để thực hiện nhiệm vụ quốc phòng, an ninh và sẵn sang chiến đấu"}],"correct_letter":"B"},{"id":"mac-lenin-q80","number":22,"source_number":80,"text":"Chọn phương án sai theo quan điểm của chủ nghĩa Mác - Lênin:","choices":[{"letter":"A","text":"Chiến tranh là bộ phận quan trọng không thể thiếu của chính trị"},{"letter":"B","text":"Chiến tranh bắt nguồn khi xuất hiện chế độ tư hữu, giai cấp và nhà nước"},{"letter":"C","text":"Chiến tranh là hiện tượng chính trị xã hội có tính lịch sử"},{"letter":"D","text":"Chiến tranh là hoạt động tự giác nhằm đạt mục đích chính trị nhất định"}],"correct_letter":"A"},{"id":"mac-lenin-q3","number":23,"source_number":3,"text":"Theo quan điểm của chủ nghĩa Mác - Lênin, luận điểm nào sau đây là sai:","choices":[{"letter":"A","text":"Chiến tranh có thể khẳng định hoặc phủ định một đường lối chính trị"},{"letter":"B","text":"Chính trị quyết định bản chất và tính chất chính trị xã hội của chiến tranh"},{"letter":"C","text":"Chiến tranh không thể làm thay đổi tương quan so sánh lực lượng chính trị"},{"letter":"D","text":"Chiến tranh có thể thúc đẩy hoặc kìm hãm tiến trình thực hiện mục đích chính trị."}],"correct_letter":"C"},{"id":"mac-lenin-q27","number":24,"source_number":27,"text":"Theo quan điểm của chủ nghĩa Mác - Lênin, quân đội ra đời vào thời kỳ nào:","choices":[{"letter":"A","text":"Thời kỳ phong kiến"},{"letter":"B","text":"Thời kỳ tư bản chủ nghĩa"},{"letter":"C","text":"Thời kỳ công xã nguyên thủy"},{"letter":"D","text":"Thời kỳ chiếm hữu nô lệ"}],"correct_letter":"D"},{"id":"mac-lenin-q6","number":25,"source_number":6,"text":"Nguồn gốc và nguyên nhân của chiến tranh được hiểu là:","choices":[{"letter":"A","text":"Chiến tranh chỉ có nguồn gốc, không có nguyên nhân"},{"letter":"B","text":"Chiến tranh chỉ có nguyên nhân, không có nguồn gốc"},{"letter":"C","text":"Nguồn gốc là cái xét đến cùng, còn nguyên nhân là sự tác động lẫn nhau giữa điều kiện khách quan và nhân tố chủ quan trong những điều kiện nhất định"},{"letter":"D","text":"Nguồn gốc là nguyên nhân của chiến tranh"}],"correct_letter":"C"},{"id":"mac-lenin-q90","number":26,"source_number":90,"text":"Đặc trưng, quân đội là tổ chức của những người có vũ trang, thực hiện chức năng bằng vũ khí chuyên dụng, phản ánh mối quan hệ nào?","choices":[{"letter":"A","text":"Mối quan hệ đặc thù giữa đường lối quân sự và vũ khí chuyên dụng"},{"letter":"B","text":"Mối quan hệ đặc thù giữa con người và vũ khí trang bị"},{"letter":"C","text":"Mối quan hệ đặc thù giữa tổ chức quân sự và vũ khí trang bị"},{"letter":"D","text":"Mối quan hệ đặc thù giữa nghệ thuật quân sự với cán bộ chỉ huy và hạ sĩ quan binh sĩ"}],"correct_letter":"B"},{"id":"mac-lenin-q95","number":27,"source_number":95,"text":"Một trong những tính chất của chiến tranh Nhân dân bảo vệ Tổ quốc Việt Nam xã hội chủ nghĩa:","choices":[{"letter":"A","text":"Là cuộc chiến tranh toàn dân, toàn diện, lấy lực lượng vũ trang làm nòng cốt"},{"letter":"B","text":"Là cuộc chiến tranh toàn diện lấy quân sự là quyết định"},{"letter":"C","text":"Là cuộc chiến tranh toàn dân, lấy lực lượng vũ trang làm nòng cốt"},{"letter":"D","text":"Là cuộc chiến tranh cách mạng chống các thế lực phản cách mạng"}],"correct_letter":"A"},{"id":"mac-lenin-q88","number":28,"source_number":88,"text":"Hoàn thiện câu nói của V.I.Lênin: “Chiến tranh chẳng qua chỉ là………từ đầu đến cuối”","choices":[{"letter":"A","text":"Bạo lực"},{"letter":"B","text":"Kinh tế"},{"letter":"C","text":"Phương thức tác chiến"},{"letter":"D","text":"Chính trị"}],"correct_letter":"D"},{"id":"mac-lenin-q85","number":29,"source_number":85,"text":"Lựa chọn phương án đúng","choices":[{"letter":"A","text":"Chiến tranh là mối quan hệ giữa người với người về sử dụng bạo lực, kết quả của những quan hệ giữa người với người trong xã hội"},{"letter":"B","text":"Chiến tranh là một hiện tượng chính trị - xã hội, kết quả của những quan hệ giữa người với người trong xã hội"},{"letter":"C","text":"Chiến tranh là những cuộc xung đột tự phát ngẫu nhiên, kết quả của những quan hệ giữa người với người trong xã hội"},{"letter":"D","text":"Chiến tranh là những xung đột do mâu thuẫn không mang tính xã hội"}],"correct_letter":"B"},{"id":"mac-lenin-q74","number":30,"source_number":74,"text":"Tư tưởng xuyên suốt của nghệ thuật quân sự Việt Nam là:","choices":[{"letter":"A","text":"Tích cực, chủ động tiến công"},{"letter":"B","text":"Phòng thủ trận địa vững chắc"},{"letter":"C","text":"Dựa vào sức mạnh vũ khí"},{"letter":"D","text":"Chủ động tiến công"}],"correct_letter":"A"}]},{"number":4,"title":"Đề 4","questions":[{"id":"mac-lenin-q72","number":1,"source_number":72,"text":"Một trong những cơ sở hình thành nghệ thuật quân sự Việt Nam:","choices":[{"letter":"A","text":"Từ nghệ thuật quân sự của các nước"},{"letter":"B","text":"Từ quan điểm của chủ nghĩa Mác - Lênin về đấu tranh giai cấp"},{"letter":"C","text":"Từ quan điểm của chủ nghĩa Mác - Lênin về đấu tranh dân tộc"},{"letter":"D","text":"Tư tưởng quân sự Hồ Chí Minh"}],"correct_letter":"D"},{"id":"mac-lenin-q14","number":2,"source_number":14,"text":"Bản chất của chiến tranh là:","choices":[{"letter":"A","text":"Chiến tranh là bản chất của xã hội loài người"},{"letter":"B","text":"Chiến tranh thể hiện quy luật sinh tồn của con người"},{"letter":"C","text":"Chiến tranh là sự kế tục của chính trị bằng thủ đoạn bạo lực"},{"letter":"D","text":"Chiến tranh là thủ đoạn kinh tế"}],"correct_letter":"C"},{"id":"mac-lenin-q39","number":3,"source_number":39,"text":"Đâu không phải là chủ trương xây dựng Quân đội Nhân dân Việt Nam hiện nay:","choices":[{"letter":"A","text":"Xây dựng quân đội chuyên nghiệp, thiện chiến"},{"letter":"B","text":"Xây dựng quân đội tinh nhuệ, hiện đại"},{"letter":"C","text":"Xây dựng quân đội cách mạng"},{"letter":"D","text":"Xây dựng quân đội chính quy"}],"correct_letter":"A"},{"id":"mac-lenin-q98","number":4,"source_number":98,"text":"Chọn phương án đúng về bản chất của quân đội:","choices":[{"letter":"A","text":"Là lực lượng duy nhất có nhiệm vụ bảo vệ Tổ quốc"},{"letter":"B","text":"Là công cụ bạo lực của giai cấp cầm quyền"},{"letter":"C","text":"Là lực lượng nòng cốt cho toàn dân đánh giặc"},{"letter":"D","text":"Là lực lượng phòng thủ dân sự"}],"correct_letter":"B"},{"id":"mac-lenin-q113","number":5,"source_number":113,"text":"Đâu là một trong những nhận thức và vận dụng quy luật chiến tranh của Đảng ta:","choices":[{"letter":"A","text":"Phát huy ưu thế về thế trận quốc phòng toàn dân và truyền thống, kinh nghiệm chiến đấu của quân đội"},{"letter":"B","text":"Phát huy ưu thế về tính chính nghĩa của chiến tranh nhân dân bảo vệ tổ quốc trong tương quan so sánh lực lượng quân sự"},{"letter":"C","text":"Phát huy ưu thế về khả năng lãnh đạo, tổ chức của hệ thống chính trị và sức mạnh của khối đại đoàn kết toàn dân tộc"},{"letter":"D","text":"Phát huy ưu thế về khả năng sẵn sàng chiến đấu cao của quân đội trong tương quan so sánh lực lượng kinh tế"}],"correct_letter":"C"},{"id":"mac-lenin-q17","number":6,"source_number":17,"text":"Theo V.I.Lênin, nhân tố quyết định sự thành bại của chiến tranh là:","choices":[{"letter":"A","text":"Nhân tố chính trị - tinh thần"},{"letter":"B","text":"Nhân tố vũ khí trang bị"},{"letter":"C","text":"Nhân tố tổ chức biên chế"},{"letter":"D","text":"Nhân tố nghệ thuật quân sự"}],"correct_letter":"A"},{"id":"mac-lenin-q130","number":7,"source_number":130,"text":"Nội dung cơ bản nhất xây dựng quân đội ta về chính trị hiện nay là gì:","choices":[{"letter":"A","text":"Xây dựng các tổ chức đảng trong quân đội trong sạch vững mạnh"},{"letter":"B","text":"Xây dựng, tăng cường, củng cố bản chất giai cấp công nhân của quân đội"},{"letter":"C","text":"Giữ vững định hướng xã hội chủ nghĩa cho quân đội"},{"letter":"D","text":"Xây dựng quân đội vững mạnh cả về chính trị, tư tưởng và tổ chức"}],"correct_letter":"B"},{"id":"mac-lenin-q4","number":8,"source_number":4,"text":"Theo quan điểm của chủ nghĩa Mác - Lênin, nguồn gốc sâu xa của sự ra đời quân đội là:","choices":[{"letter":"A","text":"Sự phân chia giai cấp và đối kháng giai cấp"},{"letter":"B","text":"Sự xuất hiện nhà nước"},{"letter":"C","text":"Xuất hiện các tập đoàn người tranh giành lợi ích"},{"letter":"D","text":"Sự ra đời và tồn tại của chế độ chiếm hữu tư nhân về tư liệu sản xuất"}],"correct_letter":"D"},{"id":"mac-lenin-q106","number":9,"source_number":106,"text":"“Xây dựng Quân đội nhân dân, Công an nhân dân cách mạng, chính quy, tinh nhuệ, hiện đại, tuyệt đối trung thành với Tổ quốc, với Đảng, Nhà nước và Nhân dân” được nêu ở đâu:","choices":[{"letter":"A","text":"Đại hội Đảng lần thứ XIV"},{"letter":"B","text":"Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội năm 2011"},{"letter":"C","text":"Đại hội Đảng bộ Quân đội lần thứ XI"},{"letter":"D","text":"Hiến pháp năm 2013"}],"correct_letter":"A"},{"id":"mac-lenin-q41","number":10,"source_number":41,"text":"Đâu không phải là tiêu chí về mặt chính trị trong tính chất chính trị - xã hội của chiến tranh:","choices":[{"letter":"A","text":"Hoàn cảnh lịch sử nổ ra và diễn biến của chiến tranh"},{"letter":"B","text":"Vai trò, địa vị lịch sử của giai cấp lãnh đạo, tiến hành chiến tranh"},{"letter":"C","text":"Mục đích và nội dung chính trị của cuộc chiến tranh"},{"letter":"D","text":"Tính hợp pháp hay không hợp pháp của cuộc chiến tranh"}],"correct_letter":"D"},{"id":"mac-lenin-q5","number":11,"source_number":5,"text":"Theo quan điểm của chủ nghĩa Mác-Lênin phương án nào là đúng nhất về nguồn gốc của chiến tranh:","choices":[{"letter":"A","text":"Chiến tranh bắt nguồn từ khi xuất hiện các hình thức tôn giáo"},{"letter":"B","text":"Chiến tranh bắt nguồn ngay từ khi xuất hiện loài người"},{"letter":"C","text":"Chiến tranh xuất hiện từ khi có chế độ tư hữu, giai cấp và nhà nước"},{"letter":"D","text":"Chiến tranh bắt nguồn từ sự phát triển tất yếu khách quan của loài người"}],"correct_letter":"C"},{"id":"mac-lenin-q56","number":12,"source_number":56,"text":"Lựa chọn phương án đúng: Thái độ của Việt Nam đối với chiến tranh là:","choices":[{"letter":"A","text":"Phản đối tất cả các cuộc chiến tranh"},{"letter":"B","text":"Ủng hộ chiến tranh chính nghĩa, phản đối chiến tranh phi nghĩa"},{"letter":"C","text":"Ủng hộ các cuộc chiến tranh chống áp bức, nô dịch"},{"letter":"D","text":"Phản đối các cuộc chiến tranh phản cách mạng"}],"correct_letter":"B"},{"id":"mac-lenin-q26","number":13,"source_number":26,"text":"Theo quan điểm của chủ nghĩa Mác - Lênin, nguồn gốc trực tiếp của sự ra đời quân đội là:","choices":[{"letter":"A","text":"Bảo vệ giai cấp cầm quyền"},{"letter":"B","text":"Xâm chiếm lãnh thổ"},{"letter":"C","text":"Xuất hiện giai cấp và đối kháng giai cấp trong xã hội"},{"letter":"D","text":"Bảo vệ lãnh thổ"}],"correct_letter":"C"},{"id":"mac-lenin-q92","number":14,"source_number":92,"text":"Quan điểm: Quân đội là công cụ của Thượng đế để bảo vệ lợi ích của giai cấp địa chủ phong kiến và nhà thờ của trường phái nào?","choices":[{"letter":"A","text":"Chủ nghĩa duy tâm khách quan"},{"letter":"B","text":"Chủ nghĩa duy vật siêu hình"},{"letter":"C","text":"Chủ nghĩa duy vật biện chứng"},{"letter":"D","text":"Chủ nghĩa duy tâm chủ quan"}],"correct_letter":"A"},{"id":"mac-lenin-q58","number":15,"source_number":58,"text":"Lựa chọn phương án đúng về bản chất giai cấp của Quân đội Nhân dân Việt Nam:","choices":[{"letter":"A","text":"Mang bản chất nhân dân lao động Việt Nam"},{"letter":"B","text":"Mang bản chất giai cấp công - nông do Đảng lãnh đạo"},{"letter":"C","text":"Mang bản chất nông dân"},{"letter":"D","text":"Mang bản chất giai cấp công nhân"}],"correct_letter":"D"},{"id":"mac-lenin-q76","number":16,"source_number":76,"text":"Lựa chọn phương án sai:","choices":[{"letter":"A","text":"Học thuyết Mác - Lênin về chiến tranh và quân đội nghiên cứu những quy luật cơ bản, chung nhất của hiện tượng chiến tranh trong đời sống xã hội"},{"letter":"B","text":"Học thuyết Mác - Lênin về chiến tranh và quân đội nghiên cứu những quy luật cơ bản, chung nhất của hiện tượng đấu tranh vũ trang trong đời sống xã hội"},{"letter":"C","text":"Học thuyết Mác - Lênin về chiến tranh và quân đội nghiên cứu bản chất những quy luật cơ bản, chung nhất về sức mạnh quân sự quốc gia"},{"letter":"D","text":"Học thuyết Mác - Lênin về chiến tranh và quân đội nghiên cứu những quy luật cơ bản, chung nhất của hiện tượng quân đội"}],"correct_letter":"B"},{"id":"mac-lenin-q139","number":17,"source_number":139,"text":"Một trong những nội dung chủ yếu của chiến tranh nhân dân bảo vệ Tổ quốc là gì?","choices":[{"letter":"A","text":"Tổ chức thế trận chiến tranh nhân dân"},{"letter":"B","text":"Tổ chức thế trận phòng thủ của chiến tranh"},{"letter":"C","text":"Tổ chức các lực lượng đánh giặc"},{"letter":"D","text":"Tổ chức thế trận đánh giặc"}],"correct_letter":"A"},{"id":"mac-lenin-q93","number":18,"source_number":93,"text":"Tính hiện đại trong chiến tranh Nhân dân bảo vệ Tổ quốc Việt Nam được thể hiện:","choices":[{"letter":"A","text":"Kết hợp sử dụng vũ khí tương đối hiện đại với hiện đại để tiến hành chiến tranh"},{"letter":"B","text":"Sử dụng vũ khí trang bị hiện đại để đánh bại kẻ thù có vũ khí hiện đại hơn"},{"letter":"C","text":"Sử dụng vũ khí trang bị hiện đại để tiến hành chiến tranh"},{"letter":"D","text":"Hiện đại về vũ khí, trang bị, tri thức và nghệ thuật quân sự"}],"correct_letter":"D"},{"id":"mac-lenin-q60","number":19,"source_number":60,"text":"Tham gia xây dựng chính quyền cơ sở thể hiện chức năng nào của quân đội ta:","choices":[{"letter":"A","text":"Chức năng huấn luyện II. GÓI CÂU HỎI TRẮC NGHIỆM"},{"letter":"B","text":"Chức năng công tác"},{"letter":"C","text":"Chức năng chiến đấu"},{"letter":"D","text":"Chức năng sản xuất"}],"correct_letter":"B"},{"id":"mac-lenin-q47","number":20,"source_number":47,"text":"Chọn phương án sai: Quân đội mất đi khi nào?","choices":[{"letter":"A","text":"Trong chủ nghĩa cộng sản"},{"letter":"B","text":"Khi nhà nước bị tiêu vong"},{"letter":"C","text":"Khi tồn tại nhà nước xã hội chủ nghĩa"},{"letter":"D","text":"Khi không còn giai cấp và đối kháng giai cấp"}],"correct_letter":"C"},{"id":"mac-lenin-q65","number":21,"source_number":65,"text":"Chọn phương án sai về quy luật tiến trình và kết cục chiến tranh:","choices":[{"letter":"A","text":"Tiến trình và kết cục của chiến tranh phụ thuộc vào tổ chức trận địa của các bên tham chiến."},{"letter":"B","text":"Tiến trình và kết cục của chiến tranh phụ thuộc vào so sánh lực lượng kinh tế của các bên tham chiến."},{"letter":"C","text":"Tiến trình và kết cục của chiến tranh phụ thuộc vào so sánh lực lượng xã hội của các bên tham chiến."},{"letter":"D","text":"Tiến trình và kết cục của chiến tranh phụ thuộc vào mục đích chính trị giữa các bên tham chiến."}],"correct_letter":"A"},{"id":"mac-lenin-q69","number":22,"source_number":69,"text":"Chọn phương án đúng về chiến tranh:","choices":[{"letter":"A","text":"Chiến tranh là hiện tượng xã hội tự nhiên ngoài ý muốn của con người"},{"letter":"B","text":"Chiến tranh là hiện tượng mang tính lịch sử - xã hội của loài người"},{"letter":"C","text":"Chiến tranh là quy luật khách quan của xã hội loài người"},{"letter":"D","text":"Chiến tranh có ngay từ khi xuất hiện loài người"}],"correct_letter":"B"},{"id":"mac-lenin-q40","number":23,"source_number":40,"text":"Chọn phương án sai về bản chất sức mạnh quân sự quốc gia:","choices":[{"letter":"A","text":"Mang bản chất nhà nước tổ chức ra nó"},{"letter":"B","text":"Mang bản chất của nhà nước, giai cấp tổ chức ra và nuôi dưỡng nó"},{"letter":"C","text":"Mang bản chất thời đại"},{"letter":"D","text":"Mang bản chất giai cấp nhà nước tổ chức ra nó"}],"correct_letter":"C"},{"id":"mac-lenin-q82","number":24,"source_number":82,"text":"Theo quan điểm của chủ nghĩa Mác - Lênin về chiến tranh:","choices":[{"letter":"A","text":"Chiến tranh chỉ mất đi khi loài người không còn"},{"letter":"B","text":"Chiến tranh sẽ mất đi khi con người phát triển cao về trình độ"},{"letter":"C","text":"Chiến tranh là hiện tượng vĩnh viễn không mất đi"},{"letter":"D","text":"Chiến tranh sẽ mất đi khi chế độ tư hữu không còn"}],"correct_letter":"D"},{"id":"mac-lenin-q118","number":25,"source_number":118,"text":"Yếu tố nào biểu hiện tập trung, trực tiếp của sức mạnh quân sự quốc gia:","choices":[{"letter":"A","text":"Tiềm lực quân sự"},{"letter":"B","text":"Tiềm lực tinh thần"},{"letter":"C","text":"Tiềm lực xã hội"},{"letter":"D","text":"Tiềm lực kinh tế"}],"correct_letter":"A"},{"id":"mac-lenin-q115","number":26,"source_number":115,"text":"Đâu không phải là tiềm lực trong cấu trúc của sức mạnh quân sự quốc gia:","choices":[{"letter":"A","text":"Tiềm lực kinh tế"},{"letter":"B","text":"Tiềm lực quân sự"},{"letter":"C","text":"Tiềm lực chính trị"},{"letter":"D","text":"Tiềm lực xã hội"}],"correct_letter":"D"},{"id":"mac-lenin-q33","number":27,"source_number":33,"text":"Theo quan điểm của Đảng ta, yếu tố quyết định thắng lợi trên chiến trường là:","choices":[{"letter":"A","text":"Vũ khí trang bị kỹ thuật hiện đại"},{"letter":"B","text":"Con người và vũ khí, con người là quyết định"},{"letter":"C","text":"Vũ khí hiện đại, nghệ thuật tác chiến cao"},{"letter":"D","text":"Vũ khí hiện đại và người chỉ huy giỏi"}],"correct_letter":"B"},{"id":"mac-lenin-q100","number":28,"source_number":100,"text":"Yếu tố nào tác động lớn nhất tới bản chất quân đội:","choices":[{"letter":"A","text":"Chế độ chính trị"},{"letter":"B","text":"Yếu tố xã hội"},{"letter":"C","text":"Yếu tố giai cấp"},{"letter":"D","text":"Yếu tố nhà nước"}],"correct_letter":"C"},{"id":"mac-lenin-q122","number":29,"source_number":122,"text":"Đẩy mạnh công nghiệp hoá, hiện đại hoá là biện pháp xây dựng tiềm lực nào?","choices":[{"letter":"A","text":"Tiềm lực khoa học, kỹ thuật"},{"letter":"B","text":"Tiềm lực kinh tế"},{"letter":"C","text":"Tiềm lực quân sự, quốc phòng"},{"letter":"D","text":"Tiềm lực chính trị - xã hội"}],"correct_letter":"B"},{"id":"mac-lenin-q105","number":30,"source_number":105,"text":"Đâu không phải là biện pháp tăng cường bản chất giai cấp của quân đội:","choices":[{"letter":"A","text":"Kiểm soát các hoạt động của quân đội"},{"letter":"B","text":"Xây dựng tổ chức, xác định phương hướng hoạt động của quân đội"},{"letter":"C","text":"Truyền bá hệ tư tưởng"},{"letter":"D","text":"Tăng quân số thường trực"}],"correct_letter":"D"}]},{"number":5,"title":"Đề 5","questions":[{"id":"mac-lenin-q39","number":1,"source_number":39,"text":"Đâu không phải là chủ trương xây dựng Quân đội Nhân dân Việt Nam hiện nay:","choices":[{"letter":"A","text":"Xây dựng quân đội chính quy"},{"letter":"B","text":"Xây dựng quân đội tinh nhuệ, hiện đại"},{"letter":"C","text":"Xây dựng quân đội chuyên nghiệp, thiện chiến"},{"letter":"D","text":"Xây dựng quân đội cách mạng"}],"correct_letter":"C"},{"id":"mac-lenin-q129","number":2,"source_number":129,"text":"Xây dựng quân đội ta từng bước hiện đại đáp ứng yêu cầu gì?","choices":[{"letter":"A","text":"Nhằm đáp ứng yêu cầu mở rộng vị thế quốc gia"},{"letter":"B","text":"Nhằm đáp ứng yêu cầu nhiệm vụ xây dựng và bảo vệ Tổ quốc"},{"letter":"C","text":"Nhằm đáp ứng yêu cầu răn đe của quốc phòng"},{"letter":"D","text":"Nhằm nâng cao sức mạnh chiến đấu của quân đội"}],"correct_letter":"B"},{"id":"mac-lenin-q66","number":3,"source_number":66,"text":"Chọn phương án sai về dấu hiệu đặc trưng để phân chia các kiểu chiến tranh:","choices":[{"letter":"A","text":"Cơ sở kỹ thuật quân sự"},{"letter":"B","text":"Cơ sở lịch sử xã hội"},{"letter":"C","text":"Cơ sở về quy mô chiến tranh"},{"letter":"D","text":"Cơ sở về quy mô đấu tranh"}],"correct_letter":"D"},{"id":"mac-lenin-q55","number":4,"source_number":55,"text":"Dựa trên cơ sở nào V.I. Lênin xác định tính chất xã hội của chiến tranh?","choices":[{"letter":"A","text":"Mục đích chính trị của chiến tranh"},{"letter":"B","text":"Chế độ xã hội tiến hành chiến tranh"},{"letter":"C","text":"Bản chất xã hội của chiến tranh"},{"letter":"D","text":"Giai cấp lãnh đạo chiến tranh"}],"correct_letter":"A"},{"id":"mac-lenin-q61","number":5,"source_number":61,"text":"Điểm khác biệt chủ yếu giữa chiến tranh chống Pháp, chống Mỹ với các cuộc chiến tranh dựng nước và giữ nước trong lịch sử dân tộc ta là gì?","choices":[{"letter":"A","text":"Lực lượng tham gia"},{"letter":"B","text":"Phương tiện chiến tranh"},{"letter":"C","text":"Mục đích chính trị"},{"letter":"D","text":"Giai cấp lãnh đạo"}],"correct_letter":"D"},{"id":"mac-lenin-q30","number":6,"source_number":30,"text":"Đâu là mục tiêu phát triển trong Văn kiện Đại hội XIV của Đảng ta:","choices":[{"letter":"A","text":"Xây dựng đất nước và bảo vệ Tổ quốc; xây dựng phát triển kinh tế và quốc phòng - an ninh nhân dân…"},{"letter":"B","text":"Xây dựng phát triển kinh tế và quốc phòng; xây dựng chủ nghĩa xã hội va bảo vệ Tổ quốc xã hội chủ nghĩa…"},{"letter":"C","text":"Giữ vững môi trường hoà bình, ổn định; phát triển nhanh, bền vững đất nước và bảo vệ vững chắc Tổ quốc…"},{"letter":"D","text":"Xây dựng phát triển kinh tế và quốc phòng - an ninh nhân dân; phát triển nhanh, bền vững đất nước và bảo vệ vững chắc Tổ quốc…"}],"correct_letter":"C"},{"id":"mac-lenin-q70","number":7,"source_number":70,"text":"Đảng ta chỉ đạo phương châm tiến hành chiến tranh là gì?","choices":[{"letter":"A","text":"Tự lực cánh sinh, đánh lâu dài, dựa vào sức mình là chính"},{"letter":"B","text":"Tự lực cánh sinh tranh thủ sự giúp đỡ của các nước khác"},{"letter":"C","text":"Tự lực cánh sinh, đánh lâu dài, dựa vào sức mạnh thời đại là chính"},{"letter":"D","text":"Tự lực cánh sinh, đánh nhanh, thắng nhanh, dựa vào sức mình là chính"}],"correct_letter":"A"},{"id":"mac-lenin-q10","number":8,"source_number":10,"text":"Ai là tác giả đầu tiên đưa ra tiêu chí phân chia kiểu chiến tranh:","choices":[{"letter":"A","text":"C.Mác"},{"letter":"B","text":"V.I.Lênin"},{"letter":"C","text":"C.Ph.Claudovít"},{"letter":"D","text":"Ph.Ăngghen"}],"correct_letter":"B"},{"id":"mac-lenin-q87","number":9,"source_number":87,"text":"Theo quan điểm của chủ nghĩa Mác - Lênin, chiến tranh xuất hiện đầu tiên ở hình thái kinh tế - xã hội nào?","choices":[{"letter":"A","text":"Hình thái kinh tế - xã hội chiếm hữu nô lệ"},{"letter":"B","text":"Hình thái kinh tế - xã hội công xã nguyên thủy"},{"letter":"C","text":"Hình thái kinh tế - xã hội phong kiến"},{"letter":"D","text":"Hình thái kinh tế - xã hội tư bản chủ nghĩa"}],"correct_letter":"A"},{"id":"mac-lenin-q68","number":10,"source_number":68,"text":"Theo quan điểm của chủ nghĩa Mác - Lênin, chiến tranh là:","choices":[{"letter":"A","text":"Một thành phần, một yếu tố cấu thành của chính trị"},{"letter":"B","text":"Hậu quả của chính trị"},{"letter":"C","text":"Một bộ phận, một phương tiện của chính trị, là kết quả phản ánh những cố gắng cao nhất của chính trị"},{"letter":"D","text":"Lực lượng quan trọng không thể thiếu của chính trị"}],"correct_letter":"C"},{"id":"mac-lenin-q49","number":11,"source_number":49,"text":"Lựa chọn phương án sai:","choices":[{"letter":"A","text":"Bản chất giai cấp công nhân của quân đội ta thể hiện ở nguyên tắc tổ chức quân đội"},{"letter":"B","text":"Bản chất giai cấp công nhân của quân đội ta thể hiện ở lịch sử của dân tộc"},{"letter":"C","text":"Bản chất giai cấp công nhân của quân đội ta thể hiện ở mục tiêu, lý tưởng chiến đấu"},{"letter":"D","text":"Bản chất giai cấp công nhân của quân đội ta thể hiện ở hệ tư tưởng thống trị quân đội"}],"correct_letter":"B"},{"id":"mac-lenin-q91","number":12,"source_number":91,"text":"Lựa chọn phương án đúng","choices":[{"letter":"A","text":"Tính lịch sử của quân đội nghĩa là quân đội chịu sự chi phối bởi điều kiện và hoàn cảnh của lịch sử"},{"letter":"B","text":"Tính lịch sử của quân đội nghĩa là quân đội có lịch sử riêng của mình mất đi khi nguồn gốc sinh ra quân đội mất đi"},{"letter":"C","text":"Tính lịch sử của quân đội nghĩa là quân đội tồn tại cùng lịch sử loài người và mất đi khi nguồn gốc sinh ra quân đội mất đi"},{"letter":"D","text":"Tính lịch sử của quân đội là quân đội ra đời, biến đổi và mất đi khi nguồn gốc sinh ra quân đội mất đi"}],"correct_letter":"D"},{"id":"mac-lenin-q24","number":13,"source_number":24,"text":"Lựa chọn phương án sai về nguồn gốc quân đội:","choices":[{"letter":"A","text":"Nhà nước tổ chức ra quân đội"},{"letter":"B","text":"Xuất hiện cùng với sự xuất hiện của loài người"},{"letter":"C","text":"Các giai cấp, tập đoàn chính trị có chức năng nhà nước"},{"letter":"D","text":"Các tổ chức chính trị có chức năng nhà nước"}],"correct_letter":"B"},{"id":"mac-lenin-q124","number":14,"source_number":124,"text":"Kết hợp xây dựng kinh tế với quốc phòng thể hiện chức năng nào của quân đội ta:","choices":[{"letter":"A","text":"Chức năng chiến đấu"},{"letter":"B","text":"Chức năng công tác"},{"letter":"C","text":"Chức năng sản xuất"},{"letter":"D","text":"Chức năng huấn luyện"}],"correct_letter":"C"},{"id":"mac-lenin-q96","number":15,"source_number":96,"text":"Quan điểm nào phủ nhận tính lịch sử của quân đội:","choices":[{"letter":"A","text":"Quan điểm của giai cấp tư sản"},{"letter":"B","text":"Quan điểm của giai cấp vô sản"},{"letter":"C","text":"Quan điểm của giai cấp công nhân"},{"letter":"D","text":"Quan điểm của tầng lớp trí thức"}],"correct_letter":"A"},{"id":"mac-lenin-q67","number":16,"source_number":67,"text":"Chọn phương án đúng theo quan điểm của chủ nghĩa Mác - Lênin:","choices":[{"letter":"A","text":"Chiến tranh là mối quan hệ giữa người với người để tranh giành lợi ích"},{"letter":"B","text":"Chiến tranh là những cuộc xung đột tự phát ngẫu nhiên"},{"letter":"C","text":"Chiến tranh là những xung đột do mâu thuẫn không mang tính xã hội"},{"letter":"D","text":"Chiến tranh là hiện tượng chính trị - xã hội, kết quả của những quan hệ giữa người với người trong xã hội"}],"correct_letter":"D"},{"id":"mac-lenin-q50","number":17,"source_number":50,"text":"Chọn phương án đúng về thời gian ra đời Quân đội Nhân dân Việt Nam:","choices":[{"letter":"A","text":"Trước khi thành lập Nhà nước Việt Nam dân chủ cộng hòa"},{"letter":"B","text":"Cùng với thành lập nhà nước Việt Nam dân chủ cộng hòa"},{"letter":"C","text":"Cùng với sự ra đời nhà nước xã hội chủ nghĩa Việt Nam"},{"letter":"D","text":"Sau khi thành lập nhà nước Việt Nam dân chủ cộng hòa"}],"correct_letter":"A"},{"id":"mac-lenin-q109","number":18,"source_number":109,"text":"Lựa chọn phương án đúng: Sự ra đời của Quân đội Nhân dân Việt Nam là:","choices":[{"letter":"A","text":"Là hiện tượng tự phát do đòi hỏi của chiến tranh cách mạng"},{"letter":"B","text":"Là sự kế thừa trong lịch sử chống giặc ngoại xâm"},{"letter":"C","text":"Là hiện tượng ngẫu nhiên trong quá trình đấu tranh cách mạng của dân tộc Việt Nam"},{"letter":"D","text":"Là tất yếu có tính quy luật trong đấu tranh giai cấp, đấu tranh dân tộc ở Việt Nam"}],"correct_letter":"D"},{"id":"mac-lenin-q64","number":19,"source_number":64,"text":"Tiêu chí cơ bản nhận diện cuộc chiến tranh là phi nghĩa:","choices":[{"letter":"A","text":"Là chiến tranh lạnh"},{"letter":"B","text":"Là cuộc chiến tranh xâm chiếm quyền lợi của người khác"},{"letter":"C","text":"Là cuộc chiến tranh công nghệ cao"},{"letter":"D","text":"Là cuộc chiến tranh tiến công"}],"correct_letter":"B"},{"id":"mac-lenin-q75","number":20,"source_number":75,"text":"Cơ sở của nghệ thuật lấy nhỏ đánh lớn, lấy ít địch nhiều, lấy yếu chống mạnh của nhân dân ta là:","choices":[{"letter":"A","text":"Lấy kế thắng lực"},{"letter":"B","text":"Lấy thời thắng lực"},{"letter":"C","text":"Lấy thế thắng lực"},{"letter":"D","text":"Lấy mưu thắng lực"}],"correct_letter":"C"},{"id":"mac-lenin-q132","number":21,"source_number":132,"text":"Nhiệm vụ bảo vệ Tổ quốc Việt Nam xã hội chủ nghĩa thuộc về:","choices":[{"letter":"A","text":"Các đoàn thể, các tổ chức chính trị - xã hội"},{"letter":"B","text":"Toàn đảng, toàn dân, toàn quân"},{"letter":"C","text":"Hệ thống chính trị"},{"letter":"D","text":"Quân đội nhân dân Việt Nam"}],"correct_letter":"B"},{"id":"mac-lenin-q13","number":22,"source_number":13,"text":"Đâu là tiêu chuẩn quan trọng nhất để đánh giá tính chất chính trị - xã hội của chiến tranh:","choices":[{"letter":"A","text":"Tiêu chuẩn đạo đức"},{"letter":"B","text":"Tiêu chuẩn luật pháp"},{"letter":"C","text":"Tiêu chuẩn chính trị"},{"letter":"D","text":"Tiêu chuẩn kinh tế"}],"correct_letter":"C"},{"id":"mac-lenin-q52","number":23,"source_number":52,"text":"Chọn phương án đúng trong xây dựng tiềm lực quốc phòng:","choices":[{"letter":"A","text":"“Người trước, súng sau”"},{"letter":"B","text":"“Tập trung xây dựng người lính cách mạng”"},{"letter":"C","text":"“Tăng cường hiện đại vũ khí trang bị”"},{"letter":"D","text":"“Kết hợp xây dựng người và vũ khí”"}],"correct_letter":"A"},{"id":"mac-lenin-q16","number":24,"source_number":16,"text":"Tiêu chuẩn nào không đánh giá tính chất xã hội của chiến tranh:","choices":[{"letter":"A","text":"Tiêu chuẩn về mặt đạo đức"},{"letter":"B","text":"Tiêu chuẩn về mặt chính trị"},{"letter":"C","text":"Tiêu chuẩn về mặt pháp luật"},{"letter":"D","text":"Tiêu chuẩn về mặt truyền thống"}],"correct_letter":"D"},{"id":"mac-lenin-q18","number":25,"source_number":18,"text":"Chọn phương án đúng về mục đích chính trị của chiến tranh nhân dân chống thực dân Pháp dưới sự lãnh đạo của Đảng:","choices":[{"letter":"A","text":"Bảo vệ toàn vẹn lãnh thổ của Tổ quốc"},{"letter":"B","text":"Giành độc lập dân tộc và thống nhất đất nước"},{"letter":"C","text":"Đánh đổ chính quyền tay sai, giành ruộng đất cho nhân dân"},{"letter":"D","text":"Đánh đổ chính quyền tay sai, giành độc lập dân tộc và tiến lên chủ nghĩa xã hội"}],"correct_letter":"D"},{"id":"mac-lenin-q122","number":26,"source_number":122,"text":"Đẩy mạnh công nghiệp hoá, hiện đại hoá là biện pháp xây dựng tiềm lực nào?","choices":[{"letter":"A","text":"Tiềm lực chính trị - xã hội"},{"letter":"B","text":"Tiềm lực kinh tế"},{"letter":"C","text":"Tiềm lực khoa học, kỹ thuật"},{"letter":"D","text":"Tiềm lực quân sự, quốc phòng"}],"correct_letter":"B"},{"id":"mac-lenin-q73","number":27,"source_number":73,"text":"Chọn phương án đúng nhất để căn cứ phân chia kiểu chiến tranh:","choices":[{"letter":"A","text":"Cơ sở của các chế độ kinh tế - xã hội"},{"letter":"B","text":"Lực lượng tham gia đấu tranh"},{"letter":"C","text":"Cơ sở lịch sử xã hội"},{"letter":"D","text":"Cơ sở về khoa học, vũ khí sử dụng"}],"correct_letter":"C"},{"id":"mac-lenin-q7","number":28,"source_number":7,"text":"Trong quan niệm của C.Ph.Claudovít, đặc trưng cơ bản của chiến tranh là gì?","choices":[{"letter":"A","text":"Sử dụng bạo lực"},{"letter":"B","text":"Sử dụng vũ trang"},{"letter":"C","text":"Đấu tranh vũ trang"},{"letter":"D","text":"Xung đột vũ trang"}],"correct_letter":"A"},{"id":"mac-lenin-q123","number":29,"source_number":123,"text":"Một trong những nguyên tắc cơ bản xây dựng Quân đội của V.I.Lênin là gì?","choices":[{"letter":"A","text":"Xây dựng quân đội tinh nhuệ"},{"letter":"B","text":"Xây dựng quân đội có tính kỷ luật cao"},{"letter":"C","text":"Xây dựng quân đội chính quy"},{"letter":"D","text":"Xây dựng quân đội hiện đại"}],"correct_letter":"C"},{"id":"mac-lenin-q42","number":30,"source_number":42,"text":"Lựa chọn phương án đúng về thái độ của chúng ta đối với chiến tranh:","choices":[{"letter":"A","text":"Ủng hộ chiến tranh chính nghĩa, phản đối chiến tranh phi nghĩa"},{"letter":"B","text":"Phản đối các cuộc chiến tranh phản cách mạng"},{"letter":"C","text":"Ủng hộ các cuộc chiến tranh chống áp bức, nô dịch"},{"letter":"D","text":"Phản đối tất cả các cuộc chiến tranh trong lịch sử"}],"correct_letter":"A"}]},{"number":6,"title":"Đề 6","questions":[{"id":"mac-lenin-q24","number":1,"source_number":24,"text":"Lựa chọn phương án sai về nguồn gốc quân đội:","choices":[{"letter":"A","text":"Xuất hiện cùng với sự xuất hiện của loài người"},{"letter":"B","text":"Các tổ chức chính trị có chức năng nhà nước"},{"letter":"C","text":"Nhà nước tổ chức ra quân đội"},{"letter":"D","text":"Các giai cấp, tập đoàn chính trị có chức năng nhà nước"}],"correct_letter":"A"},{"id":"mac-lenin-q131","number":2,"source_number":131,"text":"Chính quy trong quân đội thể hiện ở chỗ:","choices":[{"letter":"A","text":"Là sự thống nhất về nghệ thuật tác chiến"},{"letter":"B","text":"Là thực hiện thống nhất về mọi mặt"},{"letter":"C","text":"Là sự thống nhất về tổ chức biên chế"},{"letter":"D","text":"Là sự thống nhất về huấn luyện tác chiến"}],"correct_letter":"B"},{"id":"mac-lenin-q127","number":3,"source_number":127,"text":"Quy luật làm cơ sở chạy đua vũ trang:","choices":[{"letter":"A","text":"Quy luật tiến trình và kết cục chiến tranh phụ thuộc so sánh lực lượng tinh thần của các bên tham chiến"},{"letter":"B","text":"Quy luật tiến trình và kết cục chiến tranh phụ thuộc so sánh lực lượng khoa học của các bên tham chiến"},{"letter":"C","text":"Quy luật tiến trình và kết cục chiến tranh phụ thuộc so sánh lực lượng kinh tế của các bên tham chiến"},{"letter":"D","text":"Quy luật tiến trình và kết cục chiến tranh phụ thuộc so sánh lực lượng quân sự của các bên tham chiến"}],"correct_letter":"D"},{"id":"mac-lenin-q5","number":4,"source_number":5,"text":"Theo quan điểm của chủ nghĩa Mác-Lênin phương án nào là đúng nhất về nguồn gốc của chiến tranh:","choices":[{"letter":"A","text":"Chiến tranh bắt nguồn từ sự phát triển tất yếu khách quan của loài người"},{"letter":"B","text":"Chiến tranh bắt nguồn từ khi xuất hiện các hình thức tôn giáo"},{"letter":"C","text":"Chiến tranh xuất hiện từ khi có chế độ tư hữu, giai cấp và nhà nước"},{"letter":"D","text":"Chiến tranh bắt nguồn ngay từ khi xuất hiện loài người"}],"correct_letter":"C"},{"id":"mac-lenin-q10","number":5,"source_number":10,"text":"Ai là tác giả đầu tiên đưa ra tiêu chí phân chia kiểu chiến tranh:","choices":[{"letter":"A","text":"V.I.Lênin"},{"letter":"B","text":"C.Ph.Claudovít"},{"letter":"C","text":"C.Mác"},{"letter":"D","text":"Ph.Ăngghen"}],"correct_letter":"A"},{"id":"mac-lenin-q51","number":6,"source_number":51,"text":"Quân đội ta mang bản chất giai cấp công nhân đồng thời có:","choices":[{"letter":"A","text":"Tính phong phú đa dạng"},{"letter":"B","text":"Tính phổ biến, rộng rãi"},{"letter":"C","text":"Tính quần chúng sâu sắc"},{"letter":"D","text":"Tính nhân dân, tính dân tộc sâu sắc"}],"correct_letter":"D"},{"id":"mac-lenin-q71","number":7,"source_number":71,"text":"Chọn phương án đúng về sự ra đời của Quân đội Nhân dân Việt Nam:","choices":[{"letter":"A","text":"Là sự kế thừa trong lịch sử chống giặc ngoại xâm của dân tộc ta"},{"letter":"B","text":"Là hiện tượng ngẫu nhiên trong quá trình cách mạng Việt Nam"},{"letter":"C","text":"Có tính quy luật trong đấu tranh giai cấp, đấu tranh dân tộc ở Việt Nam"},{"letter":"D","text":"Là hiện tượng tự phát do đòi hỏi đấu tranh dân tộc ở Việt Nam"}],"correct_letter":"C"},{"id":"mac-lenin-q99","number":8,"source_number":99,"text":"Lựa chọn phương án đúng theo quan điểm của chủ nghĩa Mác - Lênin:","choices":[{"letter":"A","text":"Quân đội là một bộ phận của lực lượng sản xuất"},{"letter":"B","text":"Quân đội là bộ phận của kiến trúc thượng tầng"},{"letter":"C","text":"Quân đội thuộc phương thức sản xuất"},{"letter":"D","text":"Quân đội là bộ phận của cơ sở hạ tầng"}],"correct_letter":"B"},{"id":"mac-lenin-q17","number":9,"source_number":17,"text":"Theo V.I.Lênin, nhân tố quyết định sự thành bại của chiến tranh là:","choices":[{"letter":"A","text":"Nhân tố tổ chức biên chế"},{"letter":"B","text":"Nhân tố nghệ thuật quân sự"},{"letter":"C","text":"Nhân tố chính trị - tinh thần"},{"letter":"D","text":"Nhân tố vũ khí trang bị"}],"correct_letter":"C"},{"id":"mac-lenin-q15","number":10,"source_number":15,"text":"Đâu không phải là các kiểu chiến tranh trong thời đại ngày nay:","choices":[{"letter":"A","text":"Nội chiến"},{"letter":"B","text":"Chiến tranh lạnh"},{"letter":"C","text":"Chiến tranh giữa các nước tư bản chủ nghĩa với các nước xã hội chủ nghĩa"},{"letter":"D","text":"Chiến tranh giữa các dân tộc đấu tranh giành, giữ quyền độc lập, tự chủ với bọn thực dân, đế quốc"}],"correct_letter":"B"},{"id":"mac-lenin-q12","number":11,"source_number":12,"text":"Theo quan điểm chủ nghĩa Mác - Lênin về sự tồn tại của chiến tranh:","choices":[{"letter":"A","text":"Chiến tranh sẽ mất đi khi không còn chế độ tư hữu"},{"letter":"B","text":"Chiến tranh là hiện tượng vĩnh viễn không mất đi"},{"letter":"C","text":"Chiến tranh chỉ mất đi khi loài người không còn"},{"letter":"D","text":"Chiến tranh sẽ mất đi khi con người phát triển cao về trình độ"}],"correct_letter":"A"},{"id":"mac-lenin-q129","number":12,"source_number":129,"text":"Xây dựng quân đội ta từng bước hiện đại đáp ứng yêu cầu gì?","choices":[{"letter":"A","text":"Nhằm nâng cao sức mạnh chiến đấu của quân đội"},{"letter":"B","text":"Nhằm đáp ứng yêu cầu mở rộng vị thế quốc gia"},{"letter":"C","text":"Nhằm đáp ứng yêu cầu răn đe của quốc phòng"},{"letter":"D","text":"Nhằm đáp ứng yêu cầu nhiệm vụ xây dựng và bảo vệ Tổ quốc"}],"correct_letter":"D"},{"id":"mac-lenin-q34","number":13,"source_number":34,"text":"Sau cách mạng tháng 8/1945, đối tượng tác chiến của quân và dân ta là:","choices":[{"letter":"A","text":"Quân đội Nhật, quân đội Tưởng"},{"letter":"B","text":"Quân đội Pháp xâm lược"},{"letter":"C","text":"Quân đội Nhật, quân đội Pháp"},{"letter":"D","text":"Quân đội Anh, quân đội Tưởng"}],"correct_letter":"B"},{"id":"mac-lenin-q85","number":14,"source_number":85,"text":"Lựa chọn phương án đúng","choices":[{"letter":"A","text":"Chiến tranh là những xung đột do mâu thuẫn không mang tính xã hội"},{"letter":"B","text":"Chiến tranh là mối quan hệ giữa người với người về sử dụng bạo lực, kết quả của những quan hệ giữa người với người trong xã hội"},{"letter":"C","text":"Chiến tranh là một hiện tượng chính trị - xã hội, kết quả của những quan hệ giữa người với người trong xã hội"},{"letter":"D","text":"Chiến tranh là những cuộc xung đột tự phát ngẫu nhiên, kết quả của những quan hệ giữa người với người trong xã hội"}],"correct_letter":"C"},{"id":"mac-lenin-q115","number":15,"source_number":115,"text":"Đâu không phải là tiềm lực trong cấu trúc của sức mạnh quân sự quốc gia:","choices":[{"letter":"A","text":"Tiềm lực quân sự"},{"letter":"B","text":"Tiềm lực kinh tế"},{"letter":"C","text":"Tiềm lực chính trị"},{"letter":"D","text":"Tiềm lực xã hội"}],"correct_letter":"D"},{"id":"mac-lenin-q125","number":16,"source_number":125,"text":"Yếu tố cơ bản, là cơ sở để phát huy các yếu tố khác, suy đến cùng có vai trò quyết định sức mạnh chiến đấu của quân đội:","choices":[{"letter":"A","text":"Chính trị, tinh thần và kỷ luật"},{"letter":"B","text":"Số lượng, chất lượng vũ khí, trang bị kỹ thuật quân sự"},{"letter":"C","text":"Trình độ khoa học và nghệ thuật quân sự"},{"letter":"D","text":"Quân số, tổ chức biên chế"}],"correct_letter":"A"},{"id":"mac-lenin-q42","number":17,"source_number":42,"text":"Lựa chọn phương án đúng về thái độ của chúng ta đối với chiến tranh:","choices":[{"letter":"A","text":"Phản đối tất cả các cuộc chiến tranh trong lịch sử"},{"letter":"B","text":"Ủng hộ chiến tranh chính nghĩa, phản đối chiến tranh phi nghĩa"},{"letter":"C","text":"Ủng hộ các cuộc chiến tranh chống áp bức, nô dịch"},{"letter":"D","text":"Phản đối các cuộc chiến tranh phản cách mạng"}],"correct_letter":"B"},{"id":"mac-lenin-q36","number":18,"source_number":36,"text":"Đâu không phải là mục đích của chiến tranh Nhân dân Việt Nam:","choices":[{"letter":"A","text":"Bảo vệ vững chắc độc lập, chủ quyền, thống nhất toàn vẹn lãnh thổ"},{"letter":"B","text":"Bảo vệ Đảng, nhà nước, nhân dân và chế độ xã hội chủ nghĩa"},{"letter":"C","text":"Bảo vệ quyền con người và chống khủng bố"},{"letter":"D","text":"Giữ vững ổn định chính trị và môi trường hòa bình"}],"correct_letter":"C"},{"id":"mac-lenin-q132","number":19,"source_number":132,"text":"Nhiệm vụ bảo vệ Tổ quốc Việt Nam xã hội chủ nghĩa thuộc về:","choices":[{"letter":"A","text":"Toàn đảng, toàn dân, toàn quân"},{"letter":"B","text":"Hệ thống chính trị"},{"letter":"C","text":"Quân đội nhân dân Việt Nam"},{"letter":"D","text":"Các đoàn thể, các tổ chức chính trị - xã hội"}],"correct_letter":"A"},{"id":"mac-lenin-q27","number":20,"source_number":27,"text":"Theo quan điểm của chủ nghĩa Mác - Lênin, quân đội ra đời vào thời kỳ nào:","choices":[{"letter":"A","text":"Thời kỳ công xã nguyên thủy"},{"letter":"B","text":"Thời kỳ tư bản chủ nghĩa"},{"letter":"C","text":"Thời kỳ phong kiến"},{"letter":"D","text":"Thời kỳ chiếm hữu nô lệ"}],"correct_letter":"D"},{"id":"mac-lenin-q47","number":21,"source_number":47,"text":"Chọn phương án sai: Quân đội mất đi khi nào?","choices":[{"letter":"A","text":"Khi không còn giai cấp và đối kháng giai cấp"},{"letter":"B","text":"Khi tồn tại nhà nước xã hội chủ nghĩa"},{"letter":"C","text":"Khi nhà nước bị tiêu vong"},{"letter":"D","text":"Trong chủ nghĩa cộng sản"}],"correct_letter":"B"},{"id":"mac-lenin-q121","number":22,"source_number":121,"text":"Trong nghệ thuật kết hợp đấu tranh giữa các mặt trận thì chính trị được xác định:","choices":[{"letter":"A","text":"Là mặt trận quyết định thắng lợi trực tiếp của chiến tranh"},{"letter":"B","text":"Là mặt trận chủ yếu để phân hóa, cô lập kẻ thù"},{"letter":"C","text":"Là mặt trận quan trọng nhất, chủ yếu nhất"},{"letter":"D","text":"Là cơ sở để tạo ra sức mạnh về quân sự"}],"correct_letter":"D"},{"id":"mac-lenin-q7","number":23,"source_number":7,"text":"Trong quan niệm của C.Ph.Claudovít, đặc trưng cơ bản của chiến tranh là gì?","choices":[{"letter":"A","text":"Xung đột vũ trang"},{"letter":"B","text":"Đấu tranh vũ trang"},{"letter":"C","text":"Sử dụng bạo lực"},{"letter":"D","text":"Sử dụng vũ trang"}],"correct_letter":"C"},{"id":"mac-lenin-q81","number":24,"source_number":81,"text":"Cơ sở C.Mác và Ph.Ăngghen đưa ra quan niệm chiến tranh và quân đội:","choices":[{"letter":"A","text":"Góc độ triết học - xã hội học"},{"letter":"B","text":"Góc độ triết học - tâm lý học"},{"letter":"C","text":"Góc độ chính trị - xã hội học"},{"letter":"D","text":"Góc độ triết học - chính trị học"}],"correct_letter":"A"},{"id":"mac-lenin-q13","number":25,"source_number":13,"text":"Đâu là tiêu chuẩn quan trọng nhất để đánh giá tính chất chính trị - xã hội của chiến tranh:","choices":[{"letter":"A","text":"Tiêu chuẩn chính trị"},{"letter":"B","text":"Tiêu chuẩn kinh tế"},{"letter":"C","text":"Tiêu chuẩn đạo đức"},{"letter":"D","text":"Tiêu chuẩn luật pháp"}],"correct_letter":"A"},{"id":"mac-lenin-q88","number":26,"source_number":88,"text":"Hoàn thiện câu nói của V.I.Lênin: “Chiến tranh chẳng qua chỉ là………từ đầu đến cuối”","choices":[{"letter":"A","text":"Bạo lực"},{"letter":"B","text":"Phương thức tác chiến"},{"letter":"C","text":"Kinh tế"},{"letter":"D","text":"Chính trị"}],"correct_letter":"D"},{"id":"mac-lenin-q112","number":27,"source_number":112,"text":"Chọn phương án đúng về đối tác của Việt Nam hiện nay:","choices":[{"letter":"A","text":"Những tổ chức, cá nhân tôn trọng giúp đỡ Việt Nam."},{"letter":"B","text":"Những nước xã hội chủ nghĩa và các nước đang phát triển giúp đỡ Việt Nam"},{"letter":"C","text":"Những ai tôn trọng độc lập, chủ quyền và hợp tác bình đẳng cùng có lợi với Việt Nam"},{"letter":"D","text":"Những quốc gia, vùng lãnh thổ, tổ chức phi chính phủ tạo điều kiện thuận lợi cho Việt Nam"}],"correct_letter":"C"},{"id":"mac-lenin-q31","number":28,"source_number":31,"text":"Biểu hiện của tiềm lực chính trị, tinh thần là gì?","choices":[{"letter":"A","text":"Khả năng huy động kinh tế của đất nước"},{"letter":"B","text":"Ý chí, quyết tâm của nhân dân, của các lực lượng vũ trang nhân dân."},{"letter":"C","text":"Khả năng bảo đảm vũ khí trang bị cho quân đội"},{"letter":"D","text":"Là tính chất đồng thuận hay không đồng thuận của cơ cấu giai cấp - xã hội"}],"correct_letter":"B"},{"id":"mac-lenin-q95","number":29,"source_number":95,"text":"Một trong những tính chất của chiến tranh Nhân dân bảo vệ Tổ quốc Việt Nam xã hội chủ nghĩa:","choices":[{"letter":"A","text":"Là cuộc chiến tranh toàn diện lấy quân sự là quyết định"},{"letter":"B","text":"Là cuộc chiến tranh toàn dân, lấy lực lượng vũ trang làm nòng cốt"},{"letter":"C","text":"Là cuộc chiến tranh cách mạng chống các thế lực phản cách mạng"},{"letter":"D","text":"Là cuộc chiến tranh toàn dân, toàn diện, lấy lực lượng vũ trang làm nòng cốt"}],"correct_letter":"D"},{"id":"mac-lenin-q101","number":30,"source_number":101,"text":"Quan điểm nào cho rằng quân đội tồn tại vĩnh viễn:","choices":[{"letter":"A","text":"Quan điểm vô sản"},{"letter":"B","text":"Quan điểm tư sản"},{"letter":"C","text":"Quan điểm tôn giáo"},{"letter":"D","text":"Quan điểm chủ nghĩa Mác - Lênin"}],"correct_letter":"B"}]},{"number":7,"title":"Đề 7","questions":[{"id":"mac-lenin-q3","number":1,"source_number":3,"text":"Theo quan điểm của chủ nghĩa Mác - Lênin, luận điểm nào sau đây là sai:","choices":[{"letter":"A","text":"Chiến tranh không thể làm thay đổi tương quan so sánh lực lượng chính trị"},{"letter":"B","text":"Chiến tranh có thể khẳng định hoặc phủ định một đường lối chính trị"},{"letter":"C","text":"Chính trị quyết định bản chất và tính chất chính trị xã hội của chiến tranh"},{"letter":"D","text":"Chiến tranh có thể thúc đẩy hoặc kìm hãm tiến trình thực hiện mục đích chính trị."}],"correct_letter":"A"},{"id":"mac-lenin-q77","number":2,"source_number":77,"text":"Hạn chế của C.Ph.Claudovít trong quan niệm về chính trị, trong mối quan hệ giữa chiến tranh và chính trị là gì?","choices":[{"letter":"A","text":"Chính trị quan hệ chặt chẽ với kinh tế"},{"letter":"B","text":"Chính trị là đường lối đối ngoại, tách rời với kinh tế"},{"letter":"C","text":"Chính trị là đường lối đối nội, quan hệ với kinh tế"},{"letter":"D","text":"Chính trị là đường lối đối nội và đối ngoại"}],"correct_letter":"B"},{"id":"mac-lenin-q69","number":3,"source_number":69,"text":"Chọn phương án đúng về chiến tranh:","choices":[{"letter":"A","text":"Chiến tranh có ngay từ khi xuất hiện loài người"},{"letter":"B","text":"Chiến tranh là hiện tượng xã hội tự nhiên ngoài ý muốn của con người"},{"letter":"C","text":"Chiến tranh là quy luật khách quan của xã hội loài người"},{"letter":"D","text":"Chiến tranh là hiện tượng mang tính lịch sử - xã hội của loài người"}],"correct_letter":"D"},{"id":"mac-lenin-q29","number":4,"source_number":29,"text":"Đâu không phải là kiểu quân đội của nhà nước bóc lột:","choices":[{"letter":"A","text":"Quân đội của phong kiến"},{"letter":"B","text":"Quân đội tư sản"},{"letter":"C","text":"Quân đội xã hội chủ nghĩa"},{"letter":"D","text":"Quân đội của nhà nước chiếm hữu nô lệ"}],"correct_letter":"C"},{"id":"mac-lenin-q38","number":5,"source_number":38,"text":"Khi Mỹ xâm lược Việt Nam, Đảng ta nhận định:","choices":[{"letter":"A","text":"Mỹ giàu nhưng không mạnh"},{"letter":"B","text":"Mỹ giàu và mạnh"},{"letter":"C","text":"Mỹ rất giàu và rất mạnh"},{"letter":"D","text":"Mỹ là nước giàu nhưng không thực sự mạnh"}],"correct_letter":"A"},{"id":"mac-lenin-q138","number":6,"source_number":138,"text":"Đâu là một trong những âm mưu, thủ đoạn của kẻ thù khi xâm lược nước ta:","choices":[{"letter":"A","text":"Gây bạo loạn với quy mô lớn, kết hợp tiến công quân sự từ bên ngoài"},{"letter":"B","text":"Kết hợp tiến công quân sự từ bên ngoài với bạo loạn lật đổ từ bên trong"},{"letter":"C","text":"Tiến công quân sự với quân số đông, kết hợp bạo loạn lật đổ từ bên trong"},{"letter":"D","text":"Tiến công hỏa lực với mức độ cao, kết hợp tiến công quân sự từ bên ngoài"}],"correct_letter":"B"},{"id":"mac-lenin-q118","number":7,"source_number":118,"text":"Yếu tố nào biểu hiện tập trung, trực tiếp của sức mạnh quân sự quốc gia:","choices":[{"letter":"A","text":"Tiềm lực kinh tế"},{"letter":"B","text":"Tiềm lực tinh thần"},{"letter":"C","text":"Tiềm lực xã hội"},{"letter":"D","text":"Tiềm lực quân sự"}],"correct_letter":"D"},{"id":"mac-lenin-q48","number":8,"source_number":48,"text":"Bản chất giai cấp của quân đội nào không phải là kiểu quân đội của nhà nước bóc lột?","choices":[{"letter":"A","text":"Bản chất giai cấp địa chủ, phong kiến của quân đội"},{"letter":"B","text":"Bản chất giai cấp chủ nô của quân đội"},{"letter":"C","text":"Bản chất giai cấp vô sản của quân đội"},{"letter":"D","text":"Bản chất giai cấp tư sản của quân đội"}],"correct_letter":"C"},{"id":"mac-lenin-q124","number":9,"source_number":124,"text":"Kết hợp xây dựng kinh tế với quốc phòng thể hiện chức năng nào của quân đội ta:","choices":[{"letter":"A","text":"Chức năng huấn luyện"},{"letter":"B","text":"Chức năng công tác"},{"letter":"C","text":"Chức năng sản xuất"},{"letter":"D","text":"Chức năng chiến đấu"}],"correct_letter":"C"},{"id":"mac-lenin-q20","number":10,"source_number":20,"text":"Chọn phương án đúng theo quan điểm của chủ nghĩa Mác - Lênin về quân đội:","choices":[{"letter":"A","text":"Quân đội là hiện tượng xã hội vĩnh viễn"},{"letter":"B","text":"Quân đội là hiện tượng chính trị - xã hội có tính lịch sử"},{"letter":"C","text":"Quân đội tự ra đời ngẫu nhiên của đời sống xã hội"},{"letter":"D","text":"Quân đội ra đời do ý chí của thần linh tối cao"}],"correct_letter":"B"},{"id":"mac-lenin-q25","number":11,"source_number":25,"text":"Dấu hiệu đặc thù phân biệt quân đội với các tổ chức xã hội khác:","choices":[{"letter":"A","text":"Được vũ trang, sử dụng vũ khí chuyên dùng và tiến hành chiến tranh"},{"letter":"B","text":"Được nhà nước nuôi dưỡng để bảo vệ lợi ích giai cấp thống trị"},{"letter":"C","text":"Được vũ trang để bảo vệ lợi ích giai cấp thống trị"},{"letter":"D","text":"Nhằm mục đích bảo vệ nhà nước, giai cấp sinh ra nó"}],"correct_letter":"A"},{"id":"mac-lenin-q16","number":12,"source_number":16,"text":"Tiêu chuẩn nào không đánh giá tính chất xã hội của chiến tranh:","choices":[{"letter":"A","text":"Tiêu chuẩn về mặt chính trị"},{"letter":"B","text":"Tiêu chuẩn về mặt pháp luật"},{"letter":"C","text":"Tiêu chuẩn về mặt đạo đức"},{"letter":"D","text":"Tiêu chuẩn về mặt truyền thống"}],"correct_letter":"D"},{"id":"mac-lenin-q67","number":13,"source_number":67,"text":"Chọn phương án đúng theo quan điểm của chủ nghĩa Mác - Lênin:","choices":[{"letter":"A","text":"Chiến tranh là những cuộc xung đột tự phát ngẫu nhiên"},{"letter":"B","text":"Chiến tranh là mối quan hệ giữa người với người để tranh giành lợi ích"},{"letter":"C","text":"Chiến tranh là hiện tượng chính trị - xã hội, kết quả của những quan hệ giữa người với người trong xã hội"},{"letter":"D","text":"Chiến tranh là những xung đột do mâu thuẫn không mang tính xã hội"}],"correct_letter":"C"},{"id":"mac-lenin-q32","number":14,"source_number":32,"text":"Trong 4 mặt trận sau, mặt trận nào có ý nghĩa quyết định trực tiếp trong chiến tranh:","choices":[{"letter":"A","text":"Mặt trận ngoại giao"},{"letter":"B","text":"Mặt trận chính trị"},{"letter":"C","text":"Mặt trận kinh tế"},{"letter":"D","text":"Mặt trận quân sự"}],"correct_letter":"D"},{"id":"mac-lenin-q60","number":15,"source_number":60,"text":"Tham gia xây dựng chính quyền cơ sở thể hiện chức năng nào của quân đội ta:","choices":[{"letter":"A","text":"Chức năng sản xuất"},{"letter":"B","text":"Chức năng công tác"},{"letter":"C","text":"Chức năng chiến đấu"},{"letter":"D","text":"Chức năng huấn luyện II. GÓI CÂU HỎI TRẮC NGHIỆM"}],"correct_letter":"B"},{"id":"mac-lenin-q9","number":16,"source_number":9,"text":"Tính chất xã hội của chiến tranh phụ thuộc chính vào:","choices":[{"letter":"A","text":"Mục đích chính trị của cuộc chiến"},{"letter":"B","text":"Trình độ tác chiến của cuộc chiến"},{"letter":"C","text":"Trình độ vũ khí của cuộc chiến"},{"letter":"D","text":"Trình độ nghệ thuật quân sự cuộc chiến"}],"correct_letter":"A"},{"id":"mac-lenin-q117","number":17,"source_number":117,"text":"Đấu tranh chống tham nhũng, tiêu cực của Đảng ta hiện nay là xây dựng tiềm lực nào là chủ yếu trong sức mạnh quân sự quốc gia:","choices":[{"letter":"A","text":"Tiềm lực quân sự"},{"letter":"B","text":"Tiềm lực kinh tế"},{"letter":"C","text":"Tiềm lực xã hội"},{"letter":"D","text":"Tiềm lực tinh thần"}],"correct_letter":"D"},{"id":"mac-lenin-q11","number":18,"source_number":11,"text":"Chọn phương án đúng về mối quan hệ giữa chiến tranh và chính trị:","choices":[{"letter":"A","text":"Chiến tranh quyết định thắng lợi chính trị"},{"letter":"B","text":"Chính trị hỗ trợ chiến tranh"},{"letter":"C","text":"Chính trị quyết định chiến tranh"},{"letter":"D","text":"Chiến tranh hỗ trợ chính trị"}],"correct_letter":"C"},{"id":"mac-lenin-q107","number":19,"source_number":107,"text":"Theo quan điểm của chủ nghĩa Mác – Lênin, đâu không phải là quy luật vận động, phát triển của quân đội:","choices":[{"letter":"A","text":"Quy luật vận động, phát triển của quân đội phụ thuộc vào những điều kiện kinh tế - xã hội"},{"letter":"B","text":"Quy luật vận động, phát triển của quân đội phụ thuộc vào số, chất lượng binh sĩ và cơ cấu tổ chức biên chế"},{"letter":"C","text":"Quy luật vận động, phát triển của quân đội phụ thuộc vào chế độ chính trị - xã hội và vào tính chất giai cấp của nhà nước tổ chức ra nó"},{"letter":"D","text":"Quy luật vận động, phát triển của quân đội phụ thuộc vào sức mạnh tinh thần và hệ tư tưởng của xã hội"}],"correct_letter":"B"},{"id":"mac-lenin-q140","number":20,"source_number":140,"text":"Những câu trích dưới đây, câu nào không thể hiện tinh thần chiến tranh nhân dân:","choices":[{"letter":"A","text":"“Nhằm thẳng quân thù mà bắn, máy bay Mỹ không có gì đáng sợ”"},{"letter":"B","text":"“31 triệu dân tất cả hành quân, tất cả thành chiến sĩ…”"},{"letter":"C","text":"“Giặc đến nhà đàn bà cũng đánh”"},{"letter":"D","text":"“Hễ là người Việt Nam thì phải cầm vũ khí đứng lên chống thực dân Pháp cứu Tổ quốc”"}],"correct_letter":"A"},{"id":"mac-lenin-q61","number":21,"source_number":61,"text":"Điểm khác biệt chủ yếu giữa chiến tranh chống Pháp, chống Mỹ với các cuộc chiến tranh dựng nước và giữ nước trong lịch sử dân tộc ta là gì?","choices":[{"letter":"A","text":"Giai cấp lãnh đạo"},{"letter":"B","text":"Mục đích chính trị"},{"letter":"C","text":"Phương tiện chiến tranh"},{"letter":"D","text":"Lực lượng tham gia"}],"correct_letter":"A"},{"id":"mac-lenin-q94","number":22,"source_number":94,"text":"Cuộc chiến tranh nào sau đây được coi là phi nghĩa:","choices":[{"letter":"A","text":"Chiến tranh bảo vệ chủ quyền quốc gia của các nước tư bản chống chiến tranh xâm lược của các nước đế quốc"},{"letter":"B","text":"Chiến tranh giải phóng dân tộc"},{"letter":"C","text":"Chiến tranh của các nước đế quốc chống các nước xã hội chủ nghĩa"},{"letter":"D","text":"Chiến tranh bảo vệ Tổ quốc"}],"correct_letter":"C"},{"id":"mac-lenin-q65","number":23,"source_number":65,"text":"Chọn phương án sai về quy luật tiến trình và kết cục chiến tranh:","choices":[{"letter":"A","text":"Tiến trình và kết cục của chiến tranh phụ thuộc vào so sánh lực lượng xã hội của các bên tham chiến."},{"letter":"B","text":"Tiến trình và kết cục của chiến tranh phụ thuộc vào mục đích chính trị giữa các bên tham chiến."},{"letter":"C","text":"Tiến trình và kết cục của chiến tranh phụ thuộc vào so sánh lực lượng kinh tế của các bên tham chiến."},{"letter":"D","text":"Tiến trình và kết cục của chiến tranh phụ thuộc vào tổ chức trận địa của các bên tham chiến."}],"correct_letter":"D"},{"id":"mac-lenin-q33","number":24,"source_number":33,"text":"Theo quan điểm của Đảng ta, yếu tố quyết định thắng lợi trên chiến trường là:","choices":[{"letter":"A","text":"Vũ khí hiện đại, nghệ thuật tác chiến cao"},{"letter":"B","text":"Con người và vũ khí, con người là quyết định"},{"letter":"C","text":"Vũ khí trang bị kỹ thuật hiện đại"},{"letter":"D","text":"Vũ khí hiện đại và người chỉ huy giỏi"}],"correct_letter":"B"},{"id":"mac-lenin-q133","number":25,"source_number":133,"text":"Một trong những đặc trưng của nền quốc phòng toàn dân là:","choices":[{"letter":"A","text":"Vì dân, của dân và do toàn thể nhân dân tiến hành"},{"letter":"B","text":"Nền quốc phòng bảo vệ quyền lợi của dân"},{"letter":"C","text":"Do nhân dân xây dựng, mang tính nhân dân sâu sắc"},{"letter":"D","text":"Nền quốc phòng mang tính giai cấp, nhân dân sâu sắc"}],"correct_letter":"A"},{"id":"mac-lenin-q76","number":26,"source_number":76,"text":"Lựa chọn phương án sai:","choices":[{"letter":"A","text":"Học thuyết Mác - Lênin về chiến tranh và quân đội nghiên cứu bản chất những quy luật cơ bản, chung nhất về sức mạnh quân sự quốc gia"},{"letter":"B","text":"Học thuyết Mác - Lênin về chiến tranh và quân đội nghiên cứu những quy luật cơ bản, chung nhất của hiện tượng đấu tranh vũ trang trong đời sống xã hội"},{"letter":"C","text":"Học thuyết Mác - Lênin về chiến tranh và quân đội nghiên cứu những quy luật cơ bản, chung nhất của hiện tượng chiến tranh trong đời sống xã hội"},{"letter":"D","text":"Học thuyết Mác - Lênin về chiến tranh và quân đội nghiên cứu những quy luật cơ bản, chung nhất của hiện tượng quân đội"}],"correct_letter":"B"},{"id":"mac-lenin-q30","number":27,"source_number":30,"text":"Đâu là mục tiêu phát triển trong Văn kiện Đại hội XIV của Đảng ta:","choices":[{"letter":"A","text":"Xây dựng phát triển kinh tế và quốc phòng; xây dựng chủ nghĩa xã hội va bảo vệ Tổ quốc xã hội chủ nghĩa…"},{"letter":"B","text":"Xây dựng đất nước và bảo vệ Tổ quốc; xây dựng phát triển kinh tế và quốc phòng - an ninh nhân dân…"},{"letter":"C","text":"Giữ vững môi trường hoà bình, ổn định; phát triển nhanh, bền vững đất nước và bảo vệ vững chắc Tổ quốc…"},{"letter":"D","text":"Xây dựng phát triển kinh tế và quốc phòng - an ninh nhân dân; phát triển nhanh, bền vững đất nước và bảo vệ vững chắc Tổ quốc…"}],"correct_letter":"C"},{"id":"mac-lenin-q37","number":28,"source_number":37,"text":"Đối tượng của chiến tranh nhân dân bảo vệ Tổ quốc Việt Nam xã hội chủ nghĩa là:","choices":[{"letter":"A","text":"Chủ nghĩa khủng bố quốc tế"},{"letter":"B","text":"Chủ nghĩa đế quốc và chủ nghĩa ly khai"},{"letter":"C","text":"Các thế lực phản cách mạng trong và ngoài nước"},{"letter":"D","text":"Chủ nghĩa đế quốc và các thế lực phản động"}],"correct_letter":"D"},{"id":"mac-lenin-q2","number":29,"source_number":2,"text":"Theo V.I.Lênin, đánh giá tính chất chính trị - xã hội của chiến tranh phải đứng vững trên lập trường:","choices":[{"letter":"A","text":"Giai cấp nông dân"},{"letter":"B","text":"Tầng lớp trí thức"},{"letter":"C","text":"Giai cấp vô sản"},{"letter":"D","text":"Giai cấp tư sản"}],"correct_letter":"C"},{"id":"mac-lenin-q104","number":30,"source_number":104,"text":"Chức năng của quân đội:","choices":[{"letter":"A","text":"Là lực lượng lao động và bảo vệ chủ yếu của toàn xã hội"},{"letter":"B","text":"Là phương tiện quân sự để đạt mục tiêu chính trị"},{"letter":"C","text":"Là lao động sản xuất tạo ra của cải cho xã hội"},{"letter":"D","text":"Là công cụ bạo lực chủ yếu của giai cấp thống trị và nhà nước"}],"correct_letter":"D"}]}],"ho-chi-minh":[{"number":1,"title":"Đề 1","questions":[{"id":"ho-chi-minh-q16","number":1,"source_number":16,"text":"Chọn phương án đúng về nhân tố cơ bản quyết định sức mạnh của nền quốc phòng toàn dân theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Sức mạnh chính trị, tư tưởng."},{"letter":"B","text":"Sức mạnh văn hóa, khoa học kỹ thuật."},{"letter":"C","text":"Sức mạnh quân sự, vũ trang."},{"letter":"D","text":"Sức mạnh kinh tế, vật chất."}],"correct_letter":"A"},{"id":"ho-chi-minh-q4","number":2,"source_number":4,"text":"Nội dung phát huy sức mạnh của quần chúng nhân dân trong tư tưởng Hồ Chí Minh về bạo lực cách mạng?","choices":[{"letter":"A","text":"Xây dựng lực lượng vũ trang ba thứ quân vững mạnh làm nòng cốt."},{"letter":"B","text":"Kết hợp sức mạnh dân tộc với sức mạnh thời đại trong mọi hoàn cảnh."},{"letter":"C","text":"Xây dựng khối đại đoàn kết toàn dân, lấy liên minh công - nông làm nền tảng."},{"letter":"D","text":"Tiến hành đấu tranh chính trị là chủ yếu, đấu tranh quân sự là hỗ trợ."}],"correct_letter":"C"},{"id":"ho-chi-minh-q32","number":3,"source_number":32,"text":"Chọn phương án đúng về xây dựng Quân đội nhân dân Việt Nam hiện nay khi vận dụng tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Nâng cao chất lượng huấn luyện, sẵn sàng chiến đấu và khả năng hiệp đồng tác chiến."},{"letter":"B","text":"Chăm lo đời sống vật chất, tinh thần cho bộ đội và thực hiện tốt chính sách hậu phương."},{"letter":"C","text":"Xây dựng quân đội tinh, gọn, mạnh, từng bước tiến lên hiện đại về kỹ thuật, trang bị."},{"letter":"D","text":"Giữ vững bản chất giai cấp công nhân, tính nhân dân, tính dân tộc; xây dựng quân đội vững mạnh toàn diện, lấy chính trị làm cơ sở."}],"correct_letter":"D"},{"id":"ho-chi-minh-q81","number":4,"source_number":81,"text":"Theo tư tưởng Hồ Chí Minh, muốn đánh thắng được kẻ thù xâm lược thì trước hết ta phải làm gì?","choices":[{"letter":"A","text":"Tăng cường ký kết các hiệp ước an ninh đa phương"},{"letter":"B","text":"Xây dựng và phát triển thực lực cách mạng vững mạnh"},{"letter":"C","text":"Thu hẹp thế trận chiến tranh trên các địa bàn hiểm trở"},{"letter":"D","text":"Đợi chờ sự viện trợ toàn diện từ các nước lớn"}],"correct_letter":"B"},{"id":"ho-chi-minh-q9","number":5,"source_number":9,"text":"Chọn phương án đúng về nâng cao nhận thức xây dựng nền quốc phòng toàn dân theo tư tưởng Hồ Chí Minh hiện nay:","choices":[{"letter":"A","text":"Chỉ tiến hành bảo vệ Tổ quốc khi chiến tranh đã nổ ra, ưu tiên giải quyết tranh chấp bằng quân sự."},{"letter":"B","text":"Dựa vào đồng minh quân sự bên ngoài, giảm bớt vai trò của nền quốc phòng toàn dân."},{"letter":"C","text":"Kiên quyết, kiên trì bảo vệ Tổ quốc từ sớm, từ xa, giải quyết bất đồng bằng biện pháp hòa bình."},{"letter":"D","text":"Coi bảo vệ Tổ quốc là nhiệm vụ nhất thời của lực lượng vũ trang, tách rời phát triển kinh tế."}],"correct_letter":"C"},{"id":"ho-chi-minh-q11","number":6,"source_number":11,"text":"Tư tưởng Hồ Chí Minh về bạo lực cách mạng đối lập với tư tưởng nào sau đây?","choices":[{"letter":"A","text":"Tư tưởng đánh nhanh thắng nhanh và tư tưởng chiến tranh trường kỳ."},{"letter":"B","text":"Tư tưởng bất bạo động và tư tưởng bạo động, khủng bố, ám sát manh động."},{"letter":"C","text":"Tư tưởng tiến công chiến lược và tư tưởng phòng ngự chiến lược."},{"letter":"D","text":"Tư tưởng quân sự chuyên nghiệp và tư tưởng chiến tranh toàn dân."}],"correct_letter":"B"},{"id":"ho-chi-minh-q90","number":7,"source_number":90,"text":"Theo Hồ Chí Minh, nhân tố quyết định bản chất giai cấp công nhân và sức mạnh chiến đấu của Quân đội ta là gì?","choices":[{"letter":"A","text":"Số lượng và trình độ kỹ thuật của các loại vũ khí hiện đại"},{"letter":"B","text":"Nguồn lực viện trợ vũ khí, trang bị từ các nước đồng minh"},{"letter":"C","text":"Quy mô quân số và cơ cấu tổ chức các quân binh chủng"},{"letter":"D","text":"Sự lãnh đạo tuyệt đối, trực tiếp về mọi mặt của Đảng Cộng sản Việt Nam"}],"correct_letter":"D"},{"id":"ho-chi-minh-q109","number":8,"source_number":109,"text":"Chọn phương án đúng về cấu trúc lực lượng vũ trang theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Ba thứ quân: bộ đội chủ lực, bộ đội địa phương và dân quân tự vệ"},{"letter":"B","text":"Lục quân, Hải quân, Phòng không - Không quân"},{"letter":"C","text":"Quân đội thường trực chính quy và quân nhân xuất ngũ dự bị"},{"letter":"D","text":"Lực lượng chiến đấu cơ động và lực lượng cảnh giới biên phòng"}],"correct_letter":"A"},{"id":"ho-chi-minh-q69","number":9,"source_number":69,"text":"Tư tưởng Hồ Chí Minh về bạo lực cách mạng lần đầu tiên được khẳng định trong văn kiện nào sau đây?","choices":[{"letter":"A","text":"Luận cương chính trị của Đảng (10/1930)"},{"letter":"B","text":"Chính cương ngắn tắt của Đảng (2/1930)"},{"letter":"C","text":"Nghị quyết Hội nghị Ban Chấp hành Trung ương 8 (5/1941)"},{"letter":"D","text":"Tuyên ngôn của Hội Liên hiệp thuộc địa (1921)"}],"correct_letter":"B"},{"id":"ho-chi-minh-q42","number":10,"source_number":42,"text":"Theo Hồ Chí Minh, xây dựng hậu phương chiến tranh phải gắn với nội dung nào?","choices":[{"letter":"A","text":"Phải gắn xây dựng với bảo vệ và phát triển hậu phương."},{"letter":"B","text":"Phải gắn với phát triển văn hóa, giáo dục toàn dân."},{"letter":"C","text":"Phải gắn với tăng cường tiềm lực kinh tế của đất nước."},{"letter":"D","text":"Phải gắn với xây dựng lực lượng chính trị của quần chúng."}],"correct_letter":"A"},{"id":"ho-chi-minh-q106","number":11,"source_number":106,"text":"Theo tư tưởng Hồ Chí Minh, sức mạnh chính trị - tư tưởng giữ vai trò như thế nào đối với nền quốc phòng toàn dân?","choices":[{"letter":"A","text":"Là nền tảng vật chất"},{"letter":"B","text":"Là yếu tố trực tiếp quyết định"},{"letter":"C","text":"Là thành tố quan trọng"},{"letter":"D","text":"Là nhân tố cơ bản quyết định"}],"correct_letter":"D"},{"id":"ho-chi-minh-q124","number":12,"source_number":124,"text":"Biểu hiện sức mạnh kinh tế của nền quốc phòng toàn dân theo quan điểm Hồ Chí Minh là gì?","choices":[{"letter":"A","text":"Việc chuyển đổi toàn bộ cơ sở hạ tầng dân sự sang công trình quốc phòng"},{"letter":"B","text":"Khối lượng hàng hóa nhập khẩu từ các thị trường quốc tế vào nội địa"},{"letter":"C","text":"Khả năng phát triển kinh tế gắn với huy động nhân lực, vật lực phục vụ bảo vệ Tổ quốc"},{"letter":"D","text":"Duy trì ngân sách chi tiêu quân sự cao hơn tổng mức đầu tư xã hội"}],"correct_letter":"C"},{"id":"ho-chi-minh-q57","number":13,"source_number":57,"text":"Theo Hồ Chí Minh, xây dựng đội ngũ cán bộ quân đội có đức và tài giữ vị trí như thế nào?","choices":[{"letter":"A","text":"Là nhiệm vụ thường xuyên của công tác cán bộ trong quân đội."},{"letter":"B","text":"Là yêu cầu cơ bản của việc xây dựng quân đội chính quy."},{"letter":"C","text":"Là khâu then chốt trong xây dựng quân đội vững mạnh về chính trị."},{"letter":"D","text":"Là nội dung quan trọng của việc xây dựng quân đội hiện đại."}],"correct_letter":"C"},{"id":"ho-chi-minh-q49","number":14,"source_number":49,"text":"Theo Hồ Chí Minh, vị trí của hậu phương chiến tranh được xác định như thế nào?","choices":[{"letter":"A","text":"Là nơi xây dựng căn cứ địa và dự trữ chiến lược cho kháng chiến."},{"letter":"B","text":"Là nhân tố hết sức quan trọng, quyết định thắng lợi của cách mạng."},{"letter":"C","text":"Là địa bàn đứng chân và triển khai của các lực lượng vũ trang."},{"letter":"D","text":"Là nơi cung cấp sức người, sức của cho tiền tuyến trong chiến tranh."}],"correct_letter":"B"},{"id":"ho-chi-minh-q85","number":15,"source_number":85,"text":"Theo Hồ Chí Minh, biện pháp phát huy tiềm năng to lớn của nhân dân trong lĩnh vực quân sự là gì?","choices":[{"letter":"A","text":"Mở rộng hoạt động tình báo quân sự trong dân gian"},{"letter":"B","text":"Đẩy mạnh ký kết các hiệp ước an ninh quốc tế"},{"letter":"C","text":"Phổ biến kinh nghiệm quân sự của các nước phương Tây"},{"letter":"D","text":"Truyền bá hệ tư tưởng và lý luận cách mạng vào phong trào yêu nước"}],"correct_letter":"D"},{"id":"ho-chi-minh-q34","number":16,"source_number":34,"text":"Chọn phương án đúng về tư tưởng xuyên suốt trong chỉ đạo chiến lược trong nghệ thuật quân sự của Hồ Chí Minh:","choices":[{"letter":"A","text":"Nắm vững tư tưởng chiến lược tiến công, giành và giữ quyền chủ động."},{"letter":"B","text":"Lấy tác chiến chiến dịch làm phương thức chủ yếu để kết thúc chiến tranh."},{"letter":"C","text":"Giữ thế phòng ngự chiến lược là chủ yếu, chỉ tiến công khi đủ điều kiện."},{"letter":"D","text":"Đánh nhanh thắng nhanh trong mọi điều kiện, hoàn cảnh của chiến tranh."}],"correct_letter":"A"},{"id":"ho-chi-minh-q105","number":17,"source_number":105,"text":"Chọn phương án đúng về nội dung cốt lõi trong xây dựng hậu phương vững mạnh về quân sự theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Tách biệt lực lượng dân quân khỏi đời sống sản xuất"},{"letter":"B","text":"Xây dựng lực lượng vũ trang ba thứ quân vững mạnh"},{"letter":"C","text":"Tập trung toàn bộ vũ khí cho lực lượng thường trực"},{"letter":"D","text":"Thành lập các đơn vị quân đội chuyên nghiệp độc lập"}],"correct_letter":"B"},{"id":"ho-chi-minh-q66","number":18,"source_number":66,"text":"Để tránh đối đầu cùng lúc với nhiều kẻ thù nguy hiểm sau Cách mạng Tháng Tám năm 1945, Hồ Chí Minh đã chủ trương thực hiện nguyên tắc nào?","choices":[{"letter":"A","text":"Nhượng bộ toàn bộ yêu sách kinh tế của quân đội Tưởng Giới Thạch"},{"letter":"B","text":"Chờ đợi sự can thiệp từ các nước đồng minh lớn trên thế giới"},{"letter":"C","text":"Cứng rắn về nguyên tắc, mềm dẻo, linh hoạt về sách lược"},{"letter":"D","text":"Kiên quyết dùng bạo lực vũ trang đánh trả tức thì mọi lực lượng can thiệp"}],"correct_letter":"C"},{"id":"ho-chi-minh-q79","number":19,"source_number":79,"text":"Theo Hồ Chí Minh, nhân tố nào giữ vai trò quan trọng nhất của sức mạnh chính trị - tinh thần trong xây dựng nền quốc phòng toàn dân?","choices":[{"letter":"A","text":"Sự lãnh đạo tuyệt đối, trực tiếp về mọi mặt của Đảng"},{"letter":"B","text":"Khả năng dự trữ ngân sách tài chính của các địa phương"},{"letter":"C","text":"Hệ thống pháp luật và kỷ cương của chính quyền dân sự"},{"letter":"D","text":"Tỷ lệ phát triển kinh tế thương mại hàng năm"}],"correct_letter":"A"},{"id":"ho-chi-minh-q98","number":20,"source_number":98,"text":"Chọn phương án đúng về nhiệm vụ trọng tâm khi vận dụng tư tưởng bạo lực cách mạng Hồ Chí Minh trong bảo vệ Tổ quốc hiện nay:","choices":[{"letter":"A","text":"Tách biệt hoàn toàn công tác quốc phòng khỏi quan hệ đối ngoại và kinh tế"},{"letter":"B","text":"Duy trì thế trận quân sự thường trực sẵn sàng tham chiến ở mọi khu vực biên giới"},{"letter":"C","text":"Tăng cường mua sắm các loại vũ khí hiện đại, giảm huấn luyện chính trị tư tưởng"},{"letter":"D","text":"Kết hợp chặt chẽ giữa phát triển kinh tế - xã hội với củng cố quốc phòng, an ninh"}],"correct_letter":"D"},{"id":"ho-chi-minh-q15","number":21,"source_number":15,"text":"Nội dung nào thể hiện tính chất nhân văn, nhân đạo của bạo lực cách mạng trong tư tưởng Hồ Chí Minh?","choices":[{"letter":"A","text":"Sử dụng bạo lực quyết liệt nhằm nhanh chóng tiêu diệt toàn bộ kẻ thù."},{"letter":"B","text":"Kết hợp chặt chẽ đấu tranh quân sự với đấu tranh chính trị trong mọi giai đoạn."},{"letter":"C","text":"Chiến tranh là giải pháp cuối cùng, luôn tìm cách hạn chế đổ máu."},{"letter":"D","text":"Dựa chắc vào sức mạnh của quần chúng nhân dân để tiến hành chiến tranh."}],"correct_letter":"C"},{"id":"ho-chi-minh-q46","number":22,"source_number":46,"text":"Giá trị lý luận về xây dựng nền quốc phòng toàn dân hiện nay theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Làm phong phú học thuyết quân sự Mác - Lênin; là nền tảng để Đảng hoạch định đường lối quốc phòng."},{"letter":"B","text":"Là sự tổng kết thực tiễn xây dựng quốc phòng trong hai cuộc kháng chiến chống Pháp, chống Mỹ cứu nước."},{"letter":"C","text":"Là sự vận dụng nguyên mẫu lý luận bảo vệ Tổ quốc xã hội chủ nghĩa của các nước anh em."},{"letter":"D","text":"Là sự kế thừa nguyên vẹn truyền thống quân sự dân tộc cùng kinh nghiệm quân sự của thế giới."}],"correct_letter":"A"},{"id":"ho-chi-minh-q53","number":23,"source_number":53,"text":"Lựa chọn phương án đúng về giá trị thực tiễn của tư tưởng phát huy sức mạnh quần chúng nhân dân trong lĩnh vực quân sự:","choices":[{"letter":"A","text":"Chỉ tạo sức mạnh trong giai đoạn đánh thắng hai cuộc kháng chiến và thống nhất đất nước."},{"letter":"B","text":"Chỉ huy động nguồn lực cho chiến tranh, không gắn với xây dựng quốc phòng toàn dân."},{"letter":"C","text":"Chỉ xây dựng thành công lực lượng vũ trang ba thứ quân và bảo vệ miền Bắc."},{"letter":"D","text":"Tạo sức mạnh to lớn trong giành chính quyền, hai cuộc kháng chiến và xây dựng thế trận quốc phòng toàn dân."}],"correct_letter":"D"},{"id":"ho-chi-minh-q38","number":24,"source_number":38,"text":"Cơ sở tư tưởng, lý luận hình thành tư tưởng Hồ Chí Minh về xây dựng hậu phương chiến tranh gồm những nội dung nào?","choices":[{"letter":"A","text":"Tinh hoa quân sự phương Đông và lý luận về chiến tranh nhân dân của Việt Nam."},{"letter":"B","text":"Truyền thống coi trọng xây dựng hậu phương của dân tộc; giá trị tiến bộ về hậu phương trên thế giới; lý luận Mác - Lênin về hậu phương."},{"letter":"C","text":"Truyền thống dựng nước đi đôi với giữ nước và kinh nghiệm xây dựng hậu phương của Liên Xô."},{"letter":"D","text":"Kinh nghiệm kháng chiến chống Pháp, chống Mỹ và quan điểm Mác - Lênin về chiến tranh."}],"correct_letter":"B"},{"id":"ho-chi-minh-q63","number":25,"source_number":63,"text":"Theo tư tưởng Hồ Chí Minh, mối quan hệ hữu cơ giữa tiền tuyến và hậu phương chiến tranh được xác định như thế nào?","choices":[{"letter":"A","text":"Hậu phương luôn đóng vai trò bị động trước mọi yêu cầu tác chiến"},{"letter":"B","text":"Tiền tuyến và hậu phương độc lập tác chiến theo mục tiêu riêng"},{"letter":"C","text":"Tiền tuyến quyết định tuyệt đối, hậu phương chỉ cung cấp sức người"},{"letter":"D","text":"Tiền tuyến và hậu phương gắn bó mật thiết, tác động qua lại lẫn nhau"}],"correct_letter":"D"},{"id":"ho-chi-minh-q135","number":26,"source_number":135,"text":"Sau Cách mạng Tháng Tám năm 1945, Hồ Chí Minh đã phát động phong trào nào để động viên sự ủng hộ tài chính to lớn từ nhân dân?","choices":[{"letter":"A","text":"Tuần lễ vàng"},{"letter":"B","text":"Sóng Duyên hải"},{"letter":"C","text":"Mùa đông binh sĩ"},{"letter":"D","text":"Hũ gạo nuôi quân"}],"correct_letter":"A"},{"id":"ho-chi-minh-q36","number":27,"source_number":36,"text":"Chọn phương án đúng về hai hình thức cơ bản của bạo lực cách mạng theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Đấu tranh quân sự và đấu tranh binh vận."},{"letter":"B","text":"Đấu tranh chính trị và đấu tranh vũ trang."},{"letter":"C","text":"Đấu tranh vũ trang và đấu tranh ngoại giao."},{"letter":"D","text":"Đấu tranh chính trị và đấu tranh tư tưởng."}],"correct_letter":"B"},{"id":"ho-chi-minh-q91","number":28,"source_number":91,"text":"Nội dung cốt lõi của nghệ thuật quân sự phát huy sức mạnh tổng hợp theo Hồ Chí Minh là gì?","choices":[{"letter":"A","text":"Huy động toàn bộ lực lượng công nghiệp nặng phục vụ chế tạo trang bị quân sự"},{"letter":"B","text":"Đẩy mạnh tổng động viên thanh niên nhập ngũ và tập trung mua sắm vũ khí hiện đại"},{"letter":"C","text":"Động viên toàn dân đánh giặc, đánh giặc toàn diện; kết hợp sức mạnh dân tộc với sức mạnh thời đại"},{"letter":"D","text":"Nhất loạt mở các chiến dịch quy mô lớn trên toàn bộ các hướng chiến lược"}],"correct_letter":"C"},{"id":"ho-chi-minh-q123","number":29,"source_number":123,"text":"Yếu tố nào cấu thành sức mạnh vật chất của quần chúng nhân dân trong hoạt động quân sự theo tư tưởng Hồ Chí Minh?","choices":[{"letter":"A","text":"Vũ khí, phương tiện hiện đại mua từ nước ngoài"},{"letter":"B","text":"Kho dự trữ lương thực của lực lượng vũ trang"},{"letter":"C","text":"Nguồn lực con người và của cải vật chất do con người làm ra"},{"letter":"D","text":"Hệ thống phòng thủ công sự và căn cứ địa"}],"correct_letter":"C"},{"id":"ho-chi-minh-q93","number":30,"source_number":93,"text":"Luận điểm: “Toàn thể dân tộc Việt Nam quyết đem tất cả tinh thần và lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập ấy” thể hiện tính chất nào của bạo lực cách mạng?","choices":[{"letter":"A","text":"Tính ưu tiên phương tiện chiến tranh hiện đại"},{"letter":"B","text":"Tính tuyệt đối hóa sức mạnh của lực lượng quân đội"},{"letter":"C","text":"Tính linh hoạt trong giải quyết xung đột ngoại giao"},{"letter":"D","text":"Tính chính nghĩa, tự vệ và mang sức mạnh toàn dân"}],"correct_letter":"D"}]},{"number":2,"title":"Đề 2","questions":[{"id":"ho-chi-minh-q129","number":1,"source_number":129,"text":"Chọn phương án đúng về giải pháp xây dựng nền quốc phòng toàn dân hiện nay khi vận dụng tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Tách rời khu vực phòng thủ địa phương khỏi thế trận quốc phòng chung của cả nước"},{"letter":"B","text":"Kết hợp chặt chẽ, đồng bộ giữa phát triển kinh tế - xã hội với củng cố quốc phòng, an ninh"},{"letter":"C","text":"Tăng tỷ lệ quân số thường trực trong độ tuổi lao động tại các khu công nghiệp"},{"letter":"D","text":"Chuyển đổi toàn diện các tổ chức kinh tế tư nhân sang cơ chế quản lý quân sự"}],"correct_letter":"B"},{"id":"ho-chi-minh-q52","number":2,"source_number":52,"text":"Cơ sở thực tiễn hình thành tư tưởng Hồ Chí Minh về xây dựng hậu phương chiến tranh gồm những yếu tố nào?","choices":[{"letter":"A","text":"Thực tiễn xây dựng hậu phương của Liên Xô và thực tiễn kháng chiến chống Pháp, chống Mỹ ở Việt Nam."},{"letter":"B","text":"Thực tiễn các phong trào yêu nước cuối thế kỷ XIX và Cách mạng Tân Hợi ở Trung Quốc."},{"letter":"C","text":"Thực tiễn chiến tranh giữ nước thời Trần, thời Lê và kinh nghiệm của Trung Quốc."},{"letter":"D","text":"Thực tiễn Cách mạng Tháng Mười Nga và cuộc nội chiến ở nước Nga Xô viết."}],"correct_letter":"A"},{"id":"ho-chi-minh-q117","number":3,"source_number":117,"text":"Chọn phương án đúng về cơ sở lý luận phát huy sức mạnh của quần chúng nhân dân trong quân sự của Hồ Chí Minh:","choices":[{"letter":"A","text":"Tư tưởng thần quyền về định mệnh trong chiến tranh"},{"letter":"B","text":"Quan niệm chiến lược của các học giả quân sự phương Tây thế kỷ XIX"},{"letter":"C","text":"Quan điểm siêu hình về sức mạnh của vũ khí công nghệ cao"},{"letter":"D","text":"Quan điểm của chủ nghĩa Mác - Lênin: Quần chúng nhân dân là người sáng tạo ra lịch sử"}],"correct_letter":"D"},{"id":"ho-chi-minh-q22","number":4,"source_number":22,"text":"Chọn phương án đúng về nội dung phát huy sức mạnh quần chúng nhân dân theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Xây dựng lực lượng vũ trang ba thứ quân và thế trận quốc phòng."},{"letter":"B","text":"Phát triển kinh tế gắn với tăng cường quốc phòng."},{"letter":"C","text":"Nâng cao dân trí và củng cố khối đại đoàn kết toàn dân."},{"letter":"D","text":"Giáo dục lòng yêu nước và xây dựng hậu phương vững mạnh."}],"correct_letter":"C"},{"id":"ho-chi-minh-q10","number":5,"source_number":10,"text":"Chọn phương án đúng về đặc điểm bạo lực cách mạng là bạo lực của quần chúng nhân dân theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Mang tính tự phát, rộng rãi nhưng thiếu sự lãnh đạo thống nhất."},{"letter":"B","text":"Do lực lượng vũ trang chuyên nghiệp tiến hành, tách rời quần chúng."},{"letter":"C","text":"Có tổ chức và được rèn luyện trong đấu tranh cách mạng."},{"letter":"D","text":"Mang tính giai cấp công nhân thuần túy, không bao gồm tầng lớp khác."}],"correct_letter":"C"},{"id":"ho-chi-minh-q77","number":6,"source_number":77,"text":"Chọn phương án đúng về phương thức đánh địch bằng “ba mũi giáp công” theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Quân sự, chính trị, ngoại giao"},{"letter":"B","text":"Quân sự, chính trị, kinh tế"},{"letter":"C","text":"Quân sự, ngoại giao, kinh tế"},{"letter":"D","text":"Quân sự, chính trị, binh vận"}],"correct_letter":"D"},{"id":"ho-chi-minh-q88","number":7,"source_number":88,"text":"Mục đích căn bản, xuyên suốt của nền quốc phòng toàn dân theo tư tưởng Hồ Chí Minh là gì?","choices":[{"letter":"A","text":"Giữ vững hòa bình, tự vệ chính đáng và bảo vệ vững chắc độc lập, chủ quyền của Tổ quốc"},{"letter":"B","text":"Răn đe các quốc gia đối kháng bằng tiềm lực vũ khí công nghệ cao"},{"letter":"C","text":"Tìm kiếm cơ hội mở rộng ảnh hưởng quân sự sang các nước lân cận"},{"letter":"D","text":"Áp đặt vị thế ngoại giao áp đảo trên trường quốc tế"}],"correct_letter":"A"},{"id":"ho-chi-minh-q61","number":8,"source_number":61,"text":"Luận điểm: “Cách mạng là sự nghiệp của quần chúng, kháng chiến toàn diện phải dựa vào sức dân” thể hiện bản chất nào sau đây?","choices":[{"letter":"A","text":"Hậu phương hoàn toàn độc lập với sự chỉ đạo của Đảng"},{"letter":"B","text":"Hậu phương mang tính toàn dân, toàn diện sâu sắc"},{"letter":"C","text":"Hậu phương không chịu tác động từ diễn biến ngoài mặt trận"},{"letter":"D","text":"Hậu phương chỉ phục vụ các nhu cầu vật chất tiền tuyến"}],"correct_letter":"B"},{"id":"ho-chi-minh-q68","number":9,"source_number":68,"text":"Hồ Chí Minh chủ trương xây dựng nền quốc phòng Việt Nam mang tính chất cơ bản nào sau đây?","choices":[{"letter":"A","text":"Dân tộc, khoa học, đại chúng"},{"letter":"B","text":"Liên minh, bảo trợ và vũ trang hiện đại"},{"letter":"C","text":"Tiên tiến, đậm đà bản sắc dân tộc"},{"letter":"D","text":"Toàn dân, toàn diện, độc lập, tự chủ"}],"correct_letter":"D"},{"id":"ho-chi-minh-q33","number":10,"source_number":33,"text":"Quan điểm Hồ Chí Minh về khởi đầu và kết thúc chiến tranh đúng lúc nhằm mục đích gì?","choices":[{"letter":"A","text":"Giành thế chủ động chiến lược, tránh tổn thất không cần thiết."},{"letter":"B","text":"Buộc đối phương phải rút quân ngay lập tức, không điều kiện."},{"letter":"C","text":"Kéo dài chiến tranh nhằm làm kiệt quệ kinh tế của đối phương."},{"letter":"D","text":"Tiêu diệt tối đa sinh lực địch trong thời gian ngắn."}],"correct_letter":"A"},{"id":"ho-chi-minh-q20","number":11,"source_number":20,"text":"Theo Hồ Chí Minh, “thế” được hiểu là gì?","choices":[{"letter":"A","text":"Thời cơ thuận lợi nhất để tiến công tiêu diệt địch."},{"letter":"B","text":"Sức mạnh vật chất, tinh thần của toàn dân tộc trong chiến tranh."},{"letter":"C","text":"Tổng thể hoàn cảnh, điều kiện cùng xu thế vận động, khả năng phát triển của các bên tham chiến."},{"letter":"D","text":"Tài chỉ huy và thao lược của đội ngũ tướng lĩnh."}],"correct_letter":"C"},{"id":"ho-chi-minh-q45","number":12,"source_number":45,"text":"Chọn phương án đúng về giá trị lý luận tư tưởng Hồ Chí Minh về bạo lực cách mạng:","choices":[{"letter":"A","text":"Là sự kế thừa hoàn toàn tư tưởng bạo lực cách mạng của chủ nghĩa Mác - Lênin vào điều kiện Việt Nam."},{"letter":"B","text":"Là bước phát triển mới về chất tư tưởng bạo lực của dân tộc; bổ sung, phát triển học thuyết quân sự Mác - Lênin."},{"letter":"C","text":"Là sự kết hợp giữa truyền thống quân sự phương Đông và phương Tây trong điều kiện Việt Nam."},{"letter":"D","text":"Là sự tổng kết thực tiễn hai cuộc kháng chiến chống Pháp và chống Mỹ cứu nước của dân tộc."}],"correct_letter":"B"},{"id":"ho-chi-minh-q41","number":13,"source_number":41,"text":"Theo Hồ Chí Minh, nhân tố căn bản để kết hợp với nghệ thuật ngoại giao trong đấu tranh ngoại giao là gì?","choices":[{"letter":"A","text":"Thực lực của cách mạng ta."},{"letter":"B","text":"Sự giúp đỡ của các nước lớn."},{"letter":"C","text":"Sự ủng hộ của dư luận quốc tế."},{"letter":"D","text":"Nghệ thuật đàm phán khéo léo."}],"correct_letter":"A"},{"id":"ho-chi-minh-q58","number":14,"source_number":58,"text":"Bản chất giai cấp của Quân đội nhân dân Việt Nam theo tư tưởng Hồ Chí Minh là gì?","choices":[{"letter":"A","text":"Mang bản chất giai cấp công nhân và tính quốc tế vô sản."},{"letter":"B","text":"Mang bản chất giai cấp công nhân và tính hiện đại, tinh nhuệ."},{"letter":"C","text":"Mang bản chất giai cấp công nhân, tính nhân dân và tính dân tộc sâu sắc."},{"letter":"D","text":"Mang tính nhân dân và tính chính quy, không mang bản chất giai cấp."}],"correct_letter":"C"},{"id":"ho-chi-minh-q62","number":15,"source_number":62,"text":"Theo Hồ Chí Minh, cơ sở thực tiễn trực tiếp dẫn đến tất yếu phải dùng bạo lực cách mạng để tự giải phóng là gì?","choices":[{"letter":"A","text":"Kinh nghiệm tiến hành các cuộc chiến tranh giải phóng từ phương Tây"},{"letter":"B","text":"Bản chất hiếu chiến, tàn bạo và việc dùng bạo lực phản cách mạng của kẻ thù"},{"letter":"C","text":"Yêu cầu xây dựng nhanh chóng lực lượng vũ trang cách mạng chính quy"},{"letter":"D","text":"Xu thế chuyển đổi mô hình kinh tế trong thời kỳ mới"}],"correct_letter":"B"},{"id":"ho-chi-minh-q118","number":16,"source_number":118,"text":"Trong công tác hậu cần - kỹ thuật quân đội, Hồ Chí Minh từng căn dặn cán bộ cung cấp phải như là:","choices":[{"letter":"A","text":"Người điều hành tài chính độc lập của đơn vị"},{"letter":"B","text":"Người quản lý kho hàng nghiêm khắc và chặt chẽ"},{"letter":"C","text":"Người giám sát việc tiêu thụ vật chất chiến đấu"},{"letter":"D","text":"Người mẹ, người chị của người binh nhì"}],"correct_letter":"D"},{"id":"ho-chi-minh-q134","number":17,"source_number":134,"text":"Trong Chỉ thị thành lập Đội Việt Nam tuyên truyền giải phóng quân, Hồ Chí Minh đã gọi lực lượng nào là “Đội quân đàn anh”?","choices":[{"letter":"A","text":"Đội du kích Ba Tơ"},{"letter":"B","text":"Bộ đội chủ lực"},{"letter":"C","text":"Lực lượng tự vệ cứu quốc"},{"letter":"D","text":"Bộ đội địa phương"}],"correct_letter":"B"},{"id":"ho-chi-minh-q3","number":18,"source_number":3,"text":"Hồ Chí Minh khẳng định: Độc lập, tự do chỉ có thể giành được bằng phương pháp nào sau đây?","choices":[{"letter":"A","text":"Bằng bạo lực cách mạng của quần chúng nhân dân."},{"letter":"B","text":"Bằng việc xây dựng lực lượng chính trị vững mạnh mà không cần vũ trang."},{"letter":"C","text":"Bằng con đường thương lượng, đàm phán trên cơ sở giữ vững nguyên tắc."},{"letter":"D","text":"Bằng đấu tranh chính trị kết hợp với sự giúp đỡ của lực lượng quốc tế."}],"correct_letter":"A"},{"id":"ho-chi-minh-q55","number":19,"source_number":55,"text":"Chọn phương án đúng về động lực xây dựng nền quốc phòng toàn dân theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Coi trọng động lực bên trong, không tiếp nhận thành tựu khoa học - kỹ thuật của thế giới."},{"letter":"B","text":"Dựa chủ yếu vào động lực bên ngoài, lấy viện trợ quốc tế làm điều kiện quyết định."},{"letter":"C","text":"Phát huy cao độ động lực bên trong, đồng thời khai thác hiệu quả động lực bên ngoài."},{"letter":"D","text":"Lấy động lực quân sự làm quyết định, xem lực lượng thường trực là nguồn sức mạnh chủ yếu."}],"correct_letter":"C"},{"id":"ho-chi-minh-q37","number":20,"source_number":37,"text":"Chọn phương án đúng về cơ sở tư tưởng, lý luận hình thành tư tưởng Hồ Chí Minh về xây dựng Quân đội nhân dân Việt Nam:","choices":[{"letter":"A","text":"Kinh nghiệm xây dựng Giải phóng quân Trung Quốc và quan điểm của Tôn Tử."},{"letter":"B","text":"Truyền thống “ngụ binh ư nông” của dân tộc và kinh nghiệm xây dựng Hồng quân Liên Xô."},{"letter":"C","text":"Lý luận Mác - Lênin và thực tiễn cách mạng Việt Nam qua các thời kỳ."},{"letter":"D","text":"Truyền thống xây dựng quân đội của dân tộc; kinh nghiệm xây dựng quân đội trên thế giới; lý luận Mác - Lênin về quân đội kiểu mới."}],"correct_letter":"D"},{"id":"ho-chi-minh-q64","number":21,"source_number":64,"text":"Chọn phương án đúng về mục đích của bạo lực cách mạng ở Việt Nam theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Thay đổi triệt để quan hệ ngoại giao với các nước đế quốc"},{"letter":"B","text":"Khẳng định sức mạnh vượt trội của khối liên minh công nông"},{"letter":"C","text":"Giành và giữ chính quyền, bảo vệ nền độc lập tự do của Tổ quốc"},{"letter":"D","text":"Tiêu diệt toàn bộ sinh lực đối phương bằng sức mạnh quân sự"}],"correct_letter":"C"},{"id":"ho-chi-minh-q83","number":22,"source_number":83,"text":"Tư tưởng Hồ Chí Minh về xây dựng nền quốc phòng toàn dân được thể hiện qua lời dạy nào sau đây?","choices":[{"letter":"A","text":"Nước Việt Nam là một, dân tộc Việt Nam là một"},{"letter":"B","text":"Không có gì quý hơn độc lập, tự do"},{"letter":"C","text":"Trung với nước, hiếu với dân, nhiệm vụ nào cũng hoàn thành"},{"letter":"D","text":"Các Vua Hùng đã có công dựng nước, Bác cháu ta phải cùng nhau giữ lấy nước"}],"correct_letter":"D"},{"id":"ho-chi-minh-q95","number":23,"source_number":95,"text":"Dưới sự chỉ dẫn của Hồ Chí Minh, căn cứ địa cách mạng Việt Bắc được mở rộng phát triển thành Khu giải phóng gồm mấy tỉnh?","choices":[{"letter":"A","text":"6 tỉnh"},{"letter":"B","text":"4 tỉnh"},{"letter":"C","text":"3 tỉnh"},{"letter":"D","text":"5 tỉnh"}],"correct_letter":"A"},{"id":"ho-chi-minh-q30","number":24,"source_number":30,"text":"Theo Hồ Chí Minh, tiêu chuẩn hàng đầu của cán bộ quân đội là gì?","choices":[{"letter":"A","text":"Có tinh thần trách nhiệm cao và luôn gần gũi, thương yêu chiến sĩ."},{"letter":"B","text":"Có cả đức và tài, trong đó đức là gốc của người cán bộ."},{"letter":"C","text":"Có bản lĩnh chính trị vững vàng, tác phong mẫu mực và gương mẫu."},{"letter":"D","text":"Có trình độ chuyên môn giỏi, năng lực chỉ huy và tổ chức thực tiễn."}],"correct_letter":"B"},{"id":"ho-chi-minh-q121","number":25,"source_number":121,"text":"Luận điểm nào sau đây thể hiện sâu sắc tư tưởng Hồ Chí Minh về sự kết hợp giữa kinh tế và quốc phòng?","choices":[{"letter":"A","text":"Chỉ đầu tư cho công nghiệp quốc phòng, giảm bớt công nghiệp dân sinh"},{"letter":"B","text":"Phát triển kinh tế thị trường tự do tách biệt hẳn nhiệm vụ bảo vệ Tổ quốc"},{"letter":"C","text":"Dừng phát triển sản xuất để ưu tiên toàn bộ cho tác chiến phòng ngự"},{"letter":"D","text":"Vừa kháng chiến vừa kiến quốc, thực túc thì binh cường"}],"correct_letter":"D"},{"id":"ho-chi-minh-q97","number":26,"source_number":97,"text":"Giải pháp định hướng xây dựng hậu phương chiến tranh theo tinh thần Đại hội XIV của Đảng hiện nay?","choices":[{"letter":"A","text":"Xây dựng “thế trận lòng dân” vững chắc gắn với thế trận quốc phòng toàn dân"},{"letter":"B","text":"Chỉ chú trọng phát triển kinh tế vùng ven biển, giảm đầu tư vùng căn cứ địa"},{"letter":"C","text":"Tập trung toàn bộ ngân sách dự trữ quốc gia vào lĩnh vực quốc phòng"},{"letter":"D","text":"Tách rời khu vực phòng thủ địa phương khỏi thế trận quốc phòng chung"}],"correct_letter":"A"},{"id":"ho-chi-minh-q29","number":27,"source_number":29,"text":"Giá trị thực tiễn của tư tưởng Hồ Chí Minh về xây dựng nền quốc phòng toàn dân được thể hiện ở đâu?","choices":[{"letter":"A","text":"Giúp ngăn chặn mọi cuộc tiến công của đối phương, tránh phải tiến hành chiến tranh giải phóng."},{"letter":"B","text":"Bảo vệ vững chắc miền Bắc, xây dựng miền Bắc thành hậu phương lớn cho cách mạng miền Nam."},{"letter":"C","text":"Giúp đánh thắng thực dân Pháp, hoàn thành xây dựng chủ nghĩa xã hội trên phạm vi cả nước."},{"letter":"D","text":"Bảo vệ vững chắc miền Nam, xây dựng miền Nam thành căn cứ địa cho cách mạng miền Bắc."}],"correct_letter":"B"},{"id":"ho-chi-minh-q138","number":28,"source_number":138,"text":"Theo tư tưởng Hồ Chí Minh, hậu phương chiến tranh có vai trò như thế nào đối với thắng lợi của cách mạng?","choices":[{"letter":"A","text":"Là cơ sở để tiến hành hoạt động ngoại giao quân sự"},{"letter":"B","text":"Là nguồn bổ sung quân số dự bị đơn thuần cho quân đội"},{"letter":"C","text":"Là nhân tố quan trọng, quyết định đến thắng lợi của cách mạng"},{"letter":"D","text":"Là nhân tố hỗ trợ tạm thời khi tiền tuyến gặp khó khăn"}],"correct_letter":"C"},{"id":"ho-chi-minh-q92","number":29,"source_number":92,"text":"Hồ Chí Minh coi nhân tố nào giữ vai trò quan trọng nhất khi xây dựng sức mạnh hậu phương chiến tranh?","choices":[{"letter":"A","text":"Số lượng và chất lượng vũ khí hiện đại"},{"letter":"B","text":"Nguồn viện trợ lương thực từ quốc tế"},{"letter":"C","text":"Thế hiểm trở của địa hình căn cứ địa"},{"letter":"D","text":"Thế trận lòng dân"}],"correct_letter":"D"},{"id":"ho-chi-minh-q128","number":30,"source_number":128,"text":"Theo quan điểm của Hồ Chí Minh, sức mạnh kinh tế giữ vị trí nào trong cấu trúc sức mạnh của nền quốc phòng toàn dân?","choices":[{"letter":"A","text":"Là yếu tố trực tiếp quyết định"},{"letter":"B","text":"Là nền tảng vật chất"},{"letter":"C","text":"Là nhân tố cơ bản quyết định"},{"letter":"D","text":"Là lực lượng xung kích tại chỗ"}],"correct_letter":"B"}]},{"number":3,"title":"Đề 3","questions":[{"id":"ho-chi-minh-q82","number":1,"source_number":82,"text":"Đảng Cộng sản Việt Nam xác định vị trí của Chiến lược quốc phòng Việt Nam hiện nay như thế nào?","choices":[{"letter":"A","text":"Là bộ phận chủ đạo, cụ thể hóa Chiến lược bảo vệ Tổ quốc"},{"letter":"B","text":"Là bản kế hoạch kỹ thuật thuần túy của các quân chủng"},{"letter":"C","text":"Là một bộ phận độc lập nằm ngoài Chiến lược bảo vệ Tổ quốc"},{"letter":"D","text":"Là quy định hành chính điều hành tác chiến của các địa phương"}],"correct_letter":"A"},{"id":"ho-chi-minh-q96","number":2,"source_number":96,"text":"Theo Hồ Chí Minh, muốn dựa vững chắc vào nhân dân cần xây dựng lực lượng nào sau đây?","choices":[{"letter":"A","text":"Xây dựng lực lượng đặc nhiệm cơ động độc lập"},{"letter":"B","text":"Xây dựng các binh chủng kỹ thuật chuyên sâu"},{"letter":"C","text":"Xây dựng mạng lưới an ninh ngầm trong xã hội"},{"letter":"D","text":"Xây dựng lực lượng vũ trang nhân dân ba thứ quân"}],"correct_letter":"D"},{"id":"ho-chi-minh-q5","number":3,"source_number":5,"text":"Giá trị lý luận của tư tưởng Hồ Chí Minh về nghệ thuật quân sự được thể hiện ở đâu?","choices":[{"letter":"A","text":"Là sự tổng kết thực tiễn hai cuộc kháng chiến chống Pháp và chống Mỹ."},{"letter":"B","text":"Là sự áp dụng nguyên mẫu nghệ thuật quân sự thế giới vào điều kiện Việt Nam."},{"letter":"C","text":"Phát triển học thuyết quân sự Mác - Lênin; là nền tảng cho đường lối quân sự của Đảng."},{"letter":"D","text":"Là sự kế thừa nghệ thuật quân sự dân tộc, không tiếp thu yếu tố bên ngoài."}],"correct_letter":"C"},{"id":"ho-chi-minh-q132","number":4,"source_number":132,"text":"Theo Hồ Chí Minh, khái niệm “thế” trong đấu tranh quân sự được hiểu như thế nào?","choices":[{"letter":"A","text":"Môi trường thời tiết khí hậu thuận lợi để quân đội xuất kích tiến công"},{"letter":"B","text":"Thế tổ chức, bố trí, triển khai lực lượng và vũ khí trang bị trên chiến trường nhằm phát huy cao nhất sức mạnh chiến đấu"},{"letter":"C","text":"Thế áp đảo tuyệt đối về số lượng phương tiện vũ khí so với đối phương"},{"letter":"D","text":"Ưu thế ngoại giao quốc tế của đất nước trước khi mở màn chiến dịch"}],"correct_letter":"B"},{"id":"ho-chi-minh-q136","number":5,"source_number":136,"text":"Theo Hồ Chí Minh, đấu tranh chính trị được sử dụng chủ yếu trong giai đoạn cách mạng nào?","choices":[{"letter":"A","text":"Giai đoạn cả nước quá độ lên chủ nghĩa xã hội"},{"letter":"B","text":"Giai đoạn đấu tranh giành chính quyền"},{"letter":"C","text":"Giai đoạn thực hiện đường lối đổi mới đất nước"},{"letter":"D","text":"Giai đoạn bảo vệ và giữ vững chính quyền"}],"correct_letter":"B"},{"id":"ho-chi-minh-q119","number":6,"source_number":119,"text":"Thước đo cao nhất phản ánh bản chất giai cấp công nhân của Quân đội ta theo Hồ Chí Minh là gì?","choices":[{"letter":"A","text":"Khả năng chịu đựng khó khăn, gian khổ trong huấn luyện dã ngoại"},{"letter":"B","text":"Tỷ lệ cán bộ xuất thân từ công nhân trong toàn quân đội"},{"letter":"C","text":"Trình độ làm chủ vũ khí, trang bị kỹ thuật công nghệ cao"},{"letter":"D","text":"Trình độ giác ngộ; tinh thần tự giác; sự hy sinh vì mục tiêu, lý tưởng của Đảng"}],"correct_letter":"D"},{"id":"ho-chi-minh-q73","number":7,"source_number":73,"text":"Chọn phương án đúng về hình thức tổ chức huy động sức mạnh của toàn thể nhân dân đánh giặc là gì?","choices":[{"letter":"A","text":"Xây dựng nền quốc phòng toàn dân và thế trận chiến tranh nhân dân"},{"letter":"B","text":"Tập trung toàn bộ dân cư vào các căn cứ quân sự"},{"letter":"C","text":"Tổ chức các đội bảo an tư nhân tại làng xã"},{"letter":"D","text":"Thành lập các liên minh phòng thủ với lân bang"}],"correct_letter":"A"},{"id":"ho-chi-minh-q51","number":8,"source_number":51,"text":"Chọn phương án đúng về xây dựng nền quốc phòng toàn dân theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Chỉ tiến hành khi xuất hiện nguy cơ chiến tranh, tập trung vào thời gian đất nước lâm nguy."},{"letter":"B","text":"Mang tính nhất thời, được triển khai theo từng giai đoạn tùy diễn biến của tình hình."},{"letter":"C","text":"Có mục đích, có kế hoạch và được chuẩn bị thường xuyên cả trong hòa bình lẫn chiến tranh."},{"letter":"D","text":"Chủ yếu do quân đội thực hiện, nhân dân tham gia khi có yêu cầu huy động của cấp trên."}],"correct_letter":"C"},{"id":"ho-chi-minh-q71","number":9,"source_number":71,"text":"Chọn phương án đúng theo tư tưởng Hồ Chí Minh về đánh địch trên cả “ba vùng chiến lược”:","choices":[{"letter":"A","text":"Vùng trung du; duyên hải; hải phận quốc tế"},{"letter":"B","text":"Rừng núi; nông thôn, đồng bằng; đô thị"},{"letter":"C","text":"Biên giới; nội địa; hải đảo xa bờ"},{"letter":"D","text":"Vùng giải phóng; vùng tranh chấp; vùng tạm chiếm"}],"correct_letter":"B"},{"id":"ho-chi-minh-q86","number":10,"source_number":86,"text":"Quan điểm nào sau đây thể hiện sự sáng tạo, phát triển học thuyết quân sự Mác - Lênin của Hồ Chí Minh về bản chất quân đội ta?","choices":[{"letter":"A","text":"Quân đội đặt nhiệm vụ tác chiến lên trên công tác vận động quần chúng"},{"letter":"B","text":"Quân đội nhà nghề chỉ thực hiện thuần túy nhiệm vụ quân sự"},{"letter":"C","text":"Quân đội chỉ mang bản chất của giai cấp nông dân lao động"},{"letter":"D","text":"Quân đội mang bản chất giai cấp công nhân, tính nhân dân và tính dân tộc sâu sắc"}],"correct_letter":"D"},{"id":"ho-chi-minh-q67","number":11,"source_number":67,"text":"Theo tư tưởng Hồ Chí Minh, sức mạnh ngoại giao có vai trò như thế nào trong sự nghiệp củng cố quốc phòng?","choices":[{"letter":"A","text":"Là thành tố quan trọng"},{"letter":"B","text":"Là nền tảng vật chất cơ bản"},{"letter":"C","text":"Là yếu tố trực tiếp giải quyết xung đột"},{"letter":"D","text":"Là nhân tố quyết định chiến trường"}],"correct_letter":"A"},{"id":"ho-chi-minh-q72","number":12,"source_number":72,"text":"Theo quan điểm của Hồ Chí Minh, lực lượng tiến hành bạo lực cách mạng của quần chúng nhân dân bao gồm những yếu tố nào?","choices":[{"letter":"A","text":"Lực lượng công nhân công xưởng và nông dân các địa phương"},{"letter":"B","text":"Lực lượng thanh niên xung phong và dân quân du kích"},{"letter":"C","text":"Lực lượng chính trị quần chúng và lực lượng vũ trang nhân dân"},{"letter":"D","text":"Lực lượng tự vệ ở địa phương và bộ đội thường trực"}],"correct_letter":"C"},{"id":"ho-chi-minh-q35","number":13,"source_number":35,"text":"Chọn phương án đúng về giá trị lý luận xây dựng Quân đội nhân dân Việt Nam của Hồ Chí Minh:","choices":[{"letter":"A","text":"Là sự tổng kết thực tiễn xây dựng quân đội trong hai cuộc kháng chiến chống Pháp, chống Mỹ."},{"letter":"B","text":"Là sự kế thừa truyền thống xây dựng quân đội của dân tộc qua các thời kỳ lịch sử."},{"letter":"C","text":"Làm phong phú học thuyết Mác - Lênin về quân đội; là cơ sở để Đảng xác định đường lối xây dựng quân đội."},{"letter":"D","text":"Là sự vận dụng sáng tạo kinh nghiệm xây dựng quân đội của các nước xã hội chủ nghĩa."}],"correct_letter":"C"},{"id":"ho-chi-minh-q18","number":14,"source_number":18,"text":"Quan điểm nào sau đây KHÔNG mang tính nguyên tắc trong tư tưởng Hồ Chí Minh về bạo lực cách mạng?","choices":[{"letter":"A","text":"Quan điểm về bạo lực cách mạng là bạo lực của quần chúng nhân dân."},{"letter":"B","text":"Quan điểm về tính chất nhân văn, nhân đạo của bạo lực cách mạng."},{"letter":"C","text":"Quan điểm về tính tất yếu phải sử dụng bạo lực cách mạng để giành và giữ chính quyền."},{"letter":"D","text":"Quan điểm cho rằng bạo lực cách mạng không cần dựa vào quần chúng nhân dân."}],"correct_letter":"D"},{"id":"ho-chi-minh-q59","number":15,"source_number":59,"text":"Theo Hồ Chí Minh, “thời” được hiểu là gì?","choices":[{"letter":"A","text":"Nghệ thuật nghi binh, lừa địch trong tác chiến."},{"letter":"B","text":"Tình hình trong nước, khu vực, thế giới thuận lợi và thời điểm tiến công địch có lợi nhất."},{"letter":"C","text":"Thế bố trí lực lượng có lợi cho ta trên chiến trường."},{"letter":"D","text":"Sức mạnh tổng hợp của toàn dân tộc trong chiến tranh."}],"correct_letter":"B"},{"id":"ho-chi-minh-q104","number":16,"source_number":104,"text":"Chọn phương án đúng về điểm cốt lõi thể hiện tính nhân văn sâu sắc trong tư tưởng Hồ Chí Minh về bạo lực cách mạng:","choices":[{"letter":"A","text":"Tận dụng mọi khả năng hòa bình, chỉ dùng chiến tranh vũ trang khi không còn con đường nào khác"},{"letter":"B","text":"Ưu tiên đàm phán ngoại giao ngay cả khi chủ quyền lãnh thổ bị xâm phạm nghiêm trọng"},{"letter":"C","text":"Không sử dụng lực lượng chính trị khi các biện pháp quân sự đã phát huy tác dụng"},{"letter":"D","text":"Chủ động phát động tấn công quân sự ngay khi xuất hiện thời cơ thuận lợi"}],"correct_letter":"A"},{"id":"ho-chi-minh-q17","number":17,"source_number":17,"text":"Chọn phương án đúng về cơ sở thực tiễn hình thành tư tưởng Hồ Chí Minh về bạo lực cách mạng:","choices":[{"letter":"A","text":"Thực dân Pháp dùng bạo lực phản cách mạng cai trị Việt Nam; thực tiễn các phong trào yêu nước cuối thế kỷ XIX - đầu thế kỷ XX; kinh nghiệm các cuộc cách mạng trên thế giới."},{"letter":"B","text":"Thực tiễn kháng chiến chống Pháp và chống Mỹ; kinh nghiệm Cách mạng Tháng Mười Nga; truyền thống quân sự dân tộc."},{"letter":"C","text":"Thực tiễn cách mạng Việt Nam từ 1930 đến 1945; kinh nghiệm Hồng quân Liên Xô; quan điểm của Tôn Tử về chiến tranh."},{"letter":"D","text":"Thực tiễn xây dựng căn cứ địa cách mạng; kinh nghiệm Công xã Paris; sự thất bại của các phong trào yêu nước theo khuynh hướng tư sản."}],"correct_letter":"A"},{"id":"ho-chi-minh-q110","number":18,"source_number":110,"text":"Theo Hồ Chí Minh, biện pháp nào sau đây nhằm phát huy nguồn lực vật chất của nhân dân chi viện cho kháng chiến?","choices":[{"letter":"A","text":"Đóng cửa giao thương kinh tế với các vùng địch tạm chiếm"},{"letter":"B","text":"Độc quyền quản lý toàn bộ thị trường buôn bán"},{"letter":"C","text":"Trưng thu toàn bộ nông sản trong vụ thu hoạch"},{"letter":"D","text":"Xây dựng nền văn hóa mới và con người mới cách mạng"}],"correct_letter":"D"},{"id":"ho-chi-minh-q31","number":19,"source_number":31,"text":"Hồ Chí Minh yêu cầu khi lựa chọn, xây dựng căn cứ địa cách mạng phải bảo đảm yếu tố nào?","choices":[{"letter":"A","text":"Có địa hình thuận lợi, dân cư đông đúc, kinh tế phát triển."},{"letter":"B","text":"Có địa thế hiểm yếu, được quần chúng ủng hộ, có tổ chức đảng mạnh."},{"letter":"C","text":"Có vị trí trung tâm, dân trí cao, chính quyền vững chắc."},{"letter":"D","text":"Có giao thông thuận tiện, nguồn dự trữ dồi dào, lực lượng vũ trang mạnh."}],"correct_letter":"B"},{"id":"ho-chi-minh-q131","number":20,"source_number":131,"text":"Để tiếp thu tinh hoa và phát triển nghệ thuật tác chiến, Hồ Chí Minh đã trực tiếp dịch và xuất bản tác phẩm quân sự cổ đại nào?","choices":[{"letter":"A","text":"Tam lược Hoàng Thạch Công"},{"letter":"B","text":"Binh thư yếu lược"},{"letter":"C","text":"Binh pháp Tôn Tử"},{"letter":"D","text":"Lục thao Khương Tử Nha"}],"correct_letter":"C"},{"id":"ho-chi-minh-q76","number":21,"source_number":76,"text":"Hội nghị Trung ương 8 (tháng 5/1941) do Nguyễn Ái Quốc chủ trì xác định, cuộc cách mạng Đông Dương phải kết liễu bằng hình thức nào?","choices":[{"letter":"A","text":"Đấu tranh chính trị hợp pháp"},{"letter":"B","text":"Khởi nghĩa từng phần kết hợp bãi công"},{"letter":"C","text":"Đấu tranh nghị trường kết hợp ngoại giao"},{"letter":"D","text":"Khởi nghĩa vũ trang"}],"correct_letter":"D"},{"id":"ho-chi-minh-q120","number":22,"source_number":120,"text":"Theo Hồ Chí Minh, mục tiêu chiến đấu cao nhất của Quân đội nhân dân Việt Nam là gì?","choices":[{"letter":"A","text":"Xây dựng tiềm lực quốc phòng độc lập với hệ thống chính trị"},{"letter":"B","text":"Mở rộng vùng kiểm soát quân sự sang các nước trong khu vực"},{"letter":"C","text":"Tranh lại độc lập, thống nhất cho Tổ quốc, bảo vệ tự do, hạnh phúc của nhân dân"},{"letter":"D","text":"Giành ưu thế chiến lược tuyệt đối trước lực lượng đối phương"}],"correct_letter":"C"},{"id":"ho-chi-minh-q60","number":23,"source_number":60,"text":"Nội dung cốt lõi trong xây dựng hậu phương vững mạnh về chính trị theo tư tưởng Hồ Chí Minh là gì?","choices":[{"letter":"A","text":"Tổ chức phong trào thi đua yêu nước rộng khắp trong nhân dân."},{"letter":"B","text":"Xây dựng thế trận lòng dân, củng cố niềm tin của nhân dân vào Đảng, Nhà nước."},{"letter":"C","text":"Xây dựng tổ chức đảng vững mạnh ở các cấp, các địa phương."},{"letter":"D","text":"Xây dựng chính quyền và các đoàn thể nhân dân ở cơ sở."}],"correct_letter":"B"},{"id":"ho-chi-minh-q113","number":24,"source_number":113,"text":"Bác Hồ căn dặn cán bộ, chiến sĩ Đại đoàn 308: “Các Vua Hùng đã có công dựng nước, Bác cháu ta phải cùng nhau giữ lấy nước” trong bối cảnh nào?","choices":[{"letter":"A","text":"Tại Đền Hùng (Phú Thọ) năm 1954, trước khi đơn vị về tiếp quản Thủ đô"},{"letter":"B","text":"Khi về thăm khu căn cứ địa Tân Trào sau ngày Toàn quốc kháng chiến bùng nổ"},{"letter":"C","text":"Tại Hội nghị quân sự toàn quốc chuẩn bị mở chiến dịch Biên giới năm 1950"},{"letter":"D","text":"Trong Lễ tuyên thệ xuất quân mở màn chiến dịch Điện Biên Phủ năm 1954"}],"correct_letter":"A"},{"id":"ho-chi-minh-q54","number":25,"source_number":54,"text":"Cơ sở tư tưởng, lý luận hình thành tư tưởng Hồ Chí Minh về nghệ thuật quân sự:","choices":[{"letter":"A","text":"Truyền thống lấy nhỏ thắng lớn của dân tộc và kinh nghiệm xây dựng Hồng quân Liên Xô."},{"letter":"B","text":"Binh pháp Tôn Tử, nghệ thuật tác chiến của Napoléon và kinh nghiệm quân sự Trung Quốc."},{"letter":"C","text":"Kinh nghiệm chiến tranh du kích và lý luận về chiến tranh nhân dân của Việt Nam."},{"letter":"D","text":"Nghệ thuật quân sự dân tộc, tinh hoa nghệ thuật quân sự thế giới và học thuyết quân sự Mác - Lênin."}],"correct_letter":"D"},{"id":"ho-chi-minh-q114","number":26,"source_number":114,"text":"Địa bàn được xác định là hậu phương lớn của tiền tuyến miền Nam trong cuộc kháng chiến chống Mỹ, cứu nước là:","choices":[{"letter":"A","text":"Tây Nguyên"},{"letter":"B","text":"Miền Trung"},{"letter":"C","text":"Miền Bắc"},{"letter":"D","text":"Vùng giải phóng Hạ Lào"}],"correct_letter":"C"},{"id":"ho-chi-minh-q112","number":27,"source_number":112,"text":"Hồ Chí Minh đã ký với Pháp văn bản nào nhằm kéo dài thời gian chuẩn bị kháng chiến?","choices":[{"letter":"A","text":"Bản Tạm ước Việt - Pháp"},{"letter":"B","text":"Hiệp định Giơ-ne-vơ về Đông Dương"},{"letter":"C","text":"Thỏa ước quân sự Pháp - Hoa"},{"letter":"D","text":"Hiệp định sơ bộ Việt - Pháp"}],"correct_letter":"A"},{"id":"ho-chi-minh-q27","number":28,"source_number":27,"text":"Theo Hồ Chí Minh, “lực” được hiểu là gì?","choices":[{"letter":"A","text":"Tổng thể hoàn cảnh, điều kiện khách quan của các bên tham chiến."},{"letter":"B","text":"Sức mạnh vật chất, tinh thần của cá nhân, đơn vị, địa phương và cả nước."},{"letter":"C","text":"Thế tổ chức, bố trí lực lượng có lợi trên chiến trường."},{"letter":"D","text":"Xu thế vận động và khả năng phát triển của các bên tham chiến."}],"correct_letter":"B"},{"id":"ho-chi-minh-q8","number":29,"source_number":8,"text":"Chọn phương án đúng về vị trí của quần chúng nhân dân theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Là chỗ dựa của quân đội và là nguồn bảo đảm hậu cần cho kháng chiến."},{"letter":"B","text":"Là lực lượng nòng cốt trong chiến tranh và là nguồn dự bị động viên của quân đội."},{"letter":"C","text":"Là lực lượng quyết định thắng lợi và là động lực phát triển kinh tế - xã hội."},{"letter":"D","text":"Là nền tảng của dân tộc; đối tượng lãnh đạo của Đảng; mục tiêu và động lực của cách mạng."}],"correct_letter":"D"},{"id":"ho-chi-minh-q103","number":30,"source_number":103,"text":"Tháng 12/1946, Chủ tịch Hồ Chí Minh thay mặt Chính phủ đã tặng đồng bào miền Nam danh hiệu cao quý nào?","choices":[{"letter":"A","text":"Căn cứ địa bất khả xâm phạm"},{"letter":"B","text":"Ngọn cờ đầu chống giặc ngoại xâm"},{"letter":"C","text":"Thành đồng Tổ quốc"},{"letter":"D","text":"Kháng chiến anh dũng"}],"correct_letter":"C"}]},{"number":4,"title":"Đề 4","questions":[{"id":"ho-chi-minh-q44","number":1,"source_number":44,"text":"Chọn phương án đúng về sự cần thiết vận dụng tư tưởng Hồ Chí Minh trong phát huy sức mạnh quần chúng nhân dân hiện nay:","choices":[{"letter":"A","text":"Đặc điểm chiến tranh công nghệ cao và yêu cầu xây dựng quân đội tinh, gọn, mạnh."},{"letter":"B","text":"Vai trò của quần chúng nhân dân; thuận lợi, thách thức của kinh tế thị trường; sự chống phá của các thế lực thù địch."},{"letter":"C","text":"Âm mưu diễn biến hòa bình và yêu cầu xây dựng thế trận lòng dân vững chắc."},{"letter":"D","text":"Vai trò của nhân tố con người và nhiệm vụ xây dựng nền quốc phòng toàn dân."}],"correct_letter":"B"},{"id":"ho-chi-minh-q127","number":2,"source_number":127,"text":"Chọn phương án đúng về lực lượng nòng cốt của nền quốc phòng toàn dân theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Lực lượng dự bị động viên tại các thành phố lớn"},{"letter":"B","text":"Bộ đội chủ lực kết hợp cùng các công ty quốc phòng"},{"letter":"C","text":"Lực lượng vũ trang nhân dân ba thứ quân"},{"letter":"D","text":"Đội ngũ cán bộ, công chức làm công tác quân sự địa phương"}],"correct_letter":"C"},{"id":"ho-chi-minh-q133","number":3,"source_number":133,"text":"Theo Hồ Chí Minh, biện pháp hiệu quả nhất để xây dựng hậu phương kháng chiến vững mạnh là:","choices":[{"letter":"A","text":"Áp dụng các biện pháp trừng phạt kinh tế nghiêm khắc"},{"letter":"B","text":"Tăng cường huy động đóng góp tài chính bắt buộc"},{"letter":"C","text":"Tuyệt đối ưu tiên sản xuất các mặt hàng công nghiệp nặng"},{"letter":"D","text":"Tổ chức tốt phong trào thi đua ái quốc"}],"correct_letter":"D"},{"id":"ho-chi-minh-q116","number":4,"source_number":116,"text":"Đâu là một trong những cơ sở lý luận nền tảng hình thành tư tưởng Hồ Chí Minh về bạo lực cách mạng?","choices":[{"letter":"A","text":"Học thuyết Mác - Lênin về bạo lực cách mạng và khởi nghĩa vũ trang"},{"letter":"B","text":"Tư tưởng phi bạo lực của các nhà triết học cổ đại phương Đông"},{"letter":"C","text":"Lý luận về cân bằng quyền lực quân sự giữa các cường quốc"},{"letter":"D","text":"Học thuyết quân sự tư sản về chiến tranh tổng lực hiện đại"}],"correct_letter":"A"},{"id":"ho-chi-minh-q107","number":5,"source_number":107,"text":"Phong trào nào sau đây không thuộc các phong trào thi đua ái quốc trong cuộc kháng chiến chống thực dân Pháp?","choices":[{"letter":"A","text":"Mùa đông binh sĩ"},{"letter":"B","text":"Bình dân học vụ"},{"letter":"C","text":"Sóng Duyên hải - Gió Đại Phong"},{"letter":"D","text":"Tất cả các phương án"}],"correct_letter":"C"},{"id":"ho-chi-minh-q26","number":6,"source_number":26,"text":"Chọn phương án đúng về hình thức phát huy sức mạnh quần chúng nhân dân trong lĩnh vực quân sự theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Xây dựng lực lượng chính trị của quần chúng và lấy đấu tranh chính trị làm chủ yếu."},{"letter":"B","text":"Xây dựng thế trận lòng dân, tăng cường công tác địch vận và binh vận."},{"letter":"C","text":"Xây dựng căn cứ địa cách mạng, thực hiện ba mũi giáp công và nổi dậy toàn dân."},{"letter":"D","text":"Xây dựng bạo lực cách mạng, lực lượng vũ trang ba thứ quân, chiến tranh nhân dân và nền quốc phòng toàn dân."}],"correct_letter":"D"},{"id":"ho-chi-minh-q111","number":7,"source_number":111,"text":"Nội dung nào sau đây không thuộc tư tưởng Hồ Chí Minh về nghệ thuật quân sự?","choices":[{"letter":"A","text":"Nắm vững tư tưởng chiến lược tiến công, giành và giữ quyền chủ động"},{"letter":"B","text":"Xây dựng nền quốc phòng toàn dân, toàn diện"},{"letter":"C","text":"Phát huy sức mạnh tổng hợp của toàn dân tộc"},{"letter":"D","text":"Tạo lực, lập thế, tranh thời, dùng mưu linh hoạt"}],"correct_letter":"B"},{"id":"ho-chi-minh-q23","number":8,"source_number":23,"text":"Khi xây dựng thế trận quốc phòng toàn dân và thế trận an ninh nhân dân hiện nay, yếu tố quan trọng nhất là gì?","choices":[{"letter":"A","text":"Xây dựng “thế trận lòng dân” vững chắc trong toàn dân."},{"letter":"B","text":"Xây dựng thế trận phòng không nhân dân trên các hướng chiến lược."},{"letter":"C","text":"Xây dựng thế trận hậu cần - kỹ thuật tại chỗ ở các địa phương."},{"letter":"D","text":"Xây dựng thế trận phòng thủ vững chắc ở khu vực biên giới, biển đảo."}],"correct_letter":"A"},{"id":"ho-chi-minh-q115","number":9,"source_number":115,"text":"Luận điểm nào sau đây không phải là nội dung tư tưởng nghệ thuật quân sự của Hồ Chí Minh?","choices":[{"letter":"A","text":"Nắm vững tư tưởng chiến lược tiến công, giành và giữ quyền chủ động"},{"letter":"B","text":"Xây dựng Quân đội mang bản chất giai cấp công nhân, tính nhân dân, tính dân tộc sâu sắc"},{"letter":"C","text":"Chủ động đánh vào lòng người đối phương, kết hợp tác chiến với địch vận"},{"letter":"D","text":"Khởi đầu và kết thúc chiến tranh đúng lúc"}],"correct_letter":"B"},{"id":"ho-chi-minh-q137","number":10,"source_number":137,"text":"Luận điểm nào sau đây không đúng với tư tưởng Hồ Chí Minh về thời điểm thích hợp để bắt đầu chiến tranh tự vệ?","choices":[{"letter":"A","text":"Khi ta đã chuẩn bị chu đáo cả về đường lối chính trị và lực lượng vũ trang kháng chiến"},{"letter":"B","text":"Khi các giải pháp hòa bình để trì hoãn, ngăn chặn chiến tranh đã bị kẻ thù phá vỡ"},{"letter":"C","text":"Ngay khi kẻ thù vừa nhen nhóm ý định xâm lược nước ta"},{"letter":"D","text":"Khi địch buộc ta vào tình thế không còn con đường lựa chọn nào khác"}],"correct_letter":"C"},{"id":"ho-chi-minh-q108","number":11,"source_number":108,"text":"Theo Hồ Chí Minh, tên gọi “Đội Việt Nam tuyên truyền giải phóng quân” có ý nghĩa cốt lõi là gì?","choices":[{"letter":"A","text":"Chính trị và quân sự có vai trò ngang nhau"},{"letter":"B","text":"Quân sự trọng hơn chính trị"},{"letter":"C","text":"Tác chiến vũ trang là mục tiêu duy nhất"},{"letter":"D","text":"Chính trị trọng hơn quân sự"}],"correct_letter":"D"},{"id":"ho-chi-minh-q21","number":12,"source_number":21,"text":"Chọn phương án đúng về xây dựng hậu phương chiến tranh hiện nay khi vận dụng tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Xây dựng các tiềm lực, thế trận lòng dân, thế trận quốc phòng toàn dân gắn với an ninh nhân dân."},{"letter":"B","text":"Tăng cường tiềm lực kinh tế và tiềm lực quân sự của đất nước."},{"letter":"C","text":"Phát huy vai trò của cả hệ thống chính trị và của toàn thể nhân dân."},{"letter":"D","text":"Xây dựng lực lượng vũ trang vững mạnh và hoàn thiện pháp luật quốc phòng."}],"correct_letter":"A"},{"id":"ho-chi-minh-q80","number":13,"source_number":80,"text":"Trong Thư gửi lớp cán bộ cung cấp (6/1951), Hồ Chí Minh khẳng định: “Công việc cung cấp cũng quan trọng như việc…”","choices":[{"letter":"A","text":"Xây dựng hệ thống công sự trận địa vững chắc"},{"letter":"B","text":"Huấn luyện điều lệnh đội ngũ nơi hậu phương"},{"letter":"C","text":"Trực tiếp đánh giặc trước mặt trận"},{"letter":"D","text":"Chỉ huy tác chiến của các cơ quan tham mưu"}],"correct_letter":"C"},{"id":"ho-chi-minh-q126","number":14,"source_number":126,"text":"Theo Hồ Chí Minh, đâu là giải pháp nền tảng để lãnh đạo quần chúng trong lĩnh vực quân sự là gì?","choices":[{"letter":"A","text":"Tăng cường quyền lực tuyệt đối cho chính quyền cơ sở"},{"letter":"B","text":"Đặt nhiệm vụ vũ trang lên trên việc xây dựng tổ chức Đảng"},{"letter":"C","text":"Tách biệt hoàn toàn sinh hoạt Đảng khỏi các đoàn thể"},{"letter":"D","text":"Xây dựng Đảng ta thực sự là đạo đức, là văn minh"}],"correct_letter":"D"},{"id":"ho-chi-minh-q13","number":15,"source_number":13,"text":"Chọn phương án đúng về sự cần thiết xây dựng hậu phương chiến tranh hiện nay khi vận dụng tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Đặc điểm, nhiệm vụ bảo vệ Tổ quốc; âm mưu chống phá của thế lực thù địch; thực trạng xây dựng các tiềm lực."},{"letter":"B","text":"Âm mưu diễn biến hòa bình và yêu cầu kết hợp phát triển kinh tế với quốc phòng."},{"letter":"C","text":"Yêu cầu xây dựng nền quốc phòng toàn dân và đặc điểm của chiến tranh công nghệ cao."},{"letter":"D","text":"Nhiệm vụ bảo vệ Tổ quốc từ sớm, từ xa và yêu cầu xây dựng thế trận lòng dân."}],"correct_letter":"A"},{"id":"ho-chi-minh-q89","number":16,"source_number":89,"text":"Luận điểm: “Cách mệnh là sự nghiệp của cả dân chúng chứ không phải việc một hai người” được Hồ Chí Minh khẳng định trong tác phẩm nào?","choices":[{"letter":"A","text":"Lời kêu gọi toàn quốc kháng chiến"},{"letter":"B","text":"Đường cách mệnh"},{"letter":"C","text":"Tuyên ngôn độc lập"},{"letter":"D","text":"Bản án chế độ thực dân Pháp"}],"correct_letter":"B"},{"id":"ho-chi-minh-q14","number":17,"source_number":14,"text":"Theo Hồ Chí Minh, xây dựng hậu phương vững mạnh về quân sự cần tập trung vào nội dung nào sau đây?","choices":[{"letter":"A","text":"Xây dựng thế trận chiến tranh nhân dân vững chắc trên cả nước."},{"letter":"B","text":"Tăng cường khả năng phòng thủ ở hậu phương và chi viện cho tiền tuyến."},{"letter":"C","text":"Xây dựng lực lượng vũ trang ba thứ quân và nền quốc phòng toàn dân ở hậu phương."},{"letter":"D","text":"Xây dựng lực lượng thường trực và lực lượng dự bị động viên hùng hậu."}],"correct_letter":"C"},{"id":"ho-chi-minh-q102","number":18,"source_number":102,"text":"Theo Hồ Chí Minh, yếu tố nào có giá trị cao nhất trong sức mạnh tinh thần của nhân dân ở lĩnh vực quân sự?","choices":[{"letter":"A","text":"Chủ nghĩa yêu nước"},{"letter":"B","text":"Tinh thần tương thân tương ái"},{"letter":"C","text":"Lòng tự hào về truyền thống dòng họ"},{"letter":"D","text":"Ý thức tuân thủ kỷ luật quân sự"}],"correct_letter":"A"},{"id":"ho-chi-minh-q87","number":19,"source_number":87,"text":"Theo Hồ Chí Minh, vấn đề cốt lõi trong xây dựng hậu phương vững mạnh về chính trị, tư tưởng là gì?","choices":[{"letter":"A","text":"Tăng cường số lượng cán bộ hành chính cơ sở"},{"letter":"B","text":"Phát triển mạng lưới trường lớp ở nông thôn"},{"letter":"C","text":"Mở rộng bộ máy quản lý kinh tế nhà nước"},{"letter":"D","text":"Xây dựng thế trận lòng dân"}],"correct_letter":"D"},{"id":"ho-chi-minh-q74","number":20,"source_number":74,"text":"Chọn phương án đúng về phương châm tác chiến nổi bật trong nghệ thuật quân sự của Hồ Chí Minh:","choices":[{"letter":"A","text":"Đánh nhanh thắng nhanh, tập trung hỏa lực áp đảo tuyệt đối đối phương"},{"letter":"B","text":"Lấy nhỏ thắng lớn, lấy ít địch nhiều, lấy đoản binh thắng trường trận"},{"letter":"C","text":"Dựa vào viện trợ vũ khí hiện đại để mở các chiến dịch quy mô lớn"},{"letter":"D","text":"Dàn đều lực lượng trên mọi hướng để phòng ngự diện địa thụ động"}],"correct_letter":"B"},{"id":"ho-chi-minh-q40","number":21,"source_number":40,"text":"Theo Hồ Chí Minh, “mưu” được hiểu là gì?","choices":[{"letter":"A","text":"Khả năng huy động tối đa sức người, sức của cho kháng chiến."},{"letter":"B","text":"Sự kết hợp chặt chẽ giữa lực lượng chính trị và lực lượng vũ trang."},{"letter":"C","text":"Thế trận lòng dân vững chắc, rộng khắp trên toàn quốc."},{"letter":"D","text":"Chủ trương, quyết tâm chiến lược, chiến dịch, chiến đấu; tài chỉ huy, nghệ thuật nghi binh lừa địch."}],"correct_letter":"D"},{"id":"ho-chi-minh-q122","number":22,"source_number":122,"text":"Hoàn chỉnh luận điểm của Hồ Chí Minh: “… thì không quân lính nào, súng ống nào chống lại nổi”.","choices":[{"letter":"A","text":"Quân đội mạnh."},{"letter":"B","text":"Dân khí mạnh."},{"letter":"C","text":"Thực lực mạnh."},{"letter":"D","text":"Binh lính mạnh."}],"correct_letter":"B"},{"id":"ho-chi-minh-q84","number":23,"source_number":84,"text":"Luận điểm nào sau đây thể hiện đúng nội dung phát huy sức mạnh quần chúng nhân dân trong lĩnh vực quân sự của Hồ Chí Minh?","choices":[{"letter":"A","text":"Nâng cao dân trí và củng cố khối đại đoàn kết toàn dân"},{"letter":"B","text":"Mở rộng quân số thường trực ở mọi địa bàn"},{"letter":"C","text":"Giảm nhẹ công tác dân vận để tập trung tác chiến"},{"letter":"D","text":"Tăng cường mua sắm các loại vũ khí hiện đại"}],"correct_letter":"A"},{"id":"ho-chi-minh-q94","number":24,"source_number":94,"text":"Theo Hồ Chí Minh, sức mạnh quân sự giữ vai trò gì đối với tổng thể sức mạnh của nền quốc phòng toàn dân?","choices":[{"letter":"A","text":"Là nhân tố cơ bản quyết định"},{"letter":"B","text":"Là thành tố hỗ trợ vòng ngoài"},{"letter":"C","text":"Là yếu tố trực tiếp quyết định"},{"letter":"D","text":"Là nền tảng vật chất kỹ thuật"}],"correct_letter":"C"},{"id":"ho-chi-minh-q100","number":25,"source_number":100,"text":"Theo Hồ Chí Minh, việc xây dựng hậu phương chiến tranh nhất thiết phải gắn liền với vấn đề gì?","choices":[{"letter":"A","text":"Đóng cửa toàn bộ giao thương kinh tế nội địa"},{"letter":"B","text":"Thu hẹp quy mô chiến tranh vũ trang"},{"letter":"C","text":"Bảo vệ hậu phương chiến tranh"},{"letter":"D","text":"Tách rời hoàn toàn khỏi nhiệm vụ ở tiền tuyến"}],"correct_letter":"C"},{"id":"ho-chi-minh-q75","number":26,"source_number":75,"text":"Tên gọi “Quân đội nhân dân Việt Nam” chính thức được Chủ tịch Hồ Chí Minh đặt ra vào thời gian nào?","choices":[{"letter":"A","text":"Năm 1954"},{"letter":"B","text":"Năm 1950"},{"letter":"C","text":"Năm 1944"},{"letter":"D","text":"Năm 1945"}],"correct_letter":"B"},{"id":"ho-chi-minh-q43","number":27,"source_number":43,"text":"Nội dung nào sau đây thuộc nghệ thuật chỉ đạo chiến tranh trong tư tưởng Hồ Chí Minh?","choices":[{"letter":"A","text":"Chủ động đánh vào lòng người đối phương, kết hợp chặt chẽ tác chiến với địch vận."},{"letter":"B","text":"Xây dựng quân đội vững mạnh toàn diện về chính trị, tổ chức, kỹ thuật."},{"letter":"C","text":"Xây dựng hậu phương chiến tranh vững mạnh về chính trị, kinh tế, quân sự."},{"letter":"D","text":"Xây dựng nền quốc phòng toàn dân gắn với an ninh nhân dân."}],"correct_letter":"A"},{"id":"ho-chi-minh-q139","number":28,"source_number":139,"text":"Sau khi tiếp thu lý luận quân sự cổ đại phương Đông, Hồ Chí Minh đã biên soạn tài liệu nào để đào tạo đội ngũ cán bộ?","choices":[{"letter":"A","text":"Phép dùng binh của Tôn Tẫn"},{"letter":"B","text":"Kinh nghiệm tổ chức quân cơ thời cổ"},{"letter":"C","text":"Bát trận đồ ứng dụng trong chiến tranh hiện đại"},{"letter":"D","text":"Cách huấn luyện cán bộ quân sự của Khổng Minh"}],"correct_letter":"D"},{"id":"ho-chi-minh-q1","number":29,"source_number":1,"text":"Chọn phương án đúng về quan điểm xây dựng Quân đội nhân dân Việt Nam theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Xây dựng quân đội vững mạnh toàn diện trên cơ sở vững mạnh về tổ chức, trang bị."},{"letter":"B","text":"Xây dựng quân đội vững mạnh toàn diện trên cơ sở vững mạnh về chính trị."},{"letter":"C","text":"Xây dựng quân đội vững mạnh toàn diện trên cơ sở vững mạnh về kỹ thuật, chiến thuật."},{"letter":"D","text":"Xây dựng quân đội vững mạnh toàn diện trên cơ sở vững mạnh về hậu cần, kỹ thuật."}],"correct_letter":"B"},{"id":"ho-chi-minh-q99","number":30,"source_number":99,"text":"Giải pháp hàng đầu nhằm phát huy sức mạnh nhân dân trong bảo vệ Tổ quốc hiện nay khi vận dụng tư tưởng Hồ Chí Minh?","choices":[{"letter":"A","text":"Xây dựng “thế trận lòng dân” vững chắc từ cơ sở"},{"letter":"B","text":"Tách rời nhiệm vụ quân sự khỏi các chính sách an sinh xã hội"},{"letter":"C","text":"Tăng nguồn chi viện tài chính quân sự từ bên ngoài"},{"letter":"D","text":"Huy động ngay lực lượng thanh niên vào quân đội tập trung"}],"correct_letter":"A"}]},{"number":5,"title":"Đề 5","questions":[{"id":"ho-chi-minh-q37","number":1,"source_number":37,"text":"Chọn phương án đúng về cơ sở tư tưởng, lý luận hình thành tư tưởng Hồ Chí Minh về xây dựng Quân đội nhân dân Việt Nam:","choices":[{"letter":"A","text":"Truyền thống “ngụ binh ư nông” của dân tộc và kinh nghiệm xây dựng Hồng quân Liên Xô."},{"letter":"B","text":"Lý luận Mác - Lênin và thực tiễn cách mạng Việt Nam qua các thời kỳ."},{"letter":"C","text":"Kinh nghiệm xây dựng Giải phóng quân Trung Quốc và quan điểm của Tôn Tử."},{"letter":"D","text":"Truyền thống xây dựng quân đội của dân tộc; kinh nghiệm xây dựng quân đội trên thế giới; lý luận Mác - Lênin về quân đội kiểu mới."}],"correct_letter":"D"},{"id":"ho-chi-minh-q101","number":2,"source_number":101,"text":"Theo tư tưởng Hồ Chí Minh, hình thức cơ bản của bạo lực cách mạng ở nước ta trong chiến tranh giải phóng là gì?","choices":[{"letter":"A","text":"Đấu tranh kinh tế kết hợp với phong trào công nhân quốc tế"},{"letter":"B","text":"Kết hợp đấu tranh quân sự với đấu tranh chính trị và binh vận"},{"letter":"C","text":"Đấu tranh ngoại giao đơn thuần trên các diễn đàn quốc tế"},{"letter":"D","text":"Khởi nghĩa vũ trang thuần túy của bộ đội chủ lực trên chiến trường"}],"correct_letter":"B"},{"id":"ho-chi-minh-q25","number":3,"source_number":25,"text":"Chọn phương án đúng về sự cần thiết phải phát huy sức mạnh quần chúng nhân dân trong lĩnh vực quân sự:","choices":[{"letter":"A","text":"Yêu cầu xây dựng nền quốc phòng toàn dân và đặc điểm của chiến tranh hiện đại."},{"letter":"B","text":"Âm mưu chống phá của các thế lực thù địch và nhiệm vụ bảo vệ Tổ quốc."},{"letter":"C","text":"Vai trò của quần chúng trong hoạt động quân sự, bài học lịch sử dân tộc và mục tiêu, nhiệm vụ cách mạng Việt Nam."},{"letter":"D","text":"Vai trò của nhân tố chính trị - tinh thần và kinh nghiệm cách mạng thế giới."}],"correct_letter":"C"},{"id":"ho-chi-minh-q123","number":4,"source_number":123,"text":"Yếu tố nào cấu thành sức mạnh vật chất của quần chúng nhân dân trong hoạt động quân sự theo tư tưởng Hồ Chí Minh?","choices":[{"letter":"A","text":"Nguồn lực con người và của cải vật chất do con người làm ra"},{"letter":"B","text":"Hệ thống phòng thủ công sự và căn cứ địa"},{"letter":"C","text":"Vũ khí, phương tiện hiện đại mua từ nước ngoài"},{"letter":"D","text":"Kho dự trữ lương thực của lực lượng vũ trang"}],"correct_letter":"A"},{"id":"ho-chi-minh-q130","number":5,"source_number":130,"text":"Theo định hướng Đại hội XIV của Đảng về xây dựng Quân đội trong điều kiện mới, yếu tố nào giữ vai trò là cơ sở, nền tảng vững chắc để xây dựng Quân đội hiện đại?","choices":[{"letter":"A","text":"Đầu tư mua sắm toàn diện vũ khí công nghệ cao"},{"letter":"B","text":"Tách biệt công tác huấn luyện với công tác tư tưởng"},{"letter":"C","text":"Mở rộng quân số thường trực ở các quân binh chủng"},{"letter":"D","text":"Xây dựng Quân đội vững mạnh về chính trị"}],"correct_letter":"D"},{"id":"ho-chi-minh-q2","number":6,"source_number":2,"text":"Chọn phương án đúng về biện pháp phát huy sức mạnh quần chúng nhân dân trong lĩnh vực quân sự theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Xây dựng khối đại đoàn kết toàn dân, kết hợp phát triển kinh tế với tăng cường quốc phòng."},{"letter":"B","text":"Xác định mục tiêu cách mạng đúng đắn; truyền bá hệ tư tưởng; xây dựng Đảng, Nhà nước và con người mới."},{"letter":"C","text":"Phát huy vai trò Mặt trận Tổ quốc, chăm lo đời sống vật chất, tinh thần của nhân dân."},{"letter":"D","text":"Tăng cường giáo dục chính trị, xây dựng lực lượng vũ trang và hậu phương vững mạnh."}],"correct_letter":"B"},{"id":"ho-chi-minh-q56","number":7,"source_number":56,"text":"Giá trị thực tiễn của tư tưởng Hồ Chí Minh về xây dựng hậu phương chiến tranh được thể hiện ở phương án nào sau đây:","choices":[{"letter":"A","text":"Bảo vệ vững chắc miền Bắc xã hội chủ nghĩa và hoàn thành thống nhất đất nước."},{"letter":"B","text":"Xây dựng thành công thế trận quốc phòng toàn dân trong thời bình."},{"letter":"C","text":"Xây dựng Việt Bắc thành căn cứ địa, miền Bắc thành hậu phương lớn của miền Nam."},{"letter":"D","text":"Huy động sức người, sức của cho hai cuộc kháng chiến của dân tộc."}],"correct_letter":"C"},{"id":"ho-chi-minh-q63","number":8,"source_number":63,"text":"Theo tư tưởng Hồ Chí Minh, mối quan hệ hữu cơ giữa tiền tuyến và hậu phương chiến tranh được xác định như thế nào?","choices":[{"letter":"A","text":"Tiền tuyến và hậu phương gắn bó mật thiết, tác động qua lại lẫn nhau"},{"letter":"B","text":"Tiền tuyến quyết định tuyệt đối, hậu phương chỉ cung cấp sức người"},{"letter":"C","text":"Tiền tuyến và hậu phương độc lập tác chiến theo mục tiêu riêng"},{"letter":"D","text":"Hậu phương luôn đóng vai trò bị động trước mọi yêu cầu tác chiến"}],"correct_letter":"A"},{"id":"ho-chi-minh-q12","number":9,"source_number":12,"text":"Sức mạnh của quần chúng nhân dân theo Hồ Chí Minh bao gồm những yếu tố nào?","choices":[{"letter":"A","text":"Sức mạnh chính trị và sức mạnh quân sự của quần chúng."},{"letter":"B","text":"Sức mạnh của lực lượng chính trị và lực lượng vũ trang."},{"letter":"C","text":"Sức mạnh của khối đại đoàn kết và lực lượng ba thứ quân."},{"letter":"D","text":"Sức mạnh vật chất và sức mạnh tinh thần của quần chúng."}],"correct_letter":"D"},{"id":"ho-chi-minh-q108","number":10,"source_number":108,"text":"Theo Hồ Chí Minh, tên gọi “Đội Việt Nam tuyên truyền giải phóng quân” có ý nghĩa cốt lõi là gì?","choices":[{"letter":"A","text":"Chính trị và quân sự có vai trò ngang nhau"},{"letter":"B","text":"Chính trị trọng hơn quân sự"},{"letter":"C","text":"Quân sự trọng hơn chính trị"},{"letter":"D","text":"Tác chiến vũ trang là mục tiêu duy nhất"}],"correct_letter":"B"},{"id":"ho-chi-minh-q140","number":11,"source_number":140,"text":"Theo Hồ Chí Minh, biện pháp hàng đầu phát huy sức mạnh quần chúng nhân dân trong lĩnh vực quân sự là gì?","choices":[{"letter":"A","text":"Xác định mục tiêu, con đường cách mạng đúng đắn, hợp lòng dân"},{"letter":"B","text":"Thu hẹp vai trò của các tổ chức đoàn thể chính trị"},{"letter":"C","text":"Huy động tối đa tài sản đóng góp vào ngân sách quân sự"},{"letter":"D","text":"Áp dụng kỷ luật nghiêm ngặt đối với đời sống nhân dân"}],"correct_letter":"A"},{"id":"ho-chi-minh-q28","number":12,"source_number":28,"text":"Nội dung vận dụng tư tưởng Hồ Chí Minh về phát huy sức mạnh quần chúng nhân dân hiện nay gồm những vấn đề nào?","choices":[{"letter":"A","text":"Giáo dục lòng yêu nước, xây dựng lực lượng dự bị động viên hùng hậu."},{"letter":"B","text":"Xây dựng thế trận lòng dân, tăng cường tiềm lực quốc phòng, an ninh của đất nước."},{"letter":"C","text":"Nâng cao nhận thức về vai trò quần chúng, phát huy đại đoàn kết dân tộc, hoàn thiện pháp luật quốc phòng."},{"letter":"D","text":"Nâng cao cảnh giác cách mạng, xây dựng nền quốc phòng toàn dân vững mạnh."}],"correct_letter":"C"},{"id":"ho-chi-minh-q7","number":13,"source_number":7,"text":"Nội dung xây dựng quân đội vững mạnh toàn diện theo Hồ Chí Minh gồm những yếu tố nào?","choices":[{"letter":"A","text":"Tư tưởng vững, tổ chức chặt chẽ, đời sống bảo đảm, vũ khí trang bị tối tân."},{"letter":"B","text":"Chính trị vững, trang bị hiện đại, hậu cần đầy đủ, kỹ thuật giỏi, đời sống bảo đảm."},{"letter":"C","text":"Chính trị tư tưởng vững, tổ chức gọn mạnh, kỹ chiến thuật giỏi, kỷ luật nghiêm, sức khỏe tốt."},{"letter":"D","text":"Bản lĩnh chính trị vững, trình độ chuyên môn cao, tác phong chính quy, hậu cần mạnh."}],"correct_letter":"C"},{"id":"ho-chi-minh-q100","number":14,"source_number":100,"text":"Theo Hồ Chí Minh, việc xây dựng hậu phương chiến tranh nhất thiết phải gắn liền với vấn đề gì?","choices":[{"letter":"A","text":"Đóng cửa toàn bộ giao thương kinh tế nội địa"},{"letter":"B","text":"Tách rời hoàn toàn khỏi nhiệm vụ ở tiền tuyến"},{"letter":"C","text":"Thu hẹp quy mô chiến tranh vũ trang"},{"letter":"D","text":"Bảo vệ hậu phương chiến tranh"}],"correct_letter":"D"},{"id":"ho-chi-minh-q47","number":15,"source_number":47,"text":"Chọn phương án đúng về phương hướng xây dựng Quân đội nhân dân Việt Nam theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Xây dựng quân đội cách mạng, chính quy, tinh nhuệ, từng bước hiện đại."},{"letter":"B","text":"Xây dựng quân đội cách mạng, tinh nhuệ, hiện đại, chuyên nghiệp."},{"letter":"C","text":"Xây dựng quân đội cách mạng, chính quy, tinh nhuệ, kiêm chức."},{"letter":"D","text":"Xây dựng quân đội chính quy, tinh nhuệ, hiện đại ngay từ đầu."}],"correct_letter":"A"},{"id":"ho-chi-minh-q120","number":16,"source_number":120,"text":"Theo Hồ Chí Minh, mục tiêu chiến đấu cao nhất của Quân đội nhân dân Việt Nam là gì?","choices":[{"letter":"A","text":"Xây dựng tiềm lực quốc phòng độc lập với hệ thống chính trị"},{"letter":"B","text":"Tranh lại độc lập, thống nhất cho Tổ quốc, bảo vệ tự do, hạnh phúc của nhân dân"},{"letter":"C","text":"Giành ưu thế chiến lược tuyệt đối trước lực lượng đối phương"},{"letter":"D","text":"Mở rộng vùng kiểm soát quân sự sang các nước trong khu vực"}],"correct_letter":"B"},{"id":"ho-chi-minh-q104","number":17,"source_number":104,"text":"Chọn phương án đúng về điểm cốt lõi thể hiện tính nhân văn sâu sắc trong tư tưởng Hồ Chí Minh về bạo lực cách mạng:","choices":[{"letter":"A","text":"Ưu tiên đàm phán ngoại giao ngay cả khi chủ quyền lãnh thổ bị xâm phạm nghiêm trọng"},{"letter":"B","text":"Không sử dụng lực lượng chính trị khi các biện pháp quân sự đã phát huy tác dụng"},{"letter":"C","text":"Chủ động phát động tấn công quân sự ngay khi xuất hiện thời cơ thuận lợi"},{"letter":"D","text":"Tận dụng mọi khả năng hòa bình, chỉ dùng chiến tranh vũ trang khi không còn con đường nào khác"}],"correct_letter":"D"},{"id":"ho-chi-minh-q72","number":18,"source_number":72,"text":"Theo quan điểm của Hồ Chí Minh, lực lượng tiến hành bạo lực cách mạng của quần chúng nhân dân bao gồm những yếu tố nào?","choices":[{"letter":"A","text":"Lực lượng thanh niên xung phong và dân quân du kích"},{"letter":"B","text":"Lực lượng tự vệ ở địa phương và bộ đội thường trực"},{"letter":"C","text":"Lực lượng chính trị quần chúng và lực lượng vũ trang nhân dân"},{"letter":"D","text":"Lực lượng công nhân công xưởng và nông dân các địa phương"}],"correct_letter":"C"},{"id":"ho-chi-minh-q19","number":19,"source_number":19,"text":"Bản chất giai cấp công nhân của Quân đội ta thống nhất với tính nhân dân và tính dân tộc ở điểm nào?","choices":[{"letter":"A","text":"Quân đội tuyệt đối trung thành với Đảng và sẵn sàng chiến đấu, hy sinh."},{"letter":"B","text":"Quân đội từ nhân dân mà ra, vì nhân dân mà chiến đấu, không có lợi ích nào khác ngoài lợi ích của nhân dân."},{"letter":"C","text":"Quân đội có kỷ luật tự giác, nghiêm minh và nội bộ luôn đoàn kết."},{"letter":"D","text":"Quân đội mang tinh thần quốc tế vô sản trong sáng, chân chính."}],"correct_letter":"B"},{"id":"ho-chi-minh-q70","number":20,"source_number":70,"text":"Hoàn chỉnh luận điểm của Hồ Chí Minh trong Thư gửi lớp cán bộ cung cấp, (6/1951): “Cung cấp đủ súng đạn, đủ cơm áo cho bộ đội thì bộ đội mới đánh thắng trận, điều đó rất rõ ràng dễ hiểu. Nhưng để làm cho đúng, thì phải có một chính sách rõ rệt, …”","choices":[{"letter":"A","text":"một tư tưởng thấu suốt."},{"letter":"B","text":"một kế hoạch đầy đủ."},{"letter":"C","text":"một đội ngũ vững vàng."},{"letter":"D","text":"một chủ nghĩa chắc chắn."}],"correct_letter":"A"},{"id":"ho-chi-minh-q35","number":21,"source_number":35,"text":"Chọn phương án đúng về giá trị lý luận xây dựng Quân đội nhân dân Việt Nam của Hồ Chí Minh:","choices":[{"letter":"A","text":"Làm phong phú học thuyết Mác - Lênin về quân đội; là cơ sở để Đảng xác định đường lối xây dựng quân đội."},{"letter":"B","text":"Là sự tổng kết thực tiễn xây dựng quân đội trong hai cuộc kháng chiến chống Pháp, chống Mỹ."},{"letter":"C","text":"Là sự vận dụng sáng tạo kinh nghiệm xây dựng quân đội của các nước xã hội chủ nghĩa."},{"letter":"D","text":"Là sự kế thừa truyền thống xây dựng quân đội của dân tộc qua các thời kỳ lịch sử."}],"correct_letter":"A"},{"id":"ho-chi-minh-q6","number":22,"source_number":6,"text":"Chọn phương án đúng về cơ sở tư tưởng, lý luận hình thành tư tưởng bạo lực cách mạng của Hồ Chí Minh:","choices":[{"letter":"A","text":"Tinh hoa quân sự phương Đông, quan điểm của Clausewitz và lý luận Mác - Lênin về chiến tranh nhân dân."},{"letter":"B","text":"Truyền thống dựng nước đi đôi với giữ nước, kinh nghiệm Công xã Paris và quan điểm Lênin về khởi nghĩa vũ trang."},{"letter":"C","text":"Tư tưởng bạo lực trong truyền thống quân sự Việt Nam, tinh hoa quân sự nhân loại và quan điểm Mác - Lênin về bạo lực cách mạng."},{"letter":"D","text":"Tư tưởng bạo lực trong truyền thống quân sự Việt Nam, kinh nghiệm xây dựng quân đội các nước xã hội chủ nghĩa và quan điểm Mác - Lênin."}],"correct_letter":"C"},{"id":"ho-chi-minh-q125","number":23,"source_number":125,"text":"Phong trào nào sau đây không phải là phong trào thi đua yêu nước tiêu biểu trong cuộc kháng chiến chống Mỹ, cứu nước?","choices":[{"letter":"A","text":"Phụ nữ ba đảm đang"},{"letter":"B","text":"Tuần lễ vàng"},{"letter":"C","text":"Mỗi người làm việc bằng hai - tất cả vì miền Nam ruột thịt"},{"letter":"D","text":"Thanh niên ba sẵn sàng"}],"correct_letter":"B"},{"id":"ho-chi-minh-q50","number":24,"source_number":50,"text":"Theo Hồ Chí Minh, muốn thắng địch trước hết phải làm gì?","choices":[{"letter":"A","text":"Tạo thế có lợi cho ta trên chiến trường."},{"letter":"B","text":"Chớp đúng thời cơ để tiến công địch."},{"letter":"C","text":"Thực hiện nghi binh, lừa địch để giành thắng lợi."},{"letter":"D","text":"Xây dựng, phát triển thực lực của ta về mọi mặt."}],"correct_letter":"D"},{"id":"ho-chi-minh-q39","number":25,"source_number":39,"text":"Chọn phương án đúng về tính chất của nền quốc phòng toàn dân theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Là nền quốc phòng của giai cấp công nhân, do Đảng lãnh đạo, vì nhiệm vụ cách mạng."},{"letter":"B","text":"Là nền quốc phòng của Đảng, do lực lượng vũ trang đảm nhiệm, vì sự ổn định chế độ."},{"letter":"C","text":"Là nền quốc phòng của dân, do dân, vì dân, huy động sức mạnh toàn dân tộc."},{"letter":"D","text":"Là nền quốc phòng của nhà nước, do quân đội xây dựng, vì an ninh quốc gia."}],"correct_letter":"C"},{"id":"ho-chi-minh-q78","number":26,"source_number":78,"text":"Chọn phương án đúng về nội dung sức mạnh của quần chúng nhân dân trong lĩnh vực quân sự theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Khả năng chi viện của bạn bè quốc tế"},{"letter":"B","text":"Tổng thể sức mạnh vật chất và tinh thần"},{"letter":"C","text":"Sức mạnh trang bị kỹ thuật quân sự"},{"letter":"D","text":"Tiềm lực kinh tế và tài chính quốc gia"}],"correct_letter":"B"},{"id":"ho-chi-minh-q48","number":27,"source_number":48,"text":"Chọn phương án đúng về cơ sở tư tưởng, lý luận hình thành tư tưởng Hồ Chí Minh về phát huy sức mạnh quần chúng nhân dân trong lĩnh vực quân sự:","choices":[{"letter":"A","text":"Truyền thống quân sự dân tộc, tinh hoa quân sự thế giới và quan điểm Mác - Lênin về quần chúng nhân dân."},{"letter":"B","text":"Truyền thống dựng nước đi đôi với giữ nước và kinh nghiệm Cách mạng Tháng Mười Nga."},{"letter":"C","text":"Kinh nghiệm Hồng quân Liên Xô và lý luận về chiến tranh nhân dân."},{"letter":"D","text":"Tinh hoa quân sự phương Đông và quan điểm của Tôn Tử về chiến tranh."}],"correct_letter":"A"},{"id":"ho-chi-minh-q65","number":28,"source_number":65,"text":"Hồ Chí Minh yêu cầu người làm tướng trong Quân đội nhân dân Việt Nam phải hội tụ đủ những phẩm chất đạo đức nào?","choices":[{"letter":"A","text":"Dũng - Trí - Nghĩa - Khiêm - Thành - Liêm"},{"letter":"B","text":"Cần - Kiệm - Liêm - Chính - Chí công vô tư"},{"letter":"C","text":"Trí - Tín - Nhân - Nghĩa - Dũng - Cần"},{"letter":"D","text":"Trí - Dũng - Nhân - Tín - Liêm - Trung"}],"correct_letter":"D"},{"id":"ho-chi-minh-q24","number":29,"source_number":24,"text":"Chọn phương án đúng về cơ sở tư tưởng, lý luận hình thành tư tưởng xây dựng nền quốc phòng toàn dân của Hồ Chí Minh:","choices":[{"letter":"A","text":"Truyền thống “ngụ binh ư nông” của dân tộc; tinh hoa quân sự phương Đông; lý luận Mác - Lênin về xây dựng quân đội kiểu mới."},{"letter":"B","text":"Truyền thống đánh giặc giữ nước của dân tộc; kinh nghiệm xây dựng quốc phòng của Liên Xô; lý luận Mác - Lênin về chiến tranh nhân dân."},{"letter":"C","text":"Truyền thống lấy nhỏ thắng lớn của dân tộc; kinh nghiệm quân sự của Trung Quốc; lý luận Mác - Lênin về khởi nghĩa vũ trang."},{"letter":"D","text":"Truyền thống dựng nước đi đôi với giữ nước; tinh hoa quân sự Đông - Tây; lý luận Mác - Lênin về bảo vệ Tổ quốc xã hội chủ nghĩa."}],"correct_letter":"D"},{"id":"ho-chi-minh-q1","number":30,"source_number":1,"text":"Chọn phương án đúng về quan điểm xây dựng Quân đội nhân dân Việt Nam theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Xây dựng quân đội vững mạnh toàn diện trên cơ sở vững mạnh về chính trị."},{"letter":"B","text":"Xây dựng quân đội vững mạnh toàn diện trên cơ sở vững mạnh về tổ chức, trang bị."},{"letter":"C","text":"Xây dựng quân đội vững mạnh toàn diện trên cơ sở vững mạnh về kỹ thuật, chiến thuật."},{"letter":"D","text":"Xây dựng quân đội vững mạnh toàn diện trên cơ sở vững mạnh về hậu cần, kỹ thuật."}],"correct_letter":"A"}]},{"number":6,"title":"Đề 6","questions":[{"id":"ho-chi-minh-q109","number":1,"source_number":109,"text":"Chọn phương án đúng về cấu trúc lực lượng vũ trang theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Quân đội thường trực chính quy và quân nhân xuất ngũ dự bị"},{"letter":"B","text":"Lực lượng chiến đấu cơ động và lực lượng cảnh giới biên phòng"},{"letter":"C","text":"Lục quân, Hải quân, Phòng không - Không quân"},{"letter":"D","text":"Ba thứ quân: bộ đội chủ lực, bộ đội địa phương và dân quân tự vệ"}],"correct_letter":"D"},{"id":"ho-chi-minh-q39","number":2,"source_number":39,"text":"Chọn phương án đúng về tính chất của nền quốc phòng toàn dân theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Là nền quốc phòng của Đảng, do lực lượng vũ trang đảm nhiệm, vì sự ổn định chế độ."},{"letter":"B","text":"Là nền quốc phòng của nhà nước, do quân đội xây dựng, vì an ninh quốc gia."},{"letter":"C","text":"Là nền quốc phòng của dân, do dân, vì dân, huy động sức mạnh toàn dân tộc."},{"letter":"D","text":"Là nền quốc phòng của giai cấp công nhân, do Đảng lãnh đạo, vì nhiệm vụ cách mạng."}],"correct_letter":"C"},{"id":"ho-chi-minh-q11","number":3,"source_number":11,"text":"Tư tưởng Hồ Chí Minh về bạo lực cách mạng đối lập với tư tưởng nào sau đây?","choices":[{"letter":"A","text":"Tư tưởng bất bạo động và tư tưởng bạo động, khủng bố, ám sát manh động."},{"letter":"B","text":"Tư tưởng quân sự chuyên nghiệp và tư tưởng chiến tranh toàn dân."},{"letter":"C","text":"Tư tưởng đánh nhanh thắng nhanh và tư tưởng chiến tranh trường kỳ."},{"letter":"D","text":"Tư tưởng tiến công chiến lược và tư tưởng phòng ngự chiến lược."}],"correct_letter":"A"},{"id":"ho-chi-minh-q58","number":4,"source_number":58,"text":"Bản chất giai cấp của Quân đội nhân dân Việt Nam theo tư tưởng Hồ Chí Minh là gì?","choices":[{"letter":"A","text":"Mang bản chất giai cấp công nhân và tính quốc tế vô sản."},{"letter":"B","text":"Mang bản chất giai cấp công nhân, tính nhân dân và tính dân tộc sâu sắc."},{"letter":"C","text":"Mang bản chất giai cấp công nhân và tính hiện đại, tinh nhuệ."},{"letter":"D","text":"Mang tính nhân dân và tính chính quy, không mang bản chất giai cấp."}],"correct_letter":"B"},{"id":"ho-chi-minh-q137","number":5,"source_number":137,"text":"Luận điểm nào sau đây không đúng với tư tưởng Hồ Chí Minh về thời điểm thích hợp để bắt đầu chiến tranh tự vệ?","choices":[{"letter":"A","text":"Khi địch buộc ta vào tình thế không còn con đường lựa chọn nào khác"},{"letter":"B","text":"Khi ta đã chuẩn bị chu đáo cả về đường lối chính trị và lực lượng vũ trang kháng chiến"},{"letter":"C","text":"Khi các giải pháp hòa bình để trì hoãn, ngăn chặn chiến tranh đã bị kẻ thù phá vỡ"},{"letter":"D","text":"Ngay khi kẻ thù vừa nhen nhóm ý định xâm lược nước ta"}],"correct_letter":"D"},{"id":"ho-chi-minh-q75","number":6,"source_number":75,"text":"Tên gọi “Quân đội nhân dân Việt Nam” chính thức được Chủ tịch Hồ Chí Minh đặt ra vào thời gian nào?","choices":[{"letter":"A","text":"Năm 1950"},{"letter":"B","text":"Năm 1944"},{"letter":"C","text":"Năm 1945"},{"letter":"D","text":"Năm 1954"}],"correct_letter":"A"},{"id":"ho-chi-minh-q89","number":7,"source_number":89,"text":"Luận điểm: “Cách mệnh là sự nghiệp của cả dân chúng chứ không phải việc một hai người” được Hồ Chí Minh khẳng định trong tác phẩm nào?","choices":[{"letter":"A","text":"Bản án chế độ thực dân Pháp"},{"letter":"B","text":"Lời kêu gọi toàn quốc kháng chiến"},{"letter":"C","text":"Đường cách mệnh"},{"letter":"D","text":"Tuyên ngôn độc lập"}],"correct_letter":"C"},{"id":"ho-chi-minh-q83","number":8,"source_number":83,"text":"Tư tưởng Hồ Chí Minh về xây dựng nền quốc phòng toàn dân được thể hiện qua lời dạy nào sau đây?","choices":[{"letter":"A","text":"Không có gì quý hơn độc lập, tự do"},{"letter":"B","text":"Các Vua Hùng đã có công dựng nước, Bác cháu ta phải cùng nhau giữ lấy nước"},{"letter":"C","text":"Nước Việt Nam là một, dân tộc Việt Nam là một"},{"letter":"D","text":"Trung với nước, hiếu với dân, nhiệm vụ nào cũng hoàn thành"}],"correct_letter":"B"},{"id":"ho-chi-minh-q96","number":9,"source_number":96,"text":"Theo Hồ Chí Minh, muốn dựa vững chắc vào nhân dân cần xây dựng lực lượng nào sau đây?","choices":[{"letter":"A","text":"Xây dựng các binh chủng kỹ thuật chuyên sâu"},{"letter":"B","text":"Xây dựng lực lượng vũ trang nhân dân ba thứ quân"},{"letter":"C","text":"Xây dựng lực lượng đặc nhiệm cơ động độc lập"},{"letter":"D","text":"Xây dựng mạng lưới an ninh ngầm trong xã hội"}],"correct_letter":"B"},{"id":"ho-chi-minh-q112","number":10,"source_number":112,"text":"Hồ Chí Minh đã ký với Pháp văn bản nào nhằm kéo dài thời gian chuẩn bị kháng chiến?","choices":[{"letter":"A","text":"Bản Tạm ước Việt - Pháp"},{"letter":"B","text":"Hiệp định sơ bộ Việt - Pháp"},{"letter":"C","text":"Thỏa ước quân sự Pháp - Hoa"},{"letter":"D","text":"Hiệp định Giơ-ne-vơ về Đông Dương"}],"correct_letter":"A"},{"id":"ho-chi-minh-q64","number":11,"source_number":64,"text":"Chọn phương án đúng về mục đích của bạo lực cách mạng ở Việt Nam theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Thay đổi triệt để quan hệ ngoại giao với các nước đế quốc"},{"letter":"B","text":"Khẳng định sức mạnh vượt trội của khối liên minh công nông"},{"letter":"C","text":"Tiêu diệt toàn bộ sinh lực đối phương bằng sức mạnh quân sự"},{"letter":"D","text":"Giành và giữ chính quyền, bảo vệ nền độc lập tự do của Tổ quốc"}],"correct_letter":"D"},{"id":"ho-chi-minh-q113","number":12,"source_number":113,"text":"Bác Hồ căn dặn cán bộ, chiến sĩ Đại đoàn 308: “Các Vua Hùng đã có công dựng nước, Bác cháu ta phải cùng nhau giữ lấy nước” trong bối cảnh nào?","choices":[{"letter":"A","text":"Trong Lễ tuyên thệ xuất quân mở màn chiến dịch Điện Biên Phủ năm 1954"},{"letter":"B","text":"Tại Hội nghị quân sự toàn quốc chuẩn bị mở chiến dịch Biên giới năm 1950"},{"letter":"C","text":"Tại Đền Hùng (Phú Thọ) năm 1954, trước khi đơn vị về tiếp quản Thủ đô"},{"letter":"D","text":"Khi về thăm khu căn cứ địa Tân Trào sau ngày Toàn quốc kháng chiến bùng nổ"}],"correct_letter":"C"},{"id":"ho-chi-minh-q127","number":13,"source_number":127,"text":"Chọn phương án đúng về lực lượng nòng cốt của nền quốc phòng toàn dân theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Lực lượng vũ trang nhân dân ba thứ quân"},{"letter":"B","text":"Lực lượng dự bị động viên tại các thành phố lớn"},{"letter":"C","text":"Bộ đội chủ lực kết hợp cùng các công ty quốc phòng"},{"letter":"D","text":"Đội ngũ cán bộ, công chức làm công tác quân sự địa phương"}],"correct_letter":"A"},{"id":"ho-chi-minh-q16","number":14,"source_number":16,"text":"Chọn phương án đúng về nhân tố cơ bản quyết định sức mạnh của nền quốc phòng toàn dân theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Sức mạnh kinh tế, vật chất."},{"letter":"B","text":"Sức mạnh chính trị, tư tưởng."},{"letter":"C","text":"Sức mạnh quân sự, vũ trang."},{"letter":"D","text":"Sức mạnh văn hóa, khoa học kỹ thuật."}],"correct_letter":"B"},{"id":"ho-chi-minh-q20","number":15,"source_number":20,"text":"Theo Hồ Chí Minh, “thế” được hiểu là gì?","choices":[{"letter":"A","text":"Tài chỉ huy và thao lược của đội ngũ tướng lĩnh."},{"letter":"B","text":"Thời cơ thuận lợi nhất để tiến công tiêu diệt địch."},{"letter":"C","text":"Sức mạnh vật chất, tinh thần của toàn dân tộc trong chiến tranh."},{"letter":"D","text":"Tổng thể hoàn cảnh, điều kiện cùng xu thế vận động, khả năng phát triển của các bên tham chiến."}],"correct_letter":"D"},{"id":"ho-chi-minh-q78","number":16,"source_number":78,"text":"Chọn phương án đúng về nội dung sức mạnh của quần chúng nhân dân trong lĩnh vực quân sự theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Khả năng chi viện của bạn bè quốc tế"},{"letter":"B","text":"Sức mạnh trang bị kỹ thuật quân sự"},{"letter":"C","text":"Tổng thể sức mạnh vật chất và tinh thần"},{"letter":"D","text":"Tiềm lực kinh tế và tài chính quốc gia"}],"correct_letter":"C"},{"id":"ho-chi-minh-q117","number":17,"source_number":117,"text":"Chọn phương án đúng về cơ sở lý luận phát huy sức mạnh của quần chúng nhân dân trong quân sự của Hồ Chí Minh:","choices":[{"letter":"A","text":"Quan niệm chiến lược của các học giả quân sự phương Tây thế kỷ XIX"},{"letter":"B","text":"Tư tưởng thần quyền về định mệnh trong chiến tranh"},{"letter":"C","text":"Quan điểm của chủ nghĩa Mác - Lênin: Quần chúng nhân dân là người sáng tạo ra lịch sử"},{"letter":"D","text":"Quan điểm siêu hình về sức mạnh của vũ khí công nghệ cao"}],"correct_letter":"C"},{"id":"ho-chi-minh-q40","number":18,"source_number":40,"text":"Theo Hồ Chí Minh, “mưu” được hiểu là gì?","choices":[{"letter":"A","text":"Sự kết hợp chặt chẽ giữa lực lượng chính trị và lực lượng vũ trang."},{"letter":"B","text":"Khả năng huy động tối đa sức người, sức của cho kháng chiến."},{"letter":"C","text":"Thế trận lòng dân vững chắc, rộng khắp trên toàn quốc."},{"letter":"D","text":"Chủ trương, quyết tâm chiến lược, chiến dịch, chiến đấu; tài chỉ huy, nghệ thuật nghi binh lừa địch."}],"correct_letter":"D"},{"id":"ho-chi-minh-q85","number":19,"source_number":85,"text":"Theo Hồ Chí Minh, biện pháp phát huy tiềm năng to lớn của nhân dân trong lĩnh vực quân sự là gì?","choices":[{"letter":"A","text":"Phổ biến kinh nghiệm quân sự của các nước phương Tây"},{"letter":"B","text":"Truyền bá hệ tư tưởng và lý luận cách mạng vào phong trào yêu nước"},{"letter":"C","text":"Mở rộng hoạt động tình báo quân sự trong dân gian"},{"letter":"D","text":"Đẩy mạnh ký kết các hiệp ước an ninh quốc tế"}],"correct_letter":"B"},{"id":"ho-chi-minh-q92","number":20,"source_number":92,"text":"Hồ Chí Minh coi nhân tố nào giữ vai trò quan trọng nhất khi xây dựng sức mạnh hậu phương chiến tranh?","choices":[{"letter":"A","text":"Thế trận lòng dân"},{"letter":"B","text":"Thế hiểm trở của địa hình căn cứ địa"},{"letter":"C","text":"Số lượng và chất lượng vũ khí hiện đại"},{"letter":"D","text":"Nguồn viện trợ lương thực từ quốc tế"}],"correct_letter":"A"},{"id":"ho-chi-minh-q3","number":21,"source_number":3,"text":"Hồ Chí Minh khẳng định: Độc lập, tự do chỉ có thể giành được bằng phương pháp nào sau đây?","choices":[{"letter":"A","text":"Bằng đấu tranh chính trị kết hợp với sự giúp đỡ của lực lượng quốc tế."},{"letter":"B","text":"Bằng bạo lực cách mạng của quần chúng nhân dân."},{"letter":"C","text":"Bằng con đường thương lượng, đàm phán trên cơ sở giữ vững nguyên tắc."},{"letter":"D","text":"Bằng việc xây dựng lực lượng chính trị vững mạnh mà không cần vũ trang."}],"correct_letter":"B"},{"id":"ho-chi-minh-q54","number":22,"source_number":54,"text":"Cơ sở tư tưởng, lý luận hình thành tư tưởng Hồ Chí Minh về nghệ thuật quân sự:","choices":[{"letter":"A","text":"Nghệ thuật quân sự dân tộc, tinh hoa nghệ thuật quân sự thế giới và học thuyết quân sự Mác - Lênin."},{"letter":"B","text":"Kinh nghiệm chiến tranh du kích và lý luận về chiến tranh nhân dân của Việt Nam."},{"letter":"C","text":"Binh pháp Tôn Tử, nghệ thuật tác chiến của Napoléon và kinh nghiệm quân sự Trung Quốc."},{"letter":"D","text":"Truyền thống lấy nhỏ thắng lớn của dân tộc và kinh nghiệm xây dựng Hồng quân Liên Xô."}],"correct_letter":"A"},{"id":"ho-chi-minh-q34","number":23,"source_number":34,"text":"Chọn phương án đúng về tư tưởng xuyên suốt trong chỉ đạo chiến lược trong nghệ thuật quân sự của Hồ Chí Minh:","choices":[{"letter":"A","text":"Lấy tác chiến chiến dịch làm phương thức chủ yếu để kết thúc chiến tranh."},{"letter":"B","text":"Đánh nhanh thắng nhanh trong mọi điều kiện, hoàn cảnh của chiến tranh."},{"letter":"C","text":"Nắm vững tư tưởng chiến lược tiến công, giành và giữ quyền chủ động."},{"letter":"D","text":"Giữ thế phòng ngự chiến lược là chủ yếu, chỉ tiến công khi đủ điều kiện."}],"correct_letter":"C"},{"id":"ho-chi-minh-q122","number":24,"source_number":122,"text":"Hoàn chỉnh luận điểm của Hồ Chí Minh: “… thì không quân lính nào, súng ống nào chống lại nổi”.","choices":[{"letter":"A","text":"Thực lực mạnh."},{"letter":"B","text":"Quân đội mạnh."},{"letter":"C","text":"Binh lính mạnh."},{"letter":"D","text":"Dân khí mạnh."}],"correct_letter":"D"},{"id":"ho-chi-minh-q131","number":25,"source_number":131,"text":"Để tiếp thu tinh hoa và phát triển nghệ thuật tác chiến, Hồ Chí Minh đã trực tiếp dịch và xuất bản tác phẩm quân sự cổ đại nào?","choices":[{"letter":"A","text":"Tam lược Hoàng Thạch Công"},{"letter":"B","text":"Binh pháp Tôn Tử"},{"letter":"C","text":"Binh thư yếu lược"},{"letter":"D","text":"Lục thao Khương Tử Nha"}],"correct_letter":"B"},{"id":"ho-chi-minh-q48","number":26,"source_number":48,"text":"Chọn phương án đúng về cơ sở tư tưởng, lý luận hình thành tư tưởng Hồ Chí Minh về phát huy sức mạnh quần chúng nhân dân trong lĩnh vực quân sự:","choices":[{"letter":"A","text":"Truyền thống quân sự dân tộc, tinh hoa quân sự thế giới và quan điểm Mác - Lênin về quần chúng nhân dân."},{"letter":"B","text":"Truyền thống dựng nước đi đôi với giữ nước và kinh nghiệm Cách mạng Tháng Mười Nga."},{"letter":"C","text":"Kinh nghiệm Hồng quân Liên Xô và lý luận về chiến tranh nhân dân."},{"letter":"D","text":"Tinh hoa quân sự phương Đông và quan điểm của Tôn Tử về chiến tranh."}],"correct_letter":"A"},{"id":"ho-chi-minh-q68","number":27,"source_number":68,"text":"Hồ Chí Minh chủ trương xây dựng nền quốc phòng Việt Nam mang tính chất cơ bản nào sau đây?","choices":[{"letter":"A","text":"Liên minh, bảo trợ và vũ trang hiện đại"},{"letter":"B","text":"Tiên tiến, đậm đà bản sắc dân tộc"},{"letter":"C","text":"Dân tộc, khoa học, đại chúng"},{"letter":"D","text":"Toàn dân, toàn diện, độc lập, tự chủ"}],"correct_letter":"D"},{"id":"ho-chi-minh-q45","number":28,"source_number":45,"text":"Chọn phương án đúng về giá trị lý luận tư tưởng Hồ Chí Minh về bạo lực cách mạng:","choices":[{"letter":"A","text":"Là sự kế thừa hoàn toàn tư tưởng bạo lực cách mạng của chủ nghĩa Mác - Lênin vào điều kiện Việt Nam."},{"letter":"B","text":"Là sự kết hợp giữa truyền thống quân sự phương Đông và phương Tây trong điều kiện Việt Nam."},{"letter":"C","text":"Là bước phát triển mới về chất tư tưởng bạo lực của dân tộc; bổ sung, phát triển học thuyết quân sự Mác - Lênin."},{"letter":"D","text":"Là sự tổng kết thực tiễn hai cuộc kháng chiến chống Pháp và chống Mỹ cứu nước của dân tộc."}],"correct_letter":"C"},{"id":"ho-chi-minh-q42","number":29,"source_number":42,"text":"Theo Hồ Chí Minh, xây dựng hậu phương chiến tranh phải gắn với nội dung nào?","choices":[{"letter":"A","text":"Phải gắn với tăng cường tiềm lực kinh tế của đất nước."},{"letter":"B","text":"Phải gắn với phát triển văn hóa, giáo dục toàn dân."},{"letter":"C","text":"Phải gắn với xây dựng lực lượng chính trị của quần chúng."},{"letter":"D","text":"Phải gắn xây dựng với bảo vệ và phát triển hậu phương."}],"correct_letter":"D"},{"id":"ho-chi-minh-q53","number":30,"source_number":53,"text":"Lựa chọn phương án đúng về giá trị thực tiễn của tư tưởng phát huy sức mạnh quần chúng nhân dân trong lĩnh vực quân sự:","choices":[{"letter":"A","text":"Chỉ huy động nguồn lực cho chiến tranh, không gắn với xây dựng quốc phòng toàn dân."},{"letter":"B","text":"Tạo sức mạnh to lớn trong giành chính quyền, hai cuộc kháng chiến và xây dựng thế trận quốc phòng toàn dân."},{"letter":"C","text":"Chỉ xây dựng thành công lực lượng vũ trang ba thứ quân và bảo vệ miền Bắc."},{"letter":"D","text":"Chỉ tạo sức mạnh trong giai đoạn đánh thắng hai cuộc kháng chiến và thống nhất đất nước."}],"correct_letter":"B"}]},{"number":7,"title":"Đề 7","questions":[{"id":"ho-chi-minh-q132","number":1,"source_number":132,"text":"Theo Hồ Chí Minh, khái niệm “thế” trong đấu tranh quân sự được hiểu như thế nào?","choices":[{"letter":"A","text":"Thế tổ chức, bố trí, triển khai lực lượng và vũ khí trang bị trên chiến trường nhằm phát huy cao nhất sức mạnh chiến đấu"},{"letter":"B","text":"Môi trường thời tiết khí hậu thuận lợi để quân đội xuất kích tiến công"},{"letter":"C","text":"Thế áp đảo tuyệt đối về số lượng phương tiện vũ khí so với đối phương"},{"letter":"D","text":"Ưu thế ngoại giao quốc tế của đất nước trước khi mở màn chiến dịch"}],"correct_letter":"A"},{"id":"ho-chi-minh-q24","number":2,"source_number":24,"text":"Chọn phương án đúng về cơ sở tư tưởng, lý luận hình thành tư tưởng xây dựng nền quốc phòng toàn dân của Hồ Chí Minh:","choices":[{"letter":"A","text":"Truyền thống lấy nhỏ thắng lớn của dân tộc; kinh nghiệm quân sự của Trung Quốc; lý luận Mác - Lênin về khởi nghĩa vũ trang."},{"letter":"B","text":"Truyền thống “ngụ binh ư nông” của dân tộc; tinh hoa quân sự phương Đông; lý luận Mác - Lênin về xây dựng quân đội kiểu mới."},{"letter":"C","text":"Truyền thống đánh giặc giữ nước của dân tộc; kinh nghiệm xây dựng quốc phòng của Liên Xô; lý luận Mác - Lênin về chiến tranh nhân dân."},{"letter":"D","text":"Truyền thống dựng nước đi đôi với giữ nước; tinh hoa quân sự Đông - Tây; lý luận Mác - Lênin về bảo vệ Tổ quốc xã hội chủ nghĩa."}],"correct_letter":"D"},{"id":"ho-chi-minh-q28","number":3,"source_number":28,"text":"Nội dung vận dụng tư tưởng Hồ Chí Minh về phát huy sức mạnh quần chúng nhân dân hiện nay gồm những vấn đề nào?","choices":[{"letter":"A","text":"Nâng cao cảnh giác cách mạng, xây dựng nền quốc phòng toàn dân vững mạnh."},{"letter":"B","text":"Giáo dục lòng yêu nước, xây dựng lực lượng dự bị động viên hùng hậu."},{"letter":"C","text":"Nâng cao nhận thức về vai trò quần chúng, phát huy đại đoàn kết dân tộc, hoàn thiện pháp luật quốc phòng."},{"letter":"D","text":"Xây dựng thế trận lòng dân, tăng cường tiềm lực quốc phòng, an ninh của đất nước."}],"correct_letter":"C"},{"id":"ho-chi-minh-q101","number":4,"source_number":101,"text":"Theo tư tưởng Hồ Chí Minh, hình thức cơ bản của bạo lực cách mạng ở nước ta trong chiến tranh giải phóng là gì?","choices":[{"letter":"A","text":"Đấu tranh ngoại giao đơn thuần trên các diễn đàn quốc tế"},{"letter":"B","text":"Kết hợp đấu tranh quân sự với đấu tranh chính trị và binh vận"},{"letter":"C","text":"Khởi nghĩa vũ trang thuần túy của bộ đội chủ lực trên chiến trường"},{"letter":"D","text":"Đấu tranh kinh tế kết hợp với phong trào công nhân quốc tế"}],"correct_letter":"B"},{"id":"ho-chi-minh-q115","number":5,"source_number":115,"text":"Luận điểm nào sau đây không phải là nội dung tư tưởng nghệ thuật quân sự của Hồ Chí Minh?","choices":[{"letter":"A","text":"Chủ động đánh vào lòng người đối phương, kết hợp tác chiến với địch vận"},{"letter":"B","text":"Khởi đầu và kết thúc chiến tranh đúng lúc"},{"letter":"C","text":"Nắm vững tư tưởng chiến lược tiến công, giành và giữ quyền chủ động"},{"letter":"D","text":"Xây dựng Quân đội mang bản chất giai cấp công nhân, tính nhân dân, tính dân tộc sâu sắc"}],"correct_letter":"D"},{"id":"ho-chi-minh-q43","number":6,"source_number":43,"text":"Nội dung nào sau đây thuộc nghệ thuật chỉ đạo chiến tranh trong tư tưởng Hồ Chí Minh?","choices":[{"letter":"A","text":"Xây dựng hậu phương chiến tranh vững mạnh về chính trị, kinh tế, quân sự."},{"letter":"B","text":"Chủ động đánh vào lòng người đối phương, kết hợp chặt chẽ tác chiến với địch vận."},{"letter":"C","text":"Xây dựng quân đội vững mạnh toàn diện về chính trị, tổ chức, kỹ thuật."},{"letter":"D","text":"Xây dựng nền quốc phòng toàn dân gắn với an ninh nhân dân."}],"correct_letter":"B"},{"id":"ho-chi-minh-q60","number":7,"source_number":60,"text":"Nội dung cốt lõi trong xây dựng hậu phương vững mạnh về chính trị theo tư tưởng Hồ Chí Minh là gì?","choices":[{"letter":"A","text":"Xây dựng chính quyền và các đoàn thể nhân dân ở cơ sở."},{"letter":"B","text":"Tổ chức phong trào thi đua yêu nước rộng khắp trong nhân dân."},{"letter":"C","text":"Xây dựng thế trận lòng dân, củng cố niềm tin của nhân dân vào Đảng, Nhà nước."},{"letter":"D","text":"Xây dựng tổ chức đảng vững mạnh ở các cấp, các địa phương."}],"correct_letter":"C"},{"id":"ho-chi-minh-q29","number":8,"source_number":29,"text":"Giá trị thực tiễn của tư tưởng Hồ Chí Minh về xây dựng nền quốc phòng toàn dân được thể hiện ở đâu?","choices":[{"letter":"A","text":"Bảo vệ vững chắc miền Bắc, xây dựng miền Bắc thành hậu phương lớn cho cách mạng miền Nam."},{"letter":"B","text":"Giúp đánh thắng thực dân Pháp, hoàn thành xây dựng chủ nghĩa xã hội trên phạm vi cả nước."},{"letter":"C","text":"Bảo vệ vững chắc miền Nam, xây dựng miền Nam thành căn cứ địa cho cách mạng miền Bắc."},{"letter":"D","text":"Giúp ngăn chặn mọi cuộc tiến công của đối phương, tránh phải tiến hành chiến tranh giải phóng."}],"correct_letter":"A"},{"id":"ho-chi-minh-q114","number":9,"source_number":114,"text":"Địa bàn được xác định là hậu phương lớn của tiền tuyến miền Nam trong cuộc kháng chiến chống Mỹ, cứu nước là:","choices":[{"letter":"A","text":"Tây Nguyên"},{"letter":"B","text":"Vùng giải phóng Hạ Lào"},{"letter":"C","text":"Miền Bắc"},{"letter":"D","text":"Miền Trung"}],"correct_letter":"C"},{"id":"ho-chi-minh-q73","number":10,"source_number":73,"text":"Chọn phương án đúng về hình thức tổ chức huy động sức mạnh của toàn thể nhân dân đánh giặc là gì?","choices":[{"letter":"A","text":"Tập trung toàn bộ dân cư vào các căn cứ quân sự"},{"letter":"B","text":"Tổ chức các đội bảo an tư nhân tại làng xã"},{"letter":"C","text":"Thành lập các liên minh phòng thủ với lân bang"},{"letter":"D","text":"Xây dựng nền quốc phòng toàn dân và thế trận chiến tranh nhân dân"}],"correct_letter":"D"},{"id":"ho-chi-minh-q121","number":11,"source_number":121,"text":"Luận điểm nào sau đây thể hiện sâu sắc tư tưởng Hồ Chí Minh về sự kết hợp giữa kinh tế và quốc phòng?","choices":[{"letter":"A","text":"Chỉ đầu tư cho công nghiệp quốc phòng, giảm bớt công nghiệp dân sinh"},{"letter":"B","text":"Vừa kháng chiến vừa kiến quốc, thực túc thì binh cường"},{"letter":"C","text":"Phát triển kinh tế thị trường tự do tách biệt hẳn nhiệm vụ bảo vệ Tổ quốc"},{"letter":"D","text":"Dừng phát triển sản xuất để ưu tiên toàn bộ cho tác chiến phòng ngự"}],"correct_letter":"B"},{"id":"ho-chi-minh-q25","number":12,"source_number":25,"text":"Chọn phương án đúng về sự cần thiết phải phát huy sức mạnh quần chúng nhân dân trong lĩnh vực quân sự:","choices":[{"letter":"A","text":"Vai trò của quần chúng trong hoạt động quân sự, bài học lịch sử dân tộc và mục tiêu, nhiệm vụ cách mạng Việt Nam."},{"letter":"B","text":"Âm mưu chống phá của các thế lực thù địch và nhiệm vụ bảo vệ Tổ quốc."},{"letter":"C","text":"Yêu cầu xây dựng nền quốc phòng toàn dân và đặc điểm của chiến tranh hiện đại."},{"letter":"D","text":"Vai trò của nhân tố chính trị - tinh thần và kinh nghiệm cách mạng thế giới."}],"correct_letter":"A"},{"id":"ho-chi-minh-q106","number":13,"source_number":106,"text":"Theo tư tưởng Hồ Chí Minh, sức mạnh chính trị - tư tưởng giữ vai trò như thế nào đối với nền quốc phòng toàn dân?","choices":[{"letter":"A","text":"Là thành tố quan trọng"},{"letter":"B","text":"Là nền tảng vật chất"},{"letter":"C","text":"Là yếu tố trực tiếp quyết định"},{"letter":"D","text":"Là nhân tố cơ bản quyết định"}],"correct_letter":"D"},{"id":"ho-chi-minh-q128","number":14,"source_number":128,"text":"Theo quan điểm của Hồ Chí Minh, sức mạnh kinh tế giữ vị trí nào trong cấu trúc sức mạnh của nền quốc phòng toàn dân?","choices":[{"letter":"A","text":"Là nền tảng vật chất"},{"letter":"B","text":"Là yếu tố trực tiếp quyết định"},{"letter":"C","text":"Là nhân tố cơ bản quyết định"},{"letter":"D","text":"Là lực lượng xung kích tại chỗ"}],"correct_letter":"A"},{"id":"ho-chi-minh-q133","number":15,"source_number":133,"text":"Theo Hồ Chí Minh, biện pháp hiệu quả nhất để xây dựng hậu phương kháng chiến vững mạnh là:","choices":[{"letter":"A","text":"Áp dụng các biện pháp trừng phạt kinh tế nghiêm khắc"},{"letter":"B","text":"Tuyệt đối ưu tiên sản xuất các mặt hàng công nghiệp nặng"},{"letter":"C","text":"Tổ chức tốt phong trào thi đua ái quốc"},{"letter":"D","text":"Tăng cường huy động đóng góp tài chính bắt buộc"}],"correct_letter":"C"},{"id":"ho-chi-minh-q82","number":16,"source_number":82,"text":"Đảng Cộng sản Việt Nam xác định vị trí của Chiến lược quốc phòng Việt Nam hiện nay như thế nào?","choices":[{"letter":"A","text":"Là một bộ phận độc lập nằm ngoài Chiến lược bảo vệ Tổ quốc"},{"letter":"B","text":"Là bộ phận chủ đạo, cụ thể hóa Chiến lược bảo vệ Tổ quốc"},{"letter":"C","text":"Là bản kế hoạch kỹ thuật thuần túy của các quân chủng"},{"letter":"D","text":"Là quy định hành chính điều hành tác chiến của các địa phương"}],"correct_letter":"B"},{"id":"ho-chi-minh-q91","number":17,"source_number":91,"text":"Nội dung cốt lõi của nghệ thuật quân sự phát huy sức mạnh tổng hợp theo Hồ Chí Minh là gì?","choices":[{"letter":"A","text":"Động viên toàn dân đánh giặc, đánh giặc toàn diện; kết hợp sức mạnh dân tộc với sức mạnh thời đại"},{"letter":"B","text":"Huy động toàn bộ lực lượng công nghiệp nặng phục vụ chế tạo trang bị quân sự"},{"letter":"C","text":"Đẩy mạnh tổng động viên thanh niên nhập ngũ và tập trung mua sắm vũ khí hiện đại"},{"letter":"D","text":"Nhất loạt mở các chiến dịch quy mô lớn trên toàn bộ các hướng chiến lược"}],"correct_letter":"A"},{"id":"ho-chi-minh-q12","number":18,"source_number":12,"text":"Sức mạnh của quần chúng nhân dân theo Hồ Chí Minh bao gồm những yếu tố nào?","choices":[{"letter":"A","text":"Sức mạnh của khối đại đoàn kết và lực lượng ba thứ quân."},{"letter":"B","text":"Sức mạnh chính trị và sức mạnh quân sự của quần chúng."},{"letter":"C","text":"Sức mạnh vật chất và sức mạnh tinh thần của quần chúng."},{"letter":"D","text":"Sức mạnh của lực lượng chính trị và lực lượng vũ trang."}],"correct_letter":"C"},{"id":"ho-chi-minh-q17","number":19,"source_number":17,"text":"Chọn phương án đúng về cơ sở thực tiễn hình thành tư tưởng Hồ Chí Minh về bạo lực cách mạng:","choices":[{"letter":"A","text":"Thực tiễn xây dựng căn cứ địa cách mạng; kinh nghiệm Công xã Paris; sự thất bại của các phong trào yêu nước theo khuynh hướng tư sản."},{"letter":"B","text":"Thực dân Pháp dùng bạo lực phản cách mạng cai trị Việt Nam; thực tiễn các phong trào yêu nước cuối thế kỷ XIX - đầu thế kỷ XX; kinh nghiệm các cuộc cách mạng trên thế giới."},{"letter":"C","text":"Thực tiễn kháng chiến chống Pháp và chống Mỹ; kinh nghiệm Cách mạng Tháng Mười Nga; truyền thống quân sự dân tộc."},{"letter":"D","text":"Thực tiễn cách mạng Việt Nam từ 1930 đến 1945; kinh nghiệm Hồng quân Liên Xô; quan điểm của Tôn Tử về chiến tranh."}],"correct_letter":"B"},{"id":"ho-chi-minh-q88","number":20,"source_number":88,"text":"Mục đích căn bản, xuyên suốt của nền quốc phòng toàn dân theo tư tưởng Hồ Chí Minh là gì?","choices":[{"letter":"A","text":"Áp đặt vị thế ngoại giao áp đảo trên trường quốc tế"},{"letter":"B","text":"Răn đe các quốc gia đối kháng bằng tiềm lực vũ khí công nghệ cao"},{"letter":"C","text":"Tìm kiếm cơ hội mở rộng ảnh hưởng quân sự sang các nước lân cận"},{"letter":"D","text":"Giữ vững hòa bình, tự vệ chính đáng và bảo vệ vững chắc độc lập, chủ quyền của Tổ quốc"}],"correct_letter":"D"},{"id":"ho-chi-minh-q98","number":21,"source_number":98,"text":"Chọn phương án đúng về nhiệm vụ trọng tâm khi vận dụng tư tưởng bạo lực cách mạng Hồ Chí Minh trong bảo vệ Tổ quốc hiện nay:","choices":[{"letter":"A","text":"Tách biệt hoàn toàn công tác quốc phòng khỏi quan hệ đối ngoại và kinh tế"},{"letter":"B","text":"Kết hợp chặt chẽ giữa phát triển kinh tế - xã hội với củng cố quốc phòng, an ninh"},{"letter":"C","text":"Tăng cường mua sắm các loại vũ khí hiện đại, giảm huấn luyện chính trị tư tưởng"},{"letter":"D","text":"Duy trì thế trận quân sự thường trực sẵn sàng tham chiến ở mọi khu vực biên giới"}],"correct_letter":"B"},{"id":"ho-chi-minh-q111","number":22,"source_number":111,"text":"Nội dung nào sau đây không thuộc tư tưởng Hồ Chí Minh về nghệ thuật quân sự?","choices":[{"letter":"A","text":"Xây dựng nền quốc phòng toàn dân, toàn diện"},{"letter":"B","text":"Nắm vững tư tưởng chiến lược tiến công, giành và giữ quyền chủ động"},{"letter":"C","text":"Tạo lực, lập thế, tranh thời, dùng mưu linh hoạt"},{"letter":"D","text":"Phát huy sức mạnh tổng hợp của toàn dân tộc"}],"correct_letter":"A"},{"id":"ho-chi-minh-q14","number":23,"source_number":14,"text":"Theo Hồ Chí Minh, xây dựng hậu phương vững mạnh về quân sự cần tập trung vào nội dung nào sau đây?","choices":[{"letter":"A","text":"Tăng cường khả năng phòng thủ ở hậu phương và chi viện cho tiền tuyến."},{"letter":"B","text":"Xây dựng lực lượng thường trực và lực lượng dự bị động viên hùng hậu."},{"letter":"C","text":"Xây dựng thế trận chiến tranh nhân dân vững chắc trên cả nước."},{"letter":"D","text":"Xây dựng lực lượng vũ trang ba thứ quân và nền quốc phòng toàn dân ở hậu phương."}],"correct_letter":"D"},{"id":"ho-chi-minh-q139","number":24,"source_number":139,"text":"Sau khi tiếp thu lý luận quân sự cổ đại phương Đông, Hồ Chí Minh đã biên soạn tài liệu nào để đào tạo đội ngũ cán bộ?","choices":[{"letter":"A","text":"Bát trận đồ ứng dụng trong chiến tranh hiện đại"},{"letter":"B","text":"Phép dùng binh của Tôn Tẫn"},{"letter":"C","text":"Cách huấn luyện cán bộ quân sự của Khổng Minh"},{"letter":"D","text":"Kinh nghiệm tổ chức quân cơ thời cổ"}],"correct_letter":"C"},{"id":"ho-chi-minh-q26","number":25,"source_number":26,"text":"Chọn phương án đúng về hình thức phát huy sức mạnh quần chúng nhân dân trong lĩnh vực quân sự theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Xây dựng bạo lực cách mạng, lực lượng vũ trang ba thứ quân, chiến tranh nhân dân và nền quốc phòng toàn dân."},{"letter":"B","text":"Xây dựng căn cứ địa cách mạng, thực hiện ba mũi giáp công và nổi dậy toàn dân."},{"letter":"C","text":"Xây dựng thế trận lòng dân, tăng cường công tác địch vận và binh vận."},{"letter":"D","text":"Xây dựng lực lượng chính trị của quần chúng và lấy đấu tranh chính trị làm chủ yếu."}],"correct_letter":"A"},{"id":"ho-chi-minh-q67","number":26,"source_number":67,"text":"Theo tư tưởng Hồ Chí Minh, sức mạnh ngoại giao có vai trò như thế nào trong sự nghiệp củng cố quốc phòng?","choices":[{"letter":"A","text":"Là yếu tố trực tiếp giải quyết xung đột"},{"letter":"B","text":"Là thành tố quan trọng"},{"letter":"C","text":"Là nền tảng vật chất cơ bản"},{"letter":"D","text":"Là nhân tố quyết định chiến trường"}],"correct_letter":"B"},{"id":"ho-chi-minh-q59","number":27,"source_number":59,"text":"Theo Hồ Chí Minh, “thời” được hiểu là gì?","choices":[{"letter":"A","text":"Thế bố trí lực lượng có lợi cho ta trên chiến trường."},{"letter":"B","text":"Sức mạnh tổng hợp của toàn dân tộc trong chiến tranh."},{"letter":"C","text":"Tình hình trong nước, khu vực, thế giới thuận lợi và thời điểm tiến công địch có lợi nhất."},{"letter":"D","text":"Nghệ thuật nghi binh, lừa địch trong tác chiến."}],"correct_letter":"C"},{"id":"ho-chi-minh-q55","number":28,"source_number":55,"text":"Chọn phương án đúng về động lực xây dựng nền quốc phòng toàn dân theo tư tưởng Hồ Chí Minh:","choices":[{"letter":"A","text":"Lấy động lực quân sự làm quyết định, xem lực lượng thường trực là nguồn sức mạnh chủ yếu."},{"letter":"B","text":"Dựa chủ yếu vào động lực bên ngoài, lấy viện trợ quốc tế làm điều kiện quyết định."},{"letter":"C","text":"Coi trọng động lực bên trong, không tiếp nhận thành tựu khoa học - kỹ thuật của thế giới."},{"letter":"D","text":"Phát huy cao độ động lực bên trong, đồng thời khai thác hiệu quả động lực bên ngoài."}],"correct_letter":"D"},{"id":"ho-chi-minh-q33","number":29,"source_number":33,"text":"Quan điểm Hồ Chí Minh về khởi đầu và kết thúc chiến tranh đúng lúc nhằm mục đích gì?","choices":[{"letter":"A","text":"Buộc đối phương phải rút quân ngay lập tức, không điều kiện."},{"letter":"B","text":"Kéo dài chiến tranh nhằm làm kiệt quệ kinh tế của đối phương."},{"letter":"C","text":"Tiêu diệt tối đa sinh lực địch trong thời gian ngắn."},{"letter":"D","text":"Giành thế chủ động chiến lược, tránh tổn thất không cần thiết."}],"correct_letter":"D"},{"id":"ho-chi-minh-q27","number":30,"source_number":27,"text":"Theo Hồ Chí Minh, “lực” được hiểu là gì?","choices":[{"letter":"A","text":"Xu thế vận động và khả năng phát triển của các bên tham chiến."},{"letter":"B","text":"Tổng thể hoàn cảnh, điều kiện khách quan của các bên tham chiến."},{"letter":"C","text":"Sức mạnh vật chất, tinh thần của cá nhân, đơn vị, địa phương và cả nước."},{"letter":"D","text":"Thế tổ chức, bố trí lực lượng có lợi trên chiến trường."}],"correct_letter":"C"}]}]},"banks":{"mac-lenin":[{"id":"mac-lenin-source-q1","number":1,"text":"Chọn phương án đúng theo quan điểm của chủ nghĩa Mác - Lênin về chiến tranh:","options":[{"letter":"A","text":"Chiến tranh là những cuộc xung đột tự phát ngẫu nhiên","is_correct":false},{"letter":"B","text":"Chiến tranh là một hiện tượng xã hội mang tính vĩnh viễn","is_correct":false},{"letter":"C","text":"Chiến tranh là những xung đột do mâu thuẫn không mang tính xã hội bản chất và tính chất chính trị xã hội của chiến tranh","is_correct":false},{"letter":"D","text":"Chiến tranh là một hiện tượng chính trị - xã hội có tính lịch sử","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q2","number":2,"text":"Theo V.I.Lênin, đánh giá tính chất chính trị - xã hội của chiến tranh phải đứng vững trên lập trường:","options":[{"letter":"A","text":"Giai cấp tư sản","is_correct":false},{"letter":"B","text":"Giai cấp nông dân","is_correct":false},{"letter":"C","text":"Giai cấp vô sản","is_correct":true},{"letter":"D","text":"Tầng lớp trí thức","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q3","number":3,"text":"Theo quan điểm của chủ nghĩa Mác - Lênin, luận điểm nào sau đây là sai:","options":[{"letter":"A","text":"Chiến tranh có thể thúc đẩy hoặc kìm hãm tiến trình thực hiện mục đích chính trị.","is_correct":false},{"letter":"B","text":"Chiến tranh không thể làm thay đổi tương quan so sánh lực lượng chính trị","is_correct":true},{"letter":"C","text":"Chiến tranh có thể khẳng định hoặc phủ định một đường lối chính trị","is_correct":false},{"letter":"D","text":"Chính trị quyết định bản chất và tính chất chính trị xã hội của chiến tranh","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q4","number":4,"text":"Theo quan điểm của chủ nghĩa Mác - Lênin, nguồn gốc sâu xa của sự ra đời quân đội là:","options":[{"letter":"A","text":"Sự phân chia giai cấp và đối kháng giai cấp","is_correct":false},{"letter":"B","text":"Sự xuất hiện nhà nước","is_correct":false},{"letter":"C","text":"Xuất hiện các tập đoàn người tranh giành lợi ích","is_correct":false},{"letter":"D","text":"Sự ra đời và tồn tại của chế độ chiếm hữu tư nhân về tư liệu sản xuất","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q5","number":5,"text":"Theo quan điểm của chủ nghĩa Mác-Lênin phương án nào là đúng nhất về nguồn gốc của chiến tranh:","options":[{"letter":"A","text":"Chiến tranh xuất hiện từ khi có chế độ tư hữu, giai cấp và nhà nước","is_correct":true},{"letter":"B","text":"Chiến tranh bắt nguồn ngay từ khi xuất hiện loài người","is_correct":false},{"letter":"C","text":"Chiến tranh bắt nguồn từ sự phát triển tất yếu khách quan của loài người","is_correct":false},{"letter":"D","text":"Chiến tranh bắt nguồn từ khi xuất hiện các hình thức tôn giáo","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q6","number":6,"text":"Nguồn gốc và nguyên nhân của chiến tranh được hiểu là:","options":[{"letter":"A","text":"Nguồn gốc là nguyên nhân của chiến tranh","is_correct":false},{"letter":"B","text":"Nguồn gốc là cái xét đến cùng, còn nguyên nhân là sự tác động lẫn nhau giữa điều kiện khách quan và nhân tố chủ quan trong những điều kiện nhất định","is_correct":true},{"letter":"C","text":"Chiến tranh chỉ có nguyên nhân, không có nguồn gốc","is_correct":false},{"letter":"D","text":"Chiến tranh chỉ có nguồn gốc, không có nguyên nhân","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q7","number":7,"text":"Trong quan niệm của C.Ph.Claudovít, đặc trưng cơ bản của chiến tranh là gì?","options":[{"letter":"A","text":"Đấu tranh vũ trang","is_correct":false},{"letter":"B","text":"Xung đột vũ trang","is_correct":false},{"letter":"C","text":"Sử dụng bạo lực","is_correct":true},{"letter":"D","text":"Sử dụng vũ trang","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q8","number":8,"text":"Tiêu chí nhận diện đúng nhất về cuộc chiến tranh chính nghĩa:","options":[{"letter":"A","text":"Là cuộc chiến tranh phòng ngự","is_correct":false},{"letter":"B","text":"Là cuộc chiến tranh do giai cấp đã lỗi thời, lạc hậu tiến hành","is_correct":false},{"letter":"C","text":"Là chiến tranh lạnh","is_correct":false},{"letter":"D","text":"Là cuộc chiến tranh bảo vệ quyền lợi chính đáng của dân tộc","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q9","number":9,"text":"Tính chất xã hội của chiến tranh phụ thuộc chính vào:","options":[{"letter":"A","text":"Mục đích chính trị của cuộc chiến","is_correct":true},{"letter":"B","text":"Trình độ tác chiến của cuộc chiến","is_correct":false},{"letter":"C","text":"Trình độ vũ khí của cuộc chiến","is_correct":false},{"letter":"D","text":"Trình độ nghệ thuật quân sự cuộc chiến","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q10","number":10,"text":"Ai là tác giả đầu tiên đưa ra tiêu chí phân chia kiểu chiến tranh:","options":[{"letter":"A","text":"C.Ph.Claudovít","is_correct":false},{"letter":"B","text":"V.I.Lênin","is_correct":true},{"letter":"C","text":"C.Mác","is_correct":false},{"letter":"D","text":"Ph.Ăngghen","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q11","number":11,"text":"Chọn phương án đúng về mối quan hệ giữa chiến tranh và chính trị:","options":[{"letter":"A","text":"Chính trị hỗ trợ chiến tranh","is_correct":false},{"letter":"B","text":"Chính trị quyết định chiến tranh","is_correct":true},{"letter":"C","text":"Chiến tranh quyết định thắng lợi chính trị","is_correct":false},{"letter":"D","text":"Chiến tranh hỗ trợ chính trị","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q12","number":12,"text":"Theo quan điểm chủ nghĩa Mác - Lênin về sự tồn tại của chiến tranh:","options":[{"letter":"A","text":"Chiến tranh sẽ mất đi khi con người phát triển cao về trình độ","is_correct":false},{"letter":"B","text":"Chiến tranh là hiện tượng vĩnh viễn không mất đi","is_correct":false},{"letter":"C","text":"Chiến tranh sẽ mất đi khi không còn chế độ tư hữu","is_correct":true},{"letter":"D","text":"Chiến tranh chỉ mất đi khi loài người không còn","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q13","number":13,"text":"Đâu là tiêu chuẩn quan trọng nhất để đánh giá tính chất chính trị - xã hội của chiến tranh:","options":[{"letter":"A","text":"Tiêu chuẩn luật pháp","is_correct":false},{"letter":"B","text":"Tiêu chuẩn kinh tế","is_correct":false},{"letter":"C","text":"Tiêu chuẩn đạo đức","is_correct":false},{"letter":"D","text":"Tiêu chuẩn chính trị","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q14","number":14,"text":"Bản chất của chiến tranh là:","options":[{"letter":"A","text":"Chiến tranh là thủ đoạn kinh tế","is_correct":false},{"letter":"B","text":"Chiến tranh là sự kế tục của chính trị bằng thủ đoạn bạo lực","is_correct":true},{"letter":"C","text":"Chiến tranh thể hiện quy luật sinh tồn của con người","is_correct":false},{"letter":"D","text":"Chiến tranh là bản chất của xã hội loài người","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q15","number":15,"text":"Đâu không phải là các kiểu chiến tranh trong thời đại ngày nay:","options":[{"letter":"A","text":"Chiến tranh giữa các dân tộc đấu tranh giành, giữ quyền độc lập, tự chủ với bọn thực dân, đế quốc","is_correct":false},{"letter":"B","text":"Chiến tranh lạnh","is_correct":true},{"letter":"C","text":"Chiến tranh giữa các nước tư bản chủ nghĩa với các nước xã hội chủ nghĩa","is_correct":false},{"letter":"D","text":"Nội chiến","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q16","number":16,"text":"Tiêu chuẩn nào không đánh giá tính chất xã hội của chiến tranh:","options":[{"letter":"A","text":"Tiêu chuẩn về mặt chính trị","is_correct":false},{"letter":"B","text":"Tiêu chuẩn về mặt đạo đức","is_correct":false},{"letter":"C","text":"Tiêu chuẩn về mặt pháp luật","is_correct":false},{"letter":"D","text":"Tiêu chuẩn về mặt truyền thống","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q17","number":17,"text":"Theo V.I.Lênin, nhân tố quyết định sự thành bại của chiến tranh là:","options":[{"letter":"A","text":"Nhân tố vũ khí trang bị","is_correct":false},{"letter":"B","text":"Nhân tố nghệ thuật quân sự","is_correct":false},{"letter":"C","text":"Nhân tố chính trị - tinh thần","is_correct":true},{"letter":"D","text":"Nhân tố tổ chức biên chế","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q18","number":18,"text":"Chọn phương án đúng về mục đích chính trị của chiến tranh nhân dân chống thực dân Pháp dưới sự lãnh đạo của Đảng:","options":[{"letter":"A","text":"Đánh đổ chính quyền tay sai, giành độc lập dân tộc và tiến lên chủ nghĩa xã hội","is_correct":true},{"letter":"B","text":"Giành độc lập dân tộc và thống nhất đất nước","is_correct":false},{"letter":"C","text":"Đánh đổ chính quyền tay sai, giành ruộng đất cho nhân dân","is_correct":false},{"letter":"D","text":"Bảo vệ toàn vẹn lãnh thổ của Tổ quốc","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q19","number":19,"text":"Theo quan điểm của chủ nghĩa Mác - Lênin, luận điểm nào sau đây là sai:","options":[{"letter":"A","text":"Chính trị quyết định mục đích chiến tranh","is_correct":false},{"letter":"B","text":"Chính trị quyết định tiến trình và kết cục chiến tranh","is_correct":false},{"letter":"C","text":"Chính trị quyết định","is_correct":false},{"letter":"D","text":"Chính trị và chiến tranh tách rời nhau","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q20","number":20,"text":"Chọn phương án đúng theo quan điểm của chủ nghĩa Mác - Lênin về quân đội:","options":[{"letter":"A","text":"Quân đội là hiện tượng xã hội vĩnh viễn","is_correct":false},{"letter":"B","text":"Quân đội ra đời do ý chí của thần linh tối cao","is_correct":false},{"letter":"C","text":"Quân đội là hiện tượng chính trị - xã hội có tính lịch sử","is_correct":true},{"letter":"D","text":"Quân đội tự ra đời ngẫu nhiên của đời sống xã hội","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q21","number":21,"text":"Chọn phương án sai: Tại sao trong xã hội cộng sản nguyên thủy lại không có quân đội?","options":[{"letter":"A","text":"Chưa xuất hiện giai cấp","is_correct":false},{"letter":"B","text":"Chưa xuất hiện đạo đức","is_correct":true},{"letter":"C","text":"Chưa xuất hiện nhà nước","is_correct":false},{"letter":"D","text":"Trình độ của lực lượng sản xuất rất thấp kém","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q22","number":22,"text":"Bản chất giai cấp của quân đội:","options":[{"letter":"A","text":"Là lực lượng chung của xã hội","is_correct":false},{"letter":"B","text":"Là lực lượng siêu giai cấp","is_correct":false},{"letter":"C","text":"Là lực lượng chung của quảng đại quần chúng","is_correct":false},{"letter":"D","text":"Là bản chất của giai cấp sinh ra và nuôi dưỡng quân đội","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q23","number":23,"text":"Đâu không phải là mục đích cho sự ra đời của Quân đội:","options":[{"letter":"A","text":"Bảo đảm an ninh chính trị và trật tự xã hội","is_correct":true},{"letter":"B","text":"Duy trì sự áp bức, bóc lột của giai cấp thống trị trong nước","is_correct":false},{"letter":"C","text":"Bảo vệ lãnh thổ quốc gia khỏi sự xâm lược từ bên ngoài","is_correct":false},{"letter":"D","text":"Xâm chiếm lãnh thổ, quốc gia khác để mở rộng ách áp bức, bóc lột","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q24","number":24,"text":"Lựa chọn phương án sai về nguồn gốc quân đội:","options":[{"letter":"A","text":"Nhà nước tổ chức ra quân đội","is_correct":false},{"letter":"B","text":"Xuất hiện cùng với sự xuất hiện của loài người","is_correct":true},{"letter":"C","text":"Các tổ chức chính trị có chức năng nhà nước","is_correct":false},{"letter":"D","text":"Các giai cấp, tập đoàn chính trị có chức năng nhà nước","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q25","number":25,"text":"Dấu hiệu đặc thù phân biệt quân đội với các tổ chức xã hội khác:","options":[{"letter":"A","text":"Được nhà nước nuôi dưỡng để bảo vệ lợi ích giai cấp thống trị","is_correct":false},{"letter":"B","text":"Nhằm mục đích bảo vệ nhà nước, giai cấp sinh ra nó","is_correct":false},{"letter":"C","text":"Được vũ trang, sử dụng vũ khí chuyên dùng và tiến hành chiến tranh","is_correct":true},{"letter":"D","text":"Được vũ trang để bảo vệ lợi ích giai cấp thống trị","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q26","number":26,"text":"Theo quan điểm của chủ nghĩa Mác - Lênin, nguồn gốc trực tiếp của sự ra đời quân đội là:","options":[{"letter":"A","text":"Bảo vệ lãnh thổ","is_correct":false},{"letter":"B","text":"Xuất hiện giai cấp và đối kháng giai cấp trong xã hội","is_correct":true},{"letter":"C","text":"Xâm chiếm lãnh thổ","is_correct":false},{"letter":"D","text":"Bảo vệ giai cấp cầm quyền","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q27","number":27,"text":"Theo quan điểm của chủ nghĩa Mác - Lênin, quân đội ra đời vào thời kỳ nào:","options":[{"letter":"A","text":"Thời kỳ tư bản chủ nghĩa","is_correct":false},{"letter":"B","text":"Thời kỳ công xã nguyên thủy","is_correct":false},{"letter":"C","text":"Thời kỳ phong kiến","is_correct":false},{"letter":"D","text":"Thời kỳ chiếm hữu nô lệ","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q28","number":28,"text":"Nguồn gốc sâu xa về sự ra đời và tồn tại của quân đội:","options":[{"letter":"A","text":"Sự xuất hiện giai cấp và phân chia giai cấp","is_correct":false},{"letter":"B","text":"Sự xuất hiện nhà nước","is_correct":false},{"letter":"C","text":"Sự ra đời và tồn tại của chế độ chiếm hữu tư nhân về tư liệu sản xuất","is_correct":true},{"letter":"D","text":"Để bảo vệ quyền và lợi ích của giai cấp thống trị","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q29","number":29,"text":"Đâu không phải là kiểu quân đội của nhà nước bóc lột:","options":[{"letter":"A","text":"Quân đội của nhà nước chiếm hữu nô lệ","is_correct":false},{"letter":"B","text":"Quân đội của phong kiến","is_correct":false},{"letter":"C","text":"Quân đội xã hội chủ nghĩa","is_correct":true},{"letter":"D","text":"Quân đội tư sản","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q30","number":30,"text":"Đâu là mục tiêu phát triển trong Văn kiện Đại hội XIV của Đảng ta:","options":[{"letter":"A","text":"Giữ vững môi trường hoà bình, ổn định; phát triển nhanh, bền vững đất nước và bảo vệ vững chắc Tổ quốc…","is_correct":true},{"letter":"B","text":"Xây dựng phát triển kinh tế và quốc phòng; xây dựng chủ nghĩa xã hội va bảo vệ Tổ quốc xã hội chủ nghĩa…","is_correct":false},{"letter":"C","text":"Xây dựng đất nước và bảo vệ Tổ quốc; xây dựng phát triển kinh tế và quốc phòng - an ninh nhân dân…","is_correct":false},{"letter":"D","text":"Xây dựng phát triển kinh tế và quốc phòng - an ninh nhân dân; phát triển nhanh, bền vững đất nước và bảo vệ vững chắc Tổ quốc…","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q31","number":31,"text":"Biểu hiện của tiềm lực chính trị, tinh thần là gì?","options":[{"letter":"A","text":"Là tính chất đồng thuận hay không đồng thuận của cơ cấu giai cấp - xã hội","is_correct":false},{"letter":"B","text":"Khả năng huy động kinh tế của đất nước","is_correct":false},{"letter":"C","text":"Ý chí, quyết tâm của nhân dân, của các lực lượng vũ trang nhân dân.","is_correct":true},{"letter":"D","text":"Khả năng bảo đảm vũ khí trang bị cho quân đội","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q32","number":32,"text":"Trong 4 mặt trận sau, mặt trận nào có ý nghĩa quyết định trực tiếp trong chiến tranh:","options":[{"letter":"A","text":"Mặt trận kinh tế","is_correct":false},{"letter":"B","text":"Mặt trận quân sự","is_correct":true},{"letter":"C","text":"Mặt trận ngoại giao","is_correct":false},{"letter":"D","text":"Mặt trận chính trị","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q33","number":33,"text":"Theo quan điểm của Đảng ta, yếu tố quyết định thắng lợi trên chiến trường là:","options":[{"letter":"A","text":"Vũ khí trang bị kỹ thuật hiện đại","is_correct":false},{"letter":"B","text":"Con người và vũ khí, con người là quyết định","is_correct":true},{"letter":"C","text":"Vũ khí hiện đại, nghệ thuật tác chiến cao","is_correct":false},{"letter":"D","text":"Vũ khí hiện đại và người chỉ huy giỏi","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q34","number":34,"text":"Sau cách mạng tháng 8/1945, đối tượng tác chiến của quân và dân ta là:","options":[{"letter":"A","text":"Quân đội Anh, quân đội Tưởng","is_correct":false},{"letter":"B","text":"Quân đội Nhật, quân đội Pháp","is_correct":false},{"letter":"C","text":"Quân đội Nhật, quân đội Tưởng","is_correct":false},{"letter":"D","text":"Quân đội Pháp xâm lược","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q35","number":35,"text":"Xây dựng quân đội phải tinh nhuệ trên các lĩnh vực:","options":[{"letter":"A","text":"Chính trị, tư tưởng, huấn luyện","is_correct":false},{"letter":"B","text":"Chính trị, tổ chức, kỹ chiến thuật","is_correct":true},{"letter":"C","text":"Chính trị, quân sự, hậu cần","is_correct":false},{"letter":"D","text":"Chính trị, an ninh, kỹ thuật","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q36","number":36,"text":"Đâu không phải là mục đích của chiến tranh Nhân dân Việt Nam:","options":[{"letter":"A","text":"Bảo vệ vững chắc độc lập, chủ quyền, thống nhất toàn vẹn lãnh thổ","is_correct":false},{"letter":"B","text":"Giữ vững ổn định chính trị và môi trường hòa bình","is_correct":false},{"letter":"C","text":"Bảo vệ quyền con người và chống khủng bố","is_correct":true},{"letter":"D","text":"Bảo vệ Đảng, nhà nước, nhân dân và chế độ xã hội chủ nghĩa","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q37","number":37,"text":"Đối tượng của chiến tranh nhân dân bảo vệ Tổ quốc Việt Nam xã hội chủ nghĩa là:","options":[{"letter":"A","text":"Chủ nghĩa đế quốc và các thế lực phản động","is_correct":true},{"letter":"B","text":"Chủ nghĩa đế quốc và chủ nghĩa ly khai","is_correct":false},{"letter":"C","text":"Các thế lực phản cách mạng trong và ngoài nước","is_correct":false},{"letter":"D","text":"Chủ nghĩa khủng bố quốc tế","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q38","number":38,"text":"Khi Mỹ xâm lược Việt Nam, Đảng ta nhận định:","options":[{"letter":"A","text":"Mỹ rất giàu và rất mạnh","is_correct":false},{"letter":"B","text":"Mỹ giàu nhưng không mạnh","is_correct":true},{"letter":"C","text":"Mỹ giàu và mạnh","is_correct":false},{"letter":"D","text":"Mỹ là nước giàu nhưng không thực sự mạnh","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q39","number":39,"text":"Đâu không phải là chủ trương xây dựng Quân đội Nhân dân Việt Nam hiện nay:","options":[{"letter":"A","text":"Xây dựng quân đội cách mạng","is_correct":false},{"letter":"B","text":"Xây dựng quân đội chính quy","is_correct":false},{"letter":"C","text":"Xây dựng quân đội chuyên nghiệp, thiện chiến","is_correct":true},{"letter":"D","text":"Xây dựng quân đội tinh nhuệ, hiện đại","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q40","number":40,"text":"Chọn phương án sai về bản chất sức mạnh quân sự quốc gia:","options":[{"letter":"A","text":"Mang bản chất thời đại","is_correct":true},{"letter":"B","text":"Mang bản chất giai cấp nhà nước tổ chức ra nó","is_correct":false},{"letter":"C","text":"Mang bản chất nhà nước tổ chức ra nó","is_correct":false},{"letter":"D","text":"Mang bản chất của nhà nước, giai cấp tổ chức ra và nuôi dưỡng nó","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q41","number":41,"text":"Đâu không phải là tiêu chí về mặt chính trị trong tính chất chính trị - xã hội của chiến tranh:","options":[{"letter":"A","text":"Mục đích và nội dung chính trị của cuộc chiến tranh","is_correct":false},{"letter":"B","text":"Tính hợp pháp hay không hợp pháp của cuộc chiến tranh","is_correct":true},{"letter":"C","text":"Vai trò, địa vị lịch sử của giai cấp lãnh đạo, tiến hành chiến tranh","is_correct":false},{"letter":"D","text":"Hoàn cảnh lịch sử nổ ra và diễn biến của chiến tranh","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q42","number":42,"text":"Lựa chọn phương án đúng về thái độ của chúng ta đối với chiến tranh:","options":[{"letter":"A","text":"Phản đối tất cả các cuộc chiến tranh trong lịch sử","is_correct":false},{"letter":"B","text":"Ủng hộ các cuộc chiến tranh chống áp bức, nô dịch","is_correct":false},{"letter":"C","text":"Phản đối các cuộc chiến tranh phản cách mạng","is_correct":false},{"letter":"D","text":"Ủng hộ chiến tranh chính nghĩa, phản đối chiến tranh phi nghĩa","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q43","number":43,"text":"Lựa chọn phương án sai về tính tất yếu xây dựng quân đội kiểu mới:","options":[{"letter":"A","text":"Bảo vệ vững chắc thành quả của cách mạng","is_correct":false},{"letter":"B","text":"Chống lại các thế lực phản cách mạng","is_correct":false},{"letter":"C","text":"Để mở rộng lãnh thổ và lợi ích","is_correct":true},{"letter":"D","text":"Từ tính chất thời đại quy định","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q44","number":44,"text":"Chọn phương án sai về bản chất của quân đội xã hội chủ nghĩa:","options":[{"letter":"A","text":"Công cụ bạo lực vũ trang của giai cấp công nhân","is_correct":false},{"letter":"B","text":"Công cụ bạo lực của nhà nước xã hội chủ nghĩa","is_correct":false},{"letter":"C","text":"Công cụ xâm chiếm lãnh thổ các quốc gia","is_correct":true},{"letter":"D","text":"Thực hiện nghĩa vụ quốc tế","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q45","number":45,"text":"Chọn phương án sai về đặc trưng bản chất quân đội xã hội chủ nghĩa:","options":[{"letter":"A","text":"Là đội quân thiện chiến","is_correct":true},{"letter":"B","text":"Sự lãnh đạo của đảng cộng sản đối với quân đội xã hội chủ nghĩa","is_correct":false},{"letter":"C","text":"Mang tính nhân dân","is_correct":false},{"letter":"D","text":"Mang tính quốc tế","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q46","number":46,"text":"Sức mạnh chiến đấu của quân đội được biểu hiện:","options":[{"letter":"A","text":"Nhà nước tổ chức và nuôi dưỡng","is_correct":false},{"letter":"B","text":"Vai trò lãnh đạo của giai cấp","is_correct":false},{"letter":"C","text":"Nền kinh tế và lòng dũng cảm của người lính","is_correct":false},{"letter":"D","text":"Trình độ, khả năng sẵn sàng chiến đấu và chiến đấu của quân đội","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q47","number":47,"text":"Chọn phương án sai: Quân đội mất đi khi nào?","options":[{"letter":"A","text":"Khi nhà nước bị tiêu vong","is_correct":false},{"letter":"B","text":"Khi tồn tại nhà nước xã hội chủ nghĩa","is_correct":true},{"letter":"C","text":"Trong chủ nghĩa cộng sản","is_correct":false},{"letter":"D","text":"Khi không còn giai cấp và đối kháng giai cấp","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q48","number":48,"text":"Bản chất giai cấp của quân đội nào không phải là kiểu quân đội của nhà nước bóc lột?","options":[{"letter":"A","text":"Bản chất giai cấp tư sản của quân đội","is_correct":false},{"letter":"B","text":"Bản chất giai cấp chủ nô của quân đội","is_correct":false},{"letter":"C","text":"Bản chất giai cấp vô sản của quân đội","is_correct":true},{"letter":"D","text":"Bản chất giai cấp địa chủ, phong kiến của quân đội","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q49","number":49,"text":"Lựa chọn phương án sai:","options":[{"letter":"A","text":"Bản chất giai cấp công nhân của quân đội ta thể hiện ở mục tiêu, lý tưởng chiến đấu","is_correct":false},{"letter":"B","text":"Bản chất giai cấp công nhân của quân đội ta thể hiện ở lịch sử của dân tộc","is_correct":true},{"letter":"C","text":"Bản chất giai cấp công nhân của quân đội ta thể hiện ở nguyên tắc tổ chức quân đội","is_correct":false},{"letter":"D","text":"Bản chất giai cấp công nhân của quân đội ta thể hiện ở hệ tư tưởng thống trị quân đội","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q50","number":50,"text":"Chọn phương án đúng về thời gian ra đời Quân đội Nhân dân Việt Nam:","options":[{"letter":"A","text":"Trước khi thành lập Nhà nước Việt Nam dân chủ cộng hòa","is_correct":true},{"letter":"B","text":"Sau khi thành lập nhà nước Việt Nam dân chủ cộng hòa","is_correct":false},{"letter":"C","text":"Cùng với thành lập nhà nước Việt Nam dân chủ cộng hòa","is_correct":false},{"letter":"D","text":"Cùng với sự ra đời nhà nước xã hội chủ nghĩa Việt Nam","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q51","number":51,"text":"Quân đội ta mang bản chất giai cấp công nhân đồng thời có:","options":[{"letter":"A","text":"Tính quần chúng sâu sắc","is_correct":false},{"letter":"B","text":"Tính phong phú đa dạng","is_correct":false},{"letter":"C","text":"Tính phổ biến, rộng rãi","is_correct":false},{"letter":"D","text":"Tính nhân dân, tính dân tộc sâu sắc","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q52","number":52,"text":"Chọn phương án đúng trong xây dựng tiềm lực quốc phòng:","options":[{"letter":"A","text":"“Tăng cường hiện đại vũ khí trang bị”","is_correct":false},{"letter":"B","text":"“Người trước, súng sau”","is_correct":true},{"letter":"C","text":"“Kết hợp xây dựng người và vũ khí”","is_correct":false},{"letter":"D","text":"“Tập trung xây dựng người lính cách mạng”","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q53","number":53,"text":"Cơ sở của sự phát triển số lượng, chất lượng vũ khí, trang bị kỹ thuật quân sự:","options":[{"letter":"A","text":"Trình độ phát triển kinh tế","is_correct":false},{"letter":"B","text":"Trình độ phát triển của lực lượng sản xuất, khoa học công nghệ","is_correct":true},{"letter":"C","text":"Mục đích chính trị của nhà nước","is_correct":false},{"letter":"D","text":"Mục đích chính trị của giai cấp","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q54","number":54,"text":"Chọn phương án đúng về mục đích phát triển vũ khí, trang bị kỹ thuật quân sự phụ thuộc vào:","options":[{"letter":"A","text":"Trình độ phát triển kinh tế","is_correct":false},{"letter":"B","text":"Trình độ phát triển của lực lượng sản xuất, khoa học công nghệ","is_correct":false},{"letter":"C","text":"Trình độ phát triển nghệ thuật quân sự","is_correct":false},{"letter":"D","text":"Tính chất của chế độ kinh tế, chính trị - xã hội","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q55","number":55,"text":"Dựa trên cơ sở nào V.I. Lênin xác định tính chất xã hội của chiến tranh?","options":[{"letter":"A","text":"Giai cấp lãnh đạo chiến tranh","is_correct":false},{"letter":"B","text":"Mục đích chính trị của chiến tranh","is_correct":true},{"letter":"C","text":"Chế độ xã hội tiến hành chiến tranh","is_correct":false},{"letter":"D","text":"Bản chất xã hội của chiến tranh","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q56","number":56,"text":"Lựa chọn phương án đúng: Thái độ của Việt Nam đối với chiến tranh là:","options":[{"letter":"A","text":"Ủng hộ chiến tranh chính nghĩa, phản đối chiến tranh phi nghĩa","is_correct":true},{"letter":"B","text":"Phản đối tất cả các cuộc chiến tranh","is_correct":false},{"letter":"C","text":"Ủng hộ các cuộc chiến tranh chống áp bức, nô dịch","is_correct":false},{"letter":"D","text":"Phản đối các cuộc chiến tranh phản cách mạng","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q57","number":57,"text":"Theo quan điểm của chủ nghĩa Mác-Lênin về bản chất của chiến tranh:","options":[{"letter":"A","text":"Là sự tiếp tục mục tiêu kinh tế bằng thủ đoạn bạo lực","is_correct":false},{"letter":"B","text":"Là sự tiếp tục của chính trị bằng bạo lực","is_correct":true},{"letter":"C","text":"Là thủ đoạn để đạt được chính trị của một giai cấp","is_correct":false},{"letter":"D","text":"Là thủ đoạn chính trị của một giai cấp","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q58","number":58,"text":"Lựa chọn phương án đúng về bản chất giai cấp của Quân đội Nhân dân Việt Nam:","options":[{"letter":"A","text":"Mang bản chất nông dân","is_correct":false},{"letter":"B","text":"Mang bản chất giai cấp công - nông do Đảng lãnh đạo","is_correct":false},{"letter":"C","text":"Mang bản chất nhân dân lao động Việt Nam","is_correct":false},{"letter":"D","text":"Mang bản chất giai cấp công nhân","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q59","number":59,"text":"Chọn phương án đúng về chức năng của Quân đội Nhân dân Việt Nam:","options":[{"letter":"A","text":"Chiến đấu, sẵn sàng chiến đấu","is_correct":false},{"letter":"B","text":"Chiến đấu, lao động sản xuất, tuyên truyền","is_correct":false},{"letter":"C","text":"Chiến đấu, công tác, lao động sản xuất","is_correct":true},{"letter":"D","text":"Chiến đấu và tham gia giữ gìn hòa bình khu vực","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q60","number":60,"text":"Tham gia xây dựng chính quyền cơ sở thể hiện chức năng nào của quân đội ta:","options":[{"letter":"A","text":"Chức năng chiến đấu","is_correct":false},{"letter":"B","text":"Chức năng công tác","is_correct":true},{"letter":"C","text":"Chức năng sản xuất","is_correct":false},{"letter":"D","text":"Chức năng huấn luyện II. GÓI CÂU HỎI TRẮC NGHIỆM","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q61","number":61,"text":"Điểm khác biệt chủ yếu giữa chiến tranh chống Pháp, chống Mỹ với các cuộc chiến tranh dựng nước và giữ nước trong lịch sử dân tộc ta là gì?","options":[{"letter":"A","text":"Mục đích chính trị","is_correct":false},{"letter":"B","text":"Phương tiện chiến tranh","is_correct":false},{"letter":"C","text":"Lực lượng tham gia","is_correct":false},{"letter":"D","text":"Giai cấp lãnh đạo","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q62","number":62,"text":"Lựa chọn phương án đúng theo quan điểm tư sản về tiêu chuẩn tính chất chính trị - xã hội của chiến tranh:","options":[{"letter":"A","text":"Tiêu chuẩn pháp quyền","is_correct":false},{"letter":"B","text":"Bên nào tiến hành chiến tranh trên địa phận nước mình là chính nghĩa và tiến hành chiến tranh trên địa phận quốc gia, dân tộc khác là phi nghĩa","is_correct":true},{"letter":"C","text":"Căn cứ vào chiến tranh xâm lược hay phòng ngự","is_correct":false},{"letter":"D","text":"Tiêu chuẩn đạo đức, thẩm mỹ","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q63","number":63,"text":"Thực chất phạm trù tính chất chính trị - xã hội của chiến tranh là:","options":[{"letter":"A","text":"Việc xác định vị trí đóng quân của các bên tham chiến","is_correct":false},{"letter":"B","text":"Sự phân định vai trò của mỗi bên tham chiến đối với tiến bộ xã hội","is_correct":true},{"letter":"C","text":"Sự phân định việc đúng sai về mặt pháp luật của mỗi bên tham chiến","is_correct":false},{"letter":"D","text":"Là những căn cứ cơ bản để xác định chiến tranh chính nghĩa hay phi nghĩa của các bên tham chiến","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q64","number":64,"text":"Tiêu chí cơ bản nhận diện cuộc chiến tranh là phi nghĩa:","options":[{"letter":"A","text":"Là cuộc chiến tranh xâm chiếm quyền lợi của người khác","is_correct":true},{"letter":"B","text":"Là cuộc chiến tranh tiến công","is_correct":false},{"letter":"C","text":"Là chiến tranh lạnh","is_correct":false},{"letter":"D","text":"Là cuộc chiến tranh công nghệ cao","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q65","number":65,"text":"Chọn phương án sai về quy luật tiến trình và kết cục chiến tranh:","options":[{"letter":"A","text":"Tiến trình và kết cục của chiến tranh phụ thuộc vào so sánh lực lượng xã hội của các bên tham chiến.","is_correct":false},{"letter":"B","text":"Tiến trình và kết cục của chiến tranh phụ thuộc vào tổ chức trận địa của các bên tham chiến.","is_correct":true},{"letter":"C","text":"Tiến trình và kết cục của chiến tranh phụ thuộc vào mục đích chính trị giữa các bên tham chiến.","is_correct":false},{"letter":"D","text":"Tiến trình và kết cục của chiến tranh phụ thuộc vào so sánh lực lượng kinh tế của các bên tham chiến.","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q66","number":66,"text":"Chọn phương án sai về dấu hiệu đặc trưng để phân chia các kiểu chiến tranh:","options":[{"letter":"A","text":"Cơ sở lịch sử xã hội","is_correct":false},{"letter":"B","text":"Cơ sở về quy mô đấu tranh","is_correct":true},{"letter":"C","text":"Cơ sở kỹ thuật quân sự","is_correct":false},{"letter":"D","text":"Cơ sở về quy mô chiến tranh","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q67","number":67,"text":"Chọn phương án đúng theo quan điểm của chủ nghĩa Mác - Lênin:","options":[{"letter":"A","text":"Chiến tranh là những xung đột do mâu thuẫn không mang tính xã hội","is_correct":false},{"letter":"B","text":"Chiến tranh là mối quan hệ giữa người với người để tranh giành lợi ích","is_correct":false},{"letter":"C","text":"Chiến tranh là những cuộc xung đột tự phát ngẫu nhiên","is_correct":false},{"letter":"D","text":"Chiến tranh là hiện tượng chính trị - xã hội, kết quả của những quan hệ giữa người với người trong xã hội","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q68","number":68,"text":"Theo quan điểm của chủ nghĩa Mác - Lênin, chiến tranh là:","options":[{"letter":"A","text":"Một bộ phận, một phương tiện của chính trị, là kết quả phản ánh những cố gắng cao nhất của chính trị","is_correct":true},{"letter":"B","text":"Một thành phần, một yếu tố cấu thành của chính trị","is_correct":false},{"letter":"C","text":"Lực lượng quan trọng không thể thiếu của chính trị","is_correct":false},{"letter":"D","text":"Hậu quả của chính trị","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q69","number":69,"text":"Chọn phương án đúng về chiến tranh:","options":[{"letter":"A","text":"Chiến tranh là quy luật khách quan của xã hội loài người","is_correct":false},{"letter":"B","text":"Chiến tranh là hiện tượng mang tính lịch sử - xã hội của loài người","is_correct":true},{"letter":"C","text":"Chiến tranh là hiện tượng xã hội tự nhiên ngoài ý muốn của con người","is_correct":false},{"letter":"D","text":"Chiến tranh có ngay từ khi xuất hiện loài người","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q70","number":70,"text":"Đảng ta chỉ đạo phương châm tiến hành chiến tranh là gì?","options":[{"letter":"A","text":"Tự lực cánh sinh tranh thủ sự giúp đỡ của các nước khác","is_correct":false},{"letter":"B","text":"Tự lực cánh sinh, đánh lâu dài, dựa vào sức mạnh thời đại là chính","is_correct":false},{"letter":"C","text":"Tự lực cánh sinh, đánh lâu dài, dựa vào sức mình là chính","is_correct":true},{"letter":"D","text":"Tự lực cánh sinh, đánh nhanh, thắng nhanh, dựa vào sức mình là chính","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q71","number":71,"text":"Chọn phương án đúng về sự ra đời của Quân đội Nhân dân Việt Nam:","options":[{"letter":"A","text":"Là hiện tượng ngẫu nhiên trong quá trình cách mạng Việt Nam","is_correct":false},{"letter":"B","text":"Là sự kế thừa trong lịch sử chống giặc ngoại xâm của dân tộc ta","is_correct":false},{"letter":"C","text":"Có tính quy luật trong đấu tranh giai cấp, đấu tranh dân tộc ở Việt Nam","is_correct":true},{"letter":"D","text":"Là hiện tượng tự phát do đòi hỏi đấu tranh dân tộc ở Việt Nam","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q72","number":72,"text":"Một trong những cơ sở hình thành nghệ thuật quân sự Việt Nam:","options":[{"letter":"A","text":"Tư tưởng quân sự Hồ Chí Minh","is_correct":true},{"letter":"B","text":"Từ quan điểm của chủ nghĩa Mác - Lênin về đấu tranh dân tộc","is_correct":false},{"letter":"C","text":"Từ nghệ thuật quân sự của các nước","is_correct":false},{"letter":"D","text":"Từ quan điểm của chủ nghĩa Mác - Lênin về đấu tranh giai cấp","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q73","number":73,"text":"Chọn phương án đúng nhất để căn cứ phân chia kiểu chiến tranh:","options":[{"letter":"A","text":"Lực lượng tham gia đấu tranh","is_correct":false},{"letter":"B","text":"Cơ sở lịch sử xã hội","is_correct":true},{"letter":"C","text":"Cơ sở của các chế độ kinh tế - xã hội","is_correct":false},{"letter":"D","text":"Cơ sở về khoa học, vũ khí sử dụng","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q74","number":74,"text":"Tư tưởng xuyên suốt của nghệ thuật quân sự Việt Nam là:","options":[{"letter":"A","text":"Chủ động tiến công","is_correct":false},{"letter":"B","text":"Dựa vào sức mạnh vũ khí","is_correct":false},{"letter":"C","text":"Phòng thủ trận địa vững chắc","is_correct":false},{"letter":"D","text":"Tích cực, chủ động tiến công","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q75","number":75,"text":"Cơ sở của nghệ thuật lấy nhỏ đánh lớn, lấy ít địch nhiều, lấy yếu chống mạnh của nhân dân ta là:","options":[{"letter":"A","text":"Lấy thời thắng lực","is_correct":false},{"letter":"B","text":"Lấy thế thắng lực","is_correct":true},{"letter":"C","text":"Lấy kế thắng lực","is_correct":false},{"letter":"D","text":"Lấy mưu thắng lực","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q76","number":76,"text":"Lựa chọn phương án sai:","options":[{"letter":"A","text":"Học thuyết Mác - Lênin về chiến tranh và quân đội nghiên cứu những quy luật cơ bản, chung nhất của hiện tượng chiến tranh trong đời sống xã hội","is_correct":false},{"letter":"B","text":"Học thuyết Mác - Lênin về chiến tranh và quân đội nghiên cứu những quy luật cơ bản, chung nhất của hiện tượng đấu tranh vũ trang trong đời sống xã hội","is_correct":true},{"letter":"C","text":"Học thuyết Mác - Lênin về chiến tranh và quân đội nghiên cứu những quy luật cơ bản, chung nhất của hiện tượng quân đội","is_correct":false},{"letter":"D","text":"Học thuyết Mác - Lênin về chiến tranh và quân đội nghiên cứu bản chất những quy luật cơ bản, chung nhất về sức mạnh quân sự quốc gia","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q77","number":77,"text":"Hạn chế của C.Ph.Claudovít trong quan niệm về chính trị, trong mối quan hệ giữa chiến tranh và chính trị là gì?","options":[{"letter":"A","text":"Chính trị là đường lối đối nội và đối ngoại","is_correct":false},{"letter":"B","text":"Chính trị quan hệ chặt chẽ với kinh tế","is_correct":false},{"letter":"C","text":"Chính trị là đường lối đối ngoại, tách rời với kinh tế","is_correct":true},{"letter":"D","text":"Chính trị là đường lối đối nội, quan hệ với kinh tế","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q78","number":78,"text":"Hoàn chỉnh định nghĩa: Nguyên nhân của chiến tranh: “Là sự tác động tổng hợp của các nhân tố……trong những điều kiện, hoàn cảnh và không gian, thời gian xác định làm xuất hiện cuộc chiến tranh cụ thể”:","options":[{"letter":"A","text":"Chính trị - xã hội","is_correct":false},{"letter":"B","text":"Khách quan","is_correct":false},{"letter":"C","text":"Khách quan và chủ quan","is_correct":true},{"letter":"D","text":"Chủ quan","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q79","number":79,"text":"Hạn chế của C.Ph.Claudovít trong quan niệm về chiến tranh là gì?","options":[{"letter":"A","text":"Chưa luận giải được bản chất của hành vi bạo lực","is_correct":true},{"letter":"B","text":"Chưa thấy được bản chất của hành vi chiến tranh","is_correct":false},{"letter":"C","text":"Chưa khẳng định được bản chất của hành vi bạo lực","is_correct":false},{"letter":"D","text":"Không làm rõ bản chất của hành vi đấu tranh vũ trang","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q80","number":80,"text":"Chọn phương án sai theo quan điểm của chủ nghĩa Mác - Lênin:","options":[{"letter":"A","text":"Chiến tranh là hiện tượng chính trị xã hội có tính lịch sử","is_correct":false},{"letter":"B","text":"Chiến tranh là bộ phận quan trọng không thể thiếu của chính trị","is_correct":true},{"letter":"C","text":"Chiến tranh bắt nguồn khi xuất hiện chế độ tư hữu, giai cấp và nhà nước","is_correct":false},{"letter":"D","text":"Chiến tranh là hoạt động tự giác nhằm đạt mục đích chính trị nhất định","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q81","number":81,"text":"Cơ sở C.Mác và Ph.Ăngghen đưa ra quan niệm chiến tranh và quân đội:","options":[{"letter":"A","text":"Góc độ triết học - tâm lý học","is_correct":false},{"letter":"B","text":"Góc độ chính trị - xã hội học","is_correct":false},{"letter":"C","text":"Góc độ triết học - xã hội học","is_correct":true},{"letter":"D","text":"Góc độ triết học - chính trị học","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q82","number":82,"text":"Theo quan điểm của chủ nghĩa Mác - Lênin về chiến tranh:","options":[{"letter":"A","text":"Chiến tranh sẽ mất đi khi con người phát triển cao về trình độ","is_correct":false},{"letter":"B","text":"Chiến tranh là hiện tượng vĩnh viễn không mất đi","is_correct":false},{"letter":"C","text":"Chiến tranh chỉ mất đi khi loài người không còn","is_correct":false},{"letter":"D","text":"Chiến tranh sẽ mất đi khi chế độ tư hữu không còn","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q83","number":83,"text":"Một trong những hạn chế chủ yếu của các nhà tư tưởng trước C.Mác quan niệm về chiến tranh:","options":[{"letter":"A","text":"Thế giới quan","is_correct":true},{"letter":"B","text":"Lập trường giai cấp","is_correct":false},{"letter":"C","text":"Trình độ nhận thức","is_correct":false},{"letter":"D","text":"Tri thức khoa học","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q84","number":84,"text":"Chọn phương án sai về chiến tranh:","options":[{"letter":"A","text":"Chiến tranh bắt nguồn khi xuất hiện chế độ tư hữu","is_correct":false},{"letter":"B","text":"Chiến tranh bắt nguồn khi xuất hiện giai cấp","is_correct":false},{"letter":"C","text":"Chiến tranh bắt nguồn khi xuất hiện nhà nước","is_correct":false},{"letter":"D","text":"Chiến tranh bắt nguồn khi xuất hiện đảng phái","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q85","number":85,"text":"Lựa chọn phương án đúng","options":[{"letter":"A","text":"Chiến tranh là mối quan hệ giữa người với người về sử dụng bạo lực, kết quả của những quan hệ giữa người với người trong xã hội","is_correct":false},{"letter":"B","text":"Chiến tranh là một hiện tượng chính trị - xã hội, kết quả của những quan hệ giữa người với người trong xã hội","is_correct":true},{"letter":"C","text":"Chiến tranh là những cuộc xung đột tự phát ngẫu nhiên, kết quả của những quan hệ giữa người với người trong xã hội","is_correct":false},{"letter":"D","text":"Chiến tranh là những xung đột do mâu thuẫn không mang tính xã hội","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q86","number":86,"text":"Quan điểm của V.I. Lênin về nguồn gốc của chiến tranh trong giai đoạn đế quốc chủ nghĩa:","options":[{"letter":"A","text":"Trong thời đại đế quốc chủ nghĩa, chiến tranh bắt nguồn từ bản chất của các nước tư bản trên thế giới","is_correct":false},{"letter":"B","text":"Bắt nguồn từ bản chất của chủ nghĩa đế quốc","is_correct":true},{"letter":"C","text":"Bắt nguồn từ sự khác biệt về sự phát triển kinh tế của các nước đế quốc","is_correct":false},{"letter":"D","text":"Bắt nguồn từ sự phát triển mạnh mẽ của khoa học kỹ thuật","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q87","number":87,"text":"Theo quan điểm của chủ nghĩa Mác - Lênin, chiến tranh xuất hiện đầu tiên ở hình thái kinh tế - xã hội nào?","options":[{"letter":"A","text":"Hình thái kinh tế - xã hội chiếm hữu nô lệ","is_correct":true},{"letter":"B","text":"Hình thái kinh tế - xã hội tư bản chủ nghĩa","is_correct":false},{"letter":"C","text":"Hình thái kinh tế - xã hội công xã nguyên thủy","is_correct":false},{"letter":"D","text":"Hình thái kinh tế - xã hội phong kiến","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q88","number":88,"text":"Hoàn thiện câu nói của V.I.Lênin: “Chiến tranh chẳng qua chỉ là………từ đầu đến cuối”","options":[{"letter":"A","text":"Kinh tế","is_correct":false},{"letter":"B","text":"Phương thức tác chiến","is_correct":false},{"letter":"C","text":"Chính trị","is_correct":true},{"letter":"D","text":"Bạo lực","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q89","number":89,"text":"Đâu không phải là những căn cứ đánh giá tính chất chính trị - xã hội của chiến tranh:","options":[{"letter":"A","text":"Mục đích chính trị","is_correct":false},{"letter":"B","text":"Mục đích xã hội","is_correct":true},{"letter":"C","text":"Vai trò, địa vị của giai cấp lãnh đạo, tiến hành chiến tranh","is_correct":false},{"letter":"D","text":"Hoàn cảnh lịch sử nổ ra và diễn biến của cuộc chiến tranh","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q90","number":90,"text":"Đặc trưng, quân đội là tổ chức của những người có vũ trang, thực hiện chức năng bằng vũ khí chuyên dụng, phản ánh mối quan hệ nào?","options":[{"letter":"A","text":"Mối quan hệ đặc thù giữa tổ chức quân sự và vũ khí trang bị","is_correct":false},{"letter":"B","text":"Mối quan hệ đặc thù giữa nghệ thuật quân sự với cán bộ chỉ huy và hạ sĩ quan binh sĩ","is_correct":false},{"letter":"C","text":"Mối quan hệ đặc thù giữa đường lối quân sự và vũ khí chuyên dụng","is_correct":false},{"letter":"D","text":"Mối quan hệ đặc thù giữa con người và vũ khí trang bị","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q91","number":91,"text":"Lựa chọn phương án đúng","options":[{"letter":"A","text":"Tính lịch sử của quân đội là quân đội ra đời, biến đổi và mất đi khi nguồn gốc sinh ra quân đội mất đi","is_correct":true},{"letter":"B","text":"Tính lịch sử của quân đội nghĩa là quân đội tồn tại cùng lịch sử loài người và mất đi khi nguồn gốc sinh ra quân đội mất đi","is_correct":false},{"letter":"C","text":"Tính lịch sử của quân đội nghĩa là quân đội chịu sự chi phối bởi điều kiện và hoàn cảnh của lịch sử","is_correct":false},{"letter":"D","text":"Tính lịch sử của quân đội nghĩa là quân đội có lịch sử riêng của mình mất đi khi nguồn gốc sinh ra quân đội mất đi","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q92","number":92,"text":"Quan điểm: Quân đội là công cụ của Thượng đế để bảo vệ lợi ích của giai cấp địa chủ phong kiến và nhà thờ của trường phái nào?","options":[{"letter":"A","text":"Chủ nghĩa duy tâm chủ quan","is_correct":false},{"letter":"B","text":"Chủ nghĩa duy tâm khách quan","is_correct":true},{"letter":"C","text":"Chủ nghĩa duy vật siêu hình","is_correct":false},{"letter":"D","text":"Chủ nghĩa duy vật biện chứng","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q93","number":93,"text":"Tính hiện đại trong chiến tranh Nhân dân bảo vệ Tổ quốc Việt Nam được thể hiện:","options":[{"letter":"A","text":"Sử dụng vũ khí trang bị hiện đại để tiến hành chiến tranh","is_correct":false},{"letter":"B","text":"Sử dụng vũ khí trang bị hiện đại để đánh bại kẻ thù có vũ khí hiện đại hơn","is_correct":false},{"letter":"C","text":"Hiện đại về vũ khí, trang bị, tri thức và nghệ thuật quân sự","is_correct":true},{"letter":"D","text":"Kết hợp sử dụng vũ khí tương đối hiện đại với hiện đại để tiến hành chiến tranh","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q94","number":94,"text":"Cuộc chiến tranh nào sau đây được coi là phi nghĩa:","options":[{"letter":"A","text":"Chiến tranh bảo vệ Tổ quốc","is_correct":false},{"letter":"B","text":"Chiến tranh giải phóng dân tộc","is_correct":false},{"letter":"C","text":"Chiến tranh bảo vệ chủ quyền quốc gia của các nước tư bản chống chiến tranh xâm lược của các nước đế quốc","is_correct":false},{"letter":"D","text":"Chiến tranh của các nước đế quốc chống các nước xã hội chủ nghĩa","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q95","number":95,"text":"Một trong những tính chất của chiến tranh Nhân dân bảo vệ Tổ quốc Việt Nam xã hội chủ nghĩa:","options":[{"letter":"A","text":"Là cuộc chiến tranh toàn dân, lấy lực lượng vũ trang làm nòng cốt","is_correct":false},{"letter":"B","text":"Là cuộc chiến tranh toàn diện lấy quân sự là quyết định","is_correct":false},{"letter":"C","text":"Là cuộc chiến tranh toàn dân, toàn diện, lấy lực lượng vũ trang làm nòng cốt","is_correct":true},{"letter":"D","text":"Là cuộc chiến tranh cách mạng chống các thế lực phản cách mạng","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q96","number":96,"text":"Quan điểm nào phủ nhận tính lịch sử của quân đội:","options":[{"letter":"A","text":"Quan điểm của giai cấp tư sản","is_correct":true},{"letter":"B","text":"Quan điểm của giai cấp vô sản","is_correct":false},{"letter":"C","text":"Quan điểm của giai cấp công nhân","is_correct":false},{"letter":"D","text":"Quan điểm của tầng lớp trí thức","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q97","number":97,"text":"Quan điểm chủ nghĩa Mác - Lênin về bản chất giai cấp của quân đội:","options":[{"letter":"A","text":"Mang bản chất của dân tộc sử dụng quân đội đó","is_correct":false},{"letter":"B","text":"Mang bản chất của giai cấp tổ chức, nuôi dưỡng và sử dụng quân đội","is_correct":true},{"letter":"C","text":"Mang bản chất của giai cấp bóc lột","is_correct":false},{"letter":"D","text":"Mang bản chất của nhân dân lao động","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q98","number":98,"text":"Chọn phương án đúng về bản chất của quân đội:","options":[{"letter":"A","text":"Là lực lượng duy nhất có nhiệm vụ bảo vệ Tổ quốc","is_correct":false},{"letter":"B","text":"Là lực lượng phòng thủ dân sự","is_correct":false},{"letter":"C","text":"Là công cụ bạo lực của giai cấp cầm quyền","is_correct":true},{"letter":"D","text":"Là lực lượng nòng cốt cho toàn dân đánh giặc","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q99","number":99,"text":"Lựa chọn phương án đúng theo quan điểm của chủ nghĩa Mác - Lênin:","options":[{"letter":"A","text":"Quân đội thuộc phương thức sản xuất","is_correct":false},{"letter":"B","text":"Quân đội là bộ phận của cơ sở hạ tầng","is_correct":false},{"letter":"C","text":"Quân đội là một bộ phận của lực lượng sản xuất","is_correct":false},{"letter":"D","text":"Quân đội là bộ phận của kiến trúc thượng tầng","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q100","number":100,"text":"Yếu tố nào tác động lớn nhất tới bản chất quân đội:","options":[{"letter":"A","text":"Yếu tố giai cấp","is_correct":true},{"letter":"B","text":"Yếu tố xã hội","is_correct":false},{"letter":"C","text":"Chế độ chính trị","is_correct":false},{"letter":"D","text":"Yếu tố nhà nước","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q101","number":101,"text":"Quan điểm nào cho rằng quân đội tồn tại vĩnh viễn:","options":[{"letter":"A","text":"Quan điểm vô sản","is_correct":false},{"letter":"B","text":"Quan điểm tôn giáo","is_correct":false},{"letter":"C","text":"Quan điểm chủ nghĩa Mác - Lênin","is_correct":false},{"letter":"D","text":"Quan điểm tư sản","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q102","number":102,"text":"Chọn phương án đúng về quy luật xây dựng quân đội xã hội chủ nghĩa:","options":[{"letter":"A","text":"Quy luật chạy đua vũ trang","is_correct":false},{"letter":"B","text":"Quy luật lãnh đạo của Đảng Cộng sản","is_correct":true},{"letter":"C","text":"Quy luật phụ thuộc trực tiếp vào điều kiện kinh tế - xã hội đất nước","is_correct":false},{"letter":"D","text":"Quy luật sự thống nhất giữa quân đội và nhân dân","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q103","number":103,"text":"Nguyên tắc cơ bản và quan trọng nhất về xây dựng quân đội kiểu mới của V.I. Lênin là:","options":[{"letter":"A","text":"Giữ vững quan điểm giai cấp trong xây dựng quân đội","is_correct":false},{"letter":"B","text":"Tính kỷ luật cao là yếu tố quyết định sức mạnh quân đội","is_correct":false},{"letter":"C","text":"Sự lãnh đạo của Đảng Cộng sản đối với quân đội","is_correct":true},{"letter":"D","text":"Quân đội chính quy, hiện đại, trung thành với giai cấp công nhân và nhân dân lao động","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q104","number":104,"text":"Chức năng của quân đội:","options":[{"letter":"A","text":"Là công cụ bạo lực chủ yếu của giai cấp thống trị và nhà nước","is_correct":true},{"letter":"B","text":"Là lực lượng lao động và bảo vệ chủ yếu của toàn xã hội","is_correct":false},{"letter":"C","text":"Là lao động sản xuất tạo ra của cải cho xã hội","is_correct":false},{"letter":"D","text":"Là phương tiện quân sự để đạt mục tiêu chính trị","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q105","number":105,"text":"Đâu không phải là biện pháp tăng cường bản chất giai cấp của quân đội:","options":[{"letter":"A","text":"Truyền bá hệ tư tưởng","is_correct":false},{"letter":"B","text":"Xây dựng tổ chức, xác định phương hướng hoạt động của quân đội","is_correct":false},{"letter":"C","text":"Kiểm soát các hoạt động của quân đội","is_correct":false},{"letter":"D","text":"Tăng quân số thường trực","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q106","number":106,"text":"“Xây dựng Quân đội nhân dân, Công an nhân dân cách mạng, chính quy, tinh nhuệ, hiện đại, tuyệt đối trung thành với Tổ quốc, với Đảng, Nhà nước và Nhân dân” được nêu ở đâu:","options":[{"letter":"A","text":"Hiến pháp năm 2013","is_correct":false},{"letter":"B","text":"Đại hội Đảng lần thứ XIV","is_correct":true},{"letter":"C","text":"Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội năm 2011","is_correct":false},{"letter":"D","text":"Đại hội Đảng bộ Quân đội lần thứ XI","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q107","number":107,"text":"Theo quan điểm của chủ nghĩa Mác – Lênin, đâu không phải là quy luật vận động, phát triển của quân đội:","options":[{"letter":"A","text":"Quy luật vận động, phát triển của quân đội phụ thuộc vào chế độ chính trị - xã hội và vào tính chất giai cấp của nhà nước tổ chức ra nó","is_correct":false},{"letter":"B","text":"Quy luật vận động, phát triển của quân đội phụ thuộc vào những điều kiện kinh tế - xã hội","is_correct":false},{"letter":"C","text":"Quy luật vận động, phát triển của quân đội phụ thuộc vào sức mạnh tinh thần và hệ tư tưởng của xã hội","is_correct":false},{"letter":"D","text":"Quy luật vận động, phát triển của quân đội phụ thuộc vào số, chất lượng binh sĩ và cơ cấu tổ chức biên chế","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q108","number":108,"text":"Quy luật có ý nghĩa trực tiếp quyết định tiến trình và kết cục chiến tranh:","options":[{"letter":"A","text":"Quy luật tiến trình và kết cục chiến tranh phụ thuộc so sánh lực lượng tinh thần của các bên tham chiến","is_correct":false},{"letter":"B","text":"Quy luật tiến trình và kết cục chiến tranh phụ thuộc so sánh lực lượng quân sự của các bên tham chiến","is_correct":true},{"letter":"C","text":"Quy luật tiến trình và kết cục chiến tranh phụ thuộc so sánh lực lượng khoa học của các bên tham chiến","is_correct":false},{"letter":"D","text":"Quy luật tiến trình và kết cục chiến tranh phụ thuộc so sánh lực lượng kinh tế của các bên tham chiến","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q109","number":109,"text":"Lựa chọn phương án đúng: Sự ra đời của Quân đội Nhân dân Việt Nam là:","options":[{"letter":"A","text":"Là tất yếu có tính quy luật trong đấu tranh giai cấp, đấu tranh dân tộc ở Việt Nam","is_correct":true},{"letter":"B","text":"Là hiện tượng ngẫu nhiên trong quá trình đấu tranh cách mạng của dân tộc Việt Nam","is_correct":false},{"letter":"C","text":"Là sự kế thừa trong lịch sử chống giặc ngoại xâm","is_correct":false},{"letter":"D","text":"Là hiện tượng tự phát do đòi hỏi của chiến tranh cách mạng","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q110","number":110,"text":"Chọn phương án đúng theo quan điểm đại hội XIV của Đảng:","options":[{"letter":"A","text":"Việt Nam chủ trương xây dựng Quân đội nhân dân cách mạng, chính quy, tinh nhuệ, từng bước hiện đại","is_correct":false},{"letter":"B","text":"Việt Nam chủ trương xây dựng Quân đội nhân dân hiện đại, chính quy, tinh nhuệ và thực sự cách mạng","is_correct":false},{"letter":"C","text":"Việt Nam chủ trương xây dựng Quân đội nhân dân cách mạng, chính quy, tinh nhuệ, một số lực lượng hiện đại","is_correct":false},{"letter":"D","text":"Việt Nam chủ trương xây dựng Quân đội nhân dân cách mạng, chính quy, tinh nhuệ, hiện đại","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q111","number":111,"text":"Đâu không phải là yếu tố cấu thành sức mạnh chiến đấu của quân đội:","options":[{"letter":"A","text":"Quân số, cơ cấu tổ chức biên chế","is_correct":false},{"letter":"B","text":"Chính trị, tinh thần và kỷ luật","is_correct":false},{"letter":"C","text":"Trình độ huấn luyện và thể lực của bộ đội","is_correct":false},{"letter":"D","text":"Kiểm soát các hoạt động của quân đội","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q112","number":112,"text":"Chọn phương án đúng về đối tác của Việt Nam hiện nay:","options":[{"letter":"A","text":"Những ai tôn trọng độc lập, chủ quyền và hợp tác bình đẳng cùng có lợi với Việt Nam","is_correct":true},{"letter":"B","text":"Những quốc gia, vùng lãnh thổ, tổ chức phi chính phủ tạo điều kiện thuận lợi cho Việt Nam","is_correct":false},{"letter":"C","text":"Những nước xã hội chủ nghĩa và các nước đang phát triển giúp đỡ Việt Nam","is_correct":false},{"letter":"D","text":"Những tổ chức, cá nhân tôn trọng giúp đỡ Việt Nam.","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q113","number":113,"text":"Đâu là một trong những nhận thức và vận dụng quy luật chiến tranh của Đảng ta:","options":[{"letter":"A","text":"Phát huy ưu thế về tính chính nghĩa của chiến tranh nhân dân bảo vệ tổ quốc trong tương quan so sánh lực lượng quân sự","is_correct":false},{"letter":"B","text":"Phát huy ưu thế về khả năng lãnh đạo, tổ chức của hệ thống chính trị và sức mạnh của khối đại đoàn kết toàn dân tộc","is_correct":true},{"letter":"C","text":"Phát huy ưu thế về khả năng sẵn sàng chiến đấu cao của quân đội trong tương quan so sánh lực lượng kinh tế","is_correct":false},{"letter":"D","text":"Phát huy ưu thế về thế trận quốc phòng toàn dân và truyền thống, kinh nghiệm chiến đấu của quân đội","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q114","number":114,"text":"Tiến hành chiến tranh nhân dân với tinh thần tự lực tự cường nhưng:","options":[{"letter":"A","text":"Cần phát huy nội lực của đất nước không cần giúp đỡ từ bên ngoài","is_correct":false},{"letter":"B","text":"Chỉ cần một số nước xã hội chủ nghĩa giúp đỡ","is_correct":false},{"letter":"C","text":"Chỉ cần huy động mọi tiềm năng sẵn có của đất nước","is_correct":false},{"letter":"D","text":"Cần sự đồng tình ủng hộ, giúp đỡ của cả loài người tiến bộ trên thế giới","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q115","number":115,"text":"Đâu không phải là tiềm lực trong cấu trúc của sức mạnh quân sự quốc gia:","options":[{"letter":"A","text":"Tiềm lực chính trị","is_correct":false},{"letter":"B","text":"Tiềm lực kinh tế","is_correct":false},{"letter":"C","text":"Tiềm lực quân sự","is_correct":false},{"letter":"D","text":"Tiềm lực xã hội","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q116","number":116,"text":"Tiềm lực chính trị tinh thần trong nội dung xây dựng nền quốc phòng toàn dân là:","options":[{"letter":"A","text":"Khả năng về chính trị tinh thần của xã hội để thực hiện nhiệm vụ quốc phòng, an ninh và sẵn sang chiến đấu","is_correct":false},{"letter":"B","text":"Khả năng về chính trị tinh thần có thể huy động để tự vệ chống lại mọi kẻ thù xâm lược","is_correct":false},{"letter":"C","text":"Khả năng về chính trị tinh thần có thể huy động để thực hiện nhiệm vụ quốc phòng, an ninh","is_correct":true},{"letter":"D","text":"Khả năng về chính trị tinh thần của nhân dân có thể huy động được để chiến đấu chống quân xâm lược","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q117","number":117,"text":"Đấu tranh chống tham nhũng, tiêu cực của Đảng ta hiện nay là xây dựng tiềm lực nào là chủ yếu trong sức mạnh quân sự quốc gia:","options":[{"letter":"A","text":"Tiềm lực kinh tế","is_correct":false},{"letter":"B","text":"Tiềm lực tinh thần","is_correct":true},{"letter":"C","text":"Tiềm lực xã hội","is_correct":false},{"letter":"D","text":"Tiềm lực quân sự","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q118","number":118,"text":"Yếu tố nào biểu hiện tập trung, trực tiếp của sức mạnh quân sự quốc gia:","options":[{"letter":"A","text":"Tiềm lực tinh thần","is_correct":false},{"letter":"B","text":"Tiềm lực xã hội","is_correct":false},{"letter":"C","text":"Tiềm lực kinh tế","is_correct":false},{"letter":"D","text":"Tiềm lực quân sự","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q119","number":119,"text":"Khẳng định nào sau đây là đúng:","options":[{"letter":"A","text":"Chiến tranh hiện đại, sử dụng vũ khí công nghệ cao, không thể tiến hành chiến tranh nhân dân","is_correct":false},{"letter":"B","text":"Chiến tranh nhân dân chỉ phù hợp với vũ khí thông thường","is_correct":false},{"letter":"C","text":"Tương lai chiến tranh nhân dân không còn tác dụng nữa","is_correct":false},{"letter":"D","text":"Chiến tranh hiện đại, sử dụng vũ khí công nghệ cao, chiến tranh nhân dân vẫn được tiến hành và phát huy hiệu quả","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q120","number":120,"text":"Xây dựng tinh thần đoàn kết toàn dân tộc là biện pháp xây dựng tiềm lực nào?","options":[{"letter":"A","text":"Tiềm lực kinh tế","is_correct":false},{"letter":"B","text":"Tiềm lực xã hội","is_correct":false},{"letter":"C","text":"Tiềm lực tinh thần","is_correct":true},{"letter":"D","text":"Tiềm lực chính trị","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q121","number":121,"text":"Trong nghệ thuật kết hợp đấu tranh giữa các mặt trận thì chính trị được xác định:","options":[{"letter":"A","text":"Là cơ sở để tạo ra sức mạnh về quân sự","is_correct":true},{"letter":"B","text":"Là mặt trận quan trọng nhất, chủ yếu nhất","is_correct":false},{"letter":"C","text":"Là mặt trận quyết định thắng lợi trực tiếp của chiến tranh","is_correct":false},{"letter":"D","text":"Là mặt trận chủ yếu để phân hóa, cô lập kẻ thù","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q122","number":122,"text":"Đẩy mạnh công nghiệp hoá, hiện đại hoá là biện pháp xây dựng tiềm lực nào?","options":[{"letter":"A","text":"Tiềm lực chính trị - xã hội","is_correct":false},{"letter":"B","text":"Tiềm lực quân sự, quốc phòng","is_correct":false},{"letter":"C","text":"Tiềm lực khoa học, kỹ thuật","is_correct":false},{"letter":"D","text":"Tiềm lực kinh tế","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q123","number":123,"text":"Một trong những nguyên tắc cơ bản xây dựng Quân đội của V.I.Lênin là gì?","options":[{"letter":"A","text":"Xây dựng quân đội tinh nhuệ","is_correct":false},{"letter":"B","text":"Xây dựng quân đội hiện đại","is_correct":false},{"letter":"C","text":"Xây dựng quân đội chính quy","is_correct":true},{"letter":"D","text":"Xây dựng quân đội có tính kỷ luật cao","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q124","number":124,"text":"Kết hợp xây dựng kinh tế với quốc phòng thể hiện chức năng nào của quân đội ta:","options":[{"letter":"A","text":"Chức năng sản xuất","is_correct":true},{"letter":"B","text":"Chức năng chiến đấu","is_correct":false},{"letter":"C","text":"Chức năng công tác","is_correct":false},{"letter":"D","text":"Chức năng huấn luyện","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q125","number":125,"text":"Yếu tố cơ bản, là cơ sở để phát huy các yếu tố khác, suy đến cùng có vai trò quyết định sức mạnh chiến đấu của quân đội:","options":[{"letter":"A","text":"Quân số, tổ chức biên chế","is_correct":false},{"letter":"B","text":"Số lượng, chất lượng vũ khí, trang bị kỹ thuật quân sự","is_correct":false},{"letter":"C","text":"Trình độ khoa học và nghệ thuật quân sự","is_correct":false},{"letter":"D","text":"Chính trị, tinh thần và kỷ luật","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q126","number":126,"text":"Theo quan điểm của chủ nghĩa Mác - Lênin, bản chất giai cấp của quân đội phụ thuộc vào:","options":[{"letter":"A","text":"Bản chất của nhà nước tổ chức ra quân đội đó","is_correct":false},{"letter":"B","text":"Bản chất của các giai cấp và của nhà nước đã tổ chức ra quân đội đó","is_correct":true},{"letter":"C","text":"Bản chất của giai cấp công nông và nhà nước đã tổ chức ra quân đội đó","is_correct":false},{"letter":"D","text":"Bản chất của lực lượng chính trị tổ chức ra quân đội đó","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q127","number":127,"text":"Quy luật làm cơ sở chạy đua vũ trang:","options":[{"letter":"A","text":"Quy luật tiến trình và kết cục chiến tranh phụ thuộc so sánh lực lượng quân sự của các bên tham chiến","is_correct":true},{"letter":"B","text":"Quy luật tiến trình và kết cục chiến tranh phụ thuộc so sánh lực lượng kinh tế của các bên tham chiến","is_correct":false},{"letter":"C","text":"Quy luật tiến trình và kết cục chiến tranh phụ thuộc so sánh lực lượng tinh thần của các bên tham chiến","is_correct":false},{"letter":"D","text":"Quy luật tiến trình và kết cục chiến tranh phụ thuộc so sánh lực lượng khoa học của các bên tham chiến","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q128","number":128,"text":"Quân đội nhân dân Việt Nam có nhiệm vụ:","options":[{"letter":"A","text":"Xây dựng quân đội hùng mạnh và sẵn sàng chiến đấu","is_correct":false},{"letter":"B","text":"Xây dựng quân đội ngày càng đông đảo và sẵn sàng chiến đấu","is_correct":false},{"letter":"C","text":"Xây dựng quân đội ngày càng hùng mạnh và sẵn sàng chiến đấu","is_correct":true},{"letter":"D","text":"Xây dựng quân đội có chất lượng cao và sẵn sàng chiến đấu","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q129","number":129,"text":"Xây dựng quân đội ta từng bước hiện đại đáp ứng yêu cầu gì?","options":[{"letter":"A","text":"Nhằm đáp ứng yêu cầu răn đe của quốc phòng","is_correct":false},{"letter":"B","text":"Nhằm đáp ứng yêu cầu nhiệm vụ xây dựng và bảo vệ Tổ quốc","is_correct":true},{"letter":"C","text":"Nhằm nâng cao sức mạnh chiến đấu của quân đội","is_correct":false},{"letter":"D","text":"Nhằm đáp ứng yêu cầu mở rộng vị thế quốc gia","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q130","number":130,"text":"Nội dung cơ bản nhất xây dựng quân đội ta về chính trị hiện nay là gì:","options":[{"letter":"A","text":"Xây dựng các tổ chức đảng trong quân đội trong sạch vững mạnh","is_correct":false},{"letter":"B","text":"Giữ vững định hướng xã hội chủ nghĩa cho quân đội","is_correct":false},{"letter":"C","text":"Xây dựng, tăng cường, củng cố bản chất giai cấp công nhân của quân đội","is_correct":true},{"letter":"D","text":"Xây dựng quân đội vững mạnh cả về chính trị, tư tưởng và tổ chức","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q131","number":131,"text":"Chính quy trong quân đội thể hiện ở chỗ:","options":[{"letter":"A","text":"Là thực hiện thống nhất về mọi mặt","is_correct":true},{"letter":"B","text":"Là sự thống nhất về huấn luyện tác chiến","is_correct":false},{"letter":"C","text":"Là sự thống nhất về tổ chức biên chế","is_correct":false},{"letter":"D","text":"Là sự thống nhất về nghệ thuật tác chiến","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q132","number":132,"text":"Nhiệm vụ bảo vệ Tổ quốc Việt Nam xã hội chủ nghĩa thuộc về:","options":[{"letter":"A","text":"Các đoàn thể, các tổ chức chính trị - xã hội","is_correct":false},{"letter":"B","text":"Quân đội nhân dân Việt Nam","is_correct":false},{"letter":"C","text":"Hệ thống chính trị","is_correct":false},{"letter":"D","text":"Toàn đảng, toàn dân, toàn quân","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q133","number":133,"text":"Một trong những đặc trưng của nền quốc phòng toàn dân là:","options":[{"letter":"A","text":"Nền quốc phòng mang tính giai cấp, nhân dân sâu sắc","is_correct":false},{"letter":"B","text":"Vì dân, của dân và do toàn thể nhân dân tiến hành","is_correct":true},{"letter":"C","text":"Nền quốc phòng bảo vệ quyền lợi của dân","is_correct":false},{"letter":"D","text":"Do nhân dân xây dựng, mang tính nhân dân sâu sắc","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q134","number":134,"text":"Sức mạnh của nền quốc phòng toàn dân ở nước ta là:","options":[{"letter":"A","text":"Sức mạnh do các yếu tố chính trị, kinh tế, văn hóa, khoa học","is_correct":false},{"letter":"B","text":"Sức mạnh tổng hợp do thiên thời địa lợi nhân hòa tạo ra","is_correct":false},{"letter":"C","text":"Sức mạnh tổng hợp do nhiều yếu tố tạo thành","is_correct":true},{"letter":"D","text":"Sức mạnh của lực lượng vũ trang nhân dân tạo ra","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q135","number":135,"text":"Một trong những yêu cầu xây dựng Quân đội Nhân dân Việt Nam trong giai đoạn mới là gì?","options":[{"letter":"A","text":"Trung thành với Tổ quốc và chế độ xã hội chủ nghĩa Việt Nam","is_correct":false},{"letter":"B","text":"Trung thành với sự nghiệp đổi mới","is_correct":false},{"letter":"C","text":"Trung thành với chế độ xã hội chủ nghĩa và nhân dân","is_correct":false},{"letter":"D","text":"Trung thành với Tổ quốc, với Đảng và Nhân dân","is_correct":true}],"correct_letter":"D"},{"id":"mac-lenin-source-q136","number":136,"text":"Tính chất cơ bản chiến tranh nhân dân Việt Nam bảo vệ Tổ quốc là:","options":[{"letter":"A","text":"Cuộc chiến tranh toàn dân, toàn diện, dưới sự lãnh đạo của Đảng Cộng sản Việt Nam","is_correct":true},{"letter":"B","text":"Cuộc chiến tranh toàn dân, lấy lực lượng vũ trang làm nòng cốt","is_correct":false},{"letter":"C","text":"Cuộc chiến tranh toàn diện lấy mặt trận quân sự làm yếu tố quyết định","is_correct":false},{"letter":"D","text":"Cuộc chiến tranh cách mạng chống các thế lực phản cách mạng","is_correct":false}],"correct_letter":"A"},{"id":"mac-lenin-source-q137","number":137,"text":"Một trong những âm mưu, thủ đoạn chủ yếu của kẻ thù khi xâm lược nước ta là:","options":[{"letter":"A","text":"Đánh chắc, tiến chắc","is_correct":false},{"letter":"B","text":"Đánh nhanh, thắng nhanh","is_correct":true},{"letter":"C","text":"Đánh lâu dài","is_correct":false},{"letter":"D","text":"Tiến công từng bước","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q138","number":138,"text":"Đâu là một trong những âm mưu, thủ đoạn của kẻ thù khi xâm lược nước ta:","options":[{"letter":"A","text":"Tiến công hỏa lực với mức độ cao, kết hợp tiến công quân sự từ bên ngoài","is_correct":false},{"letter":"B","text":"Tiến công quân sự với quân số đông, kết hợp bạo loạn lật đổ từ bên trong","is_correct":false},{"letter":"C","text":"Kết hợp tiến công quân sự từ bên ngoài với bạo loạn lật đổ từ bên trong","is_correct":true},{"letter":"D","text":"Gây bạo loạn với quy mô lớn, kết hợp tiến công quân sự từ bên ngoài","is_correct":false}],"correct_letter":"C"},{"id":"mac-lenin-source-q139","number":139,"text":"Một trong những nội dung chủ yếu của chiến tranh nhân dân bảo vệ Tổ quốc là gì?","options":[{"letter":"A","text":"Tổ chức các lực lượng đánh giặc","is_correct":false},{"letter":"B","text":"Tổ chức thế trận chiến tranh nhân dân","is_correct":true},{"letter":"C","text":"Tổ chức thế trận đánh giặc","is_correct":false},{"letter":"D","text":"Tổ chức thế trận phòng thủ của chiến tranh","is_correct":false}],"correct_letter":"B"},{"id":"mac-lenin-source-q140","number":140,"text":"Những câu trích dưới đây, câu nào không thể hiện tinh thần chiến tranh nhân dân:","options":[{"letter":"A","text":"“Hễ là người Việt Nam thì phải cầm vũ khí đứng lên chống thực dân Pháp cứu Tổ quốc”","is_correct":false},{"letter":"B","text":"“31 triệu dân tất cả hành quân, tất cả thành chiến sĩ…”","is_correct":false},{"letter":"C","text":"“Giặc đến nhà đàn bà cũng đánh”","is_correct":false},{"letter":"D","text":"“Nhằm thẳng quân thù mà bắn, máy bay Mỹ không có gì đáng sợ”","is_correct":true}],"correct_letter":"D"}],"ho-chi-minh":[{"id":"ho-chi-minh-source-q1","number":1,"text":"Chọn phương án đúng về quan điểm xây dựng Quân đội nhân dân Việt Nam theo tư tưởng Hồ Chí Minh:","options":[{"letter":"A","text":"Xây dựng quân đội vững mạnh toàn diện trên cơ sở vững mạnh về hậu cần, kỹ thuật.","is_correct":false},{"letter":"B","text":"Xây dựng quân đội vững mạnh toàn diện trên cơ sở vững mạnh về tổ chức, trang bị.","is_correct":false},{"letter":"C","text":"Xây dựng quân đội vững mạnh toàn diện trên cơ sở vững mạnh về chính trị.","is_correct":true},{"letter":"D","text":"Xây dựng quân đội vững mạnh toàn diện trên cơ sở vững mạnh về kỹ thuật, chiến thuật.","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q2","number":2,"text":"Chọn phương án đúng về biện pháp phát huy sức mạnh quần chúng nhân dân trong lĩnh vực quân sự theo tư tưởng Hồ Chí Minh:","options":[{"letter":"A","text":"Xác định mục tiêu cách mạng đúng đắn; truyền bá hệ tư tưởng; xây dựng Đảng, Nhà nước và con người mới.","is_correct":true},{"letter":"B","text":"Xây dựng khối đại đoàn kết toàn dân, kết hợp phát triển kinh tế với tăng cường quốc phòng.","is_correct":false},{"letter":"C","text":"Tăng cường giáo dục chính trị, xây dựng lực lượng vũ trang và hậu phương vững mạnh.","is_correct":false},{"letter":"D","text":"Phát huy vai trò Mặt trận Tổ quốc, chăm lo đời sống vật chất, tinh thần của nhân dân.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q3","number":3,"text":"Hồ Chí Minh khẳng định: Độc lập, tự do chỉ có thể giành được bằng phương pháp nào sau đây?","options":[{"letter":"A","text":"Bằng bạo lực cách mạng của quần chúng nhân dân.","is_correct":true},{"letter":"B","text":"Bằng đấu tranh chính trị kết hợp với sự giúp đỡ của lực lượng quốc tế.","is_correct":false},{"letter":"C","text":"Bằng con đường thương lượng, đàm phán trên cơ sở giữ vững nguyên tắc.","is_correct":false},{"letter":"D","text":"Bằng việc xây dựng lực lượng chính trị vững mạnh mà không cần vũ trang.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q4","number":4,"text":"Nội dung phát huy sức mạnh của quần chúng nhân dân trong tư tưởng Hồ Chí Minh về bạo lực cách mạng?","options":[{"letter":"A","text":"Xây dựng khối đại đoàn kết toàn dân, lấy liên minh công - nông làm nền tảng.","is_correct":true},{"letter":"B","text":"Xây dựng lực lượng vũ trang ba thứ quân vững mạnh làm nòng cốt.","is_correct":false},{"letter":"C","text":"Kết hợp sức mạnh dân tộc với sức mạnh thời đại trong mọi hoàn cảnh.","is_correct":false},{"letter":"D","text":"Tiến hành đấu tranh chính trị là chủ yếu, đấu tranh quân sự là hỗ trợ.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q5","number":5,"text":"Giá trị lý luận của tư tưởng Hồ Chí Minh về nghệ thuật quân sự được thể hiện ở đâu?","options":[{"letter":"A","text":"Là sự tổng kết thực tiễn hai cuộc kháng chiến chống Pháp và chống Mỹ.","is_correct":false},{"letter":"B","text":"Là sự áp dụng nguyên mẫu nghệ thuật quân sự thế giới vào điều kiện Việt Nam.","is_correct":false},{"letter":"C","text":"Phát triển học thuyết quân sự Mác - Lênin; là nền tảng cho đường lối quân sự của Đảng.","is_correct":true},{"letter":"D","text":"Là sự kế thừa nghệ thuật quân sự dân tộc, không tiếp thu yếu tố bên ngoài.","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q6","number":6,"text":"Chọn phương án đúng về cơ sở tư tưởng, lý luận hình thành tư tưởng bạo lực cách mạng của Hồ Chí Minh:","options":[{"letter":"A","text":"Truyền thống dựng nước đi đôi với giữ nước, kinh nghiệm Công xã Paris và quan điểm Lênin về khởi nghĩa vũ trang.","is_correct":false},{"letter":"B","text":"Tư tưởng bạo lực trong truyền thống quân sự Việt Nam, kinh nghiệm xây dựng quân đội các nước xã hội chủ nghĩa và quan điểm Mác - Lênin.","is_correct":false},{"letter":"C","text":"Tinh hoa quân sự phương Đông, quan điểm của Clausewitz và lý luận Mác - Lênin về chiến tranh nhân dân.","is_correct":false},{"letter":"D","text":"Tư tưởng bạo lực trong truyền thống quân sự Việt Nam, tinh hoa quân sự nhân loại và quan điểm Mác - Lênin về bạo lực cách mạng.","is_correct":true}],"correct_letter":"D"},{"id":"ho-chi-minh-source-q7","number":7,"text":"Nội dung xây dựng quân đội vững mạnh toàn diện theo Hồ Chí Minh gồm những yếu tố nào?","options":[{"letter":"A","text":"Chính trị tư tưởng vững, tổ chức gọn mạnh, kỹ chiến thuật giỏi, kỷ luật nghiêm, sức khỏe tốt.","is_correct":true},{"letter":"B","text":"Bản lĩnh chính trị vững, trình độ chuyên môn cao, tác phong chính quy, hậu cần mạnh.","is_correct":false},{"letter":"C","text":"Tư tưởng vững, tổ chức chặt chẽ, đời sống bảo đảm, vũ khí trang bị tối tân.","is_correct":false},{"letter":"D","text":"Chính trị vững, trang bị hiện đại, hậu cần đầy đủ, kỹ thuật giỏi, đời sống bảo đảm.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q8","number":8,"text":"Chọn phương án đúng về vị trí của quần chúng nhân dân theo tư tưởng Hồ Chí Minh:","options":[{"letter":"A","text":"Là chỗ dựa của quân đội và là nguồn bảo đảm hậu cần cho kháng chiến.","is_correct":false},{"letter":"B","text":"Là lực lượng nòng cốt trong chiến tranh và là nguồn dự bị động viên của quân đội.","is_correct":false},{"letter":"C","text":"Là nền tảng của dân tộc; đối tượng lãnh đạo của Đảng; mục tiêu và động lực của cách mạng.","is_correct":true},{"letter":"D","text":"Là lực lượng quyết định thắng lợi và là động lực phát triển kinh tế - xã hội.","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q9","number":9,"text":"Chọn phương án đúng về nâng cao nhận thức xây dựng nền quốc phòng toàn dân theo tư tưởng Hồ Chí Minh hiện nay:","options":[{"letter":"A","text":"Coi bảo vệ Tổ quốc là nhiệm vụ nhất thời của lực lượng vũ trang, tách rời phát triển kinh tế.","is_correct":false},{"letter":"B","text":"Dựa vào đồng minh quân sự bên ngoài, giảm bớt vai trò của nền quốc phòng toàn dân.","is_correct":false},{"letter":"C","text":"Chỉ tiến hành bảo vệ Tổ quốc khi chiến tranh đã nổ ra, ưu tiên giải quyết tranh chấp bằng quân sự.","is_correct":false},{"letter":"D","text":"Kiên quyết, kiên trì bảo vệ Tổ quốc từ sớm, từ xa, giải quyết bất đồng bằng biện pháp hòa bình.","is_correct":true}],"correct_letter":"D"},{"id":"ho-chi-minh-source-q10","number":10,"text":"Chọn phương án đúng về đặc điểm bạo lực cách mạng là bạo lực của quần chúng nhân dân theo tư tưởng Hồ Chí Minh:","options":[{"letter":"A","text":"Mang tính tự phát, rộng rãi nhưng thiếu sự lãnh đạo thống nhất.","is_correct":false},{"letter":"B","text":"Mang tính giai cấp công nhân thuần túy, không bao gồm tầng lớp khác.","is_correct":false},{"letter":"C","text":"Có tổ chức và được rèn luyện trong đấu tranh cách mạng.","is_correct":true},{"letter":"D","text":"Do lực lượng vũ trang chuyên nghiệp tiến hành, tách rời quần chúng.","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q11","number":11,"text":"Tư tưởng Hồ Chí Minh về bạo lực cách mạng đối lập với tư tưởng nào sau đây?","options":[{"letter":"A","text":"Tư tưởng bất bạo động và tư tưởng bạo động, khủng bố, ám sát manh động.","is_correct":true},{"letter":"B","text":"Tư tưởng tiến công chiến lược và tư tưởng phòng ngự chiến lược.","is_correct":false},{"letter":"C","text":"Tư tưởng đánh nhanh thắng nhanh và tư tưởng chiến tranh trường kỳ.","is_correct":false},{"letter":"D","text":"Tư tưởng quân sự chuyên nghiệp và tư tưởng chiến tranh toàn dân.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q12","number":12,"text":"Sức mạnh của quần chúng nhân dân theo Hồ Chí Minh bao gồm những yếu tố nào?","options":[{"letter":"A","text":"Sức mạnh vật chất và sức mạnh tinh thần của quần chúng.","is_correct":true},{"letter":"B","text":"Sức mạnh chính trị và sức mạnh quân sự của quần chúng.","is_correct":false},{"letter":"C","text":"Sức mạnh của khối đại đoàn kết và lực lượng ba thứ quân.","is_correct":false},{"letter":"D","text":"Sức mạnh của lực lượng chính trị và lực lượng vũ trang.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q13","number":13,"text":"Chọn phương án đúng về sự cần thiết xây dựng hậu phương chiến tranh hiện nay khi vận dụng tư tưởng Hồ Chí Minh:","options":[{"letter":"A","text":"Đặc điểm, nhiệm vụ bảo vệ Tổ quốc; âm mưu chống phá của thế lực thù địch; thực trạng xây dựng các tiềm lực.","is_correct":true},{"letter":"B","text":"Yêu cầu xây dựng nền quốc phòng toàn dân và đặc điểm của chiến tranh công nghệ cao.","is_correct":false},{"letter":"C","text":"Âm mưu diễn biến hòa bình và yêu cầu kết hợp phát triển kinh tế với quốc phòng.","is_correct":false},{"letter":"D","text":"Nhiệm vụ bảo vệ Tổ quốc từ sớm, từ xa và yêu cầu xây dựng thế trận lòng dân.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q14","number":14,"text":"Theo Hồ Chí Minh, xây dựng hậu phương vững mạnh về quân sự cần tập trung vào nội dung nào sau đây?","options":[{"letter":"A","text":"Xây dựng lực lượng thường trực và lực lượng dự bị động viên hùng hậu.","is_correct":false},{"letter":"B","text":"Xây dựng thế trận chiến tranh nhân dân vững chắc trên cả nước.","is_correct":false},{"letter":"C","text":"Tăng cường khả năng phòng thủ ở hậu phương và chi viện cho tiền tuyến.","is_correct":false},{"letter":"D","text":"Xây dựng lực lượng vũ trang ba thứ quân và nền quốc phòng toàn dân ở hậu phương.","is_correct":true}],"correct_letter":"D"},{"id":"ho-chi-minh-source-q15","number":15,"text":"Nội dung nào thể hiện tính chất nhân văn, nhân đạo của bạo lực cách mạng trong tư tưởng Hồ Chí Minh?","options":[{"letter":"A","text":"Chiến tranh là giải pháp cuối cùng, luôn tìm cách hạn chế đổ máu.","is_correct":true},{"letter":"B","text":"Dựa chắc vào sức mạnh của quần chúng nhân dân để tiến hành chiến tranh.","is_correct":false},{"letter":"C","text":"Kết hợp chặt chẽ đấu tranh quân sự với đấu tranh chính trị trong mọi giai đoạn.","is_correct":false},{"letter":"D","text":"Sử dụng bạo lực quyết liệt nhằm nhanh chóng tiêu diệt toàn bộ kẻ thù.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q16","number":16,"text":"Chọn phương án đúng về nhân tố cơ bản quyết định sức mạnh của nền quốc phòng toàn dân theo tư tưởng Hồ Chí Minh:","options":[{"letter":"A","text":"Sức mạnh văn hóa, khoa học kỹ thuật.","is_correct":false},{"letter":"B","text":"Sức mạnh chính trị, tư tưởng.","is_correct":true},{"letter":"C","text":"Sức mạnh kinh tế, vật chất.","is_correct":false},{"letter":"D","text":"Sức mạnh quân sự, vũ trang.","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q17","number":17,"text":"Chọn phương án đúng về cơ sở thực tiễn hình thành tư tưởng Hồ Chí Minh về bạo lực cách mạng:","options":[{"letter":"A","text":"Thực dân Pháp dùng bạo lực phản cách mạng cai trị Việt Nam; thực tiễn các phong trào yêu nước cuối thế kỷ XIX - đầu thế kỷ XX; kinh nghiệm các cuộc cách mạng trên thế giới.","is_correct":true},{"letter":"B","text":"Thực tiễn kháng chiến chống Pháp và chống Mỹ; kinh nghiệm Cách mạng Tháng Mười Nga; truyền thống quân sự dân tộc.","is_correct":false},{"letter":"C","text":"Thực tiễn xây dựng căn cứ địa cách mạng; kinh nghiệm Công xã Paris; sự thất bại của các phong trào yêu nước theo khuynh hướng tư sản.","is_correct":false},{"letter":"D","text":"Thực tiễn cách mạng Việt Nam từ 1930 đến 1945; kinh nghiệm Hồng quân Liên Xô; quan điểm của Tôn Tử về chiến tranh.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q18","number":18,"text":"Quan điểm nào sau đây KHÔNG mang tính nguyên tắc trong tư tưởng Hồ Chí Minh về bạo lực cách mạng?","options":[{"letter":"A","text":"Quan điểm cho rằng bạo lực cách mạng không cần dựa vào quần chúng nhân dân.","is_correct":true},{"letter":"B","text":"Quan điểm về tính tất yếu phải sử dụng bạo lực cách mạng để giành và giữ chính quyền.","is_correct":false},{"letter":"C","text":"Quan điểm về bạo lực cách mạng là bạo lực của quần chúng nhân dân.","is_correct":false},{"letter":"D","text":"Quan điểm về tính chất nhân văn, nhân đạo của bạo lực cách mạng.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q19","number":19,"text":"Bản chất giai cấp công nhân của Quân đội ta thống nhất với tính nhân dân và tính dân tộc ở điểm nào?","options":[{"letter":"A","text":"Quân đội tuyệt đối trung thành với Đảng và sẵn sàng chiến đấu, hy sinh.","is_correct":false},{"letter":"B","text":"Quân đội mang tinh thần quốc tế vô sản trong sáng, chân chính.","is_correct":false},{"letter":"C","text":"Quân đội có kỷ luật tự giác, nghiêm minh và nội bộ luôn đoàn kết.","is_correct":false},{"letter":"D","text":"Quân đội từ nhân dân mà ra, vì nhân dân mà chiến đấu, không có lợi ích nào khác ngoài lợi ích của nhân dân.","is_correct":true}],"correct_letter":"D"},{"id":"ho-chi-minh-source-q20","number":20,"text":"Theo Hồ Chí Minh, “thế” được hiểu là gì?","options":[{"letter":"A","text":"Tổng thể hoàn cảnh, điều kiện cùng xu thế vận động, khả năng phát triển của các bên tham chiến.","is_correct":true},{"letter":"B","text":"Tài chỉ huy và thao lược của đội ngũ tướng lĩnh.","is_correct":false},{"letter":"C","text":"Thời cơ thuận lợi nhất để tiến công tiêu diệt địch.","is_correct":false},{"letter":"D","text":"Sức mạnh vật chất, tinh thần của toàn dân tộc trong chiến tranh.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q21","number":21,"text":"Chọn phương án đúng về xây dựng hậu phương chiến tranh hiện nay khi vận dụng tư tưởng Hồ Chí Minh:","options":[{"letter":"A","text":"Xây dựng các tiềm lực, thế trận lòng dân, thế trận quốc phòng toàn dân gắn với an ninh nhân dân.","is_correct":true},{"letter":"B","text":"Tăng cường tiềm lực kinh tế và tiềm lực quân sự của đất nước.","is_correct":false},{"letter":"C","text":"Xây dựng lực lượng vũ trang vững mạnh và hoàn thiện pháp luật quốc phòng.","is_correct":false},{"letter":"D","text":"Phát huy vai trò của cả hệ thống chính trị và của toàn thể nhân dân.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q22","number":22,"text":"Chọn phương án đúng về nội dung phát huy sức mạnh quần chúng nhân dân theo tư tưởng Hồ Chí Minh:","options":[{"letter":"A","text":"Nâng cao dân trí và củng cố khối đại đoàn kết toàn dân.","is_correct":true},{"letter":"B","text":"Phát triển kinh tế gắn với tăng cường quốc phòng.","is_correct":false},{"letter":"C","text":"Xây dựng lực lượng vũ trang ba thứ quân và thế trận quốc phòng.","is_correct":false},{"letter":"D","text":"Giáo dục lòng yêu nước và xây dựng hậu phương vững mạnh.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q23","number":23,"text":"Khi xây dựng thế trận quốc phòng toàn dân và thế trận an ninh nhân dân hiện nay, yếu tố quan trọng nhất là gì?","options":[{"letter":"A","text":"Xây dựng “thế trận lòng dân” vững chắc trong toàn dân.","is_correct":true},{"letter":"B","text":"Xây dựng thế trận phòng thủ vững chắc ở khu vực biên giới, biển đảo.","is_correct":false},{"letter":"C","text":"Xây dựng thế trận hậu cần - kỹ thuật tại chỗ ở các địa phương.","is_correct":false},{"letter":"D","text":"Xây dựng thế trận phòng không nhân dân trên các hướng chiến lược.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q24","number":24,"text":"Chọn phương án đúng về cơ sở tư tưởng, lý luận hình thành tư tưởng xây dựng nền quốc phòng toàn dân của Hồ Chí Minh:","options":[{"letter":"A","text":"Truyền thống lấy nhỏ thắng lớn của dân tộc; kinh nghiệm quân sự của Trung Quốc; lý luận Mác - Lênin về khởi nghĩa vũ trang.","is_correct":false},{"letter":"B","text":"Truyền thống “ngụ binh ư nông” của dân tộc; tinh hoa quân sự phương Đông; lý luận Mác - Lênin về xây dựng quân đội kiểu mới.","is_correct":false},{"letter":"C","text":"Truyền thống dựng nước đi đôi với giữ nước; tinh hoa quân sự Đông - Tây; lý luận Mác - Lênin về bảo vệ Tổ quốc xã hội chủ nghĩa.","is_correct":true},{"letter":"D","text":"Truyền thống đánh giặc giữ nước của dân tộc; kinh nghiệm xây dựng quốc phòng của Liên Xô; lý luận Mác - Lênin về chiến tranh nhân dân.","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q25","number":25,"text":"Chọn phương án đúng về sự cần thiết phải phát huy sức mạnh quần chúng nhân dân trong lĩnh vực quân sự:","options":[{"letter":"A","text":"Vai trò của quần chúng trong hoạt động quân sự, bài học lịch sử dân tộc và mục tiêu, nhiệm vụ cách mạng Việt Nam.","is_correct":true},{"letter":"B","text":"Âm mưu chống phá của các thế lực thù địch và nhiệm vụ bảo vệ Tổ quốc.","is_correct":false},{"letter":"C","text":"Yêu cầu xây dựng nền quốc phòng toàn dân và đặc điểm của chiến tranh hiện đại.","is_correct":false},{"letter":"D","text":"Vai trò của nhân tố chính trị - tinh thần và kinh nghiệm cách mạng thế giới.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q26","number":26,"text":"Chọn phương án đúng về hình thức phát huy sức mạnh quần chúng nhân dân trong lĩnh vực quân sự theo tư tưởng Hồ Chí Minh:","options":[{"letter":"A","text":"Xây dựng bạo lực cách mạng, lực lượng vũ trang ba thứ quân, chiến tranh nhân dân và nền quốc phòng toàn dân.","is_correct":true},{"letter":"B","text":"Xây dựng lực lượng chính trị của quần chúng và lấy đấu tranh chính trị làm chủ yếu.","is_correct":false},{"letter":"C","text":"Xây dựng căn cứ địa cách mạng, thực hiện ba mũi giáp công và nổi dậy toàn dân.","is_correct":false},{"letter":"D","text":"Xây dựng thế trận lòng dân, tăng cường công tác địch vận và binh vận.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q27","number":27,"text":"Theo Hồ Chí Minh, “lực” được hiểu là gì?","options":[{"letter":"A","text":"Sức mạnh vật chất, tinh thần của cá nhân, đơn vị, địa phương và cả nước.","is_correct":true},{"letter":"B","text":"Tổng thể hoàn cảnh, điều kiện khách quan của các bên tham chiến.","is_correct":false},{"letter":"C","text":"Xu thế vận động và khả năng phát triển của các bên tham chiến.","is_correct":false},{"letter":"D","text":"Thế tổ chức, bố trí lực lượng có lợi trên chiến trường.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q28","number":28,"text":"Nội dung vận dụng tư tưởng Hồ Chí Minh về phát huy sức mạnh quần chúng nhân dân hiện nay gồm những vấn đề nào?","options":[{"letter":"A","text":"Nâng cao nhận thức về vai trò quần chúng, phát huy đại đoàn kết dân tộc, hoàn thiện pháp luật quốc phòng.","is_correct":true},{"letter":"B","text":"Giáo dục lòng yêu nước, xây dựng lực lượng dự bị động viên hùng hậu.","is_correct":false},{"letter":"C","text":"Xây dựng thế trận lòng dân, tăng cường tiềm lực quốc phòng, an ninh của đất nước.","is_correct":false},{"letter":"D","text":"Nâng cao cảnh giác cách mạng, xây dựng nền quốc phòng toàn dân vững mạnh.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q29","number":29,"text":"Giá trị thực tiễn của tư tưởng Hồ Chí Minh về xây dựng nền quốc phòng toàn dân được thể hiện ở đâu?","options":[{"letter":"A","text":"Bảo vệ vững chắc miền Bắc, xây dựng miền Bắc thành hậu phương lớn cho cách mạng miền Nam.","is_correct":true},{"letter":"B","text":"Bảo vệ vững chắc miền Nam, xây dựng miền Nam thành căn cứ địa cho cách mạng miền Bắc.","is_correct":false},{"letter":"C","text":"Giúp đánh thắng thực dân Pháp, hoàn thành xây dựng chủ nghĩa xã hội trên phạm vi cả nước.","is_correct":false},{"letter":"D","text":"Giúp ngăn chặn mọi cuộc tiến công của đối phương, tránh phải tiến hành chiến tranh giải phóng.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q30","number":30,"text":"Theo Hồ Chí Minh, tiêu chuẩn hàng đầu của cán bộ quân đội là gì?","options":[{"letter":"A","text":"Có cả đức và tài, trong đó đức là gốc của người cán bộ.","is_correct":true},{"letter":"B","text":"Có trình độ chuyên môn giỏi, năng lực chỉ huy và tổ chức thực tiễn.","is_correct":false},{"letter":"C","text":"Có tinh thần trách nhiệm cao và luôn gần gũi, thương yêu chiến sĩ.","is_correct":false},{"letter":"D","text":"Có bản lĩnh chính trị vững vàng, tác phong mẫu mực và gương mẫu.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q31","number":31,"text":"Hồ Chí Minh yêu cầu khi lựa chọn, xây dựng căn cứ địa cách mạng phải bảo đảm yếu tố nào?","options":[{"letter":"A","text":"Có giao thông thuận tiện, nguồn dự trữ dồi dào, lực lượng vũ trang mạnh.","is_correct":false},{"letter":"B","text":"Có vị trí trung tâm, dân trí cao, chính quyền vững chắc.","is_correct":false},{"letter":"C","text":"Có địa thế hiểm yếu, được quần chúng ủng hộ, có tổ chức đảng mạnh.","is_correct":true},{"letter":"D","text":"Có địa hình thuận lợi, dân cư đông đúc, kinh tế phát triển.","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q32","number":32,"text":"Chọn phương án đúng về xây dựng Quân đội nhân dân Việt Nam hiện nay khi vận dụng tư tưởng Hồ Chí Minh:","options":[{"letter":"A","text":"Giữ vững bản chất giai cấp công nhân, tính nhân dân, tính dân tộc; xây dựng quân đội vững mạnh toàn diện, lấy chính trị làm cơ sở.","is_correct":true},{"letter":"B","text":"Xây dựng quân đội tinh, gọn, mạnh, từng bước tiến lên hiện đại về kỹ thuật, trang bị.","is_correct":false},{"letter":"C","text":"Chăm lo đời sống vật chất, tinh thần cho bộ đội và thực hiện tốt chính sách hậu phương.","is_correct":false},{"letter":"D","text":"Nâng cao chất lượng huấn luyện, sẵn sàng chiến đấu và khả năng hiệp đồng tác chiến.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q33","number":33,"text":"Quan điểm Hồ Chí Minh về khởi đầu và kết thúc chiến tranh đúng lúc nhằm mục đích gì?","options":[{"letter":"A","text":"Buộc đối phương phải rút quân ngay lập tức, không điều kiện.","is_correct":false},{"letter":"B","text":"Giành thế chủ động chiến lược, tránh tổn thất không cần thiết.","is_correct":true},{"letter":"C","text":"Kéo dài chiến tranh nhằm làm kiệt quệ kinh tế của đối phương.","is_correct":false},{"letter":"D","text":"Tiêu diệt tối đa sinh lực địch trong thời gian ngắn.","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q34","number":34,"text":"Chọn phương án đúng về tư tưởng xuyên suốt trong chỉ đạo chiến lược trong nghệ thuật quân sự của Hồ Chí Minh:","options":[{"letter":"A","text":"Nắm vững tư tưởng chiến lược tiến công, giành và giữ quyền chủ động.","is_correct":true},{"letter":"B","text":"Giữ thế phòng ngự chiến lược là chủ yếu, chỉ tiến công khi đủ điều kiện.","is_correct":false},{"letter":"C","text":"Lấy tác chiến chiến dịch làm phương thức chủ yếu để kết thúc chiến tranh.","is_correct":false},{"letter":"D","text":"Đánh nhanh thắng nhanh trong mọi điều kiện, hoàn cảnh của chiến tranh.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q35","number":35,"text":"Chọn phương án đúng về giá trị lý luận xây dựng Quân đội nhân dân Việt Nam của Hồ Chí Minh:","options":[{"letter":"A","text":"Làm phong phú học thuyết Mác - Lênin về quân đội; là cơ sở để Đảng xác định đường lối xây dựng quân đội.","is_correct":true},{"letter":"B","text":"Là sự vận dụng sáng tạo kinh nghiệm xây dựng quân đội của các nước xã hội chủ nghĩa.","is_correct":false},{"letter":"C","text":"Là sự tổng kết thực tiễn xây dựng quân đội trong hai cuộc kháng chiến chống Pháp, chống Mỹ.","is_correct":false},{"letter":"D","text":"Là sự kế thừa truyền thống xây dựng quân đội của dân tộc qua các thời kỳ lịch sử.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q36","number":36,"text":"Chọn phương án đúng về hai hình thức cơ bản của bạo lực cách mạng theo tư tưởng Hồ Chí Minh:","options":[{"letter":"A","text":"Đấu tranh chính trị và đấu tranh tư tưởng.","is_correct":false},{"letter":"B","text":"Đấu tranh quân sự và đấu tranh binh vận.","is_correct":false},{"letter":"C","text":"Đấu tranh chính trị và đấu tranh vũ trang.","is_correct":true},{"letter":"D","text":"Đấu tranh vũ trang và đấu tranh ngoại giao.","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q37","number":37,"text":"Chọn phương án đúng về cơ sở tư tưởng, lý luận hình thành tư tưởng Hồ Chí Minh về xây dựng Quân đội nhân dân Việt Nam:","options":[{"letter":"A","text":"Truyền thống “ngụ binh ư nông” của dân tộc và kinh nghiệm xây dựng Hồng quân Liên Xô.","is_correct":false},{"letter":"B","text":"Truyền thống xây dựng quân đội của dân tộc; kinh nghiệm xây dựng quân đội trên thế giới; lý luận Mác - Lênin về quân đội kiểu mới.","is_correct":true},{"letter":"C","text":"Kinh nghiệm xây dựng Giải phóng quân Trung Quốc và quan điểm của Tôn Tử.","is_correct":false},{"letter":"D","text":"Lý luận Mác - Lênin và thực tiễn cách mạng Việt Nam qua các thời kỳ.","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q38","number":38,"text":"Cơ sở tư tưởng, lý luận hình thành tư tưởng Hồ Chí Minh về xây dựng hậu phương chiến tranh gồm những nội dung nào?","options":[{"letter":"A","text":"Tinh hoa quân sự phương Đông và lý luận về chiến tranh nhân dân của Việt Nam.","is_correct":false},{"letter":"B","text":"Truyền thống dựng nước đi đôi với giữ nước và kinh nghiệm xây dựng hậu phương của Liên Xô.","is_correct":false},{"letter":"C","text":"Truyền thống coi trọng xây dựng hậu phương của dân tộc; giá trị tiến bộ về hậu phương trên thế giới; lý luận Mác - Lênin về hậu phương.","is_correct":true},{"letter":"D","text":"Kinh nghiệm kháng chiến chống Pháp, chống Mỹ và quan điểm Mác - Lênin về chiến tranh.","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q39","number":39,"text":"Chọn phương án đúng về tính chất của nền quốc phòng toàn dân theo tư tưởng Hồ Chí Minh:","options":[{"letter":"A","text":"Là nền quốc phòng của dân, do dân, vì dân, huy động sức mạnh toàn dân tộc.","is_correct":true},{"letter":"B","text":"Là nền quốc phòng của giai cấp công nhân, do Đảng lãnh đạo, vì nhiệm vụ cách mạng.","is_correct":false},{"letter":"C","text":"Là nền quốc phòng của nhà nước, do quân đội xây dựng, vì an ninh quốc gia.","is_correct":false},{"letter":"D","text":"Là nền quốc phòng của Đảng, do lực lượng vũ trang đảm nhiệm, vì sự ổn định chế độ.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q40","number":40,"text":"Theo Hồ Chí Minh, “mưu” được hiểu là gì?","options":[{"letter":"A","text":"Sự kết hợp chặt chẽ giữa lực lượng chính trị và lực lượng vũ trang.","is_correct":false},{"letter":"B","text":"Chủ trương, quyết tâm chiến lược, chiến dịch, chiến đấu; tài chỉ huy, nghệ thuật nghi binh lừa địch.","is_correct":true},{"letter":"C","text":"Thế trận lòng dân vững chắc, rộng khắp trên toàn quốc.","is_correct":false},{"letter":"D","text":"Khả năng huy động tối đa sức người, sức của cho kháng chiến.","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q41","number":41,"text":"Theo Hồ Chí Minh, nhân tố căn bản để kết hợp với nghệ thuật ngoại giao trong đấu tranh ngoại giao là gì?","options":[{"letter":"A","text":"Thực lực của cách mạng ta.","is_correct":true},{"letter":"B","text":"Sự giúp đỡ của các nước lớn.","is_correct":false},{"letter":"C","text":"Nghệ thuật đàm phán khéo léo.","is_correct":false},{"letter":"D","text":"Sự ủng hộ của dư luận quốc tế.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q42","number":42,"text":"Theo Hồ Chí Minh, xây dựng hậu phương chiến tranh phải gắn với nội dung nào?","options":[{"letter":"A","text":"Phải gắn với phát triển văn hóa, giáo dục toàn dân.","is_correct":false},{"letter":"B","text":"Phải gắn với tăng cường tiềm lực kinh tế của đất nước.","is_correct":false},{"letter":"C","text":"Phải gắn với xây dựng lực lượng chính trị của quần chúng.","is_correct":false},{"letter":"D","text":"Phải gắn xây dựng với bảo vệ và phát triển hậu phương.","is_correct":true}],"correct_letter":"D"},{"id":"ho-chi-minh-source-q43","number":43,"text":"Nội dung nào sau đây thuộc nghệ thuật chỉ đạo chiến tranh trong tư tưởng Hồ Chí Minh?","options":[{"letter":"A","text":"Xây dựng quân đội vững mạnh toàn diện về chính trị, tổ chức, kỹ thuật.","is_correct":false},{"letter":"B","text":"Xây dựng hậu phương chiến tranh vững mạnh về chính trị, kinh tế, quân sự.","is_correct":false},{"letter":"C","text":"Chủ động đánh vào lòng người đối phương, kết hợp chặt chẽ tác chiến với địch vận.","is_correct":true},{"letter":"D","text":"Xây dựng nền quốc phòng toàn dân gắn với an ninh nhân dân.","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q44","number":44,"text":"Chọn phương án đúng về sự cần thiết vận dụng tư tưởng Hồ Chí Minh trong phát huy sức mạnh quần chúng nhân dân hiện nay:","options":[{"letter":"A","text":"Vai trò của quần chúng nhân dân; thuận lợi, thách thức của kinh tế thị trường; sự chống phá của các thế lực thù địch.","is_correct":true},{"letter":"B","text":"Vai trò của nhân tố con người và nhiệm vụ xây dựng nền quốc phòng toàn dân.","is_correct":false},{"letter":"C","text":"Âm mưu diễn biến hòa bình và yêu cầu xây dựng thế trận lòng dân vững chắc.","is_correct":false},{"letter":"D","text":"Đặc điểm chiến tranh công nghệ cao và yêu cầu xây dựng quân đội tinh, gọn, mạnh.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q45","number":45,"text":"Chọn phương án đúng về giá trị lý luận tư tưởng Hồ Chí Minh về bạo lực cách mạng:","options":[{"letter":"A","text":"Là bước phát triển mới về chất tư tưởng bạo lực của dân tộc; bổ sung, phát triển học thuyết quân sự Mác - Lênin.","is_correct":true},{"letter":"B","text":"Là sự kế thừa hoàn toàn tư tưởng bạo lực cách mạng của chủ nghĩa Mác - Lênin vào điều kiện Việt Nam.","is_correct":false},{"letter":"C","text":"Là sự kết hợp giữa truyền thống quân sự phương Đông và phương Tây trong điều kiện Việt Nam.","is_correct":false},{"letter":"D","text":"Là sự tổng kết thực tiễn hai cuộc kháng chiến chống Pháp và chống Mỹ cứu nước của dân tộc.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q46","number":46,"text":"Giá trị lý luận về xây dựng nền quốc phòng toàn dân hiện nay theo tư tưởng Hồ Chí Minh:","options":[{"letter":"A","text":"Làm phong phú học thuyết quân sự Mác - Lênin; là nền tảng để Đảng hoạch định đường lối quốc phòng.","is_correct":true},{"letter":"B","text":"Là sự tổng kết thực tiễn xây dựng quốc phòng trong hai cuộc kháng chiến chống Pháp, chống Mỹ cứu nước.","is_correct":false},{"letter":"C","text":"Là sự kế thừa nguyên vẹn truyền thống quân sự dân tộc cùng kinh nghiệm quân sự của thế giới.","is_correct":false},{"letter":"D","text":"Là sự vận dụng nguyên mẫu lý luận bảo vệ Tổ quốc xã hội chủ nghĩa của các nước anh em.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q47","number":47,"text":"Chọn phương án đúng về phương hướng xây dựng Quân đội nhân dân Việt Nam theo tư tưởng Hồ Chí Minh:","options":[{"letter":"A","text":"Xây dựng quân đội cách mạng, chính quy, tinh nhuệ, từng bước hiện đại.","is_correct":true},{"letter":"B","text":"Xây dựng quân đội chính quy, tinh nhuệ, hiện đại ngay từ đầu.","is_correct":false},{"letter":"C","text":"Xây dựng quân đội cách mạng, tinh nhuệ, hiện đại, chuyên nghiệp.","is_correct":false},{"letter":"D","text":"Xây dựng quân đội cách mạng, chính quy, tinh nhuệ, kiêm chức.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q48","number":48,"text":"Chọn phương án đúng về cơ sở tư tưởng, lý luận hình thành tư tưởng Hồ Chí Minh về phát huy sức mạnh quần chúng nhân dân trong lĩnh vực quân sự:","options":[{"letter":"A","text":"Truyền thống quân sự dân tộc, tinh hoa quân sự thế giới và quan điểm Mác - Lênin về quần chúng nhân dân.","is_correct":true},{"letter":"B","text":"Truyền thống dựng nước đi đôi với giữ nước và kinh nghiệm Cách mạng Tháng Mười Nga.","is_correct":false},{"letter":"C","text":"Tinh hoa quân sự phương Đông và quan điểm của Tôn Tử về chiến tranh.","is_correct":false},{"letter":"D","text":"Kinh nghiệm Hồng quân Liên Xô và lý luận về chiến tranh nhân dân.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q49","number":49,"text":"Theo Hồ Chí Minh, vị trí của hậu phương chiến tranh được xác định như thế nào?","options":[{"letter":"A","text":"Là nơi xây dựng căn cứ địa và dự trữ chiến lược cho kháng chiến.","is_correct":false},{"letter":"B","text":"Là nơi cung cấp sức người, sức của cho tiền tuyến trong chiến tranh.","is_correct":false},{"letter":"C","text":"Là địa bàn đứng chân và triển khai của các lực lượng vũ trang.","is_correct":false},{"letter":"D","text":"Là nhân tố hết sức quan trọng, quyết định thắng lợi của cách mạng.","is_correct":true}],"correct_letter":"D"},{"id":"ho-chi-minh-source-q50","number":50,"text":"Theo Hồ Chí Minh, muốn thắng địch trước hết phải làm gì?","options":[{"letter":"A","text":"Tạo thế có lợi cho ta trên chiến trường.","is_correct":false},{"letter":"B","text":"Thực hiện nghi binh, lừa địch để giành thắng lợi.","is_correct":false},{"letter":"C","text":"Chớp đúng thời cơ để tiến công địch.","is_correct":false},{"letter":"D","text":"Xây dựng, phát triển thực lực của ta về mọi mặt.","is_correct":true}],"correct_letter":"D"},{"id":"ho-chi-minh-source-q51","number":51,"text":"Chọn phương án đúng về xây dựng nền quốc phòng toàn dân theo tư tưởng Hồ Chí Minh:","options":[{"letter":"A","text":"Mang tính nhất thời, được triển khai theo từng giai đoạn tùy diễn biến của tình hình.","is_correct":false},{"letter":"B","text":"Chỉ tiến hành khi xuất hiện nguy cơ chiến tranh, tập trung vào thời gian đất nước lâm nguy.","is_correct":false},{"letter":"C","text":"Có mục đích, có kế hoạch và được chuẩn bị thường xuyên cả trong hòa bình lẫn chiến tranh.","is_correct":true},{"letter":"D","text":"Chủ yếu do quân đội thực hiện, nhân dân tham gia khi có yêu cầu huy động của cấp trên.","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q52","number":52,"text":"Cơ sở thực tiễn hình thành tư tưởng Hồ Chí Minh về xây dựng hậu phương chiến tranh gồm những yếu tố nào?","options":[{"letter":"A","text":"Thực tiễn xây dựng hậu phương của Liên Xô và thực tiễn kháng chiến chống Pháp, chống Mỹ ở Việt Nam.","is_correct":true},{"letter":"B","text":"Thực tiễn Cách mạng Tháng Mười Nga và cuộc nội chiến ở nước Nga Xô viết.","is_correct":false},{"letter":"C","text":"Thực tiễn các phong trào yêu nước cuối thế kỷ XIX và Cách mạng Tân Hợi ở Trung Quốc.","is_correct":false},{"letter":"D","text":"Thực tiễn chiến tranh giữ nước thời Trần, thời Lê và kinh nghiệm của Trung Quốc.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q53","number":53,"text":"Lựa chọn phương án đúng về giá trị thực tiễn của tư tưởng phát huy sức mạnh quần chúng nhân dân trong lĩnh vực quân sự:","options":[{"letter":"A","text":"Tạo sức mạnh to lớn trong giành chính quyền, hai cuộc kháng chiến và xây dựng thế trận quốc phòng toàn dân.","is_correct":true},{"letter":"B","text":"Chỉ xây dựng thành công lực lượng vũ trang ba thứ quân và bảo vệ miền Bắc.","is_correct":false},{"letter":"C","text":"Chỉ tạo sức mạnh trong giai đoạn đánh thắng hai cuộc kháng chiến và thống nhất đất nước.","is_correct":false},{"letter":"D","text":"Chỉ huy động nguồn lực cho chiến tranh, không gắn với xây dựng quốc phòng toàn dân.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q54","number":54,"text":"Cơ sở tư tưởng, lý luận hình thành tư tưởng Hồ Chí Minh về nghệ thuật quân sự:","options":[{"letter":"A","text":"Binh pháp Tôn Tử, nghệ thuật tác chiến của Napoléon và kinh nghiệm quân sự Trung Quốc.","is_correct":false},{"letter":"B","text":"Truyền thống lấy nhỏ thắng lớn của dân tộc và kinh nghiệm xây dựng Hồng quân Liên Xô.","is_correct":false},{"letter":"C","text":"Nghệ thuật quân sự dân tộc, tinh hoa nghệ thuật quân sự thế giới và học thuyết quân sự Mác - Lênin.","is_correct":true},{"letter":"D","text":"Kinh nghiệm chiến tranh du kích và lý luận về chiến tranh nhân dân của Việt Nam.","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q55","number":55,"text":"Chọn phương án đúng về động lực xây dựng nền quốc phòng toàn dân theo tư tưởng Hồ Chí Minh:","options":[{"letter":"A","text":"Coi trọng động lực bên trong, không tiếp nhận thành tựu khoa học - kỹ thuật của thế giới.","is_correct":false},{"letter":"B","text":"Dựa chủ yếu vào động lực bên ngoài, lấy viện trợ quốc tế làm điều kiện quyết định.","is_correct":false},{"letter":"C","text":"Phát huy cao độ động lực bên trong, đồng thời khai thác hiệu quả động lực bên ngoài.","is_correct":true},{"letter":"D","text":"Lấy động lực quân sự làm quyết định, xem lực lượng thường trực là nguồn sức mạnh chủ yếu.","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q56","number":56,"text":"Giá trị thực tiễn của tư tưởng Hồ Chí Minh về xây dựng hậu phương chiến tranh được thể hiện ở phương án nào sau đây:","options":[{"letter":"A","text":"Huy động sức người, sức của cho hai cuộc kháng chiến của dân tộc.","is_correct":false},{"letter":"B","text":"Bảo vệ vững chắc miền Bắc xã hội chủ nghĩa và hoàn thành thống nhất đất nước.","is_correct":false},{"letter":"C","text":"Xây dựng Việt Bắc thành căn cứ địa, miền Bắc thành hậu phương lớn của miền Nam.","is_correct":true},{"letter":"D","text":"Xây dựng thành công thế trận quốc phòng toàn dân trong thời bình.","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q57","number":57,"text":"Theo Hồ Chí Minh, xây dựng đội ngũ cán bộ quân đội có đức và tài giữ vị trí như thế nào?","options":[{"letter":"A","text":"Là nội dung quan trọng của việc xây dựng quân đội hiện đại.","is_correct":false},{"letter":"B","text":"Là yêu cầu cơ bản của việc xây dựng quân đội chính quy.","is_correct":false},{"letter":"C","text":"Là khâu then chốt trong xây dựng quân đội vững mạnh về chính trị.","is_correct":true},{"letter":"D","text":"Là nhiệm vụ thường xuyên của công tác cán bộ trong quân đội.","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q58","number":58,"text":"Bản chất giai cấp của Quân đội nhân dân Việt Nam theo tư tưởng Hồ Chí Minh là gì?","options":[{"letter":"A","text":"Mang bản chất giai cấp công nhân và tính quốc tế vô sản.","is_correct":false},{"letter":"B","text":"Mang tính nhân dân và tính chính quy, không mang bản chất giai cấp.","is_correct":false},{"letter":"C","text":"Mang bản chất giai cấp công nhân và tính hiện đại, tinh nhuệ.","is_correct":false},{"letter":"D","text":"Mang bản chất giai cấp công nhân, tính nhân dân và tính dân tộc sâu sắc.","is_correct":true}],"correct_letter":"D"},{"id":"ho-chi-minh-source-q59","number":59,"text":"Theo Hồ Chí Minh, “thời” được hiểu là gì?","options":[{"letter":"A","text":"Sức mạnh tổng hợp của toàn dân tộc trong chiến tranh.","is_correct":false},{"letter":"B","text":"Thế bố trí lực lượng có lợi cho ta trên chiến trường.","is_correct":false},{"letter":"C","text":"Nghệ thuật nghi binh, lừa địch trong tác chiến.","is_correct":false},{"letter":"D","text":"Tình hình trong nước, khu vực, thế giới thuận lợi và thời điểm tiến công địch có lợi nhất.","is_correct":true}],"correct_letter":"D"},{"id":"ho-chi-minh-source-q60","number":60,"text":"Nội dung cốt lõi trong xây dựng hậu phương vững mạnh về chính trị theo tư tưởng Hồ Chí Minh là gì?","options":[{"letter":"A","text":"Xây dựng thế trận lòng dân, củng cố niềm tin của nhân dân vào Đảng, Nhà nước.","is_correct":true},{"letter":"B","text":"Xây dựng tổ chức đảng vững mạnh ở các cấp, các địa phương.","is_correct":false},{"letter":"C","text":"Xây dựng chính quyền và các đoàn thể nhân dân ở cơ sở.","is_correct":false},{"letter":"D","text":"Tổ chức phong trào thi đua yêu nước rộng khắp trong nhân dân.","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q61","number":61,"text":"Luận điểm: “Cách mạng là sự nghiệp của quần chúng, kháng chiến toàn diện phải dựa vào sức dân” thể hiện bản chất nào sau đây?","options":[{"letter":"A","text":"Hậu phương chỉ phục vụ các nhu cầu vật chất tiền tuyến","is_correct":false},{"letter":"B","text":"Hậu phương không chịu tác động từ diễn biến ngoài mặt trận","is_correct":false},{"letter":"C","text":"Hậu phương hoàn toàn độc lập với sự chỉ đạo của Đảng","is_correct":false},{"letter":"D","text":"Hậu phương mang tính toàn dân, toàn diện sâu sắc","is_correct":true}],"correct_letter":"D"},{"id":"ho-chi-minh-source-q62","number":62,"text":"Theo Hồ Chí Minh, cơ sở thực tiễn trực tiếp dẫn đến tất yếu phải dùng bạo lực cách mạng để tự giải phóng là gì?","options":[{"letter":"A","text":"Bản chất hiếu chiến, tàn bạo và việc dùng bạo lực phản cách mạng của kẻ thù","is_correct":true},{"letter":"B","text":"Yêu cầu xây dựng nhanh chóng lực lượng vũ trang cách mạng chính quy","is_correct":false},{"letter":"C","text":"Kinh nghiệm tiến hành các cuộc chiến tranh giải phóng từ phương Tây","is_correct":false},{"letter":"D","text":"Xu thế chuyển đổi mô hình kinh tế trong thời kỳ mới","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q63","number":63,"text":"Theo tư tưởng Hồ Chí Minh, mối quan hệ hữu cơ giữa tiền tuyến và hậu phương chiến tranh được xác định như thế nào?","options":[{"letter":"A","text":"Tiền tuyến quyết định tuyệt đối, hậu phương chỉ cung cấp sức người","is_correct":false},{"letter":"B","text":"Tiền tuyến và hậu phương gắn bó mật thiết, tác động qua lại lẫn nhau","is_correct":true},{"letter":"C","text":"Hậu phương luôn đóng vai trò bị động trước mọi yêu cầu tác chiến","is_correct":false},{"letter":"D","text":"Tiền tuyến và hậu phương độc lập tác chiến theo mục tiêu riêng","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q64","number":64,"text":"Chọn phương án đúng về mục đích của bạo lực cách mạng ở Việt Nam theo tư tưởng Hồ Chí Minh:","options":[{"letter":"A","text":"Tiêu diệt toàn bộ sinh lực đối phương bằng sức mạnh quân sự","is_correct":false},{"letter":"B","text":"Giành và giữ chính quyền, bảo vệ nền độc lập tự do của Tổ quốc","is_correct":true},{"letter":"C","text":"Khẳng định sức mạnh vượt trội của khối liên minh công nông","is_correct":false},{"letter":"D","text":"Thay đổi triệt để quan hệ ngoại giao với các nước đế quốc","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q65","number":65,"text":"Hồ Chí Minh yêu cầu người làm tướng trong Quân đội nhân dân Việt Nam phải hội tụ đủ những phẩm chất đạo đức nào?","options":[{"letter":"A","text":"Cần - Kiệm - Liêm - Chính - Chí công vô tư","is_correct":false},{"letter":"B","text":"Trí - Tín - Nhân - Nghĩa - Dũng - Cần","is_correct":false},{"letter":"C","text":"Trí - Dũng - Nhân - Tín - Liêm - Trung","is_correct":true},{"letter":"D","text":"Dũng - Trí - Nghĩa - Khiêm - Thành - Liêm","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q66","number":66,"text":"Để tránh đối đầu cùng lúc với nhiều kẻ thù nguy hiểm sau Cách mạng Tháng Tám năm 1945, Hồ Chí Minh đã chủ trương thực hiện nguyên tắc nào?","options":[{"letter":"A","text":"Nhượng bộ toàn bộ yêu sách kinh tế của quân đội Tưởng Giới Thạch","is_correct":false},{"letter":"B","text":"Kiên quyết dùng bạo lực vũ trang đánh trả tức thì mọi lực lượng can thiệp","is_correct":false},{"letter":"C","text":"Chờ đợi sự can thiệp từ các nước đồng minh lớn trên thế giới","is_correct":false},{"letter":"D","text":"Cứng rắn về nguyên tắc, mềm dẻo, linh hoạt về sách lược","is_correct":true}],"correct_letter":"D"},{"id":"ho-chi-minh-source-q67","number":67,"text":"Theo tư tưởng Hồ Chí Minh, sức mạnh ngoại giao có vai trò như thế nào trong sự nghiệp củng cố quốc phòng?","options":[{"letter":"A","text":"Là nền tảng vật chất cơ bản","is_correct":false},{"letter":"B","text":"Là thành tố quan trọng","is_correct":true},{"letter":"C","text":"Là nhân tố quyết định chiến trường","is_correct":false},{"letter":"D","text":"Là yếu tố trực tiếp giải quyết xung đột","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q68","number":68,"text":"Hồ Chí Minh chủ trương xây dựng nền quốc phòng Việt Nam mang tính chất cơ bản nào sau đây?","options":[{"letter":"A","text":"Toàn dân, toàn diện, độc lập, tự chủ","is_correct":true},{"letter":"B","text":"Tiên tiến, đậm đà bản sắc dân tộc","is_correct":false},{"letter":"C","text":"Dân tộc, khoa học, đại chúng","is_correct":false},{"letter":"D","text":"Liên minh, bảo trợ và vũ trang hiện đại","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q69","number":69,"text":"Tư tưởng Hồ Chí Minh về bạo lực cách mạng lần đầu tiên được khẳng định trong văn kiện nào sau đây?","options":[{"letter":"A","text":"Luận cương chính trị của Đảng (10/1930)","is_correct":false},{"letter":"B","text":"Tuyên ngôn của Hội Liên hiệp thuộc địa (1921)","is_correct":false},{"letter":"C","text":"Chính cương ngắn tắt của Đảng (2/1930)","is_correct":true},{"letter":"D","text":"Nghị quyết Hội nghị Ban Chấp hành Trung ương 8 (5/1941)","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q70","number":70,"text":"Hoàn chỉnh luận điểm của Hồ Chí Minh trong Thư gửi lớp cán bộ cung cấp, (6/1951): “Cung cấp đủ súng đạn, đủ cơm áo cho bộ đội thì bộ đội mới đánh thắng trận, điều đó rất rõ ràng dễ hiểu. Nhưng để làm cho đúng, thì phải có một chính sách rõ rệt, …”","options":[{"letter":"A","text":"một kế hoạch đầy đủ.","is_correct":false},{"letter":"B","text":"một tư tưởng thấu suốt.","is_correct":true},{"letter":"C","text":"một đội ngũ vững vàng.","is_correct":false},{"letter":"D","text":"một chủ nghĩa chắc chắn.","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q71","number":71,"text":"Chọn phương án đúng theo tư tưởng Hồ Chí Minh về đánh địch trên cả “ba vùng chiến lược”:","options":[{"letter":"A","text":"Rừng núi; nông thôn, đồng bằng; đô thị","is_correct":true},{"letter":"B","text":"Biên giới; nội địa; hải đảo xa bờ","is_correct":false},{"letter":"C","text":"Vùng trung du; duyên hải; hải phận quốc tế","is_correct":false},{"letter":"D","text":"Vùng giải phóng; vùng tranh chấp; vùng tạm chiếm","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q72","number":72,"text":"Theo quan điểm của Hồ Chí Minh, lực lượng tiến hành bạo lực cách mạng của quần chúng nhân dân bao gồm những yếu tố nào?","options":[{"letter":"A","text":"Lực lượng chính trị quần chúng và lực lượng vũ trang nhân dân","is_correct":true},{"letter":"B","text":"Lực lượng tự vệ ở địa phương và bộ đội thường trực","is_correct":false},{"letter":"C","text":"Lực lượng thanh niên xung phong và dân quân du kích","is_correct":false},{"letter":"D","text":"Lực lượng công nhân công xưởng và nông dân các địa phương","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q73","number":73,"text":"Chọn phương án đúng về hình thức tổ chức huy động sức mạnh của toàn thể nhân dân đánh giặc là gì?","options":[{"letter":"A","text":"Xây dựng nền quốc phòng toàn dân và thế trận chiến tranh nhân dân","is_correct":true},{"letter":"B","text":"Tổ chức các đội bảo an tư nhân tại làng xã","is_correct":false},{"letter":"C","text":"Thành lập các liên minh phòng thủ với lân bang","is_correct":false},{"letter":"D","text":"Tập trung toàn bộ dân cư vào các căn cứ quân sự","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q74","number":74,"text":"Chọn phương án đúng về phương châm tác chiến nổi bật trong nghệ thuật quân sự của Hồ Chí Minh:","options":[{"letter":"A","text":"Đánh nhanh thắng nhanh, tập trung hỏa lực áp đảo tuyệt đối đối phương","is_correct":false},{"letter":"B","text":"Dàn đều lực lượng trên mọi hướng để phòng ngự diện địa thụ động","is_correct":false},{"letter":"C","text":"Lấy nhỏ thắng lớn, lấy ít địch nhiều, lấy đoản binh thắng trường trận","is_correct":true},{"letter":"D","text":"Dựa vào viện trợ vũ khí hiện đại để mở các chiến dịch quy mô lớn","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q75","number":75,"text":"Tên gọi “Quân đội nhân dân Việt Nam” chính thức được Chủ tịch Hồ Chí Minh đặt ra vào thời gian nào?","options":[{"letter":"A","text":"Năm 1954","is_correct":false},{"letter":"B","text":"Năm 1945","is_correct":false},{"letter":"C","text":"Năm 1950","is_correct":true},{"letter":"D","text":"Năm 1944","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q76","number":76,"text":"Hội nghị Trung ương 8 (tháng 5/1941) do Nguyễn Ái Quốc chủ trì xác định, cuộc cách mạng Đông Dương phải kết liễu bằng hình thức nào?","options":[{"letter":"A","text":"Đấu tranh chính trị hợp pháp","is_correct":false},{"letter":"B","text":"Khởi nghĩa từng phần kết hợp bãi công","is_correct":false},{"letter":"C","text":"Đấu tranh nghị trường kết hợp ngoại giao","is_correct":false},{"letter":"D","text":"Khởi nghĩa vũ trang","is_correct":true}],"correct_letter":"D"},{"id":"ho-chi-minh-source-q77","number":77,"text":"Chọn phương án đúng về phương thức đánh địch bằng “ba mũi giáp công” theo tư tưởng Hồ Chí Minh:","options":[{"letter":"A","text":"Quân sự, chính trị, kinh tế","is_correct":false},{"letter":"B","text":"Quân sự, chính trị, binh vận","is_correct":true},{"letter":"C","text":"Quân sự, chính trị, ngoại giao","is_correct":false},{"letter":"D","text":"Quân sự, ngoại giao, kinh tế","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q78","number":78,"text":"Chọn phương án đúng về nội dung sức mạnh của quần chúng nhân dân trong lĩnh vực quân sự theo tư tưởng Hồ Chí Minh:","options":[{"letter":"A","text":"Tiềm lực kinh tế và tài chính quốc gia","is_correct":false},{"letter":"B","text":"Tổng thể sức mạnh vật chất và tinh thần","is_correct":true},{"letter":"C","text":"Khả năng chi viện của bạn bè quốc tế","is_correct":false},{"letter":"D","text":"Sức mạnh trang bị kỹ thuật quân sự","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q79","number":79,"text":"Theo Hồ Chí Minh, nhân tố nào giữ vai trò quan trọng nhất của sức mạnh chính trị - tinh thần trong xây dựng nền quốc phòng toàn dân?","options":[{"letter":"A","text":"Sự lãnh đạo tuyệt đối, trực tiếp về mọi mặt của Đảng","is_correct":true},{"letter":"B","text":"Tỷ lệ phát triển kinh tế thương mại hàng năm","is_correct":false},{"letter":"C","text":"Khả năng dự trữ ngân sách tài chính của các địa phương","is_correct":false},{"letter":"D","text":"Hệ thống pháp luật và kỷ cương của chính quyền dân sự","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q80","number":80,"text":"Trong Thư gửi lớp cán bộ cung cấp (6/1951), Hồ Chí Minh khẳng định: “Công việc cung cấp cũng quan trọng như việc…”","options":[{"letter":"A","text":"Huấn luyện điều lệnh đội ngũ nơi hậu phương","is_correct":false},{"letter":"B","text":"Trực tiếp đánh giặc trước mặt trận","is_correct":true},{"letter":"C","text":"Xây dựng hệ thống công sự trận địa vững chắc","is_correct":false},{"letter":"D","text":"Chỉ huy tác chiến của các cơ quan tham mưu","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q81","number":81,"text":"Theo tư tưởng Hồ Chí Minh, muốn đánh thắng được kẻ thù xâm lược thì trước hết ta phải làm gì?","options":[{"letter":"A","text":"Xây dựng và phát triển thực lực cách mạng vững mạnh","is_correct":true},{"letter":"B","text":"Tăng cường ký kết các hiệp ước an ninh đa phương","is_correct":false},{"letter":"C","text":"Đợi chờ sự viện trợ toàn diện từ các nước lớn","is_correct":false},{"letter":"D","text":"Thu hẹp thế trận chiến tranh trên các địa bàn hiểm trở","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q82","number":82,"text":"Đảng Cộng sản Việt Nam xác định vị trí của Chiến lược quốc phòng Việt Nam hiện nay như thế nào?","options":[{"letter":"A","text":"Là bộ phận chủ đạo, cụ thể hóa Chiến lược bảo vệ Tổ quốc","is_correct":true},{"letter":"B","text":"Là một bộ phận độc lập nằm ngoài Chiến lược bảo vệ Tổ quốc","is_correct":false},{"letter":"C","text":"Là bản kế hoạch kỹ thuật thuần túy của các quân chủng","is_correct":false},{"letter":"D","text":"Là quy định hành chính điều hành tác chiến của các địa phương","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q83","number":83,"text":"Tư tưởng Hồ Chí Minh về xây dựng nền quốc phòng toàn dân được thể hiện qua lời dạy nào sau đây?","options":[{"letter":"A","text":"Trung với nước, hiếu với dân, nhiệm vụ nào cũng hoàn thành","is_correct":false},{"letter":"B","text":"Các Vua Hùng đã có công dựng nước, Bác cháu ta phải cùng nhau giữ lấy nước","is_correct":true},{"letter":"C","text":"Không có gì quý hơn độc lập, tự do","is_correct":false},{"letter":"D","text":"Nước Việt Nam là một, dân tộc Việt Nam là một","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q84","number":84,"text":"Luận điểm nào sau đây thể hiện đúng nội dung phát huy sức mạnh quần chúng nhân dân trong lĩnh vực quân sự của Hồ Chí Minh?","options":[{"letter":"A","text":"Mở rộng quân số thường trực ở mọi địa bàn","is_correct":false},{"letter":"B","text":"Tăng cường mua sắm các loại vũ khí hiện đại","is_correct":false},{"letter":"C","text":"Nâng cao dân trí và củng cố khối đại đoàn kết toàn dân","is_correct":true},{"letter":"D","text":"Giảm nhẹ công tác dân vận để tập trung tác chiến","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q85","number":85,"text":"Theo Hồ Chí Minh, biện pháp phát huy tiềm năng to lớn của nhân dân trong lĩnh vực quân sự là gì?","options":[{"letter":"A","text":"Truyền bá hệ tư tưởng và lý luận cách mạng vào phong trào yêu nước","is_correct":true},{"letter":"B","text":"Đẩy mạnh ký kết các hiệp ước an ninh quốc tế","is_correct":false},{"letter":"C","text":"Mở rộng hoạt động tình báo quân sự trong dân gian","is_correct":false},{"letter":"D","text":"Phổ biến kinh nghiệm quân sự của các nước phương Tây","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q86","number":86,"text":"Quan điểm nào sau đây thể hiện sự sáng tạo, phát triển học thuyết quân sự Mác - Lênin của Hồ Chí Minh về bản chất quân đội ta?","options":[{"letter":"A","text":"Quân đội chỉ mang bản chất của giai cấp nông dân lao động","is_correct":false},{"letter":"B","text":"Quân đội mang bản chất giai cấp công nhân, tính nhân dân và tính dân tộc sâu sắc","is_correct":true},{"letter":"C","text":"Quân đội đặt nhiệm vụ tác chiến lên trên công tác vận động quần chúng","is_correct":false},{"letter":"D","text":"Quân đội nhà nghề chỉ thực hiện thuần túy nhiệm vụ quân sự","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q87","number":87,"text":"Theo Hồ Chí Minh, vấn đề cốt lõi trong xây dựng hậu phương vững mạnh về chính trị, tư tưởng là gì?","options":[{"letter":"A","text":"Mở rộng bộ máy quản lý kinh tế nhà nước","is_correct":false},{"letter":"B","text":"Phát triển mạng lưới trường lớp ở nông thôn","is_correct":false},{"letter":"C","text":"Xây dựng thế trận lòng dân","is_correct":true},{"letter":"D","text":"Tăng cường số lượng cán bộ hành chính cơ sở","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q88","number":88,"text":"Mục đích căn bản, xuyên suốt của nền quốc phòng toàn dân theo tư tưởng Hồ Chí Minh là gì?","options":[{"letter":"A","text":"Áp đặt vị thế ngoại giao áp đảo trên trường quốc tế","is_correct":false},{"letter":"B","text":"Tìm kiếm cơ hội mở rộng ảnh hưởng quân sự sang các nước lân cận","is_correct":false},{"letter":"C","text":"Răn đe các quốc gia đối kháng bằng tiềm lực vũ khí công nghệ cao","is_correct":false},{"letter":"D","text":"Giữ vững hòa bình, tự vệ chính đáng và bảo vệ vững chắc độc lập, chủ quyền của Tổ quốc","is_correct":true}],"correct_letter":"D"},{"id":"ho-chi-minh-source-q89","number":89,"text":"Luận điểm: “Cách mệnh là sự nghiệp của cả dân chúng chứ không phải việc một hai người” được Hồ Chí Minh khẳng định trong tác phẩm nào?","options":[{"letter":"A","text":"Lời kêu gọi toàn quốc kháng chiến","is_correct":false},{"letter":"B","text":"Bản án chế độ thực dân Pháp","is_correct":false},{"letter":"C","text":"Đường cách mệnh","is_correct":true},{"letter":"D","text":"Tuyên ngôn độc lập","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q90","number":90,"text":"Theo Hồ Chí Minh, nhân tố quyết định bản chất giai cấp công nhân và sức mạnh chiến đấu của Quân đội ta là gì?","options":[{"letter":"A","text":"Sự lãnh đạo tuyệt đối, trực tiếp về mọi mặt của Đảng Cộng sản Việt Nam","is_correct":true},{"letter":"B","text":"Số lượng và trình độ kỹ thuật của các loại vũ khí hiện đại","is_correct":false},{"letter":"C","text":"Quy mô quân số và cơ cấu tổ chức các quân binh chủng","is_correct":false},{"letter":"D","text":"Nguồn lực viện trợ vũ khí, trang bị từ các nước đồng minh","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q91","number":91,"text":"Nội dung cốt lõi của nghệ thuật quân sự phát huy sức mạnh tổng hợp theo Hồ Chí Minh là gì?","options":[{"letter":"A","text":"Huy động toàn bộ lực lượng công nghiệp nặng phục vụ chế tạo trang bị quân sự","is_correct":false},{"letter":"B","text":"Động viên toàn dân đánh giặc, đánh giặc toàn diện; kết hợp sức mạnh dân tộc với sức mạnh thời đại","is_correct":true},{"letter":"C","text":"Đẩy mạnh tổng động viên thanh niên nhập ngũ và tập trung mua sắm vũ khí hiện đại","is_correct":false},{"letter":"D","text":"Nhất loạt mở các chiến dịch quy mô lớn trên toàn bộ các hướng chiến lược","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q92","number":92,"text":"Hồ Chí Minh coi nhân tố nào giữ vai trò quan trọng nhất khi xây dựng sức mạnh hậu phương chiến tranh?","options":[{"letter":"A","text":"Thế trận lòng dân","is_correct":true},{"letter":"B","text":"Số lượng và chất lượng vũ khí hiện đại","is_correct":false},{"letter":"C","text":"Thế hiểm trở của địa hình căn cứ địa","is_correct":false},{"letter":"D","text":"Nguồn viện trợ lương thực từ quốc tế","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q93","number":93,"text":"Luận điểm: “Toàn thể dân tộc Việt Nam quyết đem tất cả tinh thần và lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập ấy” thể hiện tính chất nào của bạo lực cách mạng?","options":[{"letter":"A","text":"Tính tuyệt đối hóa sức mạnh của lực lượng quân đội","is_correct":false},{"letter":"B","text":"Tính chính nghĩa, tự vệ và mang sức mạnh toàn dân","is_correct":true},{"letter":"C","text":"Tính ưu tiên phương tiện chiến tranh hiện đại","is_correct":false},{"letter":"D","text":"Tính linh hoạt trong giải quyết xung đột ngoại giao","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q94","number":94,"text":"Theo Hồ Chí Minh, sức mạnh quân sự giữ vai trò gì đối với tổng thể sức mạnh của nền quốc phòng toàn dân?","options":[{"letter":"A","text":"Là thành tố hỗ trợ vòng ngoài","is_correct":false},{"letter":"B","text":"Là nhân tố cơ bản quyết định","is_correct":false},{"letter":"C","text":"Là nền tảng vật chất kỹ thuật","is_correct":false},{"letter":"D","text":"Là yếu tố trực tiếp quyết định","is_correct":true}],"correct_letter":"D"},{"id":"ho-chi-minh-source-q95","number":95,"text":"Dưới sự chỉ dẫn của Hồ Chí Minh, căn cứ địa cách mạng Việt Bắc được mở rộng phát triển thành Khu giải phóng gồm mấy tỉnh?","options":[{"letter":"A","text":"4 tỉnh","is_correct":false},{"letter":"B","text":"5 tỉnh","is_correct":false},{"letter":"C","text":"3 tỉnh","is_correct":false},{"letter":"D","text":"6 tỉnh","is_correct":true}],"correct_letter":"D"},{"id":"ho-chi-minh-source-q96","number":96,"text":"Theo Hồ Chí Minh, muốn dựa vững chắc vào nhân dân cần xây dựng lực lượng nào sau đây?","options":[{"letter":"A","text":"Xây dựng lực lượng vũ trang nhân dân ba thứ quân","is_correct":true},{"letter":"B","text":"Xây dựng lực lượng đặc nhiệm cơ động độc lập","is_correct":false},{"letter":"C","text":"Xây dựng mạng lưới an ninh ngầm trong xã hội","is_correct":false},{"letter":"D","text":"Xây dựng các binh chủng kỹ thuật chuyên sâu","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q97","number":97,"text":"Giải pháp định hướng xây dựng hậu phương chiến tranh theo tinh thần Đại hội XIV của Đảng hiện nay?","options":[{"letter":"A","text":"Tập trung toàn bộ ngân sách dự trữ quốc gia vào lĩnh vực quốc phòng","is_correct":false},{"letter":"B","text":"Chỉ chú trọng phát triển kinh tế vùng ven biển, giảm đầu tư vùng căn cứ địa","is_correct":false},{"letter":"C","text":"Tách rời khu vực phòng thủ địa phương khỏi thế trận quốc phòng chung","is_correct":false},{"letter":"D","text":"Xây dựng “thế trận lòng dân” vững chắc gắn với thế trận quốc phòng toàn dân","is_correct":true}],"correct_letter":"D"},{"id":"ho-chi-minh-source-q98","number":98,"text":"Chọn phương án đúng về nhiệm vụ trọng tâm khi vận dụng tư tưởng bạo lực cách mạng Hồ Chí Minh trong bảo vệ Tổ quốc hiện nay:","options":[{"letter":"A","text":"Kết hợp chặt chẽ giữa phát triển kinh tế - xã hội với củng cố quốc phòng, an ninh","is_correct":true},{"letter":"B","text":"Tăng cường mua sắm các loại vũ khí hiện đại, giảm huấn luyện chính trị tư tưởng","is_correct":false},{"letter":"C","text":"Tách biệt hoàn toàn công tác quốc phòng khỏi quan hệ đối ngoại và kinh tế","is_correct":false},{"letter":"D","text":"Duy trì thế trận quân sự thường trực sẵn sàng tham chiến ở mọi khu vực biên giới","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q99","number":99,"text":"Giải pháp hàng đầu nhằm phát huy sức mạnh nhân dân trong bảo vệ Tổ quốc hiện nay khi vận dụng tư tưởng Hồ Chí Minh?","options":[{"letter":"A","text":"Tăng nguồn chi viện tài chính quân sự từ bên ngoài","is_correct":false},{"letter":"B","text":"Tách rời nhiệm vụ quân sự khỏi các chính sách an sinh xã hội","is_correct":false},{"letter":"C","text":"Xây dựng “thế trận lòng dân” vững chắc từ cơ sở","is_correct":true},{"letter":"D","text":"Huy động ngay lực lượng thanh niên vào quân đội tập trung","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q100","number":100,"text":"Theo Hồ Chí Minh, việc xây dựng hậu phương chiến tranh nhất thiết phải gắn liền với vấn đề gì?","options":[{"letter":"A","text":"Tách rời hoàn toàn khỏi nhiệm vụ ở tiền tuyến","is_correct":false},{"letter":"B","text":"Đóng cửa toàn bộ giao thương kinh tế nội địa","is_correct":false},{"letter":"C","text":"Bảo vệ hậu phương chiến tranh","is_correct":true},{"letter":"D","text":"Thu hẹp quy mô chiến tranh vũ trang","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q101","number":101,"text":"Theo tư tưởng Hồ Chí Minh, hình thức cơ bản của bạo lực cách mạng ở nước ta trong chiến tranh giải phóng là gì?","options":[{"letter":"A","text":"Đấu tranh kinh tế kết hợp với phong trào công nhân quốc tế","is_correct":false},{"letter":"B","text":"Kết hợp đấu tranh quân sự với đấu tranh chính trị và binh vận","is_correct":true},{"letter":"C","text":"Đấu tranh ngoại giao đơn thuần trên các diễn đàn quốc tế","is_correct":false},{"letter":"D","text":"Khởi nghĩa vũ trang thuần túy của bộ đội chủ lực trên chiến trường","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q102","number":102,"text":"Theo Hồ Chí Minh, yếu tố nào có giá trị cao nhất trong sức mạnh tinh thần của nhân dân ở lĩnh vực quân sự?","options":[{"letter":"A","text":"Tinh thần tương thân tương ái","is_correct":false},{"letter":"B","text":"Chủ nghĩa yêu nước","is_correct":true},{"letter":"C","text":"Ý thức tuân thủ kỷ luật quân sự","is_correct":false},{"letter":"D","text":"Lòng tự hào về truyền thống dòng họ","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q103","number":103,"text":"Tháng 12/1946, Chủ tịch Hồ Chí Minh thay mặt Chính phủ đã tặng đồng bào miền Nam danh hiệu cao quý nào?","options":[{"letter":"A","text":"Kháng chiến anh dũng","is_correct":false},{"letter":"B","text":"Căn cứ địa bất khả xâm phạm","is_correct":false},{"letter":"C","text":"Ngọn cờ đầu chống giặc ngoại xâm","is_correct":false},{"letter":"D","text":"Thành đồng Tổ quốc","is_correct":true}],"correct_letter":"D"},{"id":"ho-chi-minh-source-q104","number":104,"text":"Chọn phương án đúng về điểm cốt lõi thể hiện tính nhân văn sâu sắc trong tư tưởng Hồ Chí Minh về bạo lực cách mạng:","options":[{"letter":"A","text":"Chủ động phát động tấn công quân sự ngay khi xuất hiện thời cơ thuận lợi","is_correct":false},{"letter":"B","text":"Tận dụng mọi khả năng hòa bình, chỉ dùng chiến tranh vũ trang khi không còn con đường nào khác","is_correct":true},{"letter":"C","text":"Không sử dụng lực lượng chính trị khi các biện pháp quân sự đã phát huy tác dụng","is_correct":false},{"letter":"D","text":"Ưu tiên đàm phán ngoại giao ngay cả khi chủ quyền lãnh thổ bị xâm phạm nghiêm trọng","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q105","number":105,"text":"Chọn phương án đúng về nội dung cốt lõi trong xây dựng hậu phương vững mạnh về quân sự theo tư tưởng Hồ Chí Minh:","options":[{"letter":"A","text":"Xây dựng lực lượng vũ trang ba thứ quân vững mạnh","is_correct":true},{"letter":"B","text":"Thành lập các đơn vị quân đội chuyên nghiệp độc lập","is_correct":false},{"letter":"C","text":"Tách biệt lực lượng dân quân khỏi đời sống sản xuất","is_correct":false},{"letter":"D","text":"Tập trung toàn bộ vũ khí cho lực lượng thường trực","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q106","number":106,"text":"Theo tư tưởng Hồ Chí Minh, sức mạnh chính trị - tư tưởng giữ vai trò như thế nào đối với nền quốc phòng toàn dân?","options":[{"letter":"A","text":"Là nền tảng vật chất","is_correct":false},{"letter":"B","text":"Là thành tố quan trọng","is_correct":false},{"letter":"C","text":"Là nhân tố cơ bản quyết định","is_correct":true},{"letter":"D","text":"Là yếu tố trực tiếp quyết định","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q107","number":107,"text":"Phong trào nào sau đây không thuộc các phong trào thi đua ái quốc trong cuộc kháng chiến chống thực dân Pháp?","options":[{"letter":"A","text":"Bình dân học vụ","is_correct":false},{"letter":"B","text":"Mùa đông binh sĩ","is_correct":false},{"letter":"C","text":"Sóng Duyên hải - Gió Đại Phong","is_correct":true},{"letter":"D","text":"Tất cả các phương án","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q108","number":108,"text":"Theo Hồ Chí Minh, tên gọi “Đội Việt Nam tuyên truyền giải phóng quân” có ý nghĩa cốt lõi là gì?","options":[{"letter":"A","text":"Tác chiến vũ trang là mục tiêu duy nhất","is_correct":false},{"letter":"B","text":"Chính trị trọng hơn quân sự","is_correct":true},{"letter":"C","text":"Quân sự trọng hơn chính trị","is_correct":false},{"letter":"D","text":"Chính trị và quân sự có vai trò ngang nhau","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q109","number":109,"text":"Chọn phương án đúng về cấu trúc lực lượng vũ trang theo tư tưởng Hồ Chí Minh:","options":[{"letter":"A","text":"Quân đội thường trực chính quy và quân nhân xuất ngũ dự bị","is_correct":false},{"letter":"B","text":"Ba thứ quân: bộ đội chủ lực, bộ đội địa phương và dân quân tự vệ","is_correct":true},{"letter":"C","text":"Lực lượng chiến đấu cơ động và lực lượng cảnh giới biên phòng","is_correct":false},{"letter":"D","text":"Lục quân, Hải quân, Phòng không - Không quân","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q110","number":110,"text":"Theo Hồ Chí Minh, biện pháp nào sau đây nhằm phát huy nguồn lực vật chất của nhân dân chi viện cho kháng chiến?","options":[{"letter":"A","text":"Trưng thu toàn bộ nông sản trong vụ thu hoạch","is_correct":false},{"letter":"B","text":"Xây dựng nền văn hóa mới và con người mới cách mạng","is_correct":true},{"letter":"C","text":"Độc quyền quản lý toàn bộ thị trường buôn bán","is_correct":false},{"letter":"D","text":"Đóng cửa giao thương kinh tế với các vùng địch tạm chiếm","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q111","number":111,"text":"Nội dung nào sau đây không thuộc tư tưởng Hồ Chí Minh về nghệ thuật quân sự?","options":[{"letter":"A","text":"Xây dựng nền quốc phòng toàn dân, toàn diện","is_correct":true},{"letter":"B","text":"Nắm vững tư tưởng chiến lược tiến công, giành và giữ quyền chủ động","is_correct":false},{"letter":"C","text":"Phát huy sức mạnh tổng hợp của toàn dân tộc","is_correct":false},{"letter":"D","text":"Tạo lực, lập thế, tranh thời, dùng mưu linh hoạt","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q112","number":112,"text":"Hồ Chí Minh đã ký với Pháp văn bản nào nhằm kéo dài thời gian chuẩn bị kháng chiến?","options":[{"letter":"A","text":"Hiệp định Giơ-ne-vơ về Đông Dương","is_correct":false},{"letter":"B","text":"Bản Tạm ước Việt - Pháp","is_correct":true},{"letter":"C","text":"Hiệp định sơ bộ Việt - Pháp","is_correct":false},{"letter":"D","text":"Thỏa ước quân sự Pháp - Hoa","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q113","number":113,"text":"Bác Hồ căn dặn cán bộ, chiến sĩ Đại đoàn 308: “Các Vua Hùng đã có công dựng nước, Bác cháu ta phải cùng nhau giữ lấy nước” trong bối cảnh nào?","options":[{"letter":"A","text":"Khi về thăm khu căn cứ địa Tân Trào sau ngày Toàn quốc kháng chiến bùng nổ","is_correct":false},{"letter":"B","text":"Tại Đền Hùng (Phú Thọ) năm 1954, trước khi đơn vị về tiếp quản Thủ đô","is_correct":true},{"letter":"C","text":"Trong Lễ tuyên thệ xuất quân mở màn chiến dịch Điện Biên Phủ năm 1954","is_correct":false},{"letter":"D","text":"Tại Hội nghị quân sự toàn quốc chuẩn bị mở chiến dịch Biên giới năm 1950","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q114","number":114,"text":"Địa bàn được xác định là hậu phương lớn của tiền tuyến miền Nam trong cuộc kháng chiến chống Mỹ, cứu nước là:","options":[{"letter":"A","text":"Vùng giải phóng Hạ Lào","is_correct":false},{"letter":"B","text":"Tây Nguyên","is_correct":false},{"letter":"C","text":"Miền Trung","is_correct":false},{"letter":"D","text":"Miền Bắc","is_correct":true}],"correct_letter":"D"},{"id":"ho-chi-minh-source-q115","number":115,"text":"Luận điểm nào sau đây không phải là nội dung tư tưởng nghệ thuật quân sự của Hồ Chí Minh?","options":[{"letter":"A","text":"Khởi đầu và kết thúc chiến tranh đúng lúc","is_correct":false},{"letter":"B","text":"Chủ động đánh vào lòng người đối phương, kết hợp tác chiến với địch vận","is_correct":false},{"letter":"C","text":"Xây dựng Quân đội mang bản chất giai cấp công nhân, tính nhân dân, tính dân tộc sâu sắc","is_correct":true},{"letter":"D","text":"Nắm vững tư tưởng chiến lược tiến công, giành và giữ quyền chủ động","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q116","number":116,"text":"Đâu là một trong những cơ sở lý luận nền tảng hình thành tư tưởng Hồ Chí Minh về bạo lực cách mạng?","options":[{"letter":"A","text":"Học thuyết Mác - Lênin về bạo lực cách mạng và khởi nghĩa vũ trang","is_correct":true},{"letter":"B","text":"Học thuyết quân sự tư sản về chiến tranh tổng lực hiện đại","is_correct":false},{"letter":"C","text":"Tư tưởng phi bạo lực của các nhà triết học cổ đại phương Đông","is_correct":false},{"letter":"D","text":"Lý luận về cân bằng quyền lực quân sự giữa các cường quốc","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q117","number":117,"text":"Chọn phương án đúng về cơ sở lý luận phát huy sức mạnh của quần chúng nhân dân trong quân sự của Hồ Chí Minh:","options":[{"letter":"A","text":"Quan điểm của chủ nghĩa Mác - Lênin: Quần chúng nhân dân là người sáng tạo ra lịch sử","is_correct":true},{"letter":"B","text":"Quan niệm chiến lược của các học giả quân sự phương Tây thế kỷ XIX","is_correct":false},{"letter":"C","text":"Tư tưởng thần quyền về định mệnh trong chiến tranh","is_correct":false},{"letter":"D","text":"Quan điểm siêu hình về sức mạnh của vũ khí công nghệ cao","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q118","number":118,"text":"Trong công tác hậu cần - kỹ thuật quân đội, Hồ Chí Minh từng căn dặn cán bộ cung cấp phải như là:","options":[{"letter":"A","text":"Người điều hành tài chính độc lập của đơn vị","is_correct":false},{"letter":"B","text":"Người giám sát việc tiêu thụ vật chất chiến đấu","is_correct":false},{"letter":"C","text":"Người mẹ, người chị của người binh nhì","is_correct":true},{"letter":"D","text":"Người quản lý kho hàng nghiêm khắc và chặt chẽ","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q119","number":119,"text":"Thước đo cao nhất phản ánh bản chất giai cấp công nhân của Quân đội ta theo Hồ Chí Minh là gì?","options":[{"letter":"A","text":"Trình độ làm chủ vũ khí, trang bị kỹ thuật công nghệ cao","is_correct":false},{"letter":"B","text":"Khả năng chịu đựng khó khăn, gian khổ trong huấn luyện dã ngoại","is_correct":false},{"letter":"C","text":"Tỷ lệ cán bộ xuất thân từ công nhân trong toàn quân đội","is_correct":false},{"letter":"D","text":"Trình độ giác ngộ; tinh thần tự giác; sự hy sinh vì mục tiêu, lý tưởng của Đảng","is_correct":true}],"correct_letter":"D"},{"id":"ho-chi-minh-source-q120","number":120,"text":"Theo Hồ Chí Minh, mục tiêu chiến đấu cao nhất của Quân đội nhân dân Việt Nam là gì?","options":[{"letter":"A","text":"Giành ưu thế chiến lược tuyệt đối trước lực lượng đối phương","is_correct":false},{"letter":"B","text":"Xây dựng tiềm lực quốc phòng độc lập với hệ thống chính trị","is_correct":false},{"letter":"C","text":"Mở rộng vùng kiểm soát quân sự sang các nước trong khu vực","is_correct":false},{"letter":"D","text":"Tranh lại độc lập, thống nhất cho Tổ quốc, bảo vệ tự do, hạnh phúc của nhân dân","is_correct":true}],"correct_letter":"D"},{"id":"ho-chi-minh-source-q121","number":121,"text":"Luận điểm nào sau đây thể hiện sâu sắc tư tưởng Hồ Chí Minh về sự kết hợp giữa kinh tế và quốc phòng?","options":[{"letter":"A","text":"Chỉ đầu tư cho công nghiệp quốc phòng, giảm bớt công nghiệp dân sinh","is_correct":false},{"letter":"B","text":"Phát triển kinh tế thị trường tự do tách biệt hẳn nhiệm vụ bảo vệ Tổ quốc","is_correct":false},{"letter":"C","text":"Vừa kháng chiến vừa kiến quốc, thực túc thì binh cường","is_correct":true},{"letter":"D","text":"Dừng phát triển sản xuất để ưu tiên toàn bộ cho tác chiến phòng ngự","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q122","number":122,"text":"Hoàn chỉnh luận điểm của Hồ Chí Minh: “… thì không quân lính nào, súng ống nào chống lại nổi”.","options":[{"letter":"A","text":"Thực lực mạnh.","is_correct":false},{"letter":"B","text":"Binh lính mạnh.","is_correct":false},{"letter":"C","text":"Dân khí mạnh.","is_correct":true},{"letter":"D","text":"Quân đội mạnh.","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q123","number":123,"text":"Yếu tố nào cấu thành sức mạnh vật chất của quần chúng nhân dân trong hoạt động quân sự theo tư tưởng Hồ Chí Minh?","options":[{"letter":"A","text":"Nguồn lực con người và của cải vật chất do con người làm ra","is_correct":true},{"letter":"B","text":"Vũ khí, phương tiện hiện đại mua từ nước ngoài","is_correct":false},{"letter":"C","text":"Hệ thống phòng thủ công sự và căn cứ địa","is_correct":false},{"letter":"D","text":"Kho dự trữ lương thực của lực lượng vũ trang","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q124","number":124,"text":"Biểu hiện sức mạnh kinh tế của nền quốc phòng toàn dân theo quan điểm Hồ Chí Minh là gì?","options":[{"letter":"A","text":"Khả năng phát triển kinh tế gắn với huy động nhân lực, vật lực phục vụ bảo vệ Tổ quốc","is_correct":true},{"letter":"B","text":"Khối lượng hàng hóa nhập khẩu từ các thị trường quốc tế vào nội địa","is_correct":false},{"letter":"C","text":"Duy trì ngân sách chi tiêu quân sự cao hơn tổng mức đầu tư xã hội","is_correct":false},{"letter":"D","text":"Việc chuyển đổi toàn bộ cơ sở hạ tầng dân sự sang công trình quốc phòng","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q125","number":125,"text":"Phong trào nào sau đây không phải là phong trào thi đua yêu nước tiêu biểu trong cuộc kháng chiến chống Mỹ, cứu nước?","options":[{"letter":"A","text":"Thanh niên ba sẵn sàng","is_correct":false},{"letter":"B","text":"Tuần lễ vàng","is_correct":true},{"letter":"C","text":"Phụ nữ ba đảm đang","is_correct":false},{"letter":"D","text":"Mỗi người làm việc bằng hai - tất cả vì miền Nam ruột thịt","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q126","number":126,"text":"Theo Hồ Chí Minh, đâu là giải pháp nền tảng để lãnh đạo quần chúng trong lĩnh vực quân sự là gì?","options":[{"letter":"A","text":"Đặt nhiệm vụ vũ trang lên trên việc xây dựng tổ chức Đảng","is_correct":false},{"letter":"B","text":"Xây dựng Đảng ta thực sự là đạo đức, là văn minh","is_correct":true},{"letter":"C","text":"Tách biệt hoàn toàn sinh hoạt Đảng khỏi các đoàn thể","is_correct":false},{"letter":"D","text":"Tăng cường quyền lực tuyệt đối cho chính quyền cơ sở","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q127","number":127,"text":"Chọn phương án đúng về lực lượng nòng cốt của nền quốc phòng toàn dân theo tư tưởng Hồ Chí Minh:","options":[{"letter":"A","text":"Lực lượng vũ trang nhân dân ba thứ quân","is_correct":true},{"letter":"B","text":"Bộ đội chủ lực kết hợp cùng các công ty quốc phòng","is_correct":false},{"letter":"C","text":"Lực lượng dự bị động viên tại các thành phố lớn","is_correct":false},{"letter":"D","text":"Đội ngũ cán bộ, công chức làm công tác quân sự địa phương","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q128","number":128,"text":"Theo quan điểm của Hồ Chí Minh, sức mạnh kinh tế giữ vị trí nào trong cấu trúc sức mạnh của nền quốc phòng toàn dân?","options":[{"letter":"A","text":"Là nhân tố cơ bản quyết định","is_correct":false},{"letter":"B","text":"Là nền tảng vật chất","is_correct":true},{"letter":"C","text":"Là lực lượng xung kích tại chỗ","is_correct":false},{"letter":"D","text":"Là yếu tố trực tiếp quyết định","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q129","number":129,"text":"Chọn phương án đúng về giải pháp xây dựng nền quốc phòng toàn dân hiện nay khi vận dụng tư tưởng Hồ Chí Minh:","options":[{"letter":"A","text":"Chuyển đổi toàn diện các tổ chức kinh tế tư nhân sang cơ chế quản lý quân sự","is_correct":false},{"letter":"B","text":"Kết hợp chặt chẽ, đồng bộ giữa phát triển kinh tế - xã hội với củng cố quốc phòng, an ninh","is_correct":true},{"letter":"C","text":"Tăng tỷ lệ quân số thường trực trong độ tuổi lao động tại các khu công nghiệp","is_correct":false},{"letter":"D","text":"Tách rời khu vực phòng thủ địa phương khỏi thế trận quốc phòng chung của cả nước","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q130","number":130,"text":"Theo định hướng Đại hội XIV của Đảng về xây dựng Quân đội trong điều kiện mới, yếu tố nào giữ vai trò là cơ sở, nền tảng vững chắc để xây dựng Quân đội hiện đại?","options":[{"letter":"A","text":"Đầu tư mua sắm toàn diện vũ khí công nghệ cao","is_correct":false},{"letter":"B","text":"Xây dựng Quân đội vững mạnh về chính trị","is_correct":true},{"letter":"C","text":"Mở rộng quân số thường trực ở các quân binh chủng","is_correct":false},{"letter":"D","text":"Tách biệt công tác huấn luyện với công tác tư tưởng","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q131","number":131,"text":"Để tiếp thu tinh hoa và phát triển nghệ thuật tác chiến, Hồ Chí Minh đã trực tiếp dịch và xuất bản tác phẩm quân sự cổ đại nào?","options":[{"letter":"A","text":"Binh thư yếu lược","is_correct":false},{"letter":"B","text":"Binh pháp Tôn Tử","is_correct":true},{"letter":"C","text":"Tam lược Hoàng Thạch Công","is_correct":false},{"letter":"D","text":"Lục thao Khương Tử Nha","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q132","number":132,"text":"Theo Hồ Chí Minh, khái niệm “thế” trong đấu tranh quân sự được hiểu như thế nào?","options":[{"letter":"A","text":"Thế áp đảo tuyệt đối về số lượng phương tiện vũ khí so với đối phương","is_correct":false},{"letter":"B","text":"Thế tổ chức, bố trí, triển khai lực lượng và vũ khí trang bị trên chiến trường nhằm phát huy cao nhất sức mạnh chiến đấu","is_correct":true},{"letter":"C","text":"Môi trường thời tiết khí hậu thuận lợi để quân đội xuất kích tiến công","is_correct":false},{"letter":"D","text":"Ưu thế ngoại giao quốc tế của đất nước trước khi mở màn chiến dịch","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q133","number":133,"text":"Theo Hồ Chí Minh, biện pháp hiệu quả nhất để xây dựng hậu phương kháng chiến vững mạnh là:","options":[{"letter":"A","text":"Tăng cường huy động đóng góp tài chính bắt buộc","is_correct":false},{"letter":"B","text":"Tổ chức tốt phong trào thi đua ái quốc","is_correct":true},{"letter":"C","text":"Áp dụng các biện pháp trừng phạt kinh tế nghiêm khắc","is_correct":false},{"letter":"D","text":"Tuyệt đối ưu tiên sản xuất các mặt hàng công nghiệp nặng","is_correct":false}],"correct_letter":"B"},{"id":"ho-chi-minh-source-q134","number":134,"text":"Trong Chỉ thị thành lập Đội Việt Nam tuyên truyền giải phóng quân, Hồ Chí Minh đã gọi lực lượng nào là “Đội quân đàn anh”?","options":[{"letter":"A","text":"Bộ đội địa phương","is_correct":false},{"letter":"B","text":"Lực lượng tự vệ cứu quốc","is_correct":false},{"letter":"C","text":"Đội du kích Ba Tơ","is_correct":false},{"letter":"D","text":"Bộ đội chủ lực","is_correct":true}],"correct_letter":"D"},{"id":"ho-chi-minh-source-q135","number":135,"text":"Sau Cách mạng Tháng Tám năm 1945, Hồ Chí Minh đã phát động phong trào nào để động viên sự ủng hộ tài chính to lớn từ nhân dân?","options":[{"letter":"A","text":"Tuần lễ vàng","is_correct":true},{"letter":"B","text":"Mùa đông binh sĩ","is_correct":false},{"letter":"C","text":"Hũ gạo nuôi quân","is_correct":false},{"letter":"D","text":"Sóng Duyên hải","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q136","number":136,"text":"Theo Hồ Chí Minh, đấu tranh chính trị được sử dụng chủ yếu trong giai đoạn cách mạng nào?","options":[{"letter":"A","text":"Giai đoạn đấu tranh giành chính quyền","is_correct":true},{"letter":"B","text":"Giai đoạn thực hiện đường lối đổi mới đất nước","is_correct":false},{"letter":"C","text":"Giai đoạn cả nước quá độ lên chủ nghĩa xã hội","is_correct":false},{"letter":"D","text":"Giai đoạn bảo vệ và giữ vững chính quyền","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q137","number":137,"text":"Luận điểm nào sau đây không đúng với tư tưởng Hồ Chí Minh về thời điểm thích hợp để bắt đầu chiến tranh tự vệ?","options":[{"letter":"A","text":"Ngay khi kẻ thù vừa nhen nhóm ý định xâm lược nước ta","is_correct":true},{"letter":"B","text":"Khi các giải pháp hòa bình để trì hoãn, ngăn chặn chiến tranh đã bị kẻ thù phá vỡ","is_correct":false},{"letter":"C","text":"Khi địch buộc ta vào tình thế không còn con đường lựa chọn nào khác","is_correct":false},{"letter":"D","text":"Khi ta đã chuẩn bị chu đáo cả về đường lối chính trị và lực lượng vũ trang kháng chiến","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q138","number":138,"text":"Theo tư tưởng Hồ Chí Minh, hậu phương chiến tranh có vai trò như thế nào đối với thắng lợi của cách mạng?","options":[{"letter":"A","text":"Là cơ sở để tiến hành hoạt động ngoại giao quân sự","is_correct":false},{"letter":"B","text":"Là nguồn bổ sung quân số dự bị đơn thuần cho quân đội","is_correct":false},{"letter":"C","text":"Là nhân tố quan trọng, quyết định đến thắng lợi của cách mạng","is_correct":true},{"letter":"D","text":"Là nhân tố hỗ trợ tạm thời khi tiền tuyến gặp khó khăn","is_correct":false}],"correct_letter":"C"},{"id":"ho-chi-minh-source-q139","number":139,"text":"Sau khi tiếp thu lý luận quân sự cổ đại phương Đông, Hồ Chí Minh đã biên soạn tài liệu nào để đào tạo đội ngũ cán bộ?","options":[{"letter":"A","text":"Cách huấn luyện cán bộ quân sự của Khổng Minh","is_correct":true},{"letter":"B","text":"Phép dùng binh của Tôn Tẫn","is_correct":false},{"letter":"C","text":"Bát trận đồ ứng dụng trong chiến tranh hiện đại","is_correct":false},{"letter":"D","text":"Kinh nghiệm tổ chức quân cơ thời cổ","is_correct":false}],"correct_letter":"A"},{"id":"ho-chi-minh-source-q140","number":140,"text":"Theo Hồ Chí Minh, biện pháp hàng đầu phát huy sức mạnh quần chúng nhân dân trong lĩnh vực quân sự là gì?","options":[{"letter":"A","text":"Xác định mục tiêu, con đường cách mạng đúng đắn, hợp lòng dân","is_correct":true},{"letter":"B","text":"Huy động tối đa tài sản đóng góp vào ngân sách quân sự","is_correct":false},{"letter":"C","text":"Áp dụng kỷ luật nghiêm ngặt đối với đời sống nhân dân","is_correct":false},{"letter":"D","text":"Thu hẹp vai trò của các tổ chức đoàn thể chính trị","is_correct":false}],"correct_letter":"A"}]}};
